/* ===== Chat file artifacts ===== */
.chat-file-artifact {
  margin-block: 16px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
}
.chat-file-artifact-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--bg-secondary);
}
.chat-file-artifact-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}
.chat-file-artifact-action {
  display: inline-flex;
  padding: 6px;
  border-radius: 4px;
  color: var(--text-secondary);
}
.chat-file-artifact-action:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.chat-file-artifact-action:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}
.chat-file-artifact-status {
  padding: 16px;
  color: var(--text-secondary);
}
.chat-file-artifact-runtime.html-artifact-block {
  margin: 0;
  border: 0;
  border-radius: 0;
}
.chat-file-artifact-source {
  margin: 0;
  padding: 16px;
  max-height: clamp(240px, 56vh, 760px);
  overflow: auto;
}

/* ===== HTML artifact preview ===== */
.html-artifact-block {
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  margin-block: 12px;
  /* The preview scales against the block width, not the window width. */
  container-type: inline-size;
  container-name: html-artifact;
}
.html-artifact-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
}
.html-artifact-toolbar button {
  padding: 4px 8px;
  border-radius: 4px;
  color: var(--text-secondary);
}
.html-artifact-toolbar button[aria-pressed="true"] {
  color: var(--text-primary);
  background: var(--bg-primary);
}
.html-artifact-toolbar button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.html-artifact-toolbar button:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}
/* The zoom controls are built by the renderer, so the slot stays empty in markup. */
.html-artifact-zoom-slot {
  display: none;
  align-items: center;
  gap: 4px;
  margin-inline-start: auto;
}
.html-artifact-block[data-html-view="preview"] .html-artifact-zoom-slot {
  display: flex;
}
.html-artifact-preview {
  display: none;
  height: clamp(240px, 56vh, 760px);
  background: var(--bg-primary);
}
@container html-artifact (max-width: 620px) {
  .html-artifact-preview {
    height: clamp(200px, 46vh, 520px);
  }
}
@container html-artifact (max-width: 420px) {
  .html-artifact-preview {
    height: clamp(180px, 40vh, 420px);
  }
}
.html-artifact-block[data-html-view="preview"] .html-artifact-preview {
  display: block;
}
.html-artifact-block[data-html-view="preview"] .html-artifact-code {
  display: none;
}
/* 与普通代码块保持一致的内边距 */
.html-artifact-block .html-artifact-code pre {
  overflow-x: auto;
  margin: 0;
  padding: 12px 14px;
}
.html-artifact-frame {
  display: block;
  width: 100%;
  height: 100%;
  border: none;
}
.html-artifact-carrier {
  margin: 0;
  height: 100vh;
  overflow: hidden;
}

/* ===== Reset & Base ===== */
* {
  box-sizing: border-box;
}

/* ===== Native Scrollbar =====
   Global scrollbar styling using the app color variables.
   Applies to all scrollable elements via ::-webkit-scrollbar. */
::-webkit-scrollbar {
  width: 10px;
  height: 10px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-thumb);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: content-box;
}
::-webkit-scrollbar-thumb:hover {
  background-color: var(--scrollbar-thumb-hover);
}
::-webkit-scrollbar-thumb:active {
  background-color: var(--scrollbar-thumb-active);
}
::-webkit-scrollbar-corner {
  background: transparent;
}
* {
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb) transparent;
}

html,
body,
#root {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--app-font-family, var(--font-sans));
  font-size: 13px;
  font-weight: var(--app-font-weight, 400);
  line-height: 1.5;
  color: var(--text-primary);
  background: var(--bg-primary);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
  margin: 0;
  color: inherit;
  -webkit-app-region: no-drag;
}

input {
  font-family: inherit;
}

/* ===== App Layout ===== */
.app-shell {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  padding-top: env(titlebar-area-height, 0px);
  overflow: hidden;
  background: var(--app-bg);
}

.app-layout {
  display: flex;
  flex: 1;
  gap: 0;
  min-height: 0;
  width: 100vw;
  padding: 0 10px 10px;
  overflow: hidden;
  background: var(--app-bg);
}

body.is-panel-resizing,
body.is-panel-resizing * {
  cursor: col-resize !important;
  user-select: none;
}

.panel-resizer {
  position: relative;
  z-index: 40;
  width: 10px;
  min-width: 10px;
  height: 100%;
  cursor: col-resize;
  touch-action: none;
  -webkit-app-region: no-drag;
  opacity: 1;
  transition:
    width 0.2s ease,
    min-width 0.2s ease,
    opacity 0.2s ease;
}

.panel-resizer::before {
  position: absolute;
  top: 16px;
  bottom: 16px;
  left: 50%;
  width: 2px;
  border-radius: 999px;
  background: transparent;
  content: "";
  transform: translateX(-50%);
  transition:
    background 0.12s ease,
    box-shadow 0.12s ease;
}

.panel-resizer:hover::before,
.panel-resizer.is-active::before {
  background: color-mix(in srgb, var(--accent-color) 45%, transparent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-color) 10%, transparent);
}

.layout-resizer {
  flex-shrink: 0;
}

/* 功能页双栏（备忘录 / 项目记忆 / 定时任务）的中轴拖拽条 */
.split-resizer {
  flex-shrink: 0;
  align-self: stretch;
}

/* ===== Top Bar ===== */
.top-bar {
  position: relative;
  z-index: 50;
  display: grid;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr) var(
      --right-panel-width
    );
  /* 行轨固定为可用高度：下拉展开把卡片 overflow 切成 visible 后，
     卡片内容（标题+副标题）的最小高度不再把整行撑高 */
  grid-template-rows: minmax(0, 1fr);
  gap: 10px;
  height: calc(var(--header-height) + 20px);
  min-height: calc(var(--header-height) + 20px);
  padding: 10px;
  background: var(--app-bg);
  transition:
    grid-template-columns 0.18s ease,
    column-gap 0.18s ease;
  -webkit-app-region: drag;
  user-select: none;
}

.top-bar.plus-menu-open,
.top-bar.todo-panel-interactive {
  -webkit-app-region: no-drag;
}
.app-shell.sidebar-collapsed .top-bar {
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr) var(
      --right-panel-width
    );
}

.app-shell.right-panel-collapsed .top-bar {
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr) 49px;
}

.app-shell.sidebar-collapsed.right-panel-collapsed .top-bar {
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr) 49px;
}

.app-shell.right-panel-fullscreen .top-bar {
  grid-template-columns: var(--sidebar-width) 0px minmax(0, 1fr);
  column-gap: 5px;
}

.app-shell.sidebar-collapsed.right-panel-fullscreen .top-bar {
  column-gap: 0px;
}

.app-shell.right-panel-fullscreen .top-bar-main {
  opacity: 0;
  pointer-events: none;
  padding: 0;
  border-radius: 0;
}

.top-bar-left,
.top-bar-main,
.top-bar-right {
  display: flex;
  align-items: center;
  min-width: 0;
  border-radius: var(--radius-xl);
  background: var(--surface-island);
  box-shadow: var(--island-shadow);
  backdrop-filter: blur(18px) saturate(1.18);
}

.top-bar-left {
  justify-content: flex-end;
  padding: 0 16px 0 var(--traffic-light-safe-area);
}

.top-bar-sidebar-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.top-bar-main-leading {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.top-bar-main-trailing {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  -webkit-app-region: no-drag;
}

.top-bar.plus-menu-open .top-bar-main {
  overflow: visible;
}

.top-bar.todo-panel-open .top-bar-main {
  overflow: visible;
}

.top-bar-main {
  justify-content: space-between;
  gap: 12px;
  overflow: hidden;
  padding: 0 16px;
  background: var(--surface-island-strong);
  opacity: 1;
  transition: opacity 0.2s ease;
}

.top-bar-right {
  justify-content: space-between;
  gap: 8px;
  padding: 0 12px;
  overflow: visible;
  min-width: 0;
}

/* 右侧圆角卡片整体脱离窗口 drag 区域：卡片空白处（项目标签与按钮的
   间隙）右键也要弹出业务菜单，drag 区域会拦截 contextmenu 事件。 */
.top-bar-right {
  -webkit-app-region: no-drag;
}

.top-bar-right-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  overflow: visible;
}

/* 设置页操作区：原面板头部的刷新/导入/清空等按钮，现由 TopBar 渲染 */
.top-bar-settings-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.top-bar-settings-action {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 11px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.14s,
    border-color 0.14s,
    color 0.14s;
}

.top-bar-settings-action:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.top-bar-settings-action.danger {
  background: var(--accent-red-bg);
  border-color: var(--accent-red);
  color: var(--accent-red-text);
}

/* 窄窗口 TopBar 紧凑模式：按优先级隐藏次要元素，避免标题/项目标签
   被过度压缩截断。窗口断点为近似值（实际可用宽度还受侧栏/右面板影响）。 */
@media (max-width: 920px) {
  .header-subtitle {
    display: none;
  }
  .top-bar-team-sync-text {
    display: none;
  }
}

@media (max-width: 720px) {
  .top-bar-branch-label,
  .top-bar-branch-info .branch-selector {
    display: none;
  }
  .top-bar-main {
    gap: 6px;
    padding: 0 10px;
  }
  /* 手机尺寸下两侧面板已自动收起：侧栏折叠时不再为其保留整列宽度，
     把空间让给聊天区（top-bar 网格与下方 .app-layout 保持一致）。 */
  .app-shell.sidebar-collapsed .top-bar {
    grid-template-columns: auto minmax(0, 1fr) var(--right-panel-width);
  }
  .app-shell.sidebar-collapsed.right-panel-collapsed .top-bar {
    grid-template-columns: auto minmax(0, 1fr) 49px;
  }
  .app-shell.sidebar-collapsed.right-panel-fullscreen .top-bar {
    grid-template-columns: auto 0px minmax(0, 1fr);
  }
}

/* ===== Windows / Linux 合并式顶栏 =====
   Windows 与 Linux 均无原生标题栏：窗口控制按钮（最小化/最大化/关闭）嵌入
   TopBar 右侧卡片、标准大小 LOGO 移至左侧卡片后，独立的窗口控制条整体移除，
   顶栏合并为单行，把原本标题条的空缺区域利用起来。 */
.app-shell.is-custom-frame .top-bar-left {
  padding: 0 16px;
}

/* ===== macOS 原生全屏顶栏 =====
   系统在全屏时会隐藏红绿灯按钮，左侧卡片改渲染 LOGO（与 Windows / Linux 方案一致），
   同时去掉红绿灯安全区留白与侧栏折叠合并布局的偏移，避免左侧空一块。 */
.app-shell:not(.is-custom-frame) .top-bar.is-native-fullscreen .top-bar-left {
  padding: 0 16px;
}

.app-shell.sidebar-collapsed:not(.is-custom-frame)
  .top-bar.sidebar-collapsed.is-native-fullscreen
  .top-bar-main-leading {
  margin-left: 0;
}

.top-bar-logo {
  width: 32px;
  height: 32px;
  margin-right: auto;
  pointer-events: none;
  -webkit-user-select: none;
  user-select: none;
  color: var(--top-bar-logo-color, var(--accent-color));
}

.top-bar .window-controls-buttons {
  margin-left: 4px;
}

.top-bar .window-control-btn {
  width: 40px;
  height: 32px;
  border-radius: var(--radius-sm);
}

/* 右面板收起时第三列固定 49px，容纳不下窗口控制按钮：自绘标题栏平台按内容自适应 */
.app-shell.is-custom-frame.right-panel-collapsed .top-bar,
.app-shell.is-custom-frame.sidebar-collapsed.right-panel-collapsed .top-bar {
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr) auto;
}

@media (max-width: 720px) {
  .app-shell.is-custom-frame.sidebar-collapsed.right-panel-collapsed .top-bar {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }
}

.app-shell.sidebar-collapsed .top-bar.sidebar-collapsed {
  grid-template-columns: minmax(0, 1fr) var(--right-panel-width);
}

.app-shell.sidebar-collapsed.right-panel-collapsed .top-bar.sidebar-collapsed {
  grid-template-columns: minmax(0, 1fr) 49px;
}

.app-shell.is-custom-frame.sidebar-collapsed.right-panel-collapsed
  .top-bar.sidebar-collapsed {
  grid-template-columns: minmax(0, 1fr) auto;
}

.app-shell.sidebar-collapsed.right-panel-fullscreen .top-bar.sidebar-collapsed {
  grid-template-columns: 0px minmax(0, 1fr);
}

.app-shell.sidebar-collapsed:not(.is-custom-frame)
  .top-bar.sidebar-collapsed
  .top-bar-main-leading {
  margin-left: var(--traffic-light-merged-offset);
}

.app-shell.right-panel-collapsed:not(.right-panel-fullscreen)
  .top-bar.right-panel-collapsed {
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
}

.app-shell.sidebar-collapsed.right-panel-collapsed:not(.right-panel-fullscreen)
  .top-bar.right-panel-collapsed {
  grid-template-columns: minmax(0, 1fr);
}

.top-bar-plus-menu {
  position: relative;
  display: flex;
  align-items: center;
  overflow: visible;
}

.top-bar-plus-btn.active {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.top-bar-plus-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 100;
  display: flex;
  min-width: 150px;
  max-width: 240px;
  flex-direction: column;
  gap: 2px;
  padding: 4px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  box-shadow: var(--shadow-md);
}

.top-bar-plus-dropdown.is-align-start {
  right: auto;
  left: 0;
}

.top-bar-plus-dropdown-item {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  transition:
    background 0.12s,
    color 0.12s;
}

.top-bar-plus-dropdown-item:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.top-bar-plus-dropdown-item > span {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.top-bar-plus-dropdown-item svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

/* TopBar TODO panel */
.top-bar-todo-menu {
  position: relative;
  display: flex;
  align-items: center;
  overflow: visible;
}

.top-bar-todo-btn {
  position: relative;
}

.top-bar-todo-btn.active {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.top-bar-todo-badge {
  position: absolute;
  top: -3px;
  right: -3px;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: #e5484d;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  line-height: 1;
  pointer-events: none;
  border: 1.5px solid var(--surface-island-strong);
}

/* TopBar codebase sync indicator */
.top-bar-codebase-sync {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.top-bar-codebase-sync.is-watching {
  color: var(--text-muted);
}

.top-bar-codebase-sync.is-pending {
  color: var(--text-muted);
}

.top-bar-codebase-sync.is-changed {
  color: var(--accent-blue);
}

.top-bar-codebase-sync.is-syncing {
  color: var(--accent-blue);
}

.top-bar-codebase-sync.is-error {
  color: var(--accent-red-text);
}

.top-bar-codebase-sync.is-error:hover {
  background: var(--accent-red-bg);
}

.top-bar-codebase-sync.is-syncing .spin {
  animation: codebase-sync-spin 1.2s linear infinite;
}

.top-bar-codebase-sync-dot {
  position: absolute;
  top: 3px;
  right: 3px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  pointer-events: none;
  border: 1.5px solid var(--surface-island-strong);
}

.top-bar-codebase-sync.is-watching .top-bar-codebase-sync-dot {
  background: var(--accent-green);
}

.top-bar-codebase-sync.is-error .top-bar-codebase-sync-dot {
  background: var(--accent-red);
  animation: codebase-sync-pulse 1.5s ease-in-out infinite;
}

.top-bar-codebase-sync.is-pending .top-bar-codebase-sync-dot {
  background: var(--accent-amber-text, #b45309);
  animation: codebase-sync-pulse 1.5s ease-in-out infinite;
}

.top-bar-codebase-sync.is-changed .top-bar-codebase-sync-dot {
  background: var(--accent-blue);
  animation: codebase-sync-pulse 1.5s ease-in-out infinite;
}

@keyframes codebase-sync-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.5;
    transform: scale(1.3);
  }
}
.top-bar-todo-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 100;
  display: flex;
  min-width: 260px;
  max-width: 360px;
  max-height: 400px;
  flex-direction: column;
  gap: 0;
  padding: 0;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  box-shadow: var(--shadow-md);
  overflow: hidden;
  -webkit-app-region: no-drag;
  transform-origin: top right;
  animation: dropdown-pop-in 0.18s cubic-bezier(0.2, 0.9, 0.25, 1.15);
}

.top-bar-todo-dropdown-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-color);
}

.top-bar-todo-dropdown-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.top-bar-todo-dropdown-count {
  font-size: 11px;
  color: var(--text-muted);
  flex-shrink: 0;
}

.top-bar-todo-dropdown-header-actions {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.top-bar-todo-pin-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.top-bar-todo-pin-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.top-bar-todo-pin-btn.active {
  color: var(--text-primary);
  background: var(--bg-active);
}

.top-bar-todo-pin-btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 1px;
}

.top-bar-todo-item-status {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin: -2px 0 0 -3px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  cursor: pointer;
  transition: background 0.12s ease;
}

.top-bar-todo-item-status:hover:not(:disabled) {
  background: var(--bg-hover);
}

.top-bar-todo-item-status:disabled {
  cursor: default;
  opacity: 0.4;
}

.top-bar-todo-item-status:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 1px;
}

.top-bar-todo-list {
  flex: 1;
  min-height: 0;
  list-style: none;
  margin: 0;
  padding: 4px;
  overflow-x: hidden;
  overflow-y: auto;
  scrollbar-width: thin;
}

.top-bar-todo-item {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 5px 8px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  line-height: 1.4;
  color: var(--text-secondary);
}

.top-bar-todo-item-icon {
  flex-shrink: 0;
  margin-top: 1px;
}

.top-bar-todo-item-content {
  word-break: break-word;
}

.top-bar-todo-item-completed .top-bar-todo-item-content {
  text-decoration: line-through;
  color: var(--text-muted);
}

.top-bar-todo-item-completed .top-bar-todo-item-icon {
  color: var(--success);
}

.top-bar-todo-item-inProgress .top-bar-todo-item-icon {
  color: var(--accent);
}
.top-bar-todo-item-pending .top-bar-todo-item-icon {
  color: var(--text-muted);
}

.top-bar-todo-item-delete {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin-left: auto;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.12s ease,
    background 0.12s ease,
    color 0.12s ease;
}

.top-bar-todo-item:hover .top-bar-todo-item-delete {
  opacity: 0.7;
}

.top-bar-todo-item-delete:hover {
  opacity: 1;
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.top-bar-todo-item-delete:disabled {
  opacity: 0.4;
  cursor: default;
}

.top-bar-todo-add-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-top: 1px solid var(--border-color);
}

.top-bar-todo-add-input {
  flex: 1;
  min-width: 0;
  height: 26px;
  padding: 0 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 12px;
  outline: none;
  transition: border-color 0.12s ease;
}

.top-bar-todo-add-input:focus {
  border-color: var(--accent-color);
}

.top-bar-todo-add-input::placeholder {
  color: var(--text-muted);
}

.top-bar-todo-add-input:disabled {
  opacity: 0.5;
  cursor: default;
}

.top-bar-todo-add-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.top-bar-todo-add-btn:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.top-bar-todo-add-btn:disabled {
  cursor: default;
  opacity: 0.4;
}

.top-bar-todo-add-btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 1px;
}

.top-bar-right .panel-tab-group {
  overflow: hidden;
  opacity: 1;
  transition:
    opacity 0.12s ease,
    max-width 0.18s ease;
  max-width: 310px;
}

.app-shell.right-panel-collapsed .right-panel-fullscreen-btn {
  display: none;
}

/* ===== Window Controls (Windows, 嵌入 TopBar 右侧卡片) ===== */
.window-controls-buttons {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 32px;
  -webkit-app-region: no-drag;
}

.window-control-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 46px;
  height: 100%;
  color: var(--text-secondary);
  -webkit-app-region: no-drag;
  transition:
    background 0.1s ease,
    color 0.1s ease;
}

.window-control-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.window-control-btn.close-btn:hover {
  background: #e81123;
  color: #fff;
}

.window-control-btn:active {
  opacity: 0.85;
}

/* ===== Icon Button ===== */
.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  transition:
    background 0.12s,
    color 0.12s;
}

.icon-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.icon-btn.ghost {
  width: 24px;
  height: 24px;
}

/* ===== Sidebar ===== */
.sidebar {
  position: relative;
  z-index: 20;
  width: var(--sidebar-width);
  min-width: var(--sidebar-width);
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-xl);
  background: var(--surface-island-muted);
  box-shadow: var(--island-shadow);
  backdrop-filter: var(--backdrop-blur-lg);
  overflow: hidden;
  user-select: none;
  -webkit-user-select: none;
  transition:
    width 0.18s ease,
    min-width 0.18s ease,
    opacity 0.12s ease;
}
.sidebar.collapsed {
  width: 0;
  min-width: 0;
  opacity: 0;
  pointer-events: none;
}

.sidebar-content-wrapper {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.sidebar-content-wrapper.is-hidden {
  display: none;
}

.sidebar-top {
  padding: 10px 12px 4px;
  flex-shrink: 0;
}

.window-controls {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  height: 28px;
  margin-bottom: 8px;
  padding-left: var(--traffic-light-safe-area);
  -webkit-app-region: drag;
}

.sidebar-action-bar {
  display: flex;
  align-items: center;
  gap: 4px;
  -webkit-app-region: no-drag;
}

.sidebar-toggle-btn,
.new-chat-btn,
.right-panel-toggle-btn,
.right-panel-fullscreen-btn,
.feature-page-close-btn {
  position: relative;
  z-index: 2;
  flex-shrink: 0;
  -webkit-app-region: no-drag;
}

/* ===== TopBar 团队协作区（团队视图专用） ===== */
.top-bar-team-sync,
.top-bar-team-me,
.top-bar-team-edit {
  -webkit-app-region: no-drag;
}

.top-bar-team-sync {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  max-width: 260px;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  font-size: 11.5px;
  white-space: nowrap;
  transition:
    background 0.12s,
    color 0.12s;
}

.top-bar-team-sync:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.top-bar-team-sync.is-error {
  color: var(--accent-red, #e5484d);
}

.top-bar-team-sync-text {
  overflow: hidden;
  text-overflow: ellipsis;
}

.top-bar-team-me {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  padding-left: 10px;
  border-left: 1px solid var(--border-subtle);
}

.top-bar-team-me-name {
  font-size: 12.5px;
  color: var(--text-secondary);
  max-width: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 图钉置顶按钮：与侧栏切换按钮同组（no-drag），激活态与待办面板图钉一致 */
.always-on-top-btn {
  position: relative;
  z-index: 2;
  flex-shrink: 0;
  -webkit-app-region: no-drag;
}

.always-on-top-btn.active {
  color: var(--text-primary);
  background: var(--bg-active);
}

.always-on-top-btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 1px;
}

.sidebar-nav {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.sidebar-content-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  flex-shrink: 0;
}

.sidebar-content-title {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 8px;
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-size: 13px;
  text-align: left;
  transition: background 0.12s;
}

.nav-item:hover {
  background: var(--bg-hover);
}

.nav-item svg {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

/* Sidebar Sections */
.sidebar-section {
  margin-top: 10px;
  padding: 0 4px 0 8px;
  flex-shrink: 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4px;
  margin-bottom: 2px;
}

.section-title {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: capitalize;
  letter-spacing: 0.02em;
}

.section-actions {
  display: flex;
  gap: 2px;
}

.section-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
  padding: 2px 4px;
  margin-left: -4px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  transition:
    background 0.12s,
    color 0.12s;
}

.section-toggle-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.section-toggle-btn svg {
  flex-shrink: 0;
  transition: transform 0.15s ease;
}

.section-toggle-btn .section-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.section-toggle-chevron--open {
  transform: rotate(90deg);
}

.section-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.sidebar-collapse {
  display: grid;
  grid-template-rows: 0fr;
  min-height: 0;
  flex-shrink: 0;
  transition: grid-template-rows 0.24s cubic-bezier(0.33, 0, 0.2, 1);
}

.sidebar-collapse.is-open {
  grid-template-rows: 1fr;
}

.sidebar-collapse-inner {
  min-height: 0;
  /* 必须允许收缩：否则 grid 自动轨道的最小尺寸会按内容的 min-content 计算，
     长标题会把整行撑破并给外层挤出横向滚动条 */
  min-width: 0;
  overflow: hidden;
}

.sidebar-collapse-loading {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 4px 19px;
  padding: 4px 8px;
  border-left: 1px solid var(--border-color);
  font-size: 11.5px;
  color: var(--text-muted);
}

/* 会话拖拽：拖入置顶/普通列表时高亮提示可放置（跟随主题强调色） */
.section-list.chat-drag-over,
.sidebar-section.chat-drag-over .section-list {
  border-radius: var(--radius-md);
  outline: 1px dashed var(--accent-color);
  outline-offset: -1px;
  background: color-mix(in srgb, var(--accent-color) 10%, transparent);
}

.sidebar-section.chat-drag-over .section-header {
  border-radius: var(--radius-md);
  outline: 1px dashed var(--accent-color);
  outline-offset: -1px;
}

/* Chats section: scrollable list with stable scrollbar gutter */
.sidebar-section.chats-section {
  flex: 1;
  min-height: var(--chats-header-h, 26px);
  display: flex;
  flex-direction: column;
  transition: flex-grow 0.24s cubic-bezier(0.33, 0, 0.2, 1);
  user-select: none;
}

.sidebar-section.chats-section .section-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  scrollbar-gutter: stable;
}

/* 运行中会话分组：位于列表最前，随列表滚动 */
.chats-running-group {
  margin-bottom: 4px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
}

.list-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-size: 12.5px;
  text-align: left;
  transition: background 0.12s;
  width: 100%;
}

.list-item:hover {
  background: var(--bg-hover);
}

.list-item.active {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.list-icon {
  color: var(--text-muted);
  flex-shrink: 0;
}

/* 项目列表图标语义配色：SSH=红 / 合集=绿（本地文件夹沿用资源管理器配色） */
.list-icon--ssh {
  color: var(--accent-red-text);
}

.list-icon--collection {
  color: var(--accent-green-text);
}

.list-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.empty-text {
  padding: 6px 8px;
  color: var(--text-muted);
  font-size: 12.5px;
}

.empty-text.loading {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.empty-text.error {
  color: var(--danger, #e5484d);
}

.chat-item {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  width: 100%;
  /* 锁定行高：hover 出现的 22px 操作按钮不再把行撑高 */
  min-height: 30px;
  padding: 4px 4px 4px 6px;
  margin-bottom: 1px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
  /* 背景不做过渡：切换会话时选中态必须立刻变色，0.15s 渐变会被看成"延迟" */
  position: relative;
}
.chat-item:hover,
.chat-item.menu-open {
  background: var(--bg-hover, rgba(255, 255, 255, 0.06));
}
.chat-item.active {
  background: var(--bg-active, rgba(255, 255, 255, 0.05));
}

.chat-item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 1px solid var(--border-color);
  background: var(--bg-tertiary);
  color: var(--text-muted);
  position: relative;
}

.chat-item-icon.attention-required {
  border-color: var(--warning, #f59e0b);
  background: color-mix(
    in srgb,
    var(--warning, #f59e0b) 14%,
    var(--bg-tertiary)
  );
  color: var(--warning, #f59e0b);
}

.chat-item-icon.streaming {
  border-color: var(--accent, #3b82f6);
  color: var(--accent, #3b82f6);
}

.chat-item-icon.completed {
  border-color: var(--accent, #3b82f6);
  background: color-mix(
    in srgb,
    var(--accent, #3b82f6) 12%,
    var(--bg-tertiary)
  );
  color: var(--accent, #3b82f6);
}

.chat-item-kind-icons {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  color: var(--text-muted);
}

.chat-item-kind-icon.workflow {
  color: var(--accent, #3b82f6);
}

.chat-item-kind-icon.sub-agent {
  color: var(--accent-secondary, #8b5cf6);
}

.chat-item-expand-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 14px;
  height: 14px;
  cursor: pointer;
  color: var(--text-muted);
  transition: color 0.12s ease;
}

.chat-item-expand-toggle:hover {
  color: var(--text-primary);
}

.chat-item-expand-toggle svg {
  transition: transform 0.15s ease;
}

.chat-item-expand-toggle svg.expanded {
  transform: rotate(90deg);
}

.sub-agent-list-panel {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0 0 4px 19px;
  padding-left: 3px;
  border-left: 1px solid var(--border-color);
}

.sub-agent-list-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border-radius: var(--radius-sm, 6px);
  cursor: pointer;
  transition: background 0.12s ease;
}

.sub-agent-list-item:hover {
  background: var(--bg-hover);
}

.sub-agent-list-item.active {
  background: var(--bg-active);
}

.sub-agent-list-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-muted);
}

.sub-agent-list-icon svg {
  color: var(--text-muted);
}

.sub-agent-list-item .sub-agent-list-icon svg[stroke="currentColor"] {
  color: var(--text-muted);
}

/* 子代理图标：静态状态用 Bot 图标（与 Workflow 节点的 Workflow 图标区分），
   运行中改用 Loader2 旋转指示器；选择器与灰色兜底规则同优先级且后定义，
   确保状态配色生效 */
.sub-agent-list-item .sub-agent-list-icon svg.sub-agent-status-running {
  color: var(--accent, #3b82f6);
}

.sub-agent-list-item .sub-agent-list-icon svg.sub-agent-status-completed {
  color: var(--accent-green, #22c55e);
}

.sub-agent-list-item .sub-agent-list-icon svg.sub-agent-status-failed {
  color: var(--accent-red-text, #ef4444);
}

.sub-agent-list-item .sub-agent-list-icon svg.sub-agent-status-pending {
  color: var(--text-tertiary);
}

/* 优先级高于 .sub-agent-list-icon svg[stroke="currentColor"] 的灰色覆盖 */
.sub-agent-list-item .sub-agent-list-icon svg.sub-agent-attention {
  color: var(--warning, #f59e0b);
}

.sub-agent-list-name-row {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  flex: 1;
}

.sub-agent-list-name {
  flex: 1;
  min-width: 0;
  font-size: 11.5px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* 子代理类型：摘要之后的次要信息，宽度受限避免挤占摘要 */
.sub-agent-list-agent {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 46%;
  font-size: 10.5px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sub-agent-list-item.active .sub-agent-list-name {
  color: var(--text-primary);
  font-weight: 500;
}

.sub-agent-list-item.active .sub-agent-list-agent {
  color: var(--text-secondary);
}

.chat-item-sub-agent-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 14px;
  height: 14px;
  padding: 0 4px;
  border-radius: 7px;
  background: var(--accent, #3b82f6);
  color: var(--bg-primary, #fff);
  font-size: 9px;
  font-weight: 600;
  line-height: 1;
  flex-shrink: 0;
}
.chat-item-sub-agent-count.attention {
  background: var(--warning, #f59e0b);
}

/* Workflow 节点列表面板：渲染在 ChatItem 外部（兄弟节点），
   从主会话图标中心引出树形轴；节点项内嵌的子代理面板再缩进一层 */
.workflow-node-list-panel {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0 0 4px 19px;
  padding-left: 3px;
  border-left: 1px solid var(--border-color);
}

.workflow-node-list-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  border-radius: var(--radius-sm, 6px);
  cursor: pointer;
  transition: background 0.12s ease;
}

.workflow-node-list-item:hover {
  background: var(--bg-hover);
}

.workflow-node-list-item.active {
  background: var(--bg-active);
}

.workflow-node-expand-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 12px;
  height: 12px;
  cursor: pointer;
  color: var(--text-muted);
  transition: color 0.12s ease;
}

.workflow-node-expand-toggle:hover {
  color: var(--text-primary);
}

.workflow-node-expand-toggle svg {
  transition: transform 0.15s ease;
}

.workflow-node-expand-toggle svg.expanded {
  transform: rotate(90deg);
}

.workflow-node-list-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-muted);
}

.workflow-node-list-icon svg {
  color: var(--text-muted);
}

.workflow-node-list-item .workflow-node-list-icon svg[stroke="currentColor"] {
  color: var(--text-muted);
}

/* 节点图标：静态状态用 Workflow 图标（与子代理的 Bot 图标区分），运行中
   改用 Loader2 旋转指示器；选择器与灰色兜底规则同优先级且后定义，确保生效 */
.workflow-node-list-item
  .workflow-node-list-icon
  svg.workflow-node-status-running {
  color: var(--accent, #3b82f6);
}

.workflow-node-list-item
  .workflow-node-list-icon
  svg.workflow-node-status-completed {
  color: var(--accent-green, #22c55e);
}

.workflow-node-list-item
  .workflow-node-list-icon
  svg.workflow-node-status-failed {
  color: var(--accent-red-text, #ef4444);
}

.workflow-node-list-item
  .workflow-node-list-icon
  svg.workflow-node-status-pending {
  color: var(--text-tertiary);
}

/* 优先级高于灰色覆盖 */
.workflow-node-list-item .workflow-node-list-icon svg.sub-agent-attention {
  color: var(--warning, #f59e0b);
}

.workflow-node-list-name {
  flex: 1;
  min-width: 0;
  font-size: 11.5px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.workflow-node-list-item.active .workflow-node-list-name {
  color: var(--text-primary);
  font-weight: 500;
}

.workflow-node-list-panel .sub-agent-list-panel {
  margin-top: 4px;
  margin-left: 10px;
}

.chat-item-content {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}

.chat-item-title {
  display: flex;
  align-items: center;
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.chat-item-actions-wrapper {
  position: relative;
  flex-shrink: 0;
}

.chat-item-actions {
  display: none;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  border-radius: var(--radius-sm, 6px);
  color: var(--text-muted);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}
.chat-item:hover .chat-item-actions,
.chat-item.menu-open .chat-item-actions {
  display: flex;
}

.chat-item-actions:hover {
  background: var(--bg-active);
  color: var(--text-primary);
}

.chat-item-menu-wrapper {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
}

.chat-item-quick-action {
  display: none;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  border-radius: var(--radius-sm, 6px);
  color: var(--text-muted);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.chat-item:hover .chat-item-quick-action,
.chat-item.menu-open .chat-item-quick-action {
  display: flex;
}

.chat-item-quick-action:hover {
  background: var(--bg-active);
  color: var(--text-primary);
}

/* ============================================================
 * 会话归档（归档冷数据库）
 * ============================================================ */

/* 归档/返回切换按钮：激活态高亮，参考 ProjectsSection 的 Plus 按钮位置 */
.chats-archive-toggle.active {
  background: var(--bg-active);
  color: var(--text-primary);
}

/* 归档会话计数徽标 */
.chats-archive-count {
  margin-left: 4px;
  padding: 0 5px;
  border-radius: 8px;
  background: var(--bg-active);
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 600;
  line-height: 15px;
}

/* ============================================================
 * 会话导入（导出 JSON 迁移）
 * ============================================================ */

/* 导入按钮：导入进行中禁用并显示转圈 */
.chats-import-toggle:disabled {
  cursor: default;
  opacity: 0.7;
}

.chat-import-progress {
  padding: 4px 10px 6px;
  color: var(--text-secondary);
  font-size: 11px;
}

.chat-import-progress-text {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.chat-import-progress-file {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chat-import-progress-track {
  height: 3px;
  border-radius: 2px;
  background: var(--bg-active);
  overflow: hidden;
}

.chat-import-progress-bar {
  height: 100%;
  border-radius: 2px;
  background: var(--accent);
  transition: width 0.15s ease;
}

/* 归档会话条目：不允许直接打开，整体弱化显示 */
.chat-item.archived .chat-item-title {
  color: var(--text-muted);
  font-weight: 400;
}

.chat-item.archived:hover .chat-item-title {
  color: var(--text-secondary);
}

/* 归档条目 hover 操作按钮（还原 / 删除） */
.archived-chat-item-actions {
  display: none;
  align-items: center;
  gap: 1px;
  flex-shrink: 0;
}

.chat-item.archived:hover .archived-chat-item-actions {
  display: inline-flex;
}

.archived-chat-item-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.archived-chat-item-action:hover {
  background: var(--bg-active);
  color: var(--text-primary);
}

.archived-chat-item-action.danger:hover {
  background: rgba(229, 72, 77, 0.1);
  color: var(--danger, #e5484d);
}

/* 归档列表工具栏：提示文案 + 多选入口 */
.archived-chat-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 2px 8px 4px;
  border-bottom: 1px solid var(--border-color);
}

.archived-chat-toolbar-hint {
  flex: 1;
  min-width: 0;
  font-size: 10.5px;
  color: var(--text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.archived-multi-select-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-secondary);
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.archived-multi-select-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* 归档会话搜索框（融合型输入框，!important 抵抗主题通用 input 规则） */
.archived-search-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 4px 6px 5px;
  padding: 0 8px;
  height: 26px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-primary);
  flex-shrink: 0;
}

.archived-search-row:focus-within {
  border-color: var(--accent-color);
}

.archived-search-icon {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.archived-search-input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  outline: none !important;
  color: var(--text-primary);
  font-size: 12px;
  font-family: inherit;
  appearance: none;
}

.archived-search-input::placeholder {
  color: var(--text-muted);
}

.archived-search-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
}

.archived-search-clear:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* ============================================================
 * 会话多选模式（批量删除）
 * ============================================================ */

.section-toggle-btn.danger {
  color: var(--accent-red-text, #ef4444);
}

.section-toggle-btn.danger:hover:not(:disabled) {
  background: color-mix(
    in srgb,
    var(--accent-red-text, #ef4444) 14%,
    transparent
  );
  color: var(--accent-red-text, #ef4444);
}

.section-toggle-btn:disabled {
  opacity: 0.4;
  cursor: default;
}

/* ============================================================
 * 会话/置顶区域收起（与项目区域一致的折叠交互）
 * ============================================================ */

.sidebar-section.chats-section.collapsed {
  flex-grow: 0;
}

.sidebar-section.projects-section {
  transition: flex-grow 0.24s cubic-bezier(0.33, 0, 0.2, 1);
}

.sidebar-section.projects-section.chats-collapsed:not(.collapsed) {
  flex: 1 1 var(--projects-natural-h, auto);
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.sidebar-section.projects-section.chats-collapsed > .sidebar-collapse {
  flex: 1;
  min-height: 0;
}

.sidebar-section.projects-section.chats-collapsed
  > .sidebar-collapse
  > .sidebar-collapse-inner {
  display: flex;
  flex-direction: column;
}

.sidebar-section.projects-section.chats-collapsed .workspace-directory-card {
  flex: 1;
  min-height: 0;
}

.sidebar-section.projects-section.chats-collapsed .workspace-directory-list {
  flex: 1;
  min-height: 0;
  max-height: none;
}

.chat-item-menu {
  position: fixed;
  min-width: 140px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg, 8px);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow, 0 4px 16px rgba(0, 0, 0, 0.12));
  z-index: 9999;
}

.chat-item-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-primary);
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  transition: background 0.1s ease;
}

.chat-item-menu-item:hover {
  background: var(--bg-hover);
}

.chat-item-menu-item.danger {
  color: var(--danger, #e5484d);
}

.chat-item-menu-item.danger:hover {
  background: rgba(229, 72, 77, 0.1);
}
.chat-item-menu-item.active {
  background: var(--bg-hover);
}

.chat-item-menu-sub-arrow {
  margin-left: auto;
  color: var(--text-tertiary, var(--text-secondary));
  flex-shrink: 0;
}

.chat-item-export-panel {
  min-width: 120px;
}

.chat-item-export-panel-header {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 8px;
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-tertiary, var(--text-secondary));
  border-bottom: 1px solid var(--border-subtle, var(--border-light));
  margin-bottom: 2px;
}

.chat-item-export-back-icon {
  flex-shrink: 0;
  color: var(--text-tertiary, var(--text-secondary));
}

.chat-item-export-format-label {
  font-size: 12px;
}

.chat-item-rename-input {
  width: 100%;
  padding: 2px 4px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12.5px;
  font-weight: 500;
  outline: none;
}
.chat-item-rename-input:focus {
  border-color: var(--accent-color);
}

.chat-time-group-header {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  padding: 8px 8px 2px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  user-select: none;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
}

.chat-time-group-header:hover {
  color: var(--text-secondary);
}

.chat-time-group-header > svg {
  flex-shrink: 0;
  transition: transform 0.15s ease;
}

.chat-time-group-chevron--open {
  transform: rotate(90deg);
}

.chat-time-group-count {
  margin-left: auto;
  font-size: 10px;
  font-weight: 500;
  opacity: 0.65;
}

.chat-pinned-group.chat-drag-over {
  border-radius: var(--radius-md);
  outline: 1px dashed var(--accent-color);
  outline-offset: -1px;
  background: color-mix(in srgb, var(--accent-color) 10%, transparent);
}

.chat-item-pin-icon {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  color: var(--accent-color);
}

/* ===== 跨项目通知区块（对话列表顶部） ===== */
.cross-project-notifications {
  margin-bottom: 6px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-color);
}

.cross-project-notifications-header {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  padding: 8px 8px 4px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--warning, #f59e0b);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  user-select: none;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: filter 0.15s ease;
}

.cross-project-notifications-header:hover {
  filter: brightness(1.15);
}

.cross-project-notifications-header > svg {
  flex-shrink: 0;
  transition: transform 0.15s ease;
}

.cross-project-notifications-chevron--open {
  transform: rotate(90deg);
}

.cross-project-notification-group {
  margin-bottom: 2px;
}

.cross-project-notification-project {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 8px 2px 10px;
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 600;
  user-select: none;
}

.cross-project-notification-project > svg {
  flex-shrink: 0;
}

.cross-project-notification-project-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cross-project-notification-project-count {
  margin-left: auto;
  flex-shrink: 0;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: color-mix(
    in srgb,
    var(--warning, #f59e0b) 18%,
    var(--bg-tertiary)
  );
  color: var(--warning, #f59e0b);
  font-size: 10px;
  font-weight: 600;
  line-height: 16px;
  text-align: center;
}

.cross-project-notification-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  margin-bottom: 2px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-primary);
  cursor: pointer;
  transition: background 0.15s ease;
  text-align: left;
}

.cross-project-notification-item:hover {
  background: var(--bg-hover, rgba(255, 255, 255, 0.06));
}

.cross-project-notification-item .chat-item-icon {
  width: 20px;
  height: 20px;
}

.cross-project-notification-item .list-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px;
}

.cross-project-notification-time {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}

/* 多选模式下分组粒度的全选复选框（三态：未选/全选/半选） */
.chat-time-group-select {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  margin-left: 6px;
  border-radius: 4px;
  border: 1.5px solid var(--border-color);
  background: transparent;
  color: var(--on-solid);
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;
}

.chat-time-group-select:hover {
  border-color: var(--accent-color);
}

.chat-time-group-select.checked {
  background: var(--accent-color);
  border-color: var(--accent-color);
}

.chat-time-group-select.indeterminate {
  border-color: var(--accent-color);
  color: var(--accent-color);
}

.chat-time-group-select.indeterminate:hover {
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
}

.chat-item-time {
  flex-shrink: 0;
  font-size: 10.5px;
  color: var(--text-muted);
  white-space: nowrap;
  margin-left: 4px;
}

/* 运行中 loading 占据时间位；圆环不再出现 */
.chat-item-time-loading {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent, #3b82f6);
}

.chat-item-time-loading.paused {
  color: var(--warning, #f59e0b);
}

/* 会话行悬浮详情：锚点铺满整行只提供坐标，不参与交互 */
.chat-item > .tooltip-wrapper:has(.chat-item-tooltip-anchor) {
  position: absolute;
  inset: 0;
  display: block;
  pointer-events: none;
}

.chat-item-tooltip {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: min(220px, 40vw);
}

.chat-item-tooltip-head {
  display: flex;
  align-items: flex-start;
  gap: 6px;
}

/* 标题完整展示：允许换行，不做省略截断 */
.chat-item-tooltip-title {
  flex: 1;
  min-width: 0;
  white-space: normal;
  overflow-wrap: anywhere;
  color: var(--text-primary);
  font-weight: 500;
}

.chat-item-tooltip-pin {
  display: inline-flex;
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--text-tertiary);
}

.chat-item-tooltip-time {
  flex-shrink: 0;
  margin-top: 1px;
  margin-left: auto;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}

.chat-item-tooltip-project {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  color: var(--text-secondary);
}

/* 图标沿用目录列表配色（本地文件夹黄、SSH 红），不在此覆盖 color */
.chat-item-tooltip-project svg {
  flex-shrink: 0;
}

.chat-item-tooltip-project-name {
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* 会话形态标记（Workflow 模式 / 有子代理），配色与列表行类型图标一致 */
.chat-item-tooltip-kinds {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  color: var(--text-secondary);
}

.chat-item-tooltip-kind {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.chat-item-tooltip-kind svg {
  flex-shrink: 0;
}

.chat-item-tooltip-kind.workflow {
  color: var(--accent, #3b82f6);
}

.chat-item-tooltip-kind.sub-agent {
  color: var(--accent-secondary, #8b5cf6);
}

.chat-item-title-row {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.chat-item-status-label {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  height: 15px;
  padding: 0 5px;
  border: 1px solid transparent;
  border-radius: 999px;
  font-size: 9px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

.chat-item-status-label.attention-required {
  border-color: color-mix(in srgb, var(--warning, #f59e0b) 38%, transparent);
  background: color-mix(in srgb, var(--warning, #f59e0b) 14%, transparent);
  color: var(--warning, #f59e0b);
}

.chat-item-status-label.completed {
  border-color: color-mix(in srgb, var(--accent, #3b82f6) 32%, transparent);
  background: color-mix(in srgb, var(--accent, #3b82f6) 12%, transparent);
  color: var(--accent, #3b82f6);
}

.chat-item-pin-badge {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  color: var(--text-tertiary);
}

.chat-item-title-row .chat-item-title {
  flex: 1;
  min-width: 0;
}

.chat-item.has-quick-actions:hover .chat-item-time,
.chat-item.has-quick-actions.menu-open .chat-item-time {
  display: none;
}

.chat-item-title-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.chat-load-more {
  display: flex;
  min-height: 32px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px;
  color: var(--text-muted);
  font-size: 11.5px;
}

.chat-load-more.is-loading {
  color: var(--text-secondary);
}

.chat-load-more svg {
  flex: 0 0 auto;
}

.chat-load-more.is-manual {
  padding: 4px 8px;
}

.chat-load-more-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: 100%;
  padding: 5px 8px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 11.5px;
  cursor: pointer;
  transition: color 0.12s;
}

.chat-load-more-btn:hover:not(:disabled) {
  color: var(--text-primary);
}

.chat-load-more-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

.chat-all-loaded {
  padding: 6px 8px;
  color: var(--text-muted);
  font-size: 11px;
  text-align: center;
  opacity: 0.6;
}

/* ===== Chat multi-select ===== */
.chat-multi-select-bar {
  /* 容器查询：按多选栏自身宽度决定是否显示按钮文字 */
  container-type: inline-size;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  margin-bottom: 2px;
  border-bottom: 1px solid var(--border-color);
}

.chat-multi-select-exit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.chat-multi-select-exit-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.chat-multi-select-exit-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.chat-multi-select-count {
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
}

.chat-multi-select-actions {
  display: flex;
  gap: 2px;
  margin-left: auto;
}

.chat-multi-select-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-secondary);
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.chat-multi-select-action-btn span {
  white-space: nowrap;
}

.chat-multi-select-action-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.chat-multi-select-action-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.chat-multi-select-action-btn.danger {
  color: var(--danger, #e5484d);
}

.chat-multi-select-action-btn.danger:hover {
  background: rgba(229, 72, 77, 0.1);
}

/* 多选栏容器查询：侧边栏可调宽度 180-420px，窄宽度下放不下
   操作按钮的完整文字（含计数约需 400px+），此时隐藏按钮文字、
   只保留图标，hover 由 Tooltip 展示完整文案；宽度充足（≥400px）
   时恢复文字显示并隐藏冗余 Tooltip。
   Electron 37 (Chromium 130+) 支持 @container。 */
@container (max-width: 399px) {
  .chat-multi-select-action-btn {
    flex-shrink: 0;
    padding: 3px 4px;
  }
  .chat-multi-select-action-btn span {
    display: none;
  }
  .chat-multi-select-count {
    flex-shrink: 1;
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

@container (min-width: 400px) {
  /* Tooltip 经 Portal 挂到 body，后代选择器已无法触达；
     改为声明禁用变量，由 Tooltip 在 hover 时读取后不显示。 */
  .chat-multi-select-bar .tooltip-wrapper {
    --tooltip-suppressed: 1;
  }
}

/* 复选框未勾选时边框使用 --text-muted 而非 --border-color：
   选中行背景为 accent 混色（默认主题 accent = text-primary，呈浅/深灰色调），
   与中性的 --border-color 接近，会导致复选框在选中行上几乎不可见 */
.chat-item-checkbox {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 1.5px solid var(--text-muted);
  background: transparent;
  color: var(--on-solid);
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.chat-item-checkbox:hover {
  border-color: var(--accent-color);
}

.chat-item-checkbox.checked {
  background: var(--accent-color);
  /* 边框改用低透明度的 accent 混色，与选中行背景拉开对比，
     保证勾选方块在选中行上轮廓清晰 */
  border-color: color-mix(in srgb, var(--accent-color) 60%, transparent);
}

.chat-item.selected {
  background: color-mix(in srgb, var(--accent-color) 10%, transparent);
}

.chat-item.selected:hover {
  background: color-mix(in srgb, var(--accent-color) 16%, transparent);
}
.workspace-directory-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 6px 4px 2px;
}

.workspace-directory-label {
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-weight: 600;
}

.workspace-directory-list {
  position: relative;
  max-height: 236px;
  overflow-y: auto;
  scrollbar-gutter: stable;
}

.workspace-directory-list-inner {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.workspace-directory-row {
  position: relative;
  border-radius: var(--radius-md);
}

.workspace-directory-row.dragging {
  opacity: 0.55;
}

/* 拖拽排序指示：目标行轻微高亮（区别于拖入合集时的整行 add 高亮） */
.workspace-directory-row.drag-over .list-item {
  background: var(--bg-hover);
}

/* 拖拽排序插入横线：显示在目标行与相邻行的间隙中，指示实际插入位置
   （top=插入目标行之前，bottom=插入目标行之后），颜色跟随主题强调色 */
.workspace-directory-drop-line {
  position: absolute;
  left: 8px;
  right: 8px;
  height: 2px;
  border-radius: 999px;
  background: var(--accent-color);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--bg-primary) 70%, transparent);
  pointer-events: none;
  z-index: 2;
}

.workspace-directory-drop-line.top {
  top: -1px;
}

.workspace-directory-drop-line.bottom {
  bottom: -1px;
}

.workspace-directory-list .list-item {
  position: relative;
  min-height: 28px;
}

.workspace-directory-list .list-item:not(:disabled) {
  cursor: pointer;
}

.workspace-directory-index {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

/* ===== 项目合集（project collections） ===== */

.project-collections {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 0 4px;
}

.project-collection-group.expanded {
  margin-bottom: 2px;
}

.project-collection-row {
  position: relative;
  display: flex;
  align-items: center;
  border-radius: var(--radius-md);
  transition: background 0.12s ease;
}

.project-collection-row:hover {
  background: var(--bg-hover);
}

/* 拖拽中的合集行：半透明提示（与项目行排序一致） */
.project-collection-row.dragging {
  opacity: 0.55;
}

/* 拖拽悬停：整行 add 高亮 + add 光标（copy），区别于项目行间的排序横线 */
.project-collection-row.drag-over {
  background: var(--bg-hover);
  box-shadow: inset 0 0 0 1px var(--accent);
  cursor: copy;
}

.project-collection-toggle {
  display: flex;
  flex: 1;
  align-items: center;
  gap: 6px;
  min-width: 0;
  min-height: 28px;
  padding: 0 4px;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-primary);
  font-size: 12.5px;
  text-align: left;
  cursor: pointer;
}

.project-collection-toggle:disabled {
  cursor: default;
}

.project-collection-toggle .list-icon {
  flex-shrink: 0;
}

.project-collection-toggle .list-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-collection-toggle svg {
  flex-shrink: 0;
  transition: transform 0.15s ease;
}

.project-collection-chevron--open {
  transform: rotate(90deg);
}

.project-collection-badge {
  flex-shrink: 0;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--bg-active);
  color: var(--text-tertiary);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  line-height: 16px;
  text-align: center;
}

.project-collection-actions {
  display: none;
  flex-shrink: 0;
  align-items: center;
  gap: 2px;
  padding-right: 4px;
}

.project-collection-row:hover .project-collection-actions,
.project-collection-row:focus-within .project-collection-actions {
  display: flex;
}

.project-collection-delete-btn:hover:not(:disabled) {
  background: var(--accent-red-bg);
  color: var(--accent-red);
}

/* 合集成员项目列表：缩进 */
.project-collection-members {
  display: flex;
  flex-direction: column;
  position: relative;
}

.project-collection-empty {
  padding: 4px 8px 6px 18px;
  color: var(--text-tertiary);
  font-size: 11px;
}

.project-collection-dot,
.workspace-directory-collection-dot {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--text-primary) 14%, transparent);
}

/* 项目条目通知徽标：该项目的跨项目通知会话数 */
.workspace-directory-notification-badge {
  flex-shrink: 0;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: color-mix(
    in srgb,
    var(--warning, #f59e0b) 18%,
    var(--bg-tertiary)
  );
  color: var(--warning, #f59e0b);
  font-size: 10px;
  font-weight: 600;
  line-height: 16px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}

/* SSH 连接状态徽标：状态点 + 本地化文案（项目列表 / 树视图共用） */
.workspace-directory-ssh-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  max-width: 112px;
  height: 16px;
  padding: 0 6px;
  border-radius: 8px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10px;
  line-height: 16px;
  white-space: nowrap;
}

.workspace-directory-ssh-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

.workspace-directory-ssh-label {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
}

.workspace-directory-ssh-badge.connected {
  color: var(--accent-green);
  background: color-mix(in srgb, var(--accent-green) 14%, transparent);
}

.workspace-directory-ssh-badge.connecting,
.workspace-directory-ssh-badge.reconnecting,
.workspace-directory-ssh-badge.degraded {
  color: var(--accent-amber-text, #b45309);
  background: color-mix(
    in srgb,
    var(--accent-amber-text, #b45309) 14%,
    transparent
  );
}

.workspace-directory-ssh-badge.connecting .workspace-directory-ssh-dot,
.workspace-directory-ssh-badge.reconnecting .workspace-directory-ssh-dot {
  animation: ssh-connection-pulse 1.2s ease-in-out infinite;
}

.workspace-directory-ssh-badge.offline,
.workspace-directory-ssh-badge.auth_required,
.workspace-directory-ssh-badge.host_key_changed {
  color: var(--accent-red);
  background: color-mix(in srgb, var(--accent-red) 14%, transparent);
}

@keyframes ssh-connection-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

/* SSH 项目未连接：新建会话入口被拦下（点击 = 显式重连） */
.sidebar-new-chat-btn[aria-disabled="true"],
.new-chat-btn[aria-disabled="true"] {
  opacity: 0.55;
}

/* 带 SSH 连接徽标的行：只在悬停/菜单打开时左移让位，给悬浮 ⋯ 按钮腾出槽位
   （22px 按钮 + 右侧 4px + 间隙），平时徽标保持贴右 */
.workspace-directory-row:has(.workspace-directory-ssh-badge):is(
    :hover,
    .menu-open
  )
  .list-item,
.tree-project-row-wrap:has(.workspace-directory-ssh-badge):is(
    :hover,
    .menu-open
  )
  .tree-project-row {
  padding-right: 30px;
}

.workspace-directory-load-more,
.workspace-directory-end-line {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 24px;
  padding: 4px 6px;
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.workspace-directory-load-more::before,
.workspace-directory-end-line::before,
.workspace-directory-load-more::after,
.workspace-directory-end-line::after {
  height: 1px;
  flex: 1;
  background: var(--border-color);
  content: "";
  opacity: 0.75;
}

.workspace-directory-list .list-item:disabled {
  cursor: default;
}

.workspace-directory-list .list-item:disabled:not(.active) {
  opacity: 0.68;
}

.form-dialog-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(2px);
}

.form-dialog-card {
  display: flex;
  width: 440px;
  max-width: 100%;
  max-height: 80vh;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  outline: none;
  background: var(--bg-primary);
  box-shadow: var(--shadow-xl);
}

.form-dialog-header {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px 12px;
}

.form-dialog-title {
  margin: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 15px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.form-dialog-close {
  flex-shrink: 0;
}

.form-dialog-body {
  display: flex;
  min-height: 0;
  flex-direction: column;
  gap: 14px;
  padding: 8px 18px 18px;
  overflow-y: auto;
}

.form-dialog-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.form-dialog-label {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 500;
}

.form-dialog-input-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* 行内输入框与按钮统一高度，避免上下边框错位 */
.form-dialog-input-row .form-dialog-input {
  height: 34px;
  padding: 0 10px;
}

.form-dialog-input {
  width: 100%;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  outline: none;
  background: var(--bg-secondary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  transition:
    border-color 0.12s,
    box-shadow 0.12s;
}

.form-dialog-input:focus {
  border-color: var(--accent-color);
}

.form-dialog-input:disabled,
.form-dialog-input[readonly] {
  color: var(--text-secondary);
}

.form-dialog-input[readonly] {
  cursor: default;
}

.form-dialog-input[readonly]:focus,
.form-dialog-input[readonly]:focus-visible {
  border-color: var(--border-color);
  outline: none;
  box-shadow: none;
}

.form-dialog-description {
  margin: 0;
  color: var(--text-tertiary);
  font-size: 11.5px;
  line-height: 1.5;
}

.form-dialog-error {
  color: var(--danger-color, #ef4444);
  font-size: 11.5px;
}

.collection-color-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.collection-color-swatch {
  width: 22px;
  height: 22px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 50%;
  cursor: pointer;
  transition:
    transform 0.12s ease,
    border-color 0.12s ease;
}

.collection-color-swatch:hover:not(:disabled) {
  transform: scale(1.08);
}

.collection-color-swatch.selected {
  border-color: var(--text-primary);
}

.collection-color-custom {
  position: relative;
  display: inline-flex;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  margin-left: 4px;
  border: 2px solid transparent;
  border-radius: 50%;
  color: #fff;
  cursor: pointer;
  background: conic-gradient(
    from 180deg,
    #f87171,
    #fbbf24,
    #34d399,
    #38bdf8,
    #a78bfa,
    #f472b6,
    #f87171
  );
  transition:
    transform 0.12s ease,
    border-color 0.12s ease;
}

.collection-color-custom:hover {
  transform: scale(1.08);
}

.collection-color-custom.selected {
  border-color: var(--text-primary);
}

.collection-color-custom input[type="color"] {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  border: none;
  opacity: 0;
  cursor: pointer;
}

.collection-color-custom svg {
  filter: drop-shadow(0 0 1px rgba(0, 0, 0, 0.55));
  pointer-events: none;
}

.link-projects-list {
  display: flex;
  max-height: 220px;
  flex-direction: column;
  gap: 2px;
  padding: 2px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-secondary);
  overflow-y: auto;
}

.link-projects-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: var(--radius-sm, 6px);
  cursor: pointer;
}

.link-projects-item:hover {
  background: var(--bg-hover);
}

.link-projects-item input {
  flex-shrink: 0;
  accent-color: var(--accent-color);
}

.link-projects-item-text {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.link-projects-item-name {
  color: var(--text-primary);
  font-size: 12px;
}

.link-projects-item-path {
  overflow: hidden;
  color: var(--text-tertiary);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.link-projects-empty {
  color: var(--text-tertiary);
  font-size: 11.5px;
}

/* git clone 实时进度行：单行截断 + 等宽数字感，避免长进度行撑开对话框 */
.clone-progress-text {
  display: block;
  overflow: hidden;
  color: var(--text-tertiary);
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Mono",
    Consolas,
    monospace
  );
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 克隆进度：百分比进度条 + 当前 git 进度行（弹窗内展示） */
.clone-progress {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.clone-progress-track {
  height: 4px;
  overflow: hidden;
  border-radius: var(--radius-pill, 999px);
  background: var(--bg-tertiary);
}

.clone-progress-fill {
  height: 100%;
  border-radius: inherit;
  background: var(--text-primary);
  transition: width 0.2s ease;
}

.clone-progress-status {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  color: var(--text-tertiary);
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Mono",
    Consolas,
    monospace
  );
  font-size: 11px;
}

.clone-progress-message {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.form-dialog-footer {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding: 12px 18px 16px;
  border-top: 1px solid var(--border-color);
}

.form-dialog-button {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm, 6px);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.12s,
    border-color 0.12s,
    opacity 0.12s;
}

.form-dialog-button.cancel {
  border-color: var(--border-color);
  background: var(--bg-secondary);
  color: var(--text-secondary);
}

.form-dialog-button.cancel:hover:not(:disabled) {
  background: var(--bg-hover);
}

/* 危险类操作（如「中止克隆」）：红调描边按钮，与常规取消区分 */
.form-dialog-button.abort {
  border-color: color-mix(in srgb, var(--accent-red) 45%, transparent);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.form-dialog-button.abort:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-red) 26%, transparent);
}

.form-dialog-button.confirm {
  background: var(--text-primary);
  color: var(--on-solid);
}

.form-dialog-button.confirm:hover:not(:disabled) {
  opacity: 0.88;
}

.form-dialog-button:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.form-dialog-button.confirm:disabled {
  background: var(--bg-tertiary);
  color: var(--text-muted);
  border-color: transparent;
  opacity: 0.6;
}

.form-dialog-spinner {
  width: 12px;
  height: 12px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

.form-dialog-browse-button {
  height: 34px;
  flex-shrink: 0;
  white-space: nowrap;
}

.form-dialog-drop-zone {
  display: flex;
  min-height: 112px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  padding: 18px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  text-align: center;
  transition:
    border-color 0.15s,
    background 0.15s,
    color 0.15s;
}

.form-dialog-drop-zone > strong {
  color: var(--text-secondary);
  font-size: 12.5px;
  font-weight: 600;
}

.form-dialog-drop-zone > span {
  font-size: 11px;
}

.form-dialog-drop-zone.drag-over {
  border-color: var(--text-muted);
  background: var(--bg-hover);
  color: var(--text-primary);
  box-shadow: inset 0 0 0 1px var(--focus-ring);
}

.project-action-grid {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.project-action-card {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 10px;
  padding: 7px 10px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
  transition: background 0.12s;
}

.project-action-card:hover {
  background: var(--bg-hover);
}

.project-action-card:focus-visible {
  outline: none;
  background: var(--bg-hover);
  box-shadow: inset 0 0 0 1px var(--focus-ring);
}

.project-action-card-icon {
  display: flex;
  width: 26px;
  height: 26px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: color 0.12s;
}

.project-action-card:hover .project-action-card-icon,
.project-action-card:focus-visible .project-action-card-icon {
  color: var(--text-secondary);
}

.project-action-card-content {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.project-action-card-content strong {
  font-size: 12.5px;
  font-weight: 500;
}

.project-action-card-content span {
  color: var(--text-tertiary);
  font-size: 11.5px;
  line-height: 1.4;
}

/* 合集与目录入口之间分组分隔 */
.project-action-separator {
  height: 1px;
  margin: 4px 10px;
  background: var(--border-light);
}

/* ===== 项目网格视图对话框（项目多时的全量浏览入口） ===== */

.form-dialog-card.project-grid-dialog-card {
  width: min(960px, calc(100vw - 48px));
  height: min(72vh, 640px);
}

.project-grid-dialog-card .form-dialog-body {
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.project-grid-dialog {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: 10px;
}

.project-grid-search {
  display: flex;
  height: 34px;
  flex-shrink: 0;
  align-items: center;
  gap: 8px;
  padding: 0 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  transition: border-color 0.12s;
}

.project-grid-search:focus-within {
  border-color: var(--accent-color);
}

.project-grid-search .project-grid-search-icon {
  flex-shrink: 0;
}

/* 融合型搜索框：容器提供边框背景，内部 input 需抵抗主题预设的通用 input 规则 */
.project-grid-search input {
  flex: 1;
  min-width: 0;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.project-grid-search input::placeholder {
  color: var(--text-tertiary);
}

.project-grid-search-clear {
  display: inline-flex;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
}

.project-grid-search-clear:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.project-grid-scroll {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: 18px;
  overflow-y: auto;
  padding: 6px;
  isolation: isolate;
  scrollbar-gutter: stable;
}

.project-grid-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.project-grid-group.drag-over {
  position: relative;
  z-index: 1;
  border-radius: var(--radius-md);
  cursor: copy;
  outline: 1px dashed var(--accent-color);
  outline-offset: 4px;
}

.project-grid-group.drop-out-target {
  position: relative;
  z-index: 1;
  border-radius: var(--radius-md);
  outline: 1px dashed color-mix(in srgb, var(--text-tertiary) 45%, transparent);
  outline-offset: 4px;
}

.project-grid-drop-hint {
  padding: 8px 10px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-tertiary);
  font-size: 11px;
}

.project-grid-group-header {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 600;
}

.project-grid-group-header svg {
  flex-shrink: 0;
}

.project-grid-group-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-grid-group-count {
  min-width: 16px;
  height: 16px;
  flex-shrink: 0;
  padding: 0 4px;
  border-radius: 999px;
  background: var(--bg-active);
  color: var(--text-tertiary);
  font-size: 10px;
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  line-height: 16px;
  text-align: center;
}

.project-grid-cards {
  display: grid;
  gap: 6px;
  grid-template-columns: repeat(auto-fill, minmax(210px, 1fr));
}

.project-grid-card {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
  transition:
    background 0.12s,
    border-color 0.12s;
}

.project-grid-card-slot {
  display: flex;
  min-width: 0;
}

.project-grid-card-slot .project-grid-card {
  flex: 1;
  min-width: 0;
}

.project-grid-card-slot.dragging {
  opacity: 0.55;
}

.project-grid-card-slot.drag-over .project-grid-card {
  border-color: color-mix(in srgb, var(--accent-color) 45%, transparent);
  background: var(--bg-hover);
}

.project-grid-card-grip {
  display: inline-flex;
  width: 14px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  color: var(--text-tertiary);
  cursor: grab;
  opacity: 0;
  transition: opacity 0.12s ease;
}

.project-grid-card:hover .project-grid-card-grip,
.project-grid-card-slot.dragging .project-grid-card-grip {
  opacity: 1;
}

.project-grid-card-grip svg {
  pointer-events: none;
}

.project-grid-card:hover:not(:disabled) {
  background: var(--bg-hover);
}

.project-grid-card:disabled {
  cursor: default;
  opacity: 0.6;
}

.project-grid-card.active {
  border-color: color-mix(in srgb, var(--accent-color) 45%, transparent);
  background: color-mix(in srgb, var(--accent-color) 10%, transparent);
}

.project-grid-card.unlinked {
  border-style: dashed;
}

.project-grid-card.unlinked .project-grid-card-name {
  color: var(--text-secondary);
}

.project-grid-card-unlinked-mark {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  color: var(--text-tertiary);
}

.project-grid-card-icon {
  display: inline-flex;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
}

.project-grid-card-body {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

.project-grid-card-name {
  overflow: hidden;
  font-size: 12.5px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-grid-card-path {
  overflow: hidden;
  color: var(--text-tertiary);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.project-grid-card-check {
  flex-shrink: 0;
  color: var(--accent-color);
}

.project-grid-empty {
  display: flex;
  flex: 1;
  align-items: center;
  justify-content: center;
  padding: 32px 0;
  color: var(--text-tertiary);
  font-size: 12px;
}

/* 目录行内重命名输入框：仿会话重命名输入框的紧凑样式 */
.workspace-directory-rename-input {
  flex: 1;
  min-width: 0;
  padding: 2px 4px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 500;
  outline: none;
}

.workspace-directory-rename-input:focus {
  border-color: var(--accent-color);
}

.workspace-directory-row.editing {
  cursor: default;
}

.workspace-directory-actions-wrapper {
  position: absolute;
  right: 4px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 5;
}

.workspace-directory-actions {
  display: none;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 22px;
  height: 22px;
  border-radius: var(--radius-sm, 6px);
  color: var(--text-muted);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.workspace-directory-row:hover .workspace-directory-actions,
.workspace-directory-row.menu-open .workspace-directory-actions {
  display: flex;
  color: var(--text-secondary);
}

.workspace-directory-actions:hover {
  background: var(--bg-active);
  color: var(--text-primary);
}
.workspace-directory-row:hover .list-item:not(.active),
.workspace-directory-row.menu-open .list-item:not(.active) {
  background: var(--bg-hover);
}

.workspace-directory-menu {
  position: fixed;
  min-width: 140px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg, 8px);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow, 0 4px 16px rgba(0, 0, 0, 0.12));
  z-index: 9999;
}

.workspace-directory-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-primary);
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  transition: background 0.1s ease;
}

.workspace-directory-menu-item:hover {
  background: var(--bg-hover);
}

.workspace-directory-menu-item.danger {
  color: var(--danger, #e5484d);
}

.workspace-directory-menu-item.danger:hover {
  background: rgba(229, 72, 77, 0.1);
}

.workspace-directory-menu-item-chevron {
  flex-shrink: 0;
  margin-left: auto;
  color: var(--text-secondary, var(--text-primary));
}

/* 真实 IDE 图标（内联 SVG）在 flex 菜单项中保持尺寸不被压缩 */
.ide-icon {
  flex-shrink: 0;
}

.workspace-directory-menu-submenu-trigger {
  position: relative;
  display: block;
}

.workspace-directory-menu-submenu {
  min-width: 180px;
  max-height: 320px;
  overflow-y: auto;
}

.workspace-directory-menu-submenu-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  color: var(--text-secondary, var(--text-primary));
  font-size: 11.5px;
}

.workspace-directory-menu-submenu-status.error {
  color: var(--danger, #e5484d);
}

.workspace-directory-menu-confirm {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 8px;
}

.workspace-directory-menu-confirm-icon {
  flex-shrink: 0;
  color: var(--danger, #e5484d);
  margin-top: 1px;
}

.workspace-directory-menu-confirm-text {
  font-size: 11.5px;
  color: var(--text-secondary, var(--text-primary));
  line-height: 1.4;
}

.workspace-directory-menu-confirm-actions {
  display: flex;
  gap: 4px;
  padding: 0 4px 4px;
}

.workspace-directory-menu-confirm-btn {
  flex: 1;
  padding: 5px 8px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  font-size: 11.5px;
  cursor: pointer;
  transition: background 0.1s ease;
}

.workspace-directory-menu-confirm-btn.cancel {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.workspace-directory-menu-confirm-btn.cancel:hover {
  background: var(--bg-hover);
}

.workspace-directory-menu-confirm-btn.delete {
  background: var(--danger, #e5484d);
  color: #fff;
}

.workspace-directory-menu-confirm-btn.delete:hover {
  opacity: 0.88;
}
.workspace-directory-ssh-form input {
  width: 100%;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.workspace-directory-ssh-form input:focus {
  border-color: var(--accent-color);
}

.workspace-directory-ssh-form input:disabled,
.workspace-directory-icon-btn:disabled {
  cursor: default;
  opacity: 0.68;
}

.workspace-directory-ssh-form {
  display: flex;
  align-items: center;
  gap: 6px;
}

.workspace-directory-ssh-actions {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 4px;
}

.workspace-directory-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  transition:
    background 0.12s,
    color 0.12s;
}

.workspace-directory-icon-btn:not(:disabled):hover {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.workspace-directory-error {
  color: var(--accent-red);
  font-size: 11.5px;
  line-height: 1.35;
}

/* 克隆占位条目：弹窗关闭后仍在后台进行的克隆（以及失败待处理的克隆）
   在项目列表下方占一行 —— 进行中显示 spinner + 百分比与中止入口，
   失败时显示原因与移除入口。 */
.clone-task-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0;
  padding: 0 2px 0 10px;
  list-style: none;
}

.clone-task-row {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  padding: 5px 6px 5px 8px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.clone-task-row.is-failed {
  border-color: color-mix(in srgb, var(--accent-red) 42%, transparent);
  background: var(--accent-red-bg);
}

.clone-task-icon {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.clone-task-row.is-failed .clone-task-icon {
  color: var(--accent-red);
}

.clone-task-body {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

.clone-task-name {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.clone-task-status {
  overflow: hidden;
  color: var(--text-tertiary);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.clone-task-row.is-failed .clone-task-status {
  color: var(--accent-red-text);
}

.clone-task-action {
  display: inline-flex;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.clone-task-action:not(:disabled):hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.clone-task-row.is-failed .clone-task-action:not(:disabled):hover {
  background: color-mix(in srgb, var(--accent-red) 22%, transparent);
  color: var(--accent-red-text);
}

.clone-task-action:disabled {
  cursor: default;
  opacity: 0.55;
}

/* 路径健康徽标：仅磁盘校验失败时显示，hover 提示原位置 */
.workspace-directory-path-badge {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border-radius: 4px;
  background: color-mix(
    in srgb,
    var(--warning, #f59e0b) 18%,
    var(--bg-tertiary)
  );
  color: var(--warning, #f59e0b);
}

.workspace-directory-path-badge.missing {
  background: color-mix(
    in srgb,
    var(--accent-red, #ef4444) 16%,
    var(--bg-tertiary)
  );
  color: var(--accent-red, #ef4444);
}

.relink-directory-path,
.relink-directory-preview {
  display: block;
  word-break: break-all;
}

.relink-directory-status {
  display: flex;
  align-items: center;
  gap: 6px;
}

/* 迁移记录列表 */
.relink-history-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 260px;
  overflow-y: auto;
}

.relink-history-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  background: var(--bg-tertiary);
  font-size: 11.5px;
}

.relink-history-item-head {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
}

.relink-history-item-time {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.relink-history-item-action {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  padding: 0;
  border: none;
  background: none;
  color: var(--accent-blue, #3b82f6);
  cursor: pointer;
  font-size: 11.5px;
}

.relink-history-item-undone {
  flex-shrink: 0;
  color: var(--text-secondary);
}

.relink-history-item-paths {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--text-primary);
}

.relink-history-item-path {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  word-break: break-all;
}

/* ===== Project Explorer ===== */

.explorer-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  flex-shrink: 0;
}

.explorer-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px 0;
  flex-shrink: 0;
}

.explorer-toolbar .explorer-search-bar {
  flex: 1;
  min-width: 0;
}

.explorer-title {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
}

.explorer-placement-btn {
  margin-left: auto;
}

.explorer-placement-btn,
.explorer-refresh-btn {
  flex-shrink: 0;
}

.explorer-content {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 4px 4px 2px;
}

.explorer-root-info {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  flex-shrink: 0;
}

.explorer-root-info svg {
  color: var(--text-muted);
  flex-shrink: 0;
}

.explorer-root-name {
  flex-shrink: 0;
}

.explorer-entry-context-menu-heading {
  padding: 6px 10px 4px;
  color: var(--text-tertiary);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.explorer-root-path {
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-weight: 400;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
  opacity: 0.7;
}

.explorer-error {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--accent-red);
  font-size: 11.5px;
  line-height: 1.35;
  padding: 4px 8px;
}

.explorer-error.stale {
  color: var(--accent-amber-text, #b45309);
}

.explorer-connection-status-dot {
  margin-left: auto;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--text-muted);
}

.explorer-connection-status-dot.connected {
  background: var(--accent-green);
}

.explorer-connection-status-dot.reconnecting,
.explorer-connection-status-dot.degraded {
  background: var(--accent-amber-text, #b45309);
}

.explorer-connection-status-dot.offline,
.explorer-connection-status-dot.auth_required,
.explorer-connection-status-dot.host_key_changed {
  background: var(--accent-red);
}

.explorer-tree {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
  /* 顶部不留 padding：否则吸顶悬浮层与其下方滚动内容之间会露出细缝 */
  padding: 0 0 2px;
}

.explorer-tree:focus {
  outline: none;
}

.explorer-tree-row {
  display: flex;
  align-items: center;
  gap: 3px;
  height: 24px;
  padding: 0 6px 0 8px;
  cursor: pointer;
  user-select: none;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 12.5px;
  position: relative;
  white-space: nowrap;
}

.explorer-tree-row:hover {
  background: var(--bg-hover);
}

.explorer-tree-row.selected {
  color: var(--text-primary);
}

/* 选中背景仅在列表获得焦点时显示，失焦后只保留文字颜色区分当前选中项 */
.explorer-tree:focus-within .explorer-tree-row.selected {
  background: var(--bg-active);
}

.explorer-tree-row.stale .tree-icon,
.explorer-tree-error {
  color: var(--accent-amber-text, #b45309);
}

.explorer-tree-error {
  flex-shrink: 0;
  margin-left: 4px;
}

.explorer-tree-chevron {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: var(--text-muted);
}

.explorer-tree-row:hover .explorer-tree-chevron {
  color: var(--text-secondary);
}

.tree-icon {
  flex-shrink: 0;
  color: var(--text-muted);
}

.explorer-tree-row.selected .tree-icon {
  color: var(--text-secondary);
}

.explorer-tree-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.explorer-tree-size {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10px;
  opacity: 0.6;
  margin-left: 4px;
}

.explorer-tree-loading {
  flex-shrink: 0;
  margin-left: 4px;
  color: var(--text-muted);
}
.explorer-tree-row:not(:hover) .explorer-tree-size,
.explorer-tree-row:not(:hover) .explorer-tree-loading {
  opacity: 0;
}

/* 已展开的目录行：在自己所在的层级位置吸顶（top / z-index 由行内联按层级给出，
   越浅的层 z-index 越高，被顶出的深层行才会从上层下面滑过）。
   上级吸顶行构成整体后，下一层滚到它的层级位置即被接入，子树滚完又自动被顶出。 */
.explorer-tree-row--sticky {
  position: sticky;
}

/* 铺底用直角矩形：行的圆角在吸顶时会露出下方滚动内容。
   颜色跟随所在面板的底色（面板 = 半透明 island 叠在 --app-bg 上），不要色差块 */
.explorer-tree-row--sticky::before {
  position: absolute;
  inset: 0;
  z-index: -1;
  background-color: var(--app-bg);
  content: "";
}

.sidebar .explorer-tree-row--sticky::before {
  background-image: linear-gradient(
    var(--surface-island-muted),
    var(--surface-island-muted)
  );
}

.right-panel .explorer-tree-row--sticky::before {
  background-image: linear-gradient(
    var(--surface-island),
    var(--surface-island)
  );
}

/* ===== Explorer Search ===== */

.explorer-search-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 5px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  color: var(--text-muted);
  flex-shrink: 0;
}

.explorer-search-bar:focus-within {
  border-color: var(--accent-color);
}

.explorer-search-bar input {
  width: 100%;
  min-width: 0;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.explorer-search-bar input::placeholder {
  color: var(--text-muted);
}

.explorer-search-clear {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  flex-shrink: 0;
  padding: 0;
}

.explorer-search-clear:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.explorer-search-count {
  display: block;
  padding: 2px 8px;
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-weight: 500;
  flex-shrink: 0;
}

.explorer-search-result {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  padding: 4px 8px;
  cursor: pointer;
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  font-size: 12.5px;
}

.explorer-search-result:hover {
  background: var(--bg-hover);
}

.explorer-search-result .tree-icon {
  margin-top: 1px;
  flex-shrink: 0;
}

.explorer-search-result-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.explorer-search-result-name {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.explorer-search-result-path {
  font-size: 10.5px;
  color: var(--text-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.explorer-search-result-line {
  display: flex;
  align-items: baseline;
  gap: 4px;
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 1px 4px;
  margin-left: -4px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  user-select: none;
}

.explorer-search-result-line:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.explorer-search-result-line.is-selected {
  background: color-mix(in srgb, var(--accent-color, #4f8cff) 22%, transparent);
  color: var(--text-primary);
}

.explorer-search-result-line.is-selected .explorer-search-line-number {
  color: var(--accent-color, #4f8cff);
}

.explorer-search-line-number {
  color: var(--text-tertiary);
  font-size: 10px;
  font-weight: 600;
  flex-shrink: 0;
  min-width: 18px;
}

.explorer-entry-context-menu {
  position: fixed;
  z-index: 9999;
  width: 208px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow);
}

.explorer-entry-context-menu-item {
  display: flex;
  align-items: center;
  gap: 7px;
  width: 100%;
  padding: 7px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  text-align: left;
}

.explorer-entry-context-menu-item:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.explorer-entry-context-menu-item.danger,
.explorer-entry-context-menu-actions .danger {
  color: var(--accent-red);
}

.explorer-entry-context-menu-form,
.explorer-entry-context-menu-confirm {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 5px;
}

.explorer-entry-context-menu-form label,
.explorer-entry-context-menu-confirm-message {
  color: var(--text-secondary);
  font-size: 11.5px;
}

.explorer-entry-context-menu-confirm-message {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  line-height: 1.4;
}

.explorer-entry-context-menu-confirm-message svg {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--accent-red);
}

.explorer-entry-context-menu-form input {
  width: 100%;
  padding: 6px 7px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.explorer-entry-context-menu-form input:focus {
  border-color: var(--accent-color);
}

.explorer-entry-context-menu-actions {
  display: flex;
  justify-content: flex-end;
  gap: 5px;
}

.explorer-entry-context-menu-actions button {
  padding: 4px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--bg-hover);
  color: var(--text-secondary);
  cursor: pointer;
  font: inherit;
  font-size: 11px;
}

.explorer-entry-context-menu-actions button:hover:not(:disabled) {
  background: var(--bg-active);
  color: var(--text-primary);
}

.explorer-entry-context-menu-actions button:disabled {
  cursor: wait;
  opacity: 0.55;
}

/* 右键菜单项之间的分隔线 */
.explorer-entry-context-menu-separator {
  height: 1px;
  margin: 4px 6px;
  background: var(--border-light);
}

/* 「打开方式」触发项的右侧箭头 */
.explorer-entry-context-menu-item-chevron {
  flex-shrink: 0;
  margin-left: auto;
  color: var(--text-secondary);
}

.explorer-entry-context-menu-submenu-trigger {
  position: relative;
  display: block;
}

/* 打开方式二级菜单：宽度自适应（主菜单固定 208px），IDE 较多时可滚动 */
.explorer-entry-context-menu-submenu {
  width: auto;
  min-width: 180px;
  max-height: 320px;
  overflow-y: auto;
}

.explorer-entry-context-menu-submenu-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  color: var(--text-secondary);
  font-size: 11.5px;
}

.explorer-entry-context-menu-submenu-status.error {
  color: var(--accent-red);
}

/* 菜单内操作失败提示（如使用系统默认应用打开失败） */
.explorer-entry-context-menu-status {
  padding: 6px 8px;
  color: var(--accent-red);
  font-size: 11.5px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.settings-content {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding-bottom: 8px;
}

.settings-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.settings-item {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 7px 8px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  text-align: left;
  transition:
    background 0.12s,
    border-color 0.12s;
}

.settings-item:hover {
  background: var(--bg-hover);
}

.settings-item.active {
  border-color: var(--border-color);
  background: var(--bg-hover);
}

.settings-item.active .settings-item-title {
  color: var(--text-primary);
}

.settings-item-content {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.settings-item-title {
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 500;
}

.settings-item-description {
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.35;
}

.settings-item-icon {
  color: var(--text-muted);
  flex-shrink: 0;
  margin-top: 1px;
}

.settings-search-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  margin: 5px 8px 6px;
  padding: 5px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  transition:
    border-color 0.12s,
    box-shadow 0.12s;
}

.settings-search-bar:focus-within {
  border-color: var(--accent-color);
}

.settings-search-icon {
  flex-shrink: 0;
  color: var(--text-muted);
}

.settings-search-input {
  flex: 1;
  min-width: 0;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--text-primary);
  font-size: 13px;
  outline: none !important;
}

.settings-search-input::placeholder {
  color: var(--text-muted);
}

.settings-search-clear {
  flex-shrink: 0;
}

.settings-search-results {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 8px;
  min-height: 0;
  overflow-y: auto;
  padding: 0 8px 10px;
}

.settings-search-group-title {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 2px 4px 4px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-align: left;
  text-transform: uppercase;
  transition: color 0.12s;
}

.settings-search-group-title:hover {
  color: var(--text-secondary);
}

.settings-search-group-title span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-search-result {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  text-align: left;
  transition:
    background 0.12s,
    border-color 0.12s;
}

.settings-search-result:hover {
  background: var(--bg-hover);
}

.settings-search-result.active {
  border-color: var(--border-color);
  background: var(--bg-active);
}

.settings-search-result-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-muted);
}

.settings-search-result-body {
  display: flex;
  flex: 1;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.settings-search-result-title {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-search-result.active .settings-search-result-title {
  color: var(--text-primary);
}

.settings-search-result-path {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 11.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-search-empty {
  padding: 18px 8px;
  color: var(--text-muted);
  font-size: 12.5px;
  text-align: center;
}

.settings-search-flash {
  animation: settings-search-flash 1.6s ease-out;
}

@keyframes settings-search-flash {
  0%,
  40% {
    background-color: var(--bg-active);
    box-shadow: 0 0 0 2px var(--focus-ring);
  }

  100% {
    background-color: transparent;
    box-shadow: none;
  }
}

.settings-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 7px 8px;
}

.remote-master-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  max-width: 820px;
  margin: 0 20px 18px;
}

.remote-master-toggle strong {
  display: block;
  color: var(--text-primary);
  font-size: 13px;
}

.remote-master-toggle p {
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.import-settings-tabs.remote-settings-tabs {
  max-width: 820px;
  margin: 0 20px 16px;
}

.remote-pairing-hint {
  max-width: 820px;
  margin: 0 20px 18px;
  padding: 12px 14px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md, 8px);
  background: var(--bg-secondary);
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.remote-port-setting {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  max-width: 820px;
  margin: 0 20px 18px;
}

.remote-port-setting strong {
  display: block;
  color: var(--text-primary);
  font-size: 13px;
}

.remote-port-setting p {
  margin: 2px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.remote-port-input {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.remote-port-input input {
  width: 96px;
  min-height: 34px;
  box-sizing: border-box;
  padding: 6px 9px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  outline: none;
  background: var(--bg-secondary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  font-weight: 400;
}

.remote-port-input input:focus {
  border-color: var(--accent-color, #4a9eff);
}

.remote-port-input input:disabled {
  cursor: default;
  opacity: 0.68;
}

.remote-port-input .api-settings-action-btn {
  flex-shrink: 0;
}

.remote-token-setting {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 820px;
  margin: 0 20px 18px;
  padding: 14px 16px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg, 12px);
  background: var(--bg-secondary);
}

.remote-token-head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.remote-token-head strong {
  color: var(--text-primary);
  font-size: 13px;
}

.remote-token-status {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 9px;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
}

.remote-token-status.pinned {
  border-color: var(--success-color, #3fbf78);
  color: var(--success-color, #3fbf78);
}

.remote-token-setting p {
  margin: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.remote-token-value {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.remote-token-value code {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.remote-token-input {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.remote-token-input input {
  flex: 1 1 240px;
  min-width: 0;
  min-height: 34px;
  box-sizing: border-box;
  padding: 6px 9px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.remote-token-input input:focus {
  border-color: var(--accent-color, #4a9eff);
}

.remote-token-input input:disabled {
  cursor: default;
  opacity: 0.68;
}

.remote-pairing-layout {
  display: grid;
  grid-template-columns: minmax(220px, 300px) minmax(280px, 1fr);
  gap: 24px;
  padding: 20px;
  max-width: 820px;
}

.remote-pairing-qr {
  display: flex;
  min-height: 300px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 16px;
  padding: 20px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-xl, 16px);
  background: var(--bg-secondary);
  color: var(--text-muted);
}

.remote-qr-card {
  display: flex;
  width: min(248px, 100%);
  aspect-ratio: 1;
  align-items: center;
  justify-content: center;
  padding: 15px;
  border-radius: calc(var(--radius-lg, 12px) + 6px);
  background: #ffffff;
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.05),
    0 3px 10px rgba(0, 0, 0, 0.1),
    0 20px 36px -18px rgba(0, 0, 0, 0.45);
  color: var(--text-muted);
}

.remote-qr-card img {
  display: block;
  width: 100%;
  aspect-ratio: 1;
  border-radius: 6px;
}

.remote-service-status {
  color: var(--text-muted);
  font-size: 12px;
}

.remote-service-status.running {
  color: var(--success-color, #3fbf78);
}

.remote-pairing-qr .remote-service-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 5px 13px 5px 10px;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  background: var(--bg-primary);
  font-weight: 500;
  line-height: 1.35;
  white-space: nowrap;
}

.remote-pairing-qr .remote-service-status::before {
  content: "";
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.45;
}

.remote-pairing-qr .remote-service-status.running {
  border-color: color-mix(
    in srgb,
    var(--accent-green, #22c55e) 32%,
    transparent
  );
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.remote-pairing-qr .remote-service-status.running::before {
  opacity: 1;
  background: var(--accent-green, #22c55e);
  animation: remote-status-pulse 2.2s ease-out infinite;
}

@keyframes remote-status-pulse {
  0% {
    box-shadow: 0 0 0 0
      color-mix(in srgb, var(--accent-green, #22c55e) 45%, transparent);
  }

  70%,
  100% {
    box-shadow: 0 0 0 7px transparent;
  }
}

@media (prefers-reduced-motion: reduce) {
  .remote-pairing-qr .remote-service-status.running::before {
    animation: none;
  }
}

.remote-pairing-details {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 8px;
}

.remote-pairing-details label {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
}

.remote-pairing-details .custom-select-trigger {
  min-height: 36px;
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-secondary);
}

.remote-pairing-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.remote-pairing-actions .api-settings-action-btn,
.remote-token-input .api-settings-action-btn,
.remote-token-value .api-settings-action-btn {
  flex-shrink: 0;
}

.remote-pairing-note,
.remote-pairing-message {
  margin: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.remote-pairing-message.error {
  color: var(--danger-color, #e75d6a);
}

.remote-tunnel-card {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 820px;
  margin: 0 20px 20px;
  padding: 18px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md, 8px);
  background: var(--bg-secondary);
}

.remote-tunnel-heading {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.remote-tunnel-heading > div {
  flex: 1;
  min-width: 0;
}

.remote-tunnel-heading strong {
  display: block;
  color: var(--text-primary);
  font-size: 14px;
}

.remote-tunnel-heading p {
  margin: 3px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.remote-tunnel-status-grid {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 6px 14px;
  padding: 10px 12px;
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-primary);
  font-size: 12px;
}

.remote-tunnel-status-grid span {
  color: var(--text-muted);
}

.remote-tunnel-status-grid strong {
  overflow: hidden;
  color: var(--text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.remote-tunnel-guide-content {
  display: grid;
  gap: 10px;
  padding: 0 0 12px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.remote-tunnel-guide-content li {
  display: grid;
  gap: 2px;
}

.remote-simple-deploy-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.remote-deploy-step {
  display: grid;
  gap: 9px;
  padding: 12px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--bg-primary) 82%, transparent);
}

.remote-deploy-step h4,
.remote-deploy-step p,
.remote-deploy-step ul {
  margin: 0;
}

.remote-deploy-step h4 {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--text-primary);
  font-size: 13px;
}

.remote-deploy-step h4 b {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  flex: 0 0 22px;
  border-radius: 50%;
  background: var(--accent-color);
  color: var(--on-solid);
}

.remote-deploy-step ul {
  display: grid;
  gap: 7px;
  padding-left: 20px;
}

.remote-deploy-step li,
.remote-deploy-step p,
.remote-deploy-step small {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.55;
}

.remote-deploy-table {
  display: grid;
  grid-template-columns: 70px 100px minmax(0, 1fr);
  overflow: hidden;
  border-radius: 6px;
  border: 1px solid var(--border-light);
}

.remote-deploy-table > * {
  min-width: 0;
  padding: 7px 8px;
  border-bottom: 1px solid var(--border-color);
  overflow-wrap: anywhere;
}

.remote-deploy-table > :nth-last-child(-n + 3) {
  border-bottom: 0;
}

.remote-deploy-table strong {
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
}

.remote-deploy-ports {
  display: grid;
  grid-template-columns: 90px minmax(0, 1fr);
  gap: 6px 10px;
  align-items: center;
  color: var(--text-secondary);
  font-size: 12px;
}

.remote-simple-deploy-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
}

.remote-simple-deploy-form label > small {
  min-height: 34px;
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-weight: 400;
  line-height: 1.4;
}

.remote-simple-deploy-form input {
  width: 100%;
  min-height: 36px;
  box-sizing: border-box;
  padding: 7px 9px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  outline: none;
  background: var(--bg-secondary);
  color: var(--text-primary);
  font: inherit;
  font-weight: 400;
}

.remote-simple-deploy-form input:focus {
  border-color: var(--accent-color, #4a9eff);
}

.remote-simple-deploy-form .custom-select-trigger {
  min-height: 36px;
  padding: 7px 9px;
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-secondary);
  font-weight: 400;
}

.remote-simple-deploy-form .custom-select-trigger:focus {
  border-color: var(--accent-color, #4a9eff);
}

.remote-simple-deploy-key {
  grid-column: 1 / -1;
}

.remote-simple-deploy-key > span {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
}

.remote-dns-check-results,
.remote-deploy-progress {
  display: grid;
  gap: 5px;
  padding: 9px 10px;
  border-radius: 7px;
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.remote-deploy-progress {
  grid-template-columns: auto 1fr;
  align-items: center;
}

.remote-tunnel-guide-content li strong {
  color: var(--text-primary);
}

.remote-tunnel-guide-callout {
  display: grid;
  gap: 3px;
  padding: 10px 12px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent-color) 9%, transparent);
}

.remote-tunnel-guide-callout.warning {
  background: color-mix(in srgb, #d99a35 10%, transparent);
}

.remote-tunnel-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.remote-tunnel-form label:not(.remote-tunnel-check) {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
}

.remote-tunnel-form input:not([type="checkbox"]),
.remote-tunnel-form textarea {
  width: 100%;
  min-height: 36px;
  box-sizing: border-box;
  padding: 7px 9px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-weight: 400;
}

.remote-tunnel-form input:focus,
.remote-tunnel-form textarea:focus {
  border-color: var(--accent-color, #4a9eff);
}

.remote-tunnel-form textarea {
  min-height: 96px;
  resize: vertical;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 11px;
}

.remote-tunnel-check {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  user-select: none;
}

.remote-tunnel-check input[type="checkbox"] {
  flex-shrink: 0;
  accent-color: var(--accent-color, #4a9eff);
  cursor: pointer;
}

.remote-tunnel-ca {
  grid-column: 1 / -1;
}

.remote-config-card,
.remote-config-empty,
.remote-config-form,
.remote-import-panel {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md, 8px);
  background: var(--bg-primary);
}

.remote-config-card {
  border-color: color-mix(
    in srgb,
    var(--accent-color) 30%,
    var(--border-color)
  );
}

.remote-config-empty {
  gap: 8px;
  justify-items: start;
}

.remote-config-head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.remote-config-head strong {
  color: var(--text-primary);
  font-size: 13px;
}

.remote-config-empty strong {
  color: var(--text-primary);
  font-size: 13px;
}

.remote-config-empty p {
  margin: 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.remote-config-form .remote-tunnel-form input:not([type="checkbox"]),
.remote-config-form .remote-tunnel-form textarea {
  background: var(--bg-secondary);
}

.api-settings-action-btn.secondary.remote-nav-danger {
  border-color: color-mix(
    in srgb,
    var(--danger, #e5484d) 32%,
    var(--border-color)
  );
  background: color-mix(
    in srgb,
    var(--danger, #e5484d) 8%,
    var(--bg-secondary)
  );
  color: var(--danger, #e5484d);
}

.api-settings-action-btn.secondary.remote-nav-danger svg {
  color: currentColor;
}

.api-settings-action-btn.secondary.remote-nav-danger:hover:not(:disabled) {
  border-color: color-mix(
    in srgb,
    var(--danger, #e5484d) 55%,
    var(--border-color)
  );
  background: color-mix(
    in srgb,
    var(--danger, #e5484d) 14%,
    var(--bg-secondary)
  );
  color: var(--danger, #e5484d);
}

@media (max-width: 720px) {
  .remote-pairing-layout {
    grid-template-columns: 1fr;
  }

  .remote-tunnel-form {
    grid-template-columns: 1fr;
  }

  .remote-simple-deploy-form {
    grid-template-columns: 1fr;
  }

  .remote-simple-deploy-key {
    grid-column: auto;
  }

  .remote-tunnel-ca {
    grid-column: auto;
  }
}

.settings-language-options {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.settings-language-option {
  padding: 4px 7px;
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  font-size: 12.5px;
  transition:
    background 0.12s,
    color 0.12s;
}

.settings-language-option:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.settings-language-option.active {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  font-weight: 600;
}

/* Settings - About / Update section */
.settings-about-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 8px;
}

.settings-about-row .settings-number-input,
.sub-agent-concurrency-row .settings-number-input {
  width: 120px;
  padding: 4px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-secondary, rgba(255, 255, 255, 0.04));
  color: var(--text-primary);
  font-size: 12px;
}
.settings-about-row .settings-number-input:focus,
.sub-agent-concurrency-row .settings-number-input:focus {
  outline: none;
  border-color: var(--accent-color, #4a9eff);
}

.settings-attach-budget-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 4px;
}
.settings-attach-budget-actions .nav-item {
  width: auto;
  padding: 4px 10px;
}

.settings-update-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.settings-update-actions .nav-item {
  width: auto;
  padding: 4px 10px;
}

.settings-update-actions .nav-item > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.settings-about-row .check-update-btn {
  margin-left: auto;
  padding: 4px 10px;
}

/* 「关闭 Snow APP 时」行为下拉：靠右固定宽度，避免撑满整行 */
.settings-close-behavior-select {
  width: 220px;
  margin-left: auto;
}

.check-update-btn.checking {
  opacity: 0.7;
  pointer-events: none;
}

/* Settings - About：开源协议与隐私说明 */
.about-legal-details {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.about-legal-details > details > summary {
  width: fit-content;
  cursor: pointer;
  font-size: 11px;
  color: var(--text-tertiary);
  transition: color 0.15s ease;
}

.about-legal-details > details > summary:hover {
  color: var(--accent-color);
}

.about-legal-text {
  margin: 6px 0 0;
  padding: 8px 10px;
  max-height: 240px;
  overflow: auto;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.check-update-btn.checking svg {
  animation: snow-spin 1.5s linear infinite;
  color: var(--accent, #2563eb);
}

.check-update-btn:disabled {
  cursor: default;
}

.settings-update-error {
  font-size: 12px;
  color: var(--danger, #dc2626);
  padding: 2px 4px;
}

.about-github-row {
  display: flex;
  align-items: center;
  gap: 9px;
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  text-align: left;
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.about-github-row:hover {
  background: var(--bg-tertiary);
  border-color: color-mix(in srgb, var(--accent-color) 30%, transparent);
}

.about-github-logo {
  flex-shrink: 0;
  color: var(--accent-color);
}

.about-github-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.about-github-title {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.about-github-url {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.about-github-external {
  flex-shrink: 0;
  margin-left: auto;
  color: var(--text-muted);
  transition:
    color 0.15s ease,
    transform 0.15s ease;
}

.about-github-row:hover .about-github-external {
  color: var(--accent-color);
  transform: translate(1px, -1px);
}

.api-settings-page {
  display: flex;
  flex: 1;
  min-height: 0;
  flex-direction: column;
  overflow: auto;
  color: var(--text-primary);
  scrollbar-gutter: stable;
}

.api-settings-summary-grid {
  display: grid;
  grid-template-columns: 0.8fr 1.4fr 1fr;
  gap: 8px;
  margin-bottom: 10px;
}

.mcp-settings-summary-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.skills-settings-summary-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.import-settings-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 18px;
  margin: 0 0 14px;
  border-bottom: 1px solid var(--border-light);
}

.import-settings-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 32px;
  padding: 0 1px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.import-settings-tab:hover {
  color: var(--text-primary);
}

.import-settings-tab.active {
  border-bottom-color: var(--accent-color);
  color: var(--text-primary);
}

.import-settings-tab:focus-visible {
  outline: 2px solid var(--focus-ring-color, var(--accent-color));
  outline-offset: -2px;
}

@media (max-width: 640px) {
  .import-settings-tabs {
    gap: 14px;
    overflow-x: auto;
  }

  .import-settings-tab {
    flex: 0 0 auto;
  }
}

/* MCP 设置二级分类 Tab 的计数徽标 */
.mcp-category-tabs .import-settings-tab small {
  display: inline-flex;
  min-width: 18px;
  height: 16px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-muted);
  font-size: 10px;
}

.mcp-category-tabs .import-settings-tab.active small {
  color: var(--text-secondary);
}

.hooks-settings-summary-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

/* Documentation modal (reusable) */
.docs-modal .app-modal-body {
  max-height: 70vh;
  overflow-y: auto;
}

.docs-container {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.docs-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--border-light);
}

.docs-section:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.docs-section-title {
  margin: 0;
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
}

.docs-section-description {
  margin: 0 0 4px 0;
  font-size: 12.5px;
  line-height: 1.5;
  color: var(--text-secondary);
}

.docs-subsection {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 4px;
}

.docs-subsection strong {
  font-size: 12px;
  font-weight: 650;
  color: var(--text-tertiary);
}

.docs-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.docs-table td {
  padding: 4px 8px;
  border: 1px solid var(--border-light);
  vertical-align: top;
}

.docs-field-name,
.docs-code-value {
  width: 30%;
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  color: var(--text-primary);
  white-space: nowrap;
}

.docs-field-desc,
.docs-code-meaning {
  color: var(--text-secondary);
  line-height: 1.4;
}

.docs-example {
  margin-top: 8px;
  padding: 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.docs-example-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.docs-example-title {
  font-size: 12px;
  font-weight: 650;
  color: var(--text-primary);
}

.docs-example-badge {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  font-size: 10px;
  font-family: var(--font-mono, monospace);
  color: var(--text-tertiary);
  white-space: nowrap;
}

.docs-example-code {
  margin: 0 0 6px 0;
  padding: 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary, var(--bg-primary));
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  line-height: 1.45;
  color: var(--text-primary);
  white-space: pre-wrap;
  word-break: break-word;
  overflow-x: auto;
}

.docs-example-explanation {
  margin: 0;
  font-size: 11.5px;
  line-height: 1.4;
  color: var(--text-muted);
}

.codebase-settings-summary-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.api-settings-summary-card {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
  padding: 9px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
}

.api-settings-summary-card svg {
  color: var(--text-tertiary);
}

.api-settings-summary-card span {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.api-settings-summary-card small {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.proxy-browser-settings-summary-grid {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.api-settings-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-bottom: 10px;
}

/* 敏感命令面板：操作按钮始终在一行等宽显示（同步/复位/添加） */
.api-settings-actions.sensitive-commands-actions {
  display: flex;
  flex-wrap: nowrap;
}

.api-settings-actions.sensitive-commands-actions .api-settings-action-btn {
  flex: 1 1 0;
  min-width: 0;
}

.api-settings-actions.sensitive-commands-actions
  .api-settings-action-btn
  > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 敏感命令面板：决策模型辅助设置（全局开关 + 模型选择 + 托管开关） */
.sensitive-command-assist {
  display: grid;
  gap: 10px;
  margin-bottom: 10px;
  padding: 10px 12px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.sensitive-command-assist-header {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  color: var(--text-secondary);
}

.sensitive-command-assist-icon {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  margin-top: 1px;
  color: var(--text-tertiary);
}

.sensitive-command-assist-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.sensitive-command-assist-copy strong {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
}

.sensitive-command-assist-rows {
  display: grid;
  gap: 6px;
}

.sensitive-command-assist-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.sensitive-command-assist-row-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.sensitive-command-assist-row-copy strong {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
}

.sensitive-command-assist-row-copy small {
  color: var(--text-tertiary);
  font-size: 11px;
  line-height: 1.45;
}

.sensitive-command-assist-control {
  flex: 0 0 auto;
  min-width: 160px;
  max-width: 220px;
}

.sensitive-command-assist-number {
  flex: 0 0 auto;
}

.sensitive-command-assist-number input {
  width: 72px;
  min-height: 28px;
  box-sizing: border-box;
  padding: 4px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm, 6px);
  outline: none;
  background: var(--bg-secondary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.sensitive-command-assist-number input:focus {
  border-color: var(--accent-color, #4a9eff);
}

.sensitive-command-assist-number input:disabled {
  cursor: default;
  opacity: 0.68;
}

.sensitive-command-assist-warning {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--accent-red-text);
  font-size: 11px;
  line-height: 1.45;
}

/* 敏感命令面板：规则列表撑满卡片剩余高度，由列表自身滚动 */
.sensitive-command-table-wrap {
  min-height: 0;
  max-height: none;
  flex: 1 1 auto;
  overscroll-behavior: contain;
}

/* 敏感命令面板：卡片与列表链路逐层撑满页面剩余高度 */
.sensitive-commands-page > .import-settings-tabs,
.sensitive-commands-page > .api-settings-summary-grid,
.sensitive-commands-page > .api-settings-actions,
.sensitive-commands-page > .skills-settings-tabs {
  flex-shrink: 0;
}

.sensitive-commands-page .api-settings-manual-form {
  min-height: 0;
  margin-bottom: 0;
  flex: 1 1 auto;
}

.sensitive-commands-page .api-settings-manual-form > .api-settings-form-body,
.sensitive-commands-page
  .api-settings-manual-form
  > .api-settings-form-body
  > .api-settings-form-section {
  min-height: 0;
  flex: 1 1 auto;
}

/* API 设置页：同步 / 手动添加 / 导入配置 三键并排等宽 */
.api-settings-actions.api-settings-actions-trio {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.api-settings-actions.api-settings-actions-trio
  .api-settings-action-btn
  > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* API 设置：四个操作按钮（OAuth 登录 / 同步 / 手动添加 / 导入）两行两列 */
.api-settings-actions.api-settings-actions-quad {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.api-settings-actions.api-settings-actions-quad
  .api-settings-action-btn
  > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.api-settings-action-btn,
.api-settings-form-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  font-size: 12px;
  font-weight: 650;
}

.api-settings-action-btn {
  transition: none;
  transform: none;
}
.api-settings-form-btn {
  line-height: 1;
  transition:
    background 0.12s,
    border-color 0.12s,
    opacity 0.12s;
}

.api-settings-form-btn > svg {
  display: block;
  flex-shrink: 0;
}

.api-settings-form-btn > span {
  display: inline-flex;
  align-items: center;
  line-height: 1;
}

.api-settings-action-btn.primary,
.api-settings-form-btn.primary {
  background: var(--text-primary);
  color: var(--on-solid);
}

.api-settings-action-btn.secondary,
.api-settings-form-btn.secondary {
  border-color: var(--border-color);
  background: var(--bg-secondary);
  color: var(--text-secondary);
}

.api-settings-action-btn:hover:not(:disabled) {
  transform: none;
}

.api-settings-form-btn:hover:not(:disabled) {
  border-color: var(--border-color);
  background: var(--bg-hover);
}

.api-settings-action-btn.secondary:hover:not(:disabled) {
  border-color: var(--border-color);
  background: var(--bg-hover);
}

.api-settings-action-btn.primary:hover:not(:disabled),
.api-settings-form-btn.primary:hover:not(:disabled) {
  border-color: transparent;
  background: var(--text-primary);
}

.api-settings-action-btn:disabled,
.api-settings-form-btn:disabled {
  cursor: default;
  opacity: 0.68;
}

.auto-dismiss-notice {
  position: fixed;
  top: calc(env(titlebar-area-height, 0px) + 18px);
  left: 50%;
  z-index: 10010;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: auto;
  max-width: min(560px, calc(100vw - 32px));
  min-height: 38px;
  padding: 9px 14px;
  border: 1px solid transparent;
  border-radius: var(--radius-lg);
  box-shadow:
    0 16px 36px rgba(15, 23, 42, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.48);
  backdrop-filter: blur(14px);
  font-size: 12px;
  font-weight: 650;
  line-height: 1.35;
  pointer-events: none;
  transform: translateX(-50%);
  animation: auto-dismiss-notice-pop 180ms ease-out;
}

.auto-dismiss-notice-icon {
  display: inline-flex;
  flex-shrink: 0;
}

.auto-dismiss-notice-message {
  min-width: 0;
  text-align: center;
  /* 允许换行，长消息（如导入统计）完整显示 */
  white-space: normal;
  overflow-wrap: anywhere;
}

.auto-dismiss-notice.success {
  border-color: rgba(34, 197, 94, 0.24);
  background: color-mix(in srgb, var(--accent-green-bg) 88%, transparent);
  color: var(--accent-green-text);
}

.auto-dismiss-notice.error {
  border-color: rgba(239, 68, 68, 0.24);
  background: color-mix(in srgb, var(--accent-red-bg) 90%, transparent);
  color: var(--accent-red-text);
}

.auto-dismiss-notice.info {
  border-color: rgba(59, 130, 246, 0.24);
  background: rgba(59, 130, 246, 0.14);
  color: var(--accent-blue);
}

.auto-dismiss-notice.warning {
  border-color: rgba(245, 158, 11, 0.24);
  background: color-mix(in srgb, var(--accent-amber-bg) 90%, transparent);
  color: var(--accent-amber-text);
}

@keyframes auto-dismiss-notice-pop {
  from {
    opacity: 0;
    transform: translate(-50%, -8px) scale(0.98);
  }

  to {
    opacity: 1;
    transform: translate(-50%, 0) scale(1);
  }
}

.api-settings-manual-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 10px;
  padding: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
}

.api-settings-manual-header {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.api-settings-manual-header strong {
  font-size: 12.5px;
}

.api-settings-manual-header span {
  color: var(--text-muted);
  font-size: 11px;
}

/* 决策模型面板：header 直接挂在页面下（不在卡片内），补与下方表格的间距 */
.api-settings-page > .api-settings-manual-header {
  margin-bottom: 10px;
}

.api-settings-form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.api-settings-form-grid.api-settings-form-grid-responsive {
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 240px), 1fr));
  align-items: start;
  gap: 12px;
}

.api-settings-form-grid-responsive
  .api-settings-field
  > input:not([type="checkbox"]):not([type="range"]),
.api-settings-form-grid-responsive .custom-select-trigger {
  min-height: 32px;
}

.api-settings-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
}

.api-settings-field.wide {
  grid-column: 1 / -1;
}

.api-settings-field span,
.api-settings-form-options span {
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-weight: 600;
}

.api-settings-field input:not([type="checkbox"]):not([type="range"]),
.api-settings-field select {
  width: 100%;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.api-settings-field input:not([type="checkbox"]):not([type="range"]):focus,
.api-settings-field select:focus {
  border-color: var(--accent-color);
}

.api-settings-field input:not([type="checkbox"]):not([type="range"]):disabled,
.api-settings-field select:disabled {
  cursor: default;
  opacity: 0.68;
}

.api-settings-field textarea.api-settings-field-textarea {
  width: 100%;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  line-height: 1.5;
  resize: vertical;
  font-family: var(--font-mono, ui-monospace, "SF Mono", Consolas, monospace);
}

.api-settings-field textarea.api-settings-field-textarea:focus {
  border-color: var(--accent-color);
}

.api-settings-field textarea.api-settings-field-textarea:disabled {
  cursor: default;
  opacity: 0.68;
}

/* ===== Custom Select Dropdown ===== */
.custom-select {
  position: relative;
  width: 100%;
}

.custom-select-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  width: 100%;
  padding: 7px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  text-align: left;
}

.custom-select-trigger:hover:not(:disabled) {
  border-color: var(--text-muted);
}

.custom-select-trigger:focus {
  outline: none;
  border-color: var(--accent-color);
}

.custom-select-trigger:disabled {
  cursor: default;
  opacity: 0.68;
}

.custom-select-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
}

.custom-select-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  right: 0;
  z-index: 100;
  min-width: 100%;
  max-height: 240px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow);
}

/* Portal variant: rendered into document.body to escape `overflow: hidden`
   ancestors (e.g. inside a Modal). The outer wrapper handles fixed
   positioning; the inner dropdown resets absolute offsets and fills width. */
.custom-select-dropdown-portal {
  pointer-events: auto;
}

.custom-select-dropdown-portal .custom-select-dropdown {
  position: static;
  top: auto;
  left: auto;
  right: auto;
  z-index: auto;
  min-width: 0;
  width: 100%;
}

.custom-select-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  text-align: left;
}

.custom-select-item:hover {
  background: var(--bg-hover);
}

.custom-select-item:disabled {
  cursor: default;
  opacity: 0.5;
}

.custom-select-item > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
}
.custom-select-check {
  flex-shrink: 0;
  color: var(--text-primary);
}

.search-engine-option {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

/* 搜索引擎多选：复选框 + 图标 + 名称（混合检索时全部生效） */
.search-engine-checklist {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 14px;
}

.search-engine-check {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
}

.search-engine-check input[type="checkbox"] {
  margin: 0;
  accent-color: var(--accent-color);
  cursor: pointer;
}

.search-engine-check input[type="checkbox"]:disabled {
  cursor: default;
}

/* 块级 flex：内联图标会按基线撑高下拉框 */
.request-method-option {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.custom-select-empty,
.model-dropdown-empty {
  padding: 10px 8px;
  color: var(--text-muted);
  font-size: 12px;
  text-align: center;
}

.custom-select-filter {
  width: 100%;
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  outline: none;
  transition:
    border-color 0.12s ease,
    box-shadow 0.12s ease;
}

.custom-select-filter:focus {
  border-color: var(--accent-color);
}

.api-settings-hint-text {
  color: var(--text-muted);
  font-size: 10.5px;
  line-height: 1.4;
}

/* ===== 模型连接自检（决策模型 / 嵌入 / 重排） ===== */
.model-health-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  white-space: nowrap;
}

.model-health-status.is-untested {
  color: var(--text-muted);
}

.model-health-status.is-ok {
  color: var(--accent-green-text);
}

.model-health-status.is-failed {
  color: var(--accent-red-text);
  cursor: help;
}

.model-health-section {
  display: grid;
  gap: 8px;
  margin-top: 10px;
}

.model-health-section-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.model-health-warning {
  display: inline-flex;
  align-items: flex-start;
  gap: 5px;
  color: var(--accent-amber-text);
  font-size: 11px;
  line-height: 1.45;
}

.model-health-warning > svg {
  flex-shrink: 0;
  margin-top: 2px;
}

.model-health-result {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
}

.model-health-result-head {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.model-health-result.is-ok .model-health-result-head {
  color: var(--accent-green-text);
}

.model-health-result.is-failed .model-health-result-head {
  color: var(--accent-red-text);
}

.model-health-result-time {
  margin-left: auto;
  color: var(--text-muted);
  font-size: 11px;
  white-space: nowrap;
}

.model-health-result-grid {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 3px 12px;
  margin: 0;
  font-size: 11.5px;
}

.model-health-result-grid dt {
  color: var(--text-muted);
}

.model-health-result-grid dd {
  margin: 0;
  min-width: 0;
  overflow: hidden;
  color: var(--text-secondary);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.model-health-result-error {
  margin: 0;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.5;
  overflow-wrap: anywhere;
  user-select: text;
}

.api-model-combobox-field {
  position: relative;
}

/* 组合框标签行：标签 + 可选操作按钮（如「按模型 ID 填充能力」）同排两端对齐，
   避免调用方在外层重复渲染一遍标签导致列高错位 */
.api-model-combobox-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.api-model-combobox-label > span:first-child {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.api-model-combobox {
  position: relative;
  min-width: 0;
}

.api-model-combobox-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.api-settings-field
  .api-model-combobox
  .api-model-combobox-input-wrap
  > input:not([type="checkbox"]):not([type="range"]) {
  padding-left: 30px;
  padding-right: 30px;
}

.api-model-combobox-search,
.api-model-combobox-status {
  position: absolute;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  pointer-events: none;
}

.api-model-combobox-search {
  left: 9px;
}

.api-model-combobox-status {
  right: 9px;
}

.api-model-combobox-spin {
  animation: spin 1s linear infinite;
}

.api-model-combobox-menu {
