  background: var(--bg-primary);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.14);
}

.terminal-combobox-list {
  max-height: 220px;
  overflow-y: auto;
  padding: 4px;
}

.terminal-combobox-option {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 7px 8px;
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  text-align: left;
  transition:
    background 0.12s,
    color 0.12s;
}

.terminal-combobox-option.highlighted,
.terminal-combobox-option:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.terminal-combobox-option.selected {
  color: var(--text-primary);
  font-weight: 600;
}

.terminal-combobox-option-info {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.terminal-combobox-option-name {
  font-size: 12px;
  font-weight: 650;
  color: inherit;
}

.terminal-combobox-option-path {
  overflow: hidden;
  font-size: 10.5px;
  color: var(--text-muted);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.terminal-combobox-empty {
  padding: 10px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
}

.terminal-combobox-browse {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  border-top: 1px solid var(--border-light);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  transition:
    background 0.12s,
    color 0.12s;
}

.terminal-combobox-browse:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.terminal-combobox-browse:disabled {
  cursor: default;
  opacity: 0.68;
}

.terminal-combobox-spin {
  animation: spin 1s linear infinite;
}
.api-settings-inline-check {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  cursor: pointer;
}

.api-settings-inline-check input[type="checkbox"] {
  margin: 0;
}

.icon-btn.primary {
  color: var(--accent-green);
}

.icon-btn.primary:hover {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.icon-btn.danger {
  color: var(--accent-red-text);
}

.icon-btn.danger:hover {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.api-settings-form-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.api-settings-form-error {
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: rgba(239, 68, 68, 0.1);
  color: var(--text-danger, #ef4444);
  font-size: 12px;
  line-height: 1.4;
}

.api-settings-form-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 5px;
}

.api-settings-form-section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.api-settings-form-section-title {
  font-size: 11px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding-bottom: 2px;
  border-bottom: 1px solid var(--border-light);
}

.toggle-switch {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  cursor: pointer;
  font-size: 11.5px;
  color: var(--text-tertiary);
}

.toggle-switch input[type="checkbox"] {
  display: none;
}

.toggle-slider {
  position: relative;
  width: 32px;
  height: 18px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  transition:
    background 0.15s,
    border-color 0.15s;
  flex-shrink: 0;
}

.toggle-slider::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 1px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--text-tertiary);
  transition:
    transform 0.15s,
    background 0.15s;
}

.toggle-switch input:checked + .toggle-slider {
  background: var(--text-primary);
  border-color: var(--text-primary);
}

.toggle-switch input:checked + .toggle-slider::after {
  transform: translateX(14px);
  background: var(--on-solid);
}

.toggle-switch input:disabled + .toggle-slider {
  opacity: 0.5;
  cursor: default;
}

.toggle-switch input:focus-visible + .toggle-slider {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}

/* ===== Keyboard shortcuts settings ===== */
.shortcut-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.shortcut-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 9px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  transition:
    background 0.12s,
    border-color 0.12s;
}

.shortcut-item:hover {
  background: var(--bg-hover);
  border-color: var(--border-color);
}

/* 录制状态：高亮边框 + 脉冲提示 */
.shortcut-item.recording {
  border-color: var(--text-muted);
  box-shadow: 0 0 0 3px var(--focus-ring);
}

/* 冲突状态：红色边框提示 */
.shortcut-item.conflict {
  border-color: var(--accent-red-text);
}

/* 启停开关：紧凑型纯滑块，位于首位 */
.shortcut-enabled-switch {
  gap: 0;
  flex-shrink: 0;
}

/* 按键标签 + 描述：可点击进入录制 */
.shortcut-info {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 0;
  border: none;
  background: transparent;
  text-align: left;
  cursor: pointer;
  color: inherit;
  font: inherit;
}

.shortcut-info:disabled {
  cursor: default;
  opacity: 0.6;
}

.shortcut-info:not(:disabled):hover .shortcut-key {
  border-color: var(--text-muted);
  color: var(--text-primary);
}

.shortcut-key {
  width: fit-content;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  border: 1px solid var(--border-light);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.4;
  transition:
    border-color 0.12s,
    color 0.12s;
}

/* 录制中按键标签闪烁动画 */
.shortcut-item.recording .shortcut-key {
  border-color: var(--text-muted);
  color: var(--text-primary);
  animation: shortcut-record-pulse 1.2s ease-in-out infinite;
}

/* 界面就近快捷键提示：键帽样式 */
.shortcut-hint {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  white-space: nowrap;
  pointer-events: none;
  user-select: none;
}

.shortcut-hint-group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.shortcut-hint-key {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 17px;
  height: 17px;
  padding: 0 5px;
  border-radius: 4px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-light);
  box-shadow: inset 0 -1px 0 var(--border-light);
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
}

.shortcut-hint-sep {
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1;
  opacity: 0.65;
}

.nav-item > .shortcut-hint {
  margin-left: auto;
}

.nav-item > .shortcut-hint ~ .sidebar-memo-badge,
.nav-item > .shortcut-hint ~ .sidebar-memory-badge {
  margin-left: 0;
}

@keyframes shortcut-record-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.shortcut-desc {
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.3;
}

/* 冲突提示文案 */
.shortcut-conflict-hint {
  color: var(--accent-red-text);
  font-size: 11px;
  line-height: 1.3;
}

/* 仅前台开关 + 恢复默认按钮 */
.shortcut-toggles {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.shortcut-foreground-switch span:last-child {
  white-space: nowrap;
}

.shortcut-foreground-switch input:disabled ~ span:last-child {
  opacity: 0.5;
}

.shortcut-reset-btn {
  flex-shrink: 0;
}

/* 录制提示条 */
.shortcut-recording-hint {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  padding: 7px 10px;
  border-radius: var(--radius-md);
  background: var(--focus-ring);
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.4;
}

.shortcut-note {
  margin-top: 4px;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  color: var(--text-muted);
  font-size: 11.5px;
  line-height: 1.4;
}

/* 快捷键帮助浮层 */
.shortcut-help-modal .app-modal-body {
  padding: 0;
}

.shortcut-help-body {
  display: flex;
  flex-direction: column;
}

.shortcut-help-content {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 14px 16px 16px;
}

.shortcut-help-group-title {
  margin: 0 0 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.shortcut-help-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.shortcut-help-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 8px;
  border-radius: var(--radius-md);
}

.shortcut-help-item:nth-child(odd) {
  background: var(--bg-tertiary);
}

.shortcut-help-key {
  min-width: 110px;
  flex-shrink: 0;
  font-family: var(--font-mono, monospace);
  font-size: 11px;
  color: var(--text-primary);
}

.shortcut-help-desc {
  font-size: 12px;
  color: var(--text-secondary);
}

/* 帮助浮层顶部搜索栏：模态主体去掉内边距后吸顶，滚动内容不会漏到其上 */
.shortcut-help-search {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-primary);
}

.shortcut-help-search-icon {
  flex-shrink: 0;
  color: var(--text-muted);
}

.shortcut-help-search:focus-within .shortcut-help-search-icon {
  color: var(--accent-color);
}

.shortcut-help-search-input {
  flex: 1;
  min-width: 0;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--text-primary);
  font-size: 13px;
  outline: none !important;
}

.shortcut-help-search-input::placeholder {
  color: var(--text-muted);
}

.shortcut-help-search-clear {
  flex-shrink: 0;
}

.shortcut-help-empty {
  padding: 28px 0;
  color: var(--text-muted);
  font-size: 12.5px;
  text-align: center;
}

/* 分组标题行内的快捷键提示：紧随标题、不抢占操作按钮空间 */
.section-header .shortcut-hint {
  margin-left: 2px;
}

/* 菜单项内的快捷键提示：右对齐 */
.workspace-directory-menu-item > .shortcut-hint {
  margin-left: auto;
}

/* 搜索弹窗底部快捷键提示条 */
.search-modal-hints {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 6px 12px 2px;
  color: var(--text-muted);
  font-size: 11px;
}

.search-modal-hints span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.search-modal-hints kbd {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-secondary);
}

.api-settings-password-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

/* 与 .api-settings-field input 同特异性，确保右侧留白生效 */
.api-settings-password-wrap input:not([type="checkbox"]):not([type="range"]) {
  width: 100%;
  padding-right: 30px;
}

.api-settings-password-toggle {
  position: absolute;
  right: 6px;
  top: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  transition: color 0.12s;
}

.api-settings-password-toggle:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.api-settings-edit-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 10px;
  padding: 12px;
  border: 1px solid var(--accent-blue);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
}

.api-settings-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 150px;
  padding: 18px;
  color: var(--text-muted);
  font-size: 12px;
  text-align: center;
}

.skills-settings-actions {
  grid-template-columns: minmax(150px, 220px);
}

.skills-settings-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4px;
  margin-bottom: 12px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.skills-settings-tab {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 10px;
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  font-size: 12px;
  font-weight: 600;
}

.skills-settings-tab:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.skills-settings-tab.active {
  background: var(--bg-primary);
  color: var(--text-primary);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
}

.skills-settings-tab:disabled {
  cursor: default;
  opacity: 0.45;
}

.skills-settings-tab small {
  display: inline-flex;
  min-width: 20px;
  height: 18px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-muted);
  font-size: 10px;
}

.skills-settings-tab.active small {
  color: var(--text-secondary);
}

.skills-settings-section {
  gap: 8px;
}

.skills-settings-section-header {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.skills-settings-section-header > div:first-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.skills-settings-section-header > div:first-child > span {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
}

.skills-settings-paths {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 4px;
}

.skills-settings-paths code,
.skills-settings-item code {
  font-family: var(--font-mono);
}

.skills-settings-paths code,
.skills-settings-badge,
.skills-settings-tools-count {
  padding: 2px 6px;
  border: 1px solid var(--border-light);
  border-radius: 999px;
  background: var(--surface-island-muted);
  color: var(--text-secondary);
  font-size: 10.5px;
}

.skills-settings-list {
  min-height: 96px;
}

.skills-settings-empty {
  display: flex;
  min-height: 96px;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.skills-settings-error {
  color: var(--accent-red-text);
}

.skills-settings-item {
  align-items: flex-start;
  padding: 9px 10px;
  transition:
    opacity 0.15s ease,
    background-color 0.15s ease;
}

.skills-settings-item.inactive {
  opacity: 0.68;
}

.skills-settings-item-main {
  align-items: flex-start;
  gap: 10px;
}

.skills-settings-switch {
  flex-shrink: 0;
  margin-top: 1px;
}

.skills-settings-switch > span:last-child {
  width: 48px;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-settings-item-info {
  flex: 1;
  gap: 4px;
}

.skills-settings-item-title {
  display: flex;
  min-width: 0;
  align-items: baseline;
  gap: 7px;
}

.skills-settings-item-title strong {
  overflow: hidden;
  flex-shrink: 0;
  max-width: 45%;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-settings-item-title code {
  overflow: hidden;
  color: var(--text-muted);
  font-size: 10.5px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.system-prompt-item-info .skills-settings-item-description {
  overflow: visible;
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.45;
  text-overflow: clip;
  white-space: normal;
}

.system-prompt-item-info .skills-settings-item-path {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 5px;
  color: var(--text-muted);
  font-size: 10px;
}

.skills-settings-item-path svg {
  flex-shrink: 0;
}

.skills-settings-item-path code {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skills-settings-item-actions {
  gap: 4px;
}

.skills-settings-badge,
.skills-settings-tools-count {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  line-height: 1.2;
}

.skills-settings-tools-count svg {
  flex-shrink: 0;
}

/* ===== Skills Install ===== */
.skills-settings-install-section {
  margin-top: 4px;
}

.skills-settings-install-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.skills-settings-install-row {
  display: flex;
  align-items: stretch;
  gap: 6px;
}

.skills-settings-install-input {
  flex: 1;
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
}

.skills-settings-install-input:focus {
  border-color: var(--accent-color);
}

.skills-settings-install-input:disabled {
  cursor: default;
  opacity: 0.68;
}

.skills-settings-install-btn {
  flex-shrink: 0;
  white-space: nowrap;
}

.skills-settings-install-target {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
}

.skills-settings-install-example {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.4;
}

.skills-settings-install-example code {
  color: var(--text-primary);
  word-break: break-all;
}

.skills-settings-github-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
}

.skills-settings-uninstall-btn {
  color: var(--text-muted);
}

.skills-settings-uninstall-btn:hover:not(:disabled) {
  color: var(--accent-red-text);
}

.spin {
  animation: snow-spin 0.85s linear infinite;
}

.snowflake-spin {
  /* 旋转必须挂在 HTML 包裹层：DPR>1 时 SVG 元素的 transform 动画不进合成器，
     主线程一忙（切换会话、挂载历史消息）就整段停转。span 上的动画由合成器驱动。 */
  display: inline-flex;
  animation: snow-spin 1.5s linear infinite;
  will-change: transform;
}

/* Loader2 等图标的旋转同样只能放在 HTML 包裹层（子代理 / Workflow 节点列表） */
.spin-layer {
  display: inline-flex;
  animation: snow-spin 0.85s linear infinite;
  will-change: transform;
}

@keyframes snow-spin {
  from {
    transform: rotate(0deg);
  }

  to {
    transform: rotate(360deg);
  }
}

/* Sidebar Footer */
.sidebar-footer {
  /* 使用指南浮层菜单的定位锚点（页脚行 overflow: hidden，菜单不能挂在行内） */
  position: relative;
  margin-top: auto;
  padding: 8px 12px 12px;
}

.sidebar-footer-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: nowrap;
  overflow: hidden;
}

.sidebar-footer-row .nav-item {
  flex: 0 1 auto;
  min-width: 0;
}

.sidebar-footer-row .nav-item > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 使用指南：纯图标，靠右显示（作用于 Tooltip 包裹层） */
.sidebar-footer-row > .tooltip-wrapper:has(.sidebar-user-guide-btn) {
  margin-left: auto;
  flex-shrink: 0;
}

.sidebar-user-guide-btn {
  padding: 6px;
}

/* 使用指南浮层菜单：向上弹出并右对齐使用指南按钮。
   bottom 以页脚为锚点：页脚上内边距 8px，减掉后正好对齐页脚行顶边。 */
.sidebar-help-menu {
  position: absolute;
  right: 12px;
  bottom: calc(100% - 8px);
  z-index: 60;
  display: flex;
  min-width: 168px;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 6px;
  padding: 4px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  box-shadow: var(--shadow-md);
}

.sidebar-help-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12.5px;
  text-align: left;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.sidebar-help-menu-item:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.sidebar-help-menu-item svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

.sidebar-help-menu-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* 快捷键提示靠右，与菜单文字分列两端 */
.sidebar-help-menu-item .shortcut-hint {
  margin-left: auto;
}

/* 菜单打开期间不再弹出按钮的悬浮提示，避免与菜单重叠 */
.sidebar-footer:has(.sidebar-help-menu)
  .tooltip-wrapper:has(.sidebar-user-guide-btn) {
  --tooltip-suppressed: 1;
}

.sidebar-version-badge {
  font-size: 10px;
  font-weight: 500;
  color: var(--text-tertiary);
  background: var(--bg-hover);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  line-height: 1.4;
}

.update-ready-btn {
  color: var(--accent, #2563eb);
}

.update-ready-btn:hover {
  background: var(--bg-hover);
}

.update-ready-btn svg {
  color: var(--accent, #2563eb);
}

.update-downloading {
  opacity: 0.7;
  cursor: pointer;
}

.update-downloading:hover {
  opacity: 1;
}

.update-downloading svg {
  animation: snow-spin 1.5s linear infinite;
}

.sidebar.collapsed .sidebar-content-wrapper {
  display: none;
}

/* ===== Main Content ===== */
/* position: relative anchors every absolutely-positioned child (settings
   badges, combobox menus, etc.) to this column. The default
   theme implicitly provided this containing block via backdrop-filter, but
   theme presets (e.g. cream) may set backdrop-filter: none for a flat look,
   which would make those children jump to the app window edge instead.
   Keep this explicit anchor so any theme change cannot break positioning. */
.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  border-radius: var(--radius-xl);
  background: var(--surface-island-strong);
  box-shadow: var(--island-shadow);
  backdrop-filter: var(--backdrop-blur-lg);
  overflow: hidden;
  opacity: 1;
  /* 不过渡 flex-grow：全屏切换时它必须瞬时取值，main 才能每帧吃满
     右面板 width 过渡释放的空间，行内不出现空白（右缘不离开窗口边）。
     padding 与右面板 width 过渡同曲线：main 分配宽度经过 [0, 20px)
     区间时不会被 border-box padding clamp 撑出最小占位造成溢出 */
  transition:
    opacity 0.2s ease,
    padding 0.18s ease;
  padding: 18px 10px;
}

/* 右面板拖宽越界待全屏遮罩：持续拖拽越界 500ms 后出现，提示"松手即全屏"，
   拖回可取消。pointer-events: none 保证拖拽手势不受影响。 */
.fullscreen-pending-overlay {
  position: absolute;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: center;
  justify-content: center;
  background: color-mix(in srgb, var(--bg-primary) 55%, transparent);
  backdrop-filter: blur(2px);
  pointer-events: none;
  animation: fullscreen-pending-in 0.15s ease-out;
}

.fullscreen-pending-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 18px 28px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow);
  color: var(--text-primary);
  font-size: 13px;
  text-align: center;
}

.fullscreen-pending-card > svg {
  color: var(--accent, #3b82f6);
}

.fullscreen-pending-title {
  font-weight: 600;
}

.fullscreen-pending-hint {
  font-size: 12px;
  color: var(--text-secondary);
}

@keyframes fullscreen-pending-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .fullscreen-pending-overlay {
    animation: none;
  }
}

/* 懒加载面板的 Suspense 兜底：铺满主内容区，避免分包加载时白屏 */
.main-content-loading {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: var(--text-muted);
  font-size: 13px;
  user-select: none;
  animation: main-content-loading-in 0.18s ease-out;
}

.main-content-loading .spin {
  color: var(--text-tertiary);
}

@keyframes main-content-loading-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ===== 独立页面（备忘录 / 项目记忆 / 定时任务 / 插件） ===== */
/* 页面占满主内容区，标题与关闭按钮由 TopBar 承担；内部沿用各页面原有的
   双栏布局类（.memo-panel-layout / .scheduled-tasks-panel-layout 等）。 */
.feature-page {
  display: flex;
  flex: 1;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
}

.feature-page > .memo-panel-layout,
.feature-page > .scheduled-tasks-panel-layout,
.feature-page > .plugins-panel-body {
  flex: 1;
  min-height: 0;
}

/* 独立页面空状态图标（备忘录 / 项目记忆的右栏共用）：弱化的中性色装饰 */
.feature-empty-icon {
  color: var(--text-tertiary);
  opacity: 0.5;
}

/* Header */
.main-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--header-height);
  padding: 0 16px;
  background: var(--surface-island-muted);
  flex-shrink: 0;
  -webkit-app-region: drag;
}

.header-title-group {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 1px;
}

/* 标题+副标题双行时整体下移约 3px（胶囊高度不变） */
.header-title-group:has(> .header-subtitle) {
  padding-top: 6px;
}

.header-title,
.header-subtitle {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.header-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
}

.header-subtitle {
  font-size: 11px;
  color: var(--text-muted);
}

.header-actions {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 6px;
  -webkit-app-region: no-drag;
}

.btn-commit {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  color: var(--text-secondary);
  font-size: 12.5px;
  font-weight: 500;
  transition: background 0.12s;
}

.btn-commit:hover {
  background: var(--bg-hover);
}

.diff-stat {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  font-size: 12px;
  font-weight: 500;
  font-family: var(--font-mono);
}

.diff-add {
  color: var(--accent-green);
}
.diff-del {
  color: var(--accent-red);
}

/* Chat content wrapper - manages empty vs has-messages layout.
   Background stays transparent: .main-content already paints the single
   semi-transparent island layer, stacking it again here would darken it.
   position: relative anchors the absolutely-positioned .user-message-rail
   (and any other chat overlay) to the chat column itself. This must not
   rely on .main-content's backdrop-filter creating a containing block —
   theme presets (e.g. cream) may disable it, which would make the rail
   jump to the app window's right edge. */
.chat-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 0;
}

.chat-area {
  /* 聊天内容最大宽度（响应式梯度，视口越宽内容越宽）。
     所有聊天区内容（消息列表 / 骨架屏 / 压缩消息 / 输入区）通过继承
     该变量对齐同一宽度，保证并行生图画廊与长行内容的阅读体验。 */
  --chat-content-max: 720px;
  flex-grow: var(--chat-flex-grow, 0);
  flex-shrink: 1;
  flex-basis: auto;
  overflow-y: auto;
  scrollbar-gutter: stable;
  scrollbar-color: transparent transparent;
  /* Bottom padding matches the mask fade height so the latest message rests
     fully above the fade zone when stuck to the bottom. */
  padding: 16px 20px 35px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* 用户消息定位遮罩与 .chat-area 共用内容宽度梯度（骨架屏与消息列同宽）。
   基础值在此，视口断点梯度见上方的 @media 段。 */
.user-message-locate-overlay {
  --chat-content-max: 720px;
}

.chat-area.is-scroll-anchor-off {
  overflow-anchor: none;
}

.chat-area::-webkit-scrollbar {
  width: 8px;
}
.chat-area::-webkit-scrollbar-thumb {
  background-color: transparent;
  transition: background-color 0.15s ease;
  border: 2px solid transparent;
  background-clip: content-box;
}
.chat-area.is-hovering-scrollbar,
.chat-area.is-wheelscrolling {
  scrollbar-color: var(--scrollbar-thumb) transparent;
}
.chat-area.is-hovering-scrollbar::-webkit-scrollbar-thumb,
.chat-area.is-wheelscrolling::-webkit-scrollbar-thumb {
  background-color: var(--scrollbar-thumb);
}
.chat-area.is-hovering-scrollbar::-webkit-scrollbar-thumb:hover,
.chat-area.is-wheelscrolling::-webkit-scrollbar-thumb:hover {
  background-color: var(--scrollbar-thumb-hover);
}
.chat-area.is-hovering-scrollbar::-webkit-scrollbar-thumb:active,
.chat-area.is-wheelscrolling::-webkit-scrollbar-thumb:active {
  background-color: var(--scrollbar-thumb-active);
}

/* 消息区响应式宽度梯度（按视口宽度分档，兼容 1366×768 ~ 4K/带鱼屏）：
   <1024px（小窗/平板）       720px —— 窄屏保持紧凑单列阅读
   ≥1024px（1280 笔记本）     860px
   ≥1280px（1440 屏）        1000px
   ≥1440px（1600 屏及以上）  1120px —— 与输入框 .input-content 的 max-width
   保持一致并封顶：全屏/超宽屏下消息列不再继续加宽，AI 消息左边界与用户
   消息右边界始终对齐输入框左右边界（否则两侧消息相隔过远）。 */
@media (min-width: 1024px) {
  .chat-area,
  .user-message-locate-overlay {
    --chat-content-max: 860px;
  }
}

@media (min-width: 1280px) {
  .chat-area,
  .user-message-locate-overlay {
    --chat-content-max: 1000px;
  }
}

@media (min-width: 1440px) {
  .chat-area,
  .user-message-locate-overlay {
    --chat-content-max: 1120px;
  }
}

.chat-input-region {
  position: relative;
  flex-shrink: 0;
}

/* Info header at the top of a sub-agent conversation's message list: agent
   badge + stage title (the prompt truncated at activation) + a shortcut back
   to the launching parent conversation + the full delegated prompt. Width
   follows the --chat-content-max gradient like every other chat-area element. */
.sub-agent-info-header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(100%, var(--chat-content-max));
  min-width: 0;
  margin: 0 auto;
  padding: 14px 16px;
  border: 1px solid var(--border-subtle, var(--border-color));
  border-radius: var(--radius-lg);
  background: var(--bg-secondary, transparent);
  box-shadow: var(--shadow-sm, none);
}

.sub-agent-info-header-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.sub-agent-info-agent {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 3px 9px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.4;
}

.sub-agent-info-agent svg {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.sub-agent-info-agent span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sub-agent-info-parent {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 4px 8px;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-tertiary);
  font-size: 12px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.sub-agent-info-parent:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.sub-agent-info-parent svg {
  flex-shrink: 0;
}

.sub-agent-info-parent span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sub-agent-info-title {
  overflow: hidden;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.45;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sub-agent-info-prompt {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding-top: 10px;
  border-top: 1px solid var(--border-subtle, var(--border-color));
}

/* Read-only footer that replaces the input box in a sub-agent conversation
   whose run has ended (completed / failed / cancelled). The conversation
   stays browsable, but no further messages can be sent into it. */
.sub-agent-finished-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 8px;
  border-radius: var(--radius-lg);
  color: var(--text-secondary);
  font-size: 12.5px;
  /* 小面积元素保留毛玻璃（--backdrop-blur-lg 已置 none 以消除大面开销） */
  backdrop-filter: blur(18px) saturate(1.16);
}

.sub-agent-finished-bar-status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.sub-agent-finished-bar-status svg {
  flex-shrink: 0;
  color: var(--accent-green, #22c55e);
}

.sub-agent-finished-bar.is-error .sub-agent-finished-bar-status svg {
  color: var(--accent-red-text, #ef4444);
}

.sub-agent-finished-bar-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
  padding: 6px 10px;
  border: none;
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.sub-agent-finished-bar-back:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* 子代理请求失败挂起：重试 / 放弃 */
.sub-agent-retry-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.sub-agent-finished-bar-back.is-primary {
  background: var(--text-primary);
  color: var(--on-solid);
}

.sub-agent-finished-bar-back.is-primary:hover {
  background: var(--text-primary);
  color: var(--on-solid);
  opacity: 0.88;
}

/* ===== User Message Rail (edge count pill) =====
   A glass capsule hugging the chat column's right edge: bubble icon + user
   message count. On hover it slides slightly outward and expands a floating
   popover listing all user messages for quick navigation. The popover is
   portaled to document.body so it is never clipped by the chat-area mask or
   overflow.
   The count is a flex sibling of the icon, so any number of digits simply
   widens the capsule instead of squeezing the icon — no fixed geometry needed.
   .main-content keeps its own padding, so a small gap to the island edge is
   inherent; the capsule is a floating control over the chat column and does
   not try to be flush with that edge. */
.user-message-rail {
  position: absolute;
  z-index: 4;
  top: 50%;
  right: 0;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 10px 0 9px;
  border-radius: 999px;
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  color: var(--text-tertiary);
  cursor: pointer;
  box-shadow: var(--island-shadow);
  /* 小面积元素保留毛玻璃（--backdrop-blur-lg 已置 none 以消除大面开销） */
  backdrop-filter: blur(18px) saturate(1.16);
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;
  -webkit-app-region: no-drag;
  user-select: none;
}

.user-message-rail:hover {
  background: var(--surface-island-strong);
  border-color: var(--border-color);
  color: var(--text-primary);
}

.user-message-rail-count {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.user-message-rail:hover .user-message-rail-count {
  color: var(--text-primary);
}

/* Floating popover (portaled to body). Position is set inline via JS so it
   hugs the rail's left edge and opens leftward. */
.user-message-rail-popover {
  position: fixed;
  z-index: 10000;
  display: flex;
  flex-direction: column;
  width: 260px;
  max-height: min(60vh, 520px);
  border-radius: var(--radius-lg);
  background: var(--surface-island-strong);
  border: 1px solid var(--border-subtle);
  box-shadow: var(--island-shadow);
  /* 小面积元素保留毛玻璃（--backdrop-blur-lg 已置 none 以消除大面开销） */
  backdrop-filter: blur(18px) saturate(1.16);
  overflow: hidden;
  animation: user-message-rail-popover-in 0.14s ease-out;
  -webkit-app-region: no-drag;
}

@keyframes user-message-rail-popover-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.user-message-rail-popover-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-tertiary);
  font-size: 11px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  flex-shrink: 0;
}

.user-message-rail-popover-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 18px;
  padding: 0 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.user-message-rail-popover-search {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-color);
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.user-message-rail-popover-search input {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: none;
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 12px;
  line-height: 1.4;
}

.user-message-rail-popover-search input::placeholder {
  color: var(--text-tertiary);
}

.user-message-rail-popover-search-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
}

.user-message-rail-popover-search-clear:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.user-message-rail-popover-empty {
  padding: 18px 12px;
  color: var(--text-tertiary);
  font-size: 12px;
  text-align: center;
}

.user-message-rail-popover-item.is-active {
  background: var(--bg-active);
  color: var(--text-primary);
}

.user-message-rail-popover-item.is-active
  .user-message-rail-popover-item-index {
  background: var(--accent-primary, var(--text-tertiary));
  color: var(--on-solid);
}

.user-message-rail-popover-list {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 6px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.user-message-rail-popover-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  width: 100%;
  padding: 7px 10px;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.4;
  text-align: left;
  cursor: pointer;
  transition:
    background 0.1s ease,
    color 0.1s ease;
}

.user-message-rail-popover-item:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.user-message-rail-popover-item.is-visible {
  background: var(--accent-primary-bg, var(--bg-active));
  color: var(--accent-primary-text, var(--text-primary));
}

.user-message-rail-popover-item.is-visible
  .user-message-rail-popover-item-index {
  background: var(--accent-primary, var(--text-tertiary));
  color: var(--on-solid);
}

.user-message-rail-popover-item-index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-width: 18px;
  height: 18px;
  margin-top: 1px;
  padding: 0 3px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 1;
}

.user-message-rail-popover-item:hover .user-message-rail-popover-item-index {
  background: var(--accent-primary, var(--text-tertiary));
  color: var(--on-solid);
}

.user-message-rail-popover-item-text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  word-break: break-word;
}

.user-message-rail-popover-item-text .user-message-file-chip {
  max-width: 180px;
}

/* ===== 用户消息定位遮罩 =====
   目标消息还压在未加载的分页里时，定位全程给 .chat-area 挂上
   .is-locating-message：消息列表只隐藏绘制（不影响布局与 rect，翻页锚点校正
   和目标的 scrollIntoView 照常工作），这层骨架屏盖在滚动容器的位置上接管
   视觉——翻页期间的轻微抖动与最后一帧的瞬间跳转都不会被看到。
   隐藏用 opacity 而非 visibility：消息树里有显式声明 visibility: visible 的
   子节点（如折叠展开的 .tcg-collapse.is-open），会把父级的 visibility: hidden
   漏穿；opacity 整棵子树一起生效，子节点无从抵消。 */
.chat-area.is-locating-message .chat-message-list {
  opacity: 0;
}

/* 坐标由 JS 按滚动容器的视口矩形写入（见 UserMessageRail），此处只负责铺满
   该矩形并把骨架屏垂直居中。期间吞掉消息区的点击：内容不可见时不应还能点到
   里面（输入区不在遮罩范围内，仍可正常使用）。与 .chat-area 共用
   --chat-content-max 梯度，保证骨架屏与消息列同宽。 */
.user-message-locate-overlay {
  position: fixed;
  z-index: 3;
  display: flex;
  flex-direction: column;
  justify-content: center;
  -webkit-app-region: no-drag;
}

.chat-scroll-to-bottom {
  position: absolute;
  z-index: 3;
  top: 0;
  left: 50%;
  display: inline-flex;
  width: 40px;
  height: 40px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: 1px solid var(--border-subtle);
  border-radius: 50%;
  background: var(--surface-island-strong);
  color: var(--text-primary);
  box-shadow:
    0 8px 24px rgba(0, 0, 0, 0.14),
    0 2px 6px rgba(0, 0, 0, 0.08);
  cursor: pointer;
  transform: translate(-50%, calc(-100% - 6px));
  transition:
    background-color 0.16s ease,
    border-color 0.16s ease,
    box-shadow 0.16s ease,
    transform 0.16s ease;
  animation: chat-scroll-to-bottom-in 0.16s ease-out;
  -webkit-app-region: no-drag;
}

.chat-scroll-to-bottom:hover {
  border-color: var(--border-color);
  background: var(--bg-hover);
}

.chat-scroll-to-bottom:active {
  transform: translate(-50%, calc(-100% - 5px));
}

.chat-scroll-to-bottom:focus-visible {
  outline: 2px solid var(--text-tertiary);
  outline-offset: 2px;
}

.chat-scroll-to-bottom svg {
  display: block;
}

/* AI Loop running: rotating halo ring around the button */
.chat-scroll-to-bottom.is-streaming::before {
  content: "";
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: conic-gradient(
    from 0deg,
    transparent 0deg,
    var(--accent-blue) 60deg,
    transparent 140deg,
    transparent 360deg
  );
  -webkit-mask: radial-gradient(
    farthest-side,
    transparent calc(100% - 2px),
    #000 calc(100% - 2px)
  );
  mask: radial-gradient(
    farthest-side,
    transparent calc(100% - 2px),
    #000 calc(100% - 2px)
  );
  animation: chat-scroll-to-bottom-halo 1s linear infinite;
  pointer-events: none;
}

@keyframes chat-scroll-to-bottom-halo {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes chat-scroll-to-bottom-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-scroll-to-bottom,
  .chat-scroll-to-bottom.is-streaming::before {
    animation: none;
    transition: none;
  }
}

/* Empty state keeps the composer at the bottom and centers the greeting above it. */
.chat-content.is-empty {
  justify-content: flex-start;
  padding: 0;
}

.chat-content.is-empty .chat-area {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  justify-content: safe center;
  padding-bottom: 24px;
}

.chat-content.is-empty .chat-empty-greeting {
  margin-top: 0;
}

.chat-content.is-empty .chat-input-region {
  margin-top: 0;
}

@media (max-height: 800px) {
  .chat-content.is-empty {
    overflow: hidden;
  }

  .chat-content.is-empty .chat-area {
    justify-content: flex-start;
    padding-bottom: 0;
  }
}

/* Has-messages state: chat-area grows to fill, pushing input to bottom */
.chat-content.has-messages {
  padding-bottom: 0;
}

.chat-content.has-messages .chat-area {
  --chat-flex-grow: 1;
  /* Mask layer at the input-area seam: messages fade to fully transparent as
     they enter the bottom 48px, revealing the single island surface below.
     A real transparency mask is used instead of backdrop-filter blur, which
     smeared bright text into a visible halo in dark themes. The stops
     approximate a smoothstep ease so the fade starts gently instead of
     cutting in along a visible line. */
  -webkit-mask-image: linear-gradient(
    to bottom,
    black calc(100% - 48px),
    rgba(0, 0, 0, 0.96) calc(100% - 42px),
    rgba(0, 0, 0, 0.84) calc(100% - 36px),
    rgba(0, 0, 0, 0.68) calc(100% - 30px),
    rgba(0, 0, 0, 0.5) calc(100% - 24px),
    rgba(0, 0, 0, 0.32) calc(100% - 18px),
    rgba(0, 0, 0, 0.16) calc(100% - 12px),
    rgba(0, 0, 0, 0.04) calc(100% - 6px),
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    black calc(100% - 48px),
    rgba(0, 0, 0, 0.96) calc(100% - 42px),
    rgba(0, 0, 0, 0.84) calc(100% - 36px),
    rgba(0, 0, 0, 0.68) calc(100% - 30px),
    rgba(0, 0, 0, 0.5) calc(100% - 24px),
    rgba(0, 0, 0, 0.32) calc(100% - 18px),
    rgba(0, 0, 0, 0.16) calc(100% - 12px),
    rgba(0, 0, 0, 0.04) calc(100% - 6px),
    transparent 100%
  );
}

.chat-area.is-loading-history {
  align-items: stretch;
  justify-content: center;
}

.chat-initial-history-skeleton {
  display: flex;
  width: min(100%, var(--chat-content-max));
  min-height: 192px;
  margin: 0 auto;
  flex-direction: column;
  justify-content: center;
  gap: 24px;
}

.chat-message-skeleton {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.chat-message-skeleton.is-user {
  align-items: flex-end;
}

/* 流光走 transform（合成线程驱动）而非 background-position（主线程逐帧重绘）：
   骨架屏出现时主线程往往正忙于翻页挂载与布局（定位遮罩、首屏历史加载），
   重绘驱动的动画会随之卡顿，失去加载反馈的意义。底色在行本身，高光是
   ::after 上的一条渐变带，整体平移扫过。 */
.chat-message-skeleton-line {
  position: relative;
  height: 12px;
  overflow: hidden;
  border-radius: var(--radius-sm);
  background-color: var(--bg-hover);
}

.chat-message-skeleton-line::after {
  content: "";
  position: absolute;
  inset: 0;
  background-image: linear-gradient(
    90deg,
    transparent 34%,
    var(--border-subtle) 50%,
    transparent 66%
  );
  transform: translateX(-100%);
  animation: chat-skeleton-sweep 1.5s linear infinite;
  will-change: transform;
}

.chat-message-skeleton-line.is-primary {
  width: 88%;
}

.chat-message-skeleton-line.is-secondary {
  width: 68%;
}

.chat-message-skeleton-line.is-tertiary {
  width: 42%;
}

.chat-message-skeleton.is-user .chat-message-skeleton-line {
  background-color: var(--bg-tertiary);
}

.chat-message-skeleton.is-user .chat-message-skeleton-line.is-primary {
  width: 42%;
}

.chat-message-skeleton.is-user .chat-message-skeleton-line.is-secondary {
  width: 28%;
}

@keyframes chat-skeleton-sweep {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(100%);
  }
}

@keyframes skeleton-shimmer {
  from {
    background-position: 150% 0;
  }
  to {
    background-position: -50% 0;
  }
}

.chat-empty-greeting {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 0;
  margin-bottom: 28px;
  padding: 0 20px;
  text-align: center;
  /* 容器查询锚点：quick-actions 依据此宽度决定自动隐藏 */
  container-type: inline-size;
  container-name: chat-greeting;
}

.chat-empty-greeting-brand {
  display: flex;
  align-items: center;
  justify-content: center;
}

.chat-empty-greeting-logo {
  width: auto;
  height: 52px;
  color: var(--text-primary);
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  opacity: 0.95;
}

.pixel-logo {
  display: block;
  overflow: visible;
  cursor: default;
  transition: filter 0.6s ease;
}

.pixel-logo.is-frozen {
  filter: drop-shadow(0 0 8px rgba(125, 211, 252, 0.45));
}

.pixel-logo-pixel-frost {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.6s ease;
}

.pixel-logo.is-frozen .pixel-logo-pixel-frost {
  opacity: 1;
}

.pixel-logo-flake {
  fill: #aedcf5;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.35s ease;
}

.pixel-logo.is-snowing .pixel-logo-flake {
  animation-name: pixel-logo-snowfall;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
}

.pixel-logo-icicle {
  transform: scaleY(0);
  transform-box: fill-box;
  transform-origin: 50% 0;
  pointer-events: none;
  transition: transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.pixel-logo.is-frozen .pixel-logo-icicle {
  transform: scaleY(1);
}

.pixel-logo-drip {
  fill: #cfeafb;
  opacity: 0;
  pointer-events: none;
}

.pixel-logo-deco {
  opacity: 0;
  transform: translateY(2.5px) scale(0.5);
  transform-box: fill-box;
  transform-origin: 50% 100%;
  pointer-events: none;
  transition:
    opacity 0.4s ease,
    transform 0.5s cubic-bezier(0.34, 1.56, 0.64, 1);
}
.pixel-logo.is-frozen .pixel-logo-deco {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.pixel-logo-snowcap {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s ease;
}

.pixel-logo.is-frozen .pixel-logo-snowcap {
  opacity: 1;
}

.pixel-logo-reflection {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.9s ease;
}

.pixel-logo.is-frozen .pixel-logo-reflection {
  opacity: 0.6;
}

.pixel-logo-sky {
  opacity: 0;
  pointer-events: none;
  transition: opacity 1.1s ease;
}

.pixel-logo.is-frozen .pixel-logo-sky {
  opacity: 1;
}

.pixel-logo-aurora-band {
  filter: blur(2px);
}

.pixel-logo.is-frozen .pixel-logo-aurora-band {
  animation: pixel-logo-aurora-drift 8s ease-in-out infinite alternate;
}

@keyframes pixel-logo-aurora-drift {
  from {
    transform: translateX(-3px) skewX(-5deg);
  }
  to {
    transform: translateX(3px) skewX(5deg);
  }
}

.pixel-logo-star {
  fill: #ffffff;
  opacity: 0.25;
}

.pixel-logo.is-frozen .pixel-logo-star {
  animation-name: pixel-logo-twinkle;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
}

@keyframes pixel-logo-twinkle {
  0%,
  100% {
    opacity: 0.15;
  }
  50% {
    opacity: 0.95;
  }
}

.pixel-logo-sparkle {
  opacity: 0;
  transform-box: fill-box;
  transform-origin: 50% 50%;
  pointer-events: none;
}

.pixel-logo.is-frozen .pixel-logo-sparkle {
  animation-name: pixel-logo-sparkle;
  animation-timing-function: ease-in-out;
  animation-iteration-count: infinite;
}

@keyframes pixel-logo-sparkle {
  0%,
  100% {
    opacity: 0;
    transform: scale(0.3) rotate(0deg);
  }
  50% {
    opacity: 0.95;
    transform: scale(1) rotate(90deg);
  }
}

.pixel-logo-flame {
  transform-box: fill-box;
  transform-origin: 50% 100%;
}

.pixel-logo.is-frozen .pixel-logo-flame {
  animation: pixel-logo-flicker 0.9s ease-in-out infinite;
}

@keyframes pixel-logo-flicker {
  0%,
  100% {
    transform: scale(1, 1);
  }
  30% {
    transform: scale(0.94, 1.12);
  }
  60% {
    transform: scale(1.06, 0.9);
  }
}

.pixel-logo-penguin {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.pixel-logo.is-frozen .pixel-logo-penguin {
  animation-name: pixel-logo-penguin-enter;
  animation-duration: 3s;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

@keyframes pixel-logo-penguin-enter {
  0% {
    transform: translateX(var(--penguin-from, -40px));
    opacity: 0;
  }
  4% {
    opacity: 1;
  }
  100% {
    transform: translateX(0);
    opacity: 1;
  }
}

.pixel-logo-penguin-body {
  transform-box: fill-box;
  transform-origin: 50% 100%;
}

.pixel-logo.is-frozen .pixel-logo-penguin-body {
  animation: pixel-logo-waddle 0.7s ease-in-out infinite;
}

@keyframes pixel-logo-waddle {
  0%,
  100% {
    transform: rotate(-5deg);
  }
  50% {
    transform: rotate(5deg);
  }
}

.pixel-logo.is-frozen .pixel-logo-drip {
  animation-name: pixel-logo-drip;
  animation-timing-function: ease-in;
  animation-iteration-count: infinite;
}

@keyframes pixel-logo-drip {
  0% {
    transform: translateY(0);
    opacity: 0;
  }
  8% {
    opacity: 0.95;
  }
  70% {
    opacity: 0.95;
  }
  100% {
    transform: translateY(var(--drip-fall, 14px));
    opacity: 0;
  }
}

@keyframes pixel-logo-snowfall {
  0% {
    transform: translate(0, -4px);
    opacity: 0;
  }
  12% {
    opacity: var(--flake-opacity, 0.9);
  }
  85% {
    opacity: var(--flake-opacity, 0.9);
  }
  100% {
    transform: translate(var(--flake-drift, 0px), var(--flake-fall, 26px));
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pixel-logo.is-snowing .pixel-logo-flake,
  .pixel-logo.is-frozen .pixel-logo-drip,
  .pixel-logo.is-frozen .pixel-logo-sparkle,
  .pixel-logo.is-frozen .pixel-logo-star,
  .pixel-logo.is-frozen .pixel-logo-flame,
  .pixel-logo.is-frozen .pixel-logo-penguin-body,
  .pixel-logo.is-frozen .pixel-logo-aurora-band {
    animation: none;
  }

  .pixel-logo.is-snowing .pixel-logo-flake,
  .pixel-logo.is-frozen .pixel-logo-drip,
  .pixel-logo.is-frozen .pixel-logo-sparkle {
    opacity: 0;
  }

  .pixel-logo.is-frozen .pixel-logo-penguin {
    animation: none;
    opacity: 1;
  }
}

.chat-empty-greeting-title {
  max-width: 420px;
  margin: 32px 0 0;
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.6;
  /* Long unbroken names (e.g. SSH remote workspace paths like
     user@host:/very/long/path) must wrap instead of overflowing. */
  overflow-wrap: anywhere;
  min-width: 0;
}

/* 空状态「使用指南」提示行：欢迎语下方，可收起 */
.chat-empty-help-hint {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin: 8px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.5;
}

.chat-empty-help-hint svg {
  flex-shrink: 0;
}

.chat-empty-help-hint-action,
.chat-empty-help-hint-dismiss {
  padding: 0 2px;
  border: 0;
  border-radius: 4px;
  background: none;
  color: var(--text-secondary);
  font: inherit;
  text-decoration: underline;
  text-underline-offset: 3px;
  cursor: pointer;
}

.chat-empty-help-hint-action:hover,
.chat-empty-help-hint-dismiss:hover {
  color: var(--text-primary);
}

.chat-empty-help-hint-action:focus-visible,
.chat-empty-help-hint-dismiss:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--focus-ring);
}

/* Quick action cards in empty chat state */
.chat-empty-quick-actions {
  --quick-gap: 12px;
  position: relative;
  display: flex;
  align-items: stretch;
  justify-content: center;
  gap: var(--quick-gap);
  /* 占满问候列内容宽：shrink-to-fit 会在跨断点收卡时随剩余卡片塌缩并整体
     重新居中，盒内百分比基准漂移导致隐藏卡钉位错位形变；盒宽恒等于容器
     查询宽度后基准稳定，隐藏卡得以按断点处固定尺寸逐像素钉回原槽位 */
  width: 100%;
  margin-top: 96px;
  /* 极窄时整体淡出；visibility 离散过渡保证淡出结束才不可见、淡入立即开始 */
  transition:
    opacity 0.28s ease,
    transform 0.28s ease,
    visibility 0.28s ease;
}

/* 宽度决定可见卡片数：单卡低于约 176px 舒适下限时从尾部逐张收起。
   断点处满员行恰好铺满盒宽，行尾槽位即盒的 inline-end 边缘，故隐藏卡
   absolute 钉在行尾、以断点处的固定卡宽（由断点宽度反推）淡出淡入——
   不参与 flex 行高，尺寸不随容器继续缩放而形变；恢复时固定尺寸与回流
   槽位逐像素重合，仅做淡入 */
@container chat-greeting (max-width: 551px) {
  .chat-empty-quick-actions .chat-empty-quick-card {
    width: calc((100% - var(--quick-gap)) / 2);
  }

  .chat-empty-quick-card:nth-child(3) {
    position: absolute;
    top: 0;
    inset-inline-end: 0;
    width: calc((551px - var(--quick-gap) * 2) / 3);
    opacity: 0;
    visibility: hidden;
    transform: translateY(6px);
  }
}

@container chat-greeting (max-width: 363px) {
  .chat-empty-quick-actions .chat-empty-quick-card {
    width: 100%;
  }

  .chat-empty-quick-card:nth-child(2) {
    position: absolute;
    top: 0;
    inset-inline-end: 0;
    width: calc((363px - var(--quick-gap)) / 2);
    opacity: 0;
    visibility: hidden;
    transform: translateY(6px);
  }

  /* 已完全隐藏，直接脱离渲染层 */
  .chat-empty-quick-card:nth-child(3) {
    display: none;
  }
}

@container chat-greeting (max-width: 219px) {
  .chat-empty-quick-card:nth-child(1) {
    position: absolute;
    top: 0;
    inset-inline: 0;
    margin-inline: auto;
    width: 219px;
    opacity: 0;
    visibility: hidden;
    transform: translateY(6px);
  }

  .chat-empty-quick-card:nth-child(2),
  .chat-empty-quick-card:nth-child(3) {
    display: none;
  }

  .chat-empty-quick-actions {
    opacity: 0;
    visibility: hidden;
    transform: translateY(6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .chat-empty-quick-actions,
  .chat-empty-quick-card {
    transition: none;
  }
}

.chat-empty-quick-card {
  position: relative;
  display: block;
  width: calc((100% - var(--quick-gap) * 2) / 3);
  min-width: 0;
  max-width: 220px;
  overflow: hidden;
  padding: 16px 18px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--surface-island-muted);
  color: var(--text-primary);
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    opacity 0.28s ease,
    transform 0.28s ease,
    width 0.28s ease,
    visibility 0.28s ease;
}

.chat-empty-quick-card:hover:not(:disabled) {
