  opacity: 0.7;
}

.chat-empty-quick-card-icon {
  position: absolute;
  top: 14px;
  left: 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--accent-green-text);
}
.chat-empty-quick-card.is-api .chat-empty-quick-card-icon {
  color: var(--accent-amber-text);
}

.chat-empty-quick-card.is-theme .chat-empty-quick-card-icon {
  color: var(--text-tertiary);
}

.chat-empty-quick-card-icon svg {
  display: block;
}

.chat-empty-quick-card-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  padding-left: 24px;
}

.chat-empty-quick-card-title {
