  border-radius: 7px;
  background: var(--bg-primary);
  color: var(--text-secondary);
  font-size: 11.5px;
  font-family: inherit;
  cursor: pointer;
  transition:
    background-color 0.12s ease,
    color 0.12s ease;
}

.memory-panel-locate-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.memory-panel-delete-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-primary);
  color: var(--accent-red-text);
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition:
    background-color 0.12s ease,
    border-color 0.12s ease;
}

.memory-panel-delete-btn:hover:not(:disabled) {
  background: var(--accent-red-bg);
  border-color: transparent;
}

.memory-panel-delete-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.memory-panel-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 28px 16px;
  text-align: center;
  color: var(--text-secondary);
}

.memory-panel-empty-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.memory-panel-empty-hint {
  max-width: 360px;
  font-size: 12px;
  color: var(--text-tertiary);
}

/* ===== Code review panel (/review) ===== */
.review-modal .app-modal-body {
  max-height: 66vh;
  overflow-y: auto;
}

.review-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.review-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 32px 16px;
  color: var(--text-secondary);
  font-size: 12.5px;
}

.review-error {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--accent-red-bg, rgba(248, 113, 113, 0.35));
  border-radius: 8px;
  background: var(--accent-red-bg, rgba(248, 113, 113, 0.12));
  color: var(--accent-red-text, #f87171);
  font-size: 12.5px;
}

.review-error span {
  flex: 1;
  min-width: 0;
}

.review-retry-btn,
.review-refresh-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border: 1px solid var(--border-color);
  border-radius: 7px;
  background: var(--bg-primary);
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background-color 0.12s ease,
    color 0.12s ease;
}

.review-retry-btn:hover,
.review-refresh-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.review-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 28px 16px;
  text-align: center;
  color: var(--text-secondary);
}

.review-empty-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.review-empty-hint {
  max-width: 340px;
  font-size: 12px;
  color: var(--text-tertiary);
}

.review-content {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.review-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 2px;
}

.review-branch {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Code",
    Consolas,
    "Courier New",
    monospace
  );
  font-size: 11.5px;
  color: var(--text-secondary);
}

.review-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.review-section-header {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 2px;
}

.review-section-title {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.review-select-all {
  margin-left: auto;
  padding: 1px 8px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background-color 0.12s ease,
    color 0.12s ease;
}

.review-select-all:hover {
  background: var(--bg-hover);
  color: var(--accent-primary-text, var(--text-primary));
}

.review-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 200px;
  overflow-y: auto;
  border: 1px solid var(--border-light);
  border-radius: 8px;
  background: var(--bg-secondary);
}

/* 提交记录列表：更高的可视区域以承载无限滚动。 */
.review-list.is-commits {
  max-height: 260px;
}

.review-load-more {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 9px 8px;
  font-size: 11px;
  color: var(--text-tertiary);
  cursor: default;
  user-select: none;
}

.review-load-more.is-done {
  color: var(--text-tertiary);
  opacity: 0.8;
}

.review-file-row,
.review-commit-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: 6px;
  font-size: 12px;
  min-width: 0;
  cursor: pointer;
  user-select: none;
  transition: background-color 0.12s ease;
}

.review-file-row:hover,
.review-commit-row:hover {
  background: var(--surface-island-strong);
}

.review-file-row.is-selected,
.review-commit-row.is-selected {
  background: var(--accent-primary-bg, var(--bg-active));
}

.review-check {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  border: 1.5px solid var(--border-color);
  border-radius: 4px;
  flex-shrink: 0;
  color: transparent;
  background: var(--bg-primary);
  transition:
    border-color 0.12s ease,
    background-color 0.12s ease;
}

.review-check.is-checked {
  border-color: var(--accent-primary, var(--text-primary));
  background: var(--accent-primary, var(--text-primary));
  color: var(--on-solid);
}

.review-file-path {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Code",
    Consolas,
    "Courier New",
    monospace
  );
  font-size: 11.5px;
}

.review-kind {
  display: inline-flex;
  align-items: center;
  padding: 0 7px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 600;
  line-height: 17px;
  white-space: nowrap;
  flex-shrink: 0;
}

.review-kind.is-staged {
  background: var(--accent-primary-bg, var(--bg-active));
  color: var(--accent-primary-text, var(--text-primary));
}

.review-kind.is-unstaged {
  background: var(--accent-yellow-bg, rgba(250, 204, 21, 0.16));
  color: var(--accent-amber-text, #facc15);
}

.review-kind.is-untracked {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.review-commit-icon {
  color: var(--text-secondary);
  flex-shrink: 0;
}

.review-commit-hash {
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Code",
    Consolas,
    "Courier New",
    monospace
  );
  font-size: 11px;
  color: var(--accent-primary-text, var(--text-secondary));
  flex-shrink: 0;
}

.review-commit-message {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.review-commit-author {
  flex-shrink: 0;
  max-width: 120px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  font-size: 11px;
}

.review-commit-date {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.review-section-empty {
  padding: 8px 12px;
  font-size: 11.5px;
  color: var(--text-tertiary);
}

.review-instructions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 0 2px;
}

.review-instructions-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.review-instructions-input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12.5px;
  font-family: inherit;
  resize: vertical;
  outline: none;
  transition: border-color 0.12s ease;
}

.review-instructions-input:focus {
  border-color: var(--accent-color);
}

.review-footer {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
}

.review-selected-count {
  flex: 1;
  font-size: 12px;
  color: var(--text-secondary);
}

.review-start-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 16px;
  border: none;
  border-radius: 8px;
  background: var(--accent-primary, var(--text-primary));
  color: var(--on-solid);
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.12s ease;
}

.review-start-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

/* Intermediate status card shown while the backend describes user images
   with the external vision model (textify pass). Lives at the end of the
   message list; fixed min-height keeps the scrollbar stable. */
.chat-vision-status {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 32px;
  padding: 6px 12px;
  margin-top: 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 12px;
  animation: chat-enter 0.2s ease-out both;
}

.chat-vision-status-spinner {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  border: 2px solid var(--border-light);
  border-top-color: var(--accent, var(--text-secondary));
  border-radius: 50%;
  animation: chat-vision-status-spin 0.8s linear infinite;
}

@keyframes chat-vision-status-spin {
  to {
    transform: rotate(360deg);
  }
}

.chat-vision-status-progress {
  font-variant-numeric: tabular-nums;
  color: var(--text-tertiary);
}

.chat-vision-status-model {
  margin-left: auto;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-tertiary);
  font-family: var(--font-mono, monospace);
}

/* Informational banner at the top of a conversation that was created by a
   scheduled task firing. */
.chat-task-triggered-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  padding: 5px 12px;
  margin-bottom: 8px;
  border: 1px dashed var(--accent-amber, var(--border-light));
  border-radius: var(--radius-sm);
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
  font-size: 12px;
}

.chat-task-triggered-banner svg {
  flex-shrink: 0;
}

.chat-task-triggered-text {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chat-task-triggered-time {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}

.chat-message-group {
  display: flex;
  flex-direction: column;
  gap: 10px;
  /* 消息首次挂载时柔和浮现，替代瞬间跳变。虚拟化回显（滚回视口的重新
     挂载）由 .virtualized-message.is-replay 抑制动画（见下方规则），
     避免内容重建时整片消息区闪烁。 */
  animation: chat-enter 0.18s ease-out both;
}

/* ===== Agent loop 入场动画 =====
   统一用于"新节点挂载"场景：用户消息、工具卡片、任务摘要条、
   视觉分析状态卡等。只定义 from 帧，to 帧自然落到元素常规样式，
   动画结束后无残留 transform，不影响内部 fixed/absolute 定位。 */
@keyframes chat-enter {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
}

@keyframes chat-fade-in {
  from {
    opacity: 0;
  }
}

.chat-message-hook-container {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: 8px;
}

/* ===== IM 聊天风格：头像 + 消息体并排，用户消息头像在右 ===== */
.chat-im-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.chat-im-row.is-user {
  flex-direction: row-reverse;
}

.chat-im-row > .chat-message-group {
  flex: 1;
  min-width: 0;
}

.chat-im-avatar {
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
}

.chat-im-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  border: 1px solid var(--border-light);
  border-radius: 50%;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  user-select: none;
}

.chat-im-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.chat-im-avatar.is-pet img {
  object-fit: contain;
}

/* 用户默认头像跟随主题色（--accent-color），不写死品牌蓝 */
.chat-im-row.is-user .chat-im-avatar.is-icon {
  background: color-mix(in srgb, var(--accent-color) 14%, transparent);
  color: var(--accent-color);
}

/* 设置面板：AI / 我的头像并排卡片，各自独立更换与重置 */
.theme-chat-avatar-list {
  display: grid;
  max-width: 640px;
  grid-template-columns: repeat(auto-fit, minmax(176px, 1fr));
  gap: 12px;
}

.theme-chat-avatar-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 18px 12px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--bg-primary);
}

.chat-im-avatar.theme-chat-avatar-preview {
  width: 64px;
  height: 64px;
}

.chat-im-avatar.theme-chat-avatar-preview.is-icon svg {
  width: 28px;
  height: 28px;
}

/* 预览中的默认用户头像同样跟随主题色 */
.chat-im-avatar.theme-chat-avatar-preview.is-user.is-icon {
  background: color-mix(in srgb, var(--accent-color) 14%, transparent);
  color: var(--accent-color);
}

.theme-chat-avatar-meta {
  display: flex;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  text-align: center;
}

.theme-chat-avatar-label {
  color: var(--text-primary);
  font-size: 13px;
}

.theme-chat-avatar-hint {
  color: var(--text-tertiary);
  font-size: 12px;
  overflow-wrap: anywhere;
}

.theme-chat-avatar-actions {
  display: flex;
  justify-content: center;
  gap: 8px;
  width: 100%;
}

.theme-chat-avatar-actions .api-settings-form-btn {
  min-width: 88px;
  gap: 6px;
  padding: 7px 12px;
}

.theme-chat-avatar-actions .api-settings-form-btn:disabled {
  opacity: 0.45;
}

/* Virtualized message wrapper. When visible, it just renders children
   without interference. When virtualized out, it becomes a fixed-height
   placeholder that reserves space so the scrollbar does not jump.
   content-visibility on the inner .chat-message-group is no longer needed
   because off-screen messages are fully unmounted by VirtualizedMessage. */
.virtualized-message.is-visible {
  display: block;
}

.virtualized-message.is-placeholder {
  /* Height is set inline by VirtualizedMessage based on the last measured
     value. Keep the node paint-cheap: no background, no children. */
  contain: strict;
}

/* 虚拟化回显（滚回视口 / 可见集恢复导致的重新挂载）：不重播入场动画，
   避免消息内容重建时整片区域闪烁。消息的首次出现仍播放 chat-enter。 */
.virtualized-message.is-replay > .chat-message-group,
.virtualized-message.is-replay .tcg,
.virtualized-message.is-replay .tcn,
.virtualized-message.is-replay .response-incomplete-notice,
.virtualized-message.is-replay .ai-response-actions {
  animation: none;
}

/* Tool-role messages render nothing but must keep a stable React key. */
.chat-message-hidden {
  display: none;
}

.ai-message-summary.is-streaming::after,
.stream-cursor-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  vertical-align: 0.05em;
  animation: stream-dot-pulse 1s ease-in-out infinite;
  content: "";
}

/* 流式输出新文字柔和渐显：平滑揭示的每批新增文本包进该 span，从透明
   浮现；淡入时长覆盖多个提交周期，相邻批次的渐显首尾相接，形成连续的
   书写节奏。旧文字保持原 DOM 稳定不动。 */
.md-stream-fade-in {
  animation: md-stream-fade-in 0.24s ease-out both;
}

@keyframes md-stream-fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.stream-cursor {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
  line-height: 1;
  vertical-align: 0.05em;
  /* 每轮流式开始时柔和浮现，避免指示器突兀弹出 */
  animation: chat-fade-in 0.2s ease-out both;
}

.stream-cursor-tokens {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  background: var(--surface-island);
  font-weight: 500;
  white-space: nowrap;
}

.stream-cursor-metric {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.stream-cursor-metric-icon {
  color: var(--text-tertiary);
  flex-shrink: 0;
  display: inline-flex;
}

.stream-cursor-metric-value {
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.stream-cursor-metric-label {
  color: var(--text-tertiary);
  font-weight: 400;
}

.stream-cursor-tokens-icon {
  color: #22c55e;
  flex-shrink: 0;
}

.stream-cursor-tokens-label {
  color: var(--text-tertiary);
  font-weight: 400;
}

@keyframes stream-dot-pulse {
  0%,
  100% {
    opacity: 0.25;
  }

  50% {
    opacity: 1;
  }
}

.stream-stopping {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 4px;
  font-size: 12px;
  color: var(--text-tertiary);
  animation: chat-fade-in 0.15s ease-out both;
}

/* 重试提示：与工具行同级的单行状态文本，无卡片底色；详情向下展开。 */
.stream-retry-notice {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-width: min(100%, 720px);
  margin-top: 8px;
  animation: chat-enter 0.2s ease-out both;
}

.stream-retry-notice-header {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.5;
}

.stream-retry-notice-icon {
  flex-shrink: 0;
  color: var(--accent-amber-text);
}

.stream-retry-notice-title {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 4px;
  color: var(--text-primary);
  font-weight: 500;
}

.stream-retry-notice-attempt {
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
  font-weight: 400;
}

/* 倒计时/等待响应：琥珀色胶囊，与标题平铺在同一行。 */
.stream-retry-notice-countdown {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  padding: 1px 7px;
  border-radius: 5px;
  background: color-mix(in srgb, var(--accent-amber-bg) 60%, transparent);
  color: var(--accent-amber-text);
  font-size: 11px;
  line-height: 1.45;
  font-variant-numeric: tabular-nums;
}

.stream-retry-notice-countdown-urgent {
  color: var(--accent-red-text);
  animation: stream-retry-countdown-pulse 0.8s ease-in-out infinite;
}

@keyframes stream-retry-countdown-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.45;
  }
}

.stream-retry-notice-preview {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  color: var(--text-tertiary);
  font-family: var(--font-mono, monospace);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stream-retry-notice-toggle {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 2px;
  padding: 1px 4px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
  transition:
    color 0.14s ease,
    background-color 0.14s ease;
}

.stream-retry-notice-toggle:hover {
  color: var(--text-primary);
  background: color-mix(in srgb, var(--text-primary) 7%, transparent);
}

.stream-retry-notice-toggle:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--accent-primary, #4c9aff);
}

.stream-retry-notice-error {
  display: flex;
  gap: 6px;
  max-height: 240px;
  overflow: auto;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--surface-island);
  color: var(--text-secondary);
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  line-height: 1.6;
}

.stream-retry-notice-error-text {
  flex: 1;
  min-width: 0;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.stream-retry-notice-error-copy {
  position: sticky;
  top: 0;
  align-self: flex-start;
}

.response-incomplete-notice {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px solid var(--accent-amber-bg);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--accent-amber-bg) 55%, transparent);
  color: var(--accent-amber-text);
  font-size: 12px;
  line-height: 1.5;
  animation: chat-enter 0.2s ease-out both;
}

.response-incomplete-notice-icon {
  flex-shrink: 0;
  margin-top: 2px;
}

.response-incomplete-notice-content {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.response-incomplete-notice-title {
  font-weight: 600;
}

.response-incomplete-notice-detail {
  opacity: 0.85;
}

.ai-error-notice {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 12px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--accent-red-text) 30%, transparent);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--accent-red-bg) 55%, transparent);
  font-size: 12px;
  line-height: 1.5;
  animation: chat-enter 0.2s ease-out both;
}

.ai-error-notice-header {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--accent-red-text);
}

.ai-error-notice-icon {
  flex-shrink: 0;
}

.ai-error-notice-title {
  font-weight: 600;
}

.ai-error-notice-status {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--accent-red-text) 14%, transparent);
  color: var(--accent-red-text);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.ai-error-notice-summary {
  margin: 0;
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

.ai-error-notice-toggle {
  display: inline-flex;
  align-items: center;
  align-self: flex-start;
  gap: 4px;
  padding: 0;
  border: none;
  background: none;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
}

.ai-error-notice-toggle:hover {
  color: var(--text-primary);
}

.ai-error-notice-detail {
  display: flex;
  gap: 6px;
  max-height: 260px;
  overflow: auto;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Code",
    Consolas,
    monospace
  );
  font-size: 11px;
  line-height: 1.55;
  animation: chat-fade-in 0.15s ease-out both;
}

.ai-error-notice-detail-text {
  flex: 1;
  min-width: 0;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.ai-error-notice-detail-copy {
  position: sticky;
  top: 0;
  align-self: flex-start;
}

.chat-message-group.is-error .ai-message {
  color: var(--accent-red-text);
}

.user-message-action-btn,
.ai-response-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.user-message-row {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}

.user-message-bubble {
  max-width: min(560px, 76%);
  padding: 12px 18px;
  border-radius: var(--radius-xl);
  background: var(--bg-tertiary);
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

:root[data-theme="dark"] .user-message-bubble {
  background: #2e2e2e;
}

.user-message-bubble p {
  margin: 0;
}

.user-message-text-collapsed {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 6;
  line-clamp: 6;
  overflow: hidden;
}

.user-message-toggle {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-top: 6px;
  padding: 2px 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.4;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.user-message-toggle:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.user-message-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-right: 6px;
  color: var(--text-muted);
}

.user-message-action-btn {
  width: 26px;
  height: 26px;
  border-radius: var(--radius-md);
  color: inherit;
  transition:
    background 0.12s,
    color 0.12s;
}

.user-message-action-btn:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.user-message-action-btn:disabled {
  cursor: default;
  opacity: 0.6;
}

.user-message-action-btn:disabled:hover {
  background: transparent;
  color: inherit;
}

.message-time {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: var(--text-tertiary);
  font-size: 11.5px;
  line-height: 1.4;
  white-space: nowrap;
  user-select: none;
}

.message-time-value {
  font-variant-numeric: tabular-nums;
}

.user-message-time {
  color: inherit;
}

.ai-message-footer {
  display: flex;
  align-items: center;
  gap: 10px;
}

.previous-messages {
  align-self: center;
  padding: 4px 10px;
  border-radius: var(--radius-md);
  color: var(--text-tertiary);
  font-size: 12px;
  transition:
    background 0.12s,
    color 0.12s;
}

.previous-messages:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.ai-message {
  display: flex;
  flex-direction: column;
  gap: 12px;
  color: var(--text-primary);
  font-size: var(--app-chat-font-size, 15px);
  line-height: var(--app-chat-line-height, 1.75);
}

.ai-message-content {
  /* 跟随 .chat-area 的响应式最大宽度，留 40px 呼吸空间 */
  width: min(100%, calc(var(--chat-content-max, 720px) - 40px));
}

/* Raw Markdown view — shown when the user toggles off rendered output */
.ai-message-raw {
  margin: 8px 0;
  padding: 12px 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md, 6px);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Code",
    Consolas,
    monospace
  );
  font-size: 13px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  overflow-x: auto;
  max-height: 480px;
  overflow-y: auto;
}

.ai-response-actions {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  /* AI 流程结束后操作按钮浮现，避免与正文同时硬切出现 */
  animation: chat-fade-in 0.25s ease-out both;
}

.ai-response-action-btn {
  width: 26px;
  height: 26px;
  border-radius: var(--radius-md);
  color: inherit;
  transition:
    background 0.12s,
    color 0.12s;
}

.ai-response-action-btn:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.ai-response-action-btn.is-open {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

/* Copy submenu rendered via portal (document.body) so it is never clipped by
   overflow: hidden ancestors. Follows the same pattern as BrowserMenu. */
.message-copy-menu {
  position: fixed;
  min-width: 160px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg, 8px);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow, 0 4px 16px rgba(0, 0, 0, 0.12));
  z-index: 9999;
}

.message-copy-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-primary);
  font-size: 12px;
  font-family: inherit;
  cursor: pointer;
  text-align: left;
  transition: background 0.1s ease;
}

.message-copy-menu-item:hover {
  background: var(--bg-hover);
}

.message-copy-menu-label {
  flex: 1;
  line-height: 1.4;
}

.message-copy-menu-item svg {
  flex-shrink: 0;
}

.chat-fork-divider-line {
  flex: 1;
  height: 1px;
  background: var(--border-color);
}

.chat-fork-divider-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  color: var(--accent-blue-text, var(--text-link, #3b82f6));
  white-space: nowrap;
  cursor: pointer;
  border: none;
  background: none;
  padding: 0;
  transition: opacity 0.12s;
}

.chat-fork-divider-link:hover {
  opacity: 0.7;
}

/* AI 流程结束后的任务摘要条：fork-divider 同款「线 + 居中内容」布局 */
.chat-run-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  width: min(100%, var(--chat-content-max));
  margin: 4px auto 0;
  padding: 0 12px;
  /* run 结束时摘要条从消息流尾部柔和浮现 */
  animation: chat-enter 0.25s ease-out both;
}

.chat-run-summary-content {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 4px 12px;
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.5;
  user-select: text;
}

.chat-run-summary-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  white-space: nowrap;
}

.chat-run-summary-item svg {
  flex-shrink: 0;
  opacity: 0.75;
}

/* 模型品牌 logo 保持原色，不随描边图标降透明度 */
.chat-run-summary-item .model-brand-icon > svg {
  opacity: 1;
}

/* 模型名不截断：空间不足时在条目内部换行，保证完整名称可见 */
.chat-run-summary-model {
  white-space: normal;
  overflow-wrap: anywhere;
  align-items: flex-start;
}

/* 图标与首行文字垂直居中（12px 图标在 18px 行高内的偏移） */
.chat-run-summary-model .model-brand-icon {
  margin-top: 3px;
}

.chat-run-summary-sep {
  opacity: 0.45;
  user-select: none;
}

.context-compaction-message {
  width: min(100%, var(--chat-content-max));
  margin: 0 auto;
}

.context-compaction-message-bar {
  display: flex;
  align-items: center;
  gap: 10px;
}

.context-compaction-message-rule {
  height: 1px;
  flex: 1;
  background: var(--border-color);
}

.context-compaction-message-cluster {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 2px;
}

.context-compaction-message-toggle {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  padding: 4px 9px;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--text-tertiary);
  font-size: 12px;
  line-height: 1.4;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.context-compaction-message-toggle:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.context-compaction-message-toggle svg {
  flex-shrink: 0;
}

.context-compaction-message-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-compaction-message-chevron {
  opacity: 0.7;
  transition: transform 0.18s ease;
}

.context-compaction-message.is-expanded .context-compaction-message-chevron {
  transform: rotate(180deg);
}

.context-compaction-message-actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
}

.context-compaction-message-action-btn {
  display: inline-flex;
  width: 24px;
  height: 24px;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.context-compaction-message-action-btn:hover,
.context-compaction-message-action-btn.is-open {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.context-compaction-message-action-btn:disabled {
  cursor: default;
  opacity: 0.6;
}

.context-compaction-message-action-btn:disabled:hover {
  background: transparent;
  color: var(--text-muted);
}

.context-compaction-message-body {
  max-height: min(46vh, 420px);
  overflow: auto;
  margin-top: 10px;
  padding: 14px 16px 16px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  animation: chat-fade-in 0.18s ease-out both;
}

.context-compaction-message-body .context-compaction-markdown {
  font-size: 13px;
  line-height: 1.65;
}

.context-compaction-message-body .context-compaction-markdown h1,
.context-compaction-message-body .context-compaction-markdown h2,
.context-compaction-message-body .context-compaction-markdown h3,
.context-compaction-message-body .context-compaction-markdown h4 {
  margin: 16px 0 8px;
}

.context-compaction-message-body .context-compaction-markdown h1 {
  font-size: 17px;
}

.context-compaction-message-body .context-compaction-markdown h2 {
  font-size: 15px;
}

.context-compaction-message-body .context-compaction-markdown h3,
.context-compaction-message-body .context-compaction-markdown h4 {
  font-size: 14px;
}

.context-compaction-stream {
  display: flex;
  width: min(100%, var(--chat-content-max));
  min-height: 180px;
  max-height: min(52vh, 520px);
  flex-direction: column;
  overflow: hidden;
  margin: 0 auto;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--surface-island);
  box-shadow: var(--island-shadow);
}

.context-compaction-stream-title {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 9px;
  min-height: 42px;
  padding: 0 14px;
  border-bottom: 1px solid var(--border-color);
  background: var(--surface-island-strong);
  color: var(--text-secondary);
  font-size: 12px;
}

.context-compaction-stream-icon {
  display: inline-flex;
  width: 26px;
  height: 26px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.context-compaction-stream-heading {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-compaction-stream-body {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 20px 24px 28px;
  background: var(--bg-primary);
}

.context-compaction-markdown {
  color: var(--text-primary);
  font-size: 14px;
  line-height: 1.72;
  overflow-wrap: anywhere;
}

.context-compaction-markdown h1,
.context-compaction-markdown h2,
.context-compaction-markdown h3,
.context-compaction-markdown h4 {
  margin: 22px 0 10px;
  color: var(--text-primary);
  font-weight: 720;
  line-height: 1.35;
}

.context-compaction-markdown h1:first-child,
.context-compaction-markdown h2:first-child,
.context-compaction-markdown h3:first-child,
.context-compaction-markdown h4:first-child {
  margin-top: 0;
}

.context-compaction-markdown h1 {
  font-size: 20px;
}

.context-compaction-markdown h2 {
  padding-bottom: 7px;
  border-bottom: 1px solid var(--border-light);
  font-size: 17px;
}

.context-compaction-markdown h3,
.context-compaction-markdown h4 {
  font-size: 15px;
}

.context-compaction-markdown p {
  margin: 0 0 12px;
}

.context-compaction-markdown p:last-child {
  margin-bottom: 0;
}

.context-compaction-markdown ul,
.context-compaction-markdown ol {
  margin: 0 0 14px;
  padding-left: 24px;
}

.context-compaction-markdown li {
  margin: 5px 0;
  padding-left: 2px;
}

.context-compaction-markdown blockquote {
  margin: 0 0 14px;
  padding: 8px 12px;
  border-left: 3px solid var(--border-color);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
}

.context-compaction-markdown a {
  color: var(--accent-blue);
  text-decoration: none;
}

.context-compaction-markdown a:hover {
  text-decoration: underline;
}

.context-compaction-markdown table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.context-compaction-markdown th,
.context-compaction-markdown td {
  padding: 7px 10px;
  border: 1px solid var(--border-light);
  text-align: left;
  vertical-align: top;
}

.context-compaction-markdown th {
  background: var(--bg-active);
  font-weight: 680;
}

.context-compaction-markdown code {
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--bg-tertiary);
  font-family: var(--font-mono);
  font-size: 12px;
}

.context-compaction-markdown .code-block-wrapper {
  margin: 0 0 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-tertiary);
}

.context-compaction-markdown .code-block-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px 4px 12px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-active);
}

.context-compaction-markdown .code-block-lang,
.context-compaction-markdown .code-block-copy {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
}

.context-compaction-markdown .code-block-lang {
  gap: 4px;
  padding: 2px 6px;
  margin-left: -6px;
  font-family: var(--font-mono);
  font-size: 11px;
}

.context-compaction-markdown .code-block-copy {
  width: 26px;
  height: 26px;
  padding: 0;
}

.context-compaction-markdown .code-block-copy .code-block-copy-icon-check {
  display: none;
}

.context-compaction-markdown
  .code-block-copy.copied
  .code-block-copy-icon-copy {
  display: none;
}

.context-compaction-markdown
  .code-block-copy.copied
  .code-block-copy-icon-check {
  display: block;
}

.context-compaction-markdown .code-block-lang:hover,
.context-compaction-markdown .code-block-copy:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.context-compaction-markdown .code-block-chevron {
  flex-shrink: 0;
  transition: transform 0.2s ease;
}

.context-compaction-markdown .code-block-wrapper.collapsed {
  width: fit-content;
}

.context-compaction-markdown .code-block-wrapper.collapsed .code-block-chevron {
  transform: rotate(-90deg);
}

.context-compaction-markdown .code-block-wrapper.collapsed pre {
  display: none;
}

.context-compaction-markdown .code-block-wrapper pre {
  margin: 0;
  padding: 12px 14px;
  overflow-x: auto;
  background: transparent;
}

.context-compaction-markdown .code-block-wrapper pre code {
  padding: 0;
  background: transparent;
}

.context-compaction-placeholder {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 4px;
}

.context-compaction-placeholder span {
  width: 84%;
  height: 10px;
  border-radius: var(--radius-sm);
  background-image: linear-gradient(
    90deg,
    var(--bg-tertiary) 0%,
    var(--bg-tertiary) 42%,
    var(--border-subtle) 50%,
    var(--bg-tertiary) 58%,
    var(--bg-tertiary) 100%
  );
  background-size: 200% 100%;
  background-repeat: repeat;
  animation: skeleton-shimmer 1.5s linear infinite;
}

.context-compaction-placeholder span:nth-child(2) {
  width: 68%;
}

.context-compaction-placeholder span:nth-child(3) {
  width: 76%;
}

/* 压缩失败提示：沿用「上下文摘要」的横线样式（两侧细线 + 居中标签），
   弱化呈现——警告色小字、不描边、不占高度。 */
.context-compaction-notice {
  display: flex;
  width: min(100%, var(--chat-content-max));
  align-items: center;
  gap: 10px;
  margin: 8px auto;
}

.context-compaction-notice-rule {
  height: 1px;
  flex: 1;
  background: var(--border-color);
}

.context-compaction-notice-label {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  color: var(--warning-color, #d29922);
  font-size: 12px;
  line-height: 1.4;
  opacity: 0.85;
}

.context-compaction-notice-label svg {
  flex-shrink: 0;
}

.context-compaction-notice-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-compaction-notice-close {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  margin-left: -4px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--warning-color, #d29922);
  cursor: pointer;
  opacity: 0.7;
}

.context-compaction-notice-close:hover {
  background: var(--hover-bg, rgba(127, 127, 127, 0.15));
  opacity: 1;
}

.ai-message h2,
.ai-message h3,
.ai-message p,
.ai-message ol {
  margin-top: 0;
}

.ai-message h2 {
  margin-bottom: 16px;
  font-size: 20px;
  font-weight: 760;
  line-height: 1.35;
}

.ai-message h3 {
  margin-bottom: 10px;
  font-size: 17px;
  font-weight: 740;
  line-height: 1.4;
}

.ai-message p {
  margin-bottom: 14px;
}

.ai-message p:last-child {
  margin-bottom: 0;
}

.ai-message-section {
  margin-top: 22px;
}

.ai-message ol {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-bottom: 0;
  padding-left: 26px;
}

.ai-message li {
  padding-left: 2px;
}

.ai-message li strong {
  color: var(--text-primary);
  font-weight: 760;
}

.ai-message li span {
  color: var(--text-secondary);
}

.ai-message a {
  color: var(--accent-blue);
  text-decoration: none;
}

.ai-message a:hover {
  text-decoration: underline;
}

/* ===== 网络来源徽章 =====
   模型按提示词在正文中用 `[来源:标题](url "摘要")` 内联标注来源，
   markdownWorker 将其渲染为 .md-source-badge（favicon + 缩略标题）；
   React 层负责悬停 Tooltip 摘要与点击打开来源页。
   颜色跟随主题色（--accent-color），不写死品牌蓝。 */
.md-source-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  max-width: 220px;
  margin: 0 2px;
  padding: 1px 8px 1px 4px;
  border: 1px solid color-mix(in srgb, var(--accent-color) 30%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent-color) 8%, transparent);
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.6;
  vertical-align: middle;
  cursor: pointer;
  user-select: none;
  transition:
    border-color 0.15s,
    background 0.15s;
}

.md-source-badge:hover {
  border-color: color-mix(in srgb, var(--accent-color) 60%, transparent);
  background: color-mix(in srgb, var(--accent-color) 14%, transparent);
}

/* favicon 默认隐藏，加载成功（.favicon-ok）才显示；失败/缺失/无 favicon
   站点稳定回退到内置地球占位图标（向后兼容，不出现破图）。
   本条为基础兜底；.ai-message 等容器内全局 Markdown 图片规则的
   display:block 优先级更高，由下方带容器前缀的提权规则接管显隐。 */
.md-source-badge-favicon {
  display: none;
  width: 14px;
  height: 14px;
  border-radius: 3px;
  object-fit: contain;
  flex-shrink: 0;
}

.md-source-badge-fallback {
  display: inline-flex;
  width: 14px;
  height: 14px;
  flex-shrink: 0;
  color: var(--accent-color);
}

.md-source-badge.favicon-ok .md-source-badge-favicon {
  display: block;
}

.md-source-badge.favicon-ok .md-source-badge-fallback {
  display: none;
}

.md-source-badge-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 覆盖全局 Markdown 图片规则（display: block / max-width / margin 等）。
   favicon 显隐只由 .favicon-ok 状态决定：本条 (0,3,1) 高于全局图片规则
   (0,2,1)，把加载中的 img 压为隐藏，避免网站图标与占位图标同时显示；
   加载成功的显示由下方 (0,4,1) 规则接管。 */
:is(.ai-message, .context-compaction-markdown, .thinking-block-body)
  .md-source-badge
  img.md-source-badge-favicon {
  display: none;
  max-width: none;
  max-height: none;
  margin: 0;
  cursor: default;
}

/* favicon 加载成功：.favicon-ok 提权显示，压过上一条隐藏规则 */
:is(.ai-message, .context-compaction-markdown, .thinking-block-body)
  .md-source-badge.favicon-ok
  img.md-source-badge-favicon {
  display: block;
}

/* Tooltip 定位宿主：fixed 于徽章顶部中心，Tooltip 在宿主上方弹出 */
.md-source-tooltip-host {
  position: fixed;
  width: 0;
  height: 0;
  z-index: 1000;
}

/* 悬停锚点：0 尺寸纯占位（Tooltip 为受控显示，不拦截徽章鼠标事件，
   避免覆盖导致徽章 :hover 丢失造成图标闪烁） */
.md-source-badge-anchor {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
}

/* Tooltip 摘要详情：固定宽度多行布局，覆盖默认 nowrap（fit-content 会让
   长文本把 tooltip 撑成窄条，固定宽度才能正确换行截断）。
   宽度必须扣除 .tooltip 自身的内边距与边框（.tooltip 为 border-box 且
   max-width: min(280px, 70vw)，padding 6px 10px、border 1px，共 22px），
   否则内层按 280px 排版会横向溢出到圆角框之外。 */
.md-source-tooltip {
  display: flex;
  flex-direction: column;
  gap: 4px;
  width: min(258px, calc(70vw - 22px));
  white-space: normal;
  text-align: left;
}

.md-source-tooltip-title {
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.45;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.md-source-tooltip-summary {
  font-size: 11.5px;
  line-height: 1.55;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.md-source-tooltip-url {
  font-size: 10.5px;
  color: var(--text-tertiary);
  word-break: break-all;
}

/* Markdown 内联图片：
   - 图片限高居中展示（复用生图工具卡的相框观感）：过大图片不再撑满消息，
     点击可在灯箱中查看原图（cursor: zoom-in 提示）。 */
:is(.ai-message, .context-compaction-markdown, .thinking-block-body) img {
  display: block;
  max-width: 100%;
  max-height: 420px;
  height: auto;
  margin: 8px auto;
  border-radius: var(--radius-md);
  object-fit: contain;
  cursor: zoom-in;
}

/* Table — .table-wrapper 只负责外框与定位，内层 .table-scroll 才承担横向滚动，
   这样右上角下载按钮不会被滚动带走，始终贴在容器最右侧 */
:is(.ai-message, .context-compaction-markdown) .table-wrapper {
  width: 100%;
  margin: 0 0 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
}

:is(.ai-message, .context-compaction-markdown) .table-scroll {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  border-radius: inherit;
}

.ai-message table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
  line-height: 1.5;
}

.ai-message thead {
  background: var(--bg-active);
  border-bottom: 1px solid var(--border-light);
}

.ai-message th {
  padding: 8px 12px;
  font-weight: 680;
  text-align: left;
  color: var(--text-primary);
  white-space: nowrap;
}

.ai-message td {
  padding: 7px 12px;
  color: var(--text-secondary);
  border-top: 1px solid var(--border-light);
}

.ai-message tbody tr:nth-child(odd) {
  background: transparent;
}

.ai-message tbody tr:nth-child(even) {
  background: var(--bg-tertiary);
}

/* 表格右上角下载按钮（markdownWorker 在 .table-wrapper 内生成）：
   悬浮在表格之上，低对比默认态，悬停表格时提亮；点击弹出 CSV / XLSX
   格式菜单（tableExport.openTableExportMenu）。 */
.table-wrapper {
  position: relative;
}

.table-download-btn {
  position: absolute;
  top: 6px;
  right: 8px;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 1px solid var(--border-light);
  border-radius: 4px;
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.12);
  cursor: pointer;
  opacity: 0.45;
  transition:
    opacity 0.15s,
    background 0.15s,
    color 0.15s;
}

.table-wrapper:hover .table-download-btn {
  opacity: 1;
}

.table-download-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* Inline code */
.ai-message code {
  padding: 1px 5px;
  border-radius: 4px;
  background: var(--bg-tertiary);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: var(--app-code-font-size, 12.5px);
}

/* inline code 中识别出的文件 / 目录路径（markdownWorker 的 md-file-path 标记）：
   前置与资源管理器一致的文件类型图标；点击打开文件。只在有点击处理的容器
   （聊天区 / 文件阅读器 markdown 预览）中呈现可点击态；点击后确认不存在的
   路径降为普通样式。 */
.md-file-path-icon {
  display: inline-flex;
  align-items: center;
  margin-right: 4px;
  vertical-align: -1px;
}

.md-file-path-icon:empty {
  display: none;
}

.md-file-path-icon svg {
  display: block;
  width: 12px;
  height: 12px;
  flex-shrink: 0;
}

.chat-area .md-file-path,
.file-viewer-markdown .md-file-path {
  cursor: pointer;
  text-decoration: underline dotted;
  text-decoration-color: color-mix(
    in srgb,
    var(--accent-color) 55%,
    transparent
  );
  text-underline-offset: 3px;
  transition:
    color 0.15s ease,
    background-color 0.15s ease;
}

.chat-area .md-file-path:hover,
.file-viewer-markdown .md-file-path:hover {
  color: var(--accent-color);
  text-decoration-style: solid;
  background: color-mix(in srgb, var(--accent-color) 12%, var(--bg-tertiary));
}

.chat-area .md-file-path.md-file-path-missing,
.file-viewer-markdown .md-file-path.md-file-path-missing {
  cursor: default;
  color: var(--text-muted);
  text-decoration: none;
  background: var(--bg-tertiary);
}

.md-file-path.md-file-path-missing .md-file-path-icon {
  opacity: 0.45;
  filter: grayscale(1);
}

/* Handoff tag（工作流交接文档折叠块，由 markdown-it handoff_block 生成）：
   收起态是与来源徽章同语言的主题色胶囊（accent 淡底 + 主题色交接图标 +
   chevron），点击展开主题色引用面板（accent 左竖线 + 淡底）。 */
.md-handoff-block {
  margin: 0 0 14px;
}

.md-handoff-toggle {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 10px;
  border: 1px solid color-mix(in srgb, var(--accent-color) 30%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent-color) 8%, transparent);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  line-height: 1.6;
  cursor: pointer;
  user-select: none;
  transition:
    border-color 0.15s,
    background 0.15s,
    color 0.15s;
}

.md-handoff-toggle:hover,
.md-handoff-block.expanded .md-handoff-toggle {
  border-color: color-mix(in srgb, var(--accent-color) 60%, transparent);
  background: color-mix(in srgb, var(--accent-color) 14%, transparent);
  color: var(--text-primary);
}

.md-handoff-icon {
  display: inline-flex;
  width: 13px;
  height: 13px;
  color: var(--accent-color);
  flex-shrink: 0;
}

.md-handoff-label {
  white-space: nowrap;
}

.md-handoff-chevron {
  flex-shrink: 0;
  color: var(--text-tertiary);
  transition: transform 0.2s ease;
}

.md-handoff-toggle:hover .md-handoff-chevron {
  color: var(--text-secondary);
}

.md-handoff-block.expanded .md-handoff-chevron {
  transform: rotate(180deg);
}

.md-handoff-content {
  display: none;
  margin-top: 6px;
  padding: 10px 14px;
  border: 1px solid color-mix(in srgb, var(--accent-color) 22%, transparent);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--accent-color) 4%, transparent);
}

.md-handoff-content > :first-child {
  margin-top: 0;
}

.md-handoff-content > :last-child {
  margin-bottom: 0;
}

.md-handoff-block.expanded .md-handoff-content {
  display: block;
}

/* Code block wrapper (generated by markdown-it highlight callback) */
.ai-message .code-block-wrapper {
  margin: 0 0 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-tertiary);
}

.ai-message .code-block-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px 4px 12px;
  background: var(--bg-active);
  border-bottom: 1px solid var(--border-light);
}

.ai-message .code-block-lang {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  margin-left: -6px;
  border: none;
  border-radius: 4px;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--text-tertiary);
  cursor: pointer;
  user-select: none;
  transition:
    background 0.15s,
    color 0.15s;
}

.ai-message .code-block-lang:hover {
  color: var(--text-primary);
}

.ai-message .code-block-chevron {
  transition: transform 0.2s ease;
  flex-shrink: 0;
}

.ai-message .code-block-wrapper.collapsed {
  width: fit-content;
}

.ai-message .code-block-wrapper.collapsed .code-block-chevron {
  transform: rotate(-90deg);
}

.ai-message .code-block-wrapper.collapsed pre {
  display: none;
}

.ai-message .code-block-copy {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.15s,
    color 0.15s;
}

.ai-message .code-block-copy:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.ai-message .code-block-copy.copied {
  color: var(--accent-green);
}

.ai-message .code-block-copy .code-block-copy-icon-check {
  display: none;
}

.ai-message .code-block-copy.copied .code-block-copy-icon-copy {
  display: none;
}

.ai-message .code-block-copy.copied .code-block-copy-icon-check {
  display: block;
}

.ai-message .code-block-wrapper pre {
  overflow-x: auto;
  margin: 0;
  padding: 12px 14px;
  border: none;
  border-radius: 0;
  background: transparent;
}

.ai-message .code-block-wrapper pre code {
  padding: 0;
  background: transparent;
  font-size: var(--app-code-font-size, 12.5px);
  line-height: 1.6;
}

/* KaTeX math formulas (generated by markdown-it-texmath in the worker).
   Inline formulas render inside <eq>, display formulas inside <eqn>. */
:is(.ai-message, .file-viewer-code, .context-compaction-markdown) eq {
  display: inline-block;
  max-width: 100%;
  vertical-align: middle;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown) eqn {
  display: block;
  margin: 0 0 14px;
  padding: 4px 0;
  text-align: center;
}

/* Keep KaTeX glyphs at the same size as surrounding text. */
:is(.ai-message, .file-viewer-code, .context-compaction-markdown) .katex {
  font-size: 1em;
}

/* Mermaid diagrams (rendered on the main thread from worker-emitted placeholders).
   The worker emits a `.mermaid-block` with:
     - `.mermaid-toolbar` (copy + view-toggle buttons)
     - `.mermaid-view-code` (highlighted source, visible during streaming)
     - `.mermaid-view-diagram` (SVG filled by mermaidRenderer once parsed)
   `data-mermaid-view` on the block controls which view is visible. */
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block {
  margin: 0 0 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--bg-tertiary);
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px 4px 12px;
  background: var(--bg-active);
  border-bottom: 1px solid var(--border-light);
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-toolbar-label {
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--text-tertiary);
  user-select: none;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-toolbar-actions {
  display: flex;
  align-items: center;
  gap: 2px;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-copy,
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-download,
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-code,
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-diagram {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.15s,
    color 0.15s;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-copy:hover,
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-download:hover,
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-code:hover,
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-diagram:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-btn-copy.copied {
  color: var(--accent-green);
}

/* Active view-toggle button (matches the current view). */
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block[data-mermaid-view="code"]
  .mermaid-btn-code,
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block[data-mermaid-view="diagram"]
  .mermaid-btn-diagram {
  color: var(--text-primary);
  background: var(--bg-hover);
}

/* Code view: visible by default (during streaming and when view=code). */
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-view-code {
  display: block;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-view-code
  pre {
  margin: 0;
  padding: 12px 14px;
  overflow-x: auto;
  border: none;
  background: transparent;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-view-code
  code {
  padding: 0;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 12.5px;
  line-height: 1.6;
}

/* Diagram view: hidden by default, shown when view=diagram. */
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-view-diagram {
  display: none;
  padding: 16px;
  overflow: auto;
  text-align: center;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block[data-mermaid-view="code"]
  .mermaid-view-code {
  display: block;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block[data-mermaid-view="code"]
  .mermaid-view-diagram {
  display: none;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block[data-mermaid-view="diagram"]
  .mermaid-view-code {
  display: none;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block[data-mermaid-view="diagram"]
  .mermaid-view-diagram {
  display: block;
}

:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-view-diagram
  svg {
  max-width: 100%;
  height: auto;
}

/* Export dropdown menu (created dynamically by mermaidRenderer.openExportMenu
   and tableExport.openTableExportMenu). Rendered in document.body, so it is
   not nested under .ai-message. */
.mermaid-export-menu,
.table-export-menu,
.link-open-menu {
  z-index: 10000;
  min-width: 88px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);
}

.mermaid-export-menu-item,
.table-export-menu-item,
.link-open-menu-item {
  display: block;
  width: 100%;
  padding: 6px 12px;
  border: none;
  border-radius: 4px;
  background: transparent;
  font-family: var(--font-mono);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  cursor: pointer;
  text-align: left;
  transition:
    background 0.15s,
    color 0.15s;
}

.mermaid-export-menu-item:hover,
.table-export-menu-item:hover,
.link-open-menu-item:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.link-open-menu-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--app-font-family, var(--font-sans));
  font-weight: var(--app-font-weight, 400);
  letter-spacing: normal;
}

.link-open-menu-item-icon {
  display: inline-flex;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.link-open-menu-item:hover .link-open-menu-item-icon {
  color: var(--text-primary);
}

/* Diagram is clickable: hint with a zoom cursor when the diagram view is
   active (the SVG is only present once it has been rendered). */
:is(.ai-message, .file-viewer-code, .context-compaction-markdown)
  .mermaid-block[data-mermaid-view="diagram"]
  .mermaid-view-diagram
  svg {
  cursor: zoom-in;
}

/* Mermaid image viewer (lightbox) — created dynamically by
   mermaidRenderer.openMermaidImageViewer. Rendered in document.body, so it is
   not nested under .ai-message. */
.mermaid-image-viewer {
  position: fixed;
  inset: 0;
  z-index: 10001;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.82);
  backdrop-filter: blur(2px);
  animation: mermaid-image-viewer-fade 0.16s ease-out;
}

.mermaid-image-viewer.is-light {
  background: rgba(245, 245, 245, 0.92);
}

@keyframes mermaid-image-viewer-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.mermaid-image-viewer-stage {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  cursor: grab;
  touch-action: none;
}

.mermaid-image-viewer-stage.is-grabbing {
  cursor: grabbing;
}

.mermaid-image-viewer-stage svg {
  max-width: none;
  max-height: none;
  height: auto;
  transform-origin: center center;
  pointer-events: none;
  user-select: none;
  -webkit-user-select: none;
}

.mermaid-image-viewer-toolbar {
  position: absolute;
  top: 16px;
  right: 16px;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.28);
}

.mermaid-image-viewer-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
  transition:
    background 0.15s,
    color 0.15s;
}

.mermaid-image-viewer-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* Fallback for pre/code not wrapped (e.g. plain code without language) */
.ai-message pre {
  overflow-x: auto;
  margin: 0 0 14px;
  padding: 5;
  /* border: 1px solid var(--border-light); */
  /* border-radius: var(--radius-md); */
  /* background: var(--bg-tertiary); */
}

.ai-message pre code {
  padding: 0;
  background: transparent;
  font-size: 12.5px;
  line-height: 1.6;
}

.ai-message blockquote {
  margin: 0 0 14px;
  padding: 2px 0 2px 12px;
  border-left: 3px solid var(--border-color);
  color: var(--text-secondary);
}

.ai-message ul {
  margin-top: 0;
  margin-bottom: 14px;
  padding-left: 24px;
}

/* ===== Thinking Block ===== */
/* 头部与消息正文左边缘对齐，只有内容区做竖线缩进 */
.thinking-block {
  margin: 0 0 14px;
  color: var(--text-tertiary);
}

/* Header row: clickable to collapse/expand the whole section.
   必须用块级 flex（而非 inline-flex）：inline 级元素会落入父级行盒，
   与行盒 strut 做 baseline 对齐后在头顶/底部产生幽灵空隙。width:
   fit-content 保持收缩宽度。 */
.thinking-block-header {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 100%;
  padding: 0;
  color: var(--text-secondary);
  font-size: 13px;
  font-weight: 400;
  line-height: 1.45;
  cursor: pointer;
  user-select: none;
  border-radius: var(--radius-sm, 4px);
  outline: none;
}

.thinking-block-header:hover {
  color: var(--text-primary);
}

.thinking-block-header:focus-visible {
  box-shadow: 0 0 0 2px var(--accent-primary, #4c9aff);
}

/* 自绘思考云图标：header 左侧的思考语义标识，恒定装饰不参与状态表达 */
.thinking-block-thinking-icon {
  flex-shrink: 0;
  color: currentColor;
}

/* 右侧展开/收起箭头：展开时旋转 90 度指示 */
.thinking-block-chevron {
  flex-shrink: 0;
  color: currentColor;
  transition: transform 0.14s ease;
}

.thinking-block-chevron--open {
  transform: rotate(90deg);
}

/* 思考完成自动收起的瞬间：绿色圆勾替代展开箭头提示成功，1s 后还原 */
.thinking-block-check {
  flex-shrink: 0;
  color: var(--success, #22c55e);
  animation: thinking-check-in 0.22s ease-out both;
}

@keyframes thinking-check-in {
  from {
    opacity: 0;
    transform: scale(0.55);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* 思考统计（时长 · token 数）：后端实时统计，思考中与结束后都显示。
   注意：思考中头部整行流光靠 background-clip: text 裁切，而自身形成绘制层
   （opacity < 1、或处于运行/填充态的动画）的后代会脱离这层裁切——文字只剩
   透明的 text-fill、拿不到父级渐变，等于整段消失。所以这里与
   .thinking-block-preview 都不能加入场动画或 opacity；需要压暗的子元素改用
   color-mix 降低颜色透明度（见 -sep / -label）。 */
.thinking-block-meta {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: 6px;
  color: var(--text-tertiary);
  font-size: 11.5px;
  line-height: 1.4;
  white-space: nowrap;
}

.thinking-block-meta-icon {
  flex-shrink: 0;
  opacity: 0.8;
}

.thinking-block-meta-value {
  font-variant-numeric: tabular-nums;
}

.thinking-block-meta-sep {
  color: color-mix(in srgb, var(--text-tertiary) 55%, transparent);
}

.thinking-block-meta-label {
  color: color-mix(in srgb, var(--text-tertiary) 75%, transparent);
}

/* 单行思考内容预览：取尾部文本，纯文本展示，自动后滚
   （流式输出时 content 增长，尾部自然更新展示最新片段）。
   white-space: nowrap + overflow: hidden 保证永远单行不折行。
   同样不能加 opacity / 入场动画，原因见 .thinking-block-meta。 */
.thinking-block-preview {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  margin-left: 6px;
  color: var(--text-tertiary);
  font-size: 12px;
  line-height: 1.4;
}

/* 流光文字（思考中）：高对比扫光。低谷把基色按半透明压暗，
   峰值用 --text-primary，靠亮度差而非颜色区分；两端同为低谷色，
   配合 repeat 平铺在任意 background-position 下都不会出现断层。
   思考块头部整行共用这一层背景：渐变裁切到头部内的全部文字（标题、
   时长/token 统计、思考内容预览条），一次扫光横跨整行。这里刻意不写
   color: transparent——图标以 currentColor 描边，-webkit-text-fill-color
   不作用于 SVG，故图标保持常亮，只有文字参与流光。
   注意：background-position 每帧都要重绘，必须跑在主线程；会话标题的
   同款流光走下面的合成器实现，不再使用这条规则。 */
.thinking-block-header--shimmer {
  --shimmer-base: var(--text-tertiary);
  --shimmer-dim: color-mix(in srgb, var(--shimmer-base) 50%, transparent);
  background-image: linear-gradient(
    100deg,
    var(--shimmer-dim) 0%,
    var(--shimmer-dim) 34%,
    var(--text-primary) 47%,
    var(--text-primary) 53%,
    var(--shimmer-dim) 66%,
    var(--shimmer-dim) 100%
  );
  background-size: 200% 100%;
  background-repeat: repeat;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: text-shimmer 1.15s linear infinite;
}

/* 会话标题流光：纯合成器动画（切换会话等长任务期间也不停转）。
   background-position 每帧都要重绘文字，只能跑主线程，主线程一忙就整段
   停转；这里改成「窗口平移 + 文字静止」：底层是压暗的标题文字，上层是
   同一文本的亮色副本，装在一条带柔边的裁切窗口里——窗口平移、副本反向
   平移（两者位移任何时刻都互为相反数，文字停在原地），观感就是柔边亮带
   扫过文字。柔边由静态 mask 提供，整帧只有 transform 变化，全部交给
   合成器。副本宽度与标题盒子一致，截断（省略号）位置与底层严格对齐。 */
.chat-item-title-text--shimmer {
  --shimmer-dim: color-mix(in srgb, var(--text-secondary) 50%, transparent);
  position: relative;
  color: var(--shimmer-dim);
}

.chat-item-title-shimmer-window {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  overflow: hidden;
  pointer-events: none;
  user-select: none;
  will-change: transform;
  -webkit-mask-image: linear-gradient(
    90deg,
    transparent 16%,
    #000 46%,
    #000 54%,
    transparent 84%
  );
  mask-image: linear-gradient(
    90deg,
    transparent 16%,
    #000 46%,
    #000 54%,
    transparent 84%
  );
  animation: chat-title-shimmer-sweep 1.15s linear infinite;
}

.chat-item-title-shimmer-text {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  overflow: hidden;
  color: var(--text-primary);
  white-space: nowrap;
  text-overflow: ellipsis;
  will-change: transform;
  animation: chat-title-shimmer-counter 1.15s linear infinite;
}

/* 亮带从标题左缘之外扫到右缘之外，与思考块流光同速同向 */
@keyframes chat-title-shimmer-sweep {
  from {
    transform: translateX(-100%);
  }

  to {
    transform: translateX(100%);
  }
}

@keyframes chat-title-shimmer-counter {
  from {
    transform: translateX(100%);
  }

  to {
    transform: translateX(-100%);
  }
}

@keyframes text-shimmer {
  from {
    background-position: 150% 0;
  }
  to {
    background-position: -50% 0;
  }
}

/* 收起后的"思考完毕"摘要行：整块只剩这一行，弱化为次要色 */
.thinking-block-header--collapsed {
  color: var(--text-tertiary);
}

/* Content wrapper：展开即全文，无高度限制。左侧竖线 + 缩进让思考内容
   与正文明显分层，不再像普通段落。 */
.thinking-block-content {
  margin-top: 8px;
  margin-left: 2px;
  padding-left: 12px;
  border-left: 2px solid
    color-mix(in srgb, var(--text-tertiary) 45%, transparent);
}

/* 折叠/展开双向高度动画：grid-rows 0fr<->1fr 插值，内容常挂载。
   注意收起态不能用 content-visibility: hidden——它强制 size
   containment，会把内容高度瞬间清零，导致 1fr 的解析值（自由空间）
   归零、grid-rows 过渡失去高度差，收起因此直接跳变。改用 visibility:
   hidden：不影响布局，其离散过渡在收起动画全程保持内容可见、动画结束
   才隐藏（且跳过收起态的绘制），双向动画都平滑。 */
.thinking-block-collapse {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows 0.3s cubic-bezier(0.33, 0, 0.2, 1);
}

.thinking-block-collapse.is-collapsed {
  grid-template-rows: 0fr;
}

.thinking-block-collapse--instant {
  transition: none;
}

.thinking-block-collapse-inner {
  min-height: 0;
  overflow: hidden;
  transition: visibility 0.3s;
}

.thinking-block-collapse.is-collapsed .thinking-block-collapse-inner {
  visibility: hidden;
  transition: visibility 0.3s;
}

/* 底部"收起"入口：长思考内容读到末尾时就地收起，省去滚回头部。
   左对齐更符合阅读视线落点，与正文左边缘对齐（2px + 12px）。 */
.thinking-block-footer {
  display: flex;
  justify-content: flex-start;
  margin-top: 6px;
  margin-left: 14px;
}

.thinking-block-footer-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm, 4px);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.5;
  cursor: pointer;
  transition:
    color 0.14s ease,
    background-color 0.14s ease,
    border-color 0.14s ease;
}

.thinking-block-footer-btn:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
  border-color: var(--border-strong, var(--border-light));
}

.thinking-block-footer-btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--accent-primary, #4c9aff);
}

/* 思考正文：字号小于正文并拉开行距，与正文形成层级差 */
.thinking-block-body {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.7;
  letter-spacing: 0.01em;
}

.thinking-block-body p {
  margin: 0 0 8px;
}

.thinking-block-body p:last-child {
  margin-bottom: 0;
}

/* Tool Message */
.chat-message-tool {
  max-width: min(720px, 88%);
  padding: 10px 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
  overflow: hidden;
}

.tool-message-header {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-tertiary);
}

.tool-message-content {
  margin: 0;
  max-height: 200px;
  overflow: auto;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-all;
}

/* ============================================================
   Tool Call Group (tcg) - collapsible "N steps" wrapper
   ============================================================ */
.tcg {
  margin-bottom: 6px;
  /* 首个工具出现时整组（含 "N steps" 标签行）柔和浮现 */
  animation: chat-enter 0.18s ease-out both;
}

.tcg-toggle {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 0;
  border: none;
  background: none;
  cursor: pointer;
  font-size: 12px;
  color: var(--text-tertiary);
  transition: color 0.15s ease;
}

.tcg-toggle:hover {
  color: var(--text-secondary);
}

.tcg-label {
  font-weight: 500;
}

.tcg-time {
  display: inline-flex;
  align-items: center;
  margin-left: 6px;
}

/* 运行中/失败标记仅在 chips 风格下显示 */
.tcg-status-icon {
  display: none;
}

.tcg-chevron {
  flex-shrink: 0;
  transition: transform 0.15s ease;
  color: var(--text-tertiary);
}

.tcg-chevron--open {
  transform: rotate(90deg);
}

/* "N steps" 组的双向展开/收起高度动画：grid-rows 0fr<->1fr 插值。
   列表常挂载（工具卡的 details 关闭态内容由浏览器在 shadow 层隐藏，
   实际布局开销有限）；visibility 延迟 0.22s 才隐藏，保证收起时内容
   随高度收缩被逐步裁剪（overflow:hidden），而不是瞬间消失。 */
.tcg-collapse {
  display: grid;
  grid-template-rows: 0fr;
  visibility: hidden;
  transition:
    grid-template-rows 0.22s ease,
    visibility 0s 0.22s;
}

.tcg-collapse.is-open {
  grid-template-rows: 1fr;
  visibility: visible;
  transition:
    grid-template-rows 0.22s ease,
    visibility 0s;
}

.tcg-list {
  display: flex;
  position: relative;
  flex-direction: column;
  gap: 0;
  padding-left: 20px;
  --tcn-line-width: 1.5px;
  --tcn-pad-left: 8.5px;
  min-height: 0;
  overflow: hidden;
}

.tcg-list::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 10px;
  width: var(--tcn-line-width, 1.5px);
  background: var(--border-light);
}

/* 新工具卡片依次浮现：交错延迟让批量出现的卡片有节奏感，
   最迟一张也在 0.18s 淡入 + 0.2s 延迟内完成，整体不拖沓。 */
.tcg-list > .tcn:nth-child(2) {
  animation-delay: 40ms;
}

.tcg-list > .tcn:nth-child(3) {
  animation-delay: 80ms;
}

.tcg-list > .tcn:nth-child(4) {
  animation-delay: 120ms;
}

.tcg-list > .tcn:nth-child(5) {
  animation-delay: 160ms;
}

.tcg-list > .tcn:nth-child(n + 6) {
  animation-delay: 200ms;
}

/* ============================================================
   Tool Call Node (tcn) - compact node-style tool call item
   ============================================================ */
.tcn {
  position: relative;
  /* 工具卡挂载时柔和浮现（模型一轮响应结束后整批出现） */
  animation: chat-enter 0.18s ease-out both;
}

.tcn-header {
  display: flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  /* 固定头部高度：摘要文案、徽章、元信息（行号/缓存标记）与预览按钮等内容
     出现或消失都不再改变行高，避免工具卡在流式与状态切换时上下抖动。
     头部内较高的元素（≤22px）在盒内居中显示，既不裁剪也不撑高。 */
  height: 26px;
  padding: 4px 6px 4px 8px;
  font-size: 12.5px;
  color: var(--text-secondary);
  cursor: pointer;
  user-select: none;
  list-style: none;
  line-height: 1.4;
  border-radius: 6px;
  transition: background 0.15s ease;
}

.tcn-header:hover {
  background: var(--bg-hover);
}

.tcn-header::-webkit-details-marker {
  display: none;
}

.tcn-dot {
  position: absolute;
  left: calc(var(--tcn-pad-left, 12px) * -1 - var(--tcn-line-width, 1.5px) / 2);
  top: 50%;
  transform: translate(-50%, -50%);
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 1.5px solid var(--bg-primary, #fff);
  box-sizing: content-box;
  /* 状态切换（pending->running->completed/error）颜色平滑过渡 */
  transition: background-color 0.2s ease;
}

.tcn-dot--completed {
  background: var(--accent-green, #22c55e);
}

.tool-call-lsp.lsp-result-partial .tcn-dot--completed {
  background: var(--accent-yellow, #d97706);
}

.tcn-dot--running {
  background: var(--accent-blue, #3b82f6);
  box-shadow: 0 0 0 2px
    color-mix(in srgb, var(--accent-blue, #3b82f6) 25%, transparent);
  /* 运行中状态点呼吸光晕表达"进行中" */
  animation: tcn-dot-pulse 1.4s ease-in-out infinite;
}

@keyframes tcn-dot-pulse {
  0%,
  100% {
    box-shadow: 0 0 0 2px
      color-mix(in srgb, var(--accent-blue, #3b82f6) 25%, transparent);
  }

  50% {
    box-shadow: 0 0 0 4px
      color-mix(in srgb, var(--accent-blue, #3b82f6) 10%, transparent);
  }
}

.tcn-dot--error {
  background: var(--accent-red, #ef4444);
}

.tcn-dot--pending {
  background: var(--text-tertiary);
  opacity: 0.5;
}

.tcn-icon {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tcn-provider {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.tcn-sep {
  color: var(--text-tertiary);
  opacity: 0.5;
  flex-shrink: 0;
}

.tcn-name {
  font-weight: 600;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 3px;
  overflow: hidden;
  white-space: nowrap;
  min-width: 0;
}

.tcn-name > svg {
  flex-shrink: 0;
}

/* 运行中但无可摘要参数时的占位文案（参数流式到达前的过渡态） */
.tcn-name--running {
  color: var(--text-secondary);
  font-weight: 500;
}

.tcn-meta {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  font-size: 11px;
  color: var(--text-tertiary);
}

/* 写入 HTML 文件后 tcn-header 上的预览开关 */
.tcn-html-preview-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 6px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 11px;
  line-height: 16px;
  cursor: pointer;
}
.tcn-html-preview-btn:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}
.tcn-html-preview-btn:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
}
/* 预览已展开：眼睛图标切成斜线态，按钮用主题色高亮，提示再点一次收起 */
.tcn-html-preview-btn[data-preview-open="true"] {
  color: var(--accent-color);
  border-color: color-mix(
    in srgb,
    var(--accent-color) 40%,
    var(--border-color)
  );
  background: color-mix(in srgb, var(--accent-color) 8%, var(--bg-secondary));
}

/* 工具调用被用户拒绝时的理由提示条：常驻显示（不随卡片展开状态隐藏），
   让用户回看历史时仍能知道当时为什么拒绝。 */
.tcn-rejection {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 3px 0 0 2px;
  padding: 6px 8px;
  border-radius: 6px;
  border: 1px solid
    color-mix(in srgb, var(--accent-red, #ef4444) 28%, transparent);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
  font-size: 12px;
  /* 固定行高：图标按首行行高精确居中（见 .tcn-rejection-icon 的 margin-top） */
  line-height: 18px;
  min-width: 0;
}

.tcn-rejection-icon {
  display: block;
  flex-shrink: 0;
  /* 12px 图标在 18px 行高内居中 */
  margin-top: 3px;
  color: var(--accent-red);
}

.tcn-rejection-label {
  flex-shrink: 0;
  font-weight: 600;
}

.tcn-rejection-reason {
  min-width: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* ============================================================
   Tool call correction tree (tct)
   ============================================================ */
.tct {
  margin: 2px 0 0 6px;
  padding-left: 10px;
  border-left: 1px solid var(--border-light);
  font-size: 12px;
  line-height: 1.45;
}

.tct-header {
  display: flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  max-width: 100%;
  padding: 4px 6px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  text-align: left;
  cursor: pointer;
  user-select: none;
  appearance: none;
  transition: background 0.15s ease;
}

.tct-header:hover {
  background: var(--bg-hover);
}

.tct-root-icon {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tct--running .tct-root-icon {
  color: var(--accent-blue, #3b82f6);
}

.tct--succeeded .tct-root-icon {
  color: var(--accent-green, #22c55e);
}

.tct--failed .tct-root-icon {
  color: var(--accent-red, #ef4444);
}

.tct-title {
  flex-shrink: 0;
  font-weight: 600;
  color: var(--text-primary);
}

.tct-subtitle {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 11px;
}

.tct-status {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 600;
  background: var(--bg-secondary);
  color: var(--text-secondary);
}

.tct-status--running {
  background: var(--accent-blue-bg, rgba(59, 130, 246, 0.15));
  color: var(--accent-blue, #3b82f6);
}

.tct-status--succeeded {
  background: var(--accent-green-bg);
  color: var(--accent-green-text, #15803d);
}

.tct-status--failed {
  background: var(--accent-red-bg);
  color: var(--accent-red-text, #ef4444);
}

.tct-status--abandoned {
  background: var(--bg-secondary);
  color: var(--text-tertiary);
}

.tct-count {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.tct-chevron {
  flex-shrink: 0;
  margin-left: 2px;
  color: var(--text-tertiary);
  opacity: 0.6;
  transition:
    transform 0.15s ease,
    opacity 0.15s ease;
}

.tct-header:hover .tct-chevron {
  opacity: 1;
}

.tct--open > .tct-header .tct-chevron {
  transform: rotate(90deg);
}

/* 展开/收起过渡：grid 轨道 0fr -> 1fr 可对内容高度做平滑动画，
   收起后 visibility 置为 hidden，内部元素不再可获得焦点。 */
.tct-body-wrap {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  visibility: hidden;
  transition:
    grid-template-rows 0.22s ease,
    opacity 0.16s ease,
    visibility 0s linear 0.22s;
}

.tct--open > .tct-body-wrap {
  grid-template-rows: 1fr;
  opacity: 1;
  visibility: visible;
  transition:
    grid-template-rows 0.22s ease,
    opacity 0.16s ease,
    visibility 0s;
}

.tct-body {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
  margin: 4px 0 2px;
  overflow: hidden;
}

.tct-attempt-detail.tct-original-detail {
  margin-left: 0;
}

.tct-k {
  display: block;
  margin-bottom: 3px;
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-weight: 600;
}

.tct-pre {
  margin: 0;
  max-height: 180px;
  overflow: auto;
  color: var(--text-secondary);
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
  line-height: 1.5;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.tct-pre--error {
  max-height: 120px;
  color: var(--accent-red-text, #ef4444);
}

.tct-pre--muted {
  max-height: 100px;
  color: var(--text-tertiary);
}

.tct-tree {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 2px 0 2px 12px;
  list-style: none;
}

.tct-tree::before {
  content: "";
  position: absolute;
  top: 2px;
  bottom: 2px;
  left: 3px;
  width: 1px;
  background: var(--border-light);
}

.tct-node {
  position: relative;
  min-width: 0;
}

.tct-node::before {
  content: "";
  position: absolute;
  top: 9px;
  left: -9px;
  width: 9px;
  height: 1px;
  background: var(--border-light);
}

.tct-node-head {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  color: var(--text-tertiary);
}

.tct-node--running .tct-node-head > svg {
  color: var(--accent-blue, #3b82f6);
}

.tct-node--succeeded .tct-node-head > svg {
  color: var(--accent-green, #22c55e);
}

.tct-node--failed .tct-node-head > svg {
  color: var(--accent-red, #ef4444);
}

.tct-node--rejected .tct-node-head > svg {
  color: var(--accent-yellow, #d97706);
}

.tct-node-title {
  flex-shrink: 0;
  color: var(--text-primary);
  font-weight: 600;
}

.tct-attempt-status {
  flex-shrink: 0;
  padding: 0 5px;
  border-radius: 999px;
  font-size: 10px;
  line-height: 16px;
  background: var(--bg-secondary);
  color: var(--text-secondary);
}

.tct-attempt-status--running {
  color: var(--accent-blue, #3b82f6);
}

.tct-attempt-status--succeeded {
  color: var(--accent-green-text, #15803d);
}

.tct-attempt-status--failed {
  color: var(--accent-red-text, #ef4444);
}

.tct-attempt-status--rejected {
  color: var(--accent-yellow, #d97706);
}

.tct-node-time {
  margin-left: auto;
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10px;
}

.tct-reasoning {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin: 3px 0 0 17px;
  color: var(--text-secondary);
  overflow-wrap: anywhere;
}

.tct-reasoning > svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--text-tertiary);
}

.tct-node > .tct-pre {
  margin: 4px 0 0 17px;
}

.tct-attempt-detail {
  margin: 4px 0 0 17px;
}

.tct-attempt-detail > summary {
  width: fit-content;
  padding: 1px 4px;
  border-radius: 4px;
  color: var(--text-tertiary);
  font-size: 10.5px;
  cursor: pointer;
  list-style: none;
}

.tct-attempt-detail > summary::-webkit-details-marker {
  display: none;
}

.tct-attempt-detail > summary:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.tct-detail-block {
  margin-top: 4px;
  padding: 5px 7px;
  border: 1px solid var(--border-light);
  border-radius: 6px;
  background: var(--bg-secondary);
}

.tct-failure {
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--accent-red-bg);
  color: var(--accent-red-text, #ef4444);
  font-size: 11.5px;
}

.tct-replaced {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 5px 8px;
  border-radius: 6px;
  background: var(--accent-green-bg);
  color: var(--accent-green-text, #15803d);
  font-size: 11.5px;
}

.tct-replaced > svg {
  flex-shrink: 0;
}

@media (prefers-reduced-motion: reduce) {
  .tct-body-wrap {
    transition: none;
  }
}

.tcn-chevron {
  flex-shrink: 0;
  transition:
    transform 0.15s ease,
    opacity 0.15s ease,
    color 0.15s ease;
  color: var(--text-tertiary);
  opacity: 0.6;
}

.tcn-header:hover .tcn-chevron {
  opacity: 1;
  color: var(--text-secondary);
}

.tcn[open] > .tcn-header .tcn-chevron {
  transform: rotate(90deg);
}

.tcn-body {
  padding: 6px 0 8px 0;
  margin-left: 2px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 12px;
  /* 0fr 高度折叠的必要条件：允许被压缩到 0 并裁剪超出内容（同 .tcg-list） */
  min-height: 0;
  overflow: hidden;
}

/* 工具卡展开/收起的镜像动画，两层同时播放：
   外层 .tcn-collapse 负责高度（grid 0fr<->1fr 插值，同 .tcg-collapse），
   内层 .tcn-body 负责淡入淡出+位移。details 关闭态的内容被浏览器在
   shadow 层隐藏（无前置渲染帧，transition 无法生效），因此双向都用
   animation；收起由 React 先挂 tcn--closing 播退场动画，animationend 才
   移除 open 真正折叠——此时高度已是 0fr，无布局跳变（闪跳）。高度层必须
   双向，否则退场动画期间 body 占满原高、结束瞬间高度骤变。 */
.tcn-collapse {
  display: grid;
  grid-template-rows: 0fr;
}

.tcn[open] > .tcn-collapse {
  grid-template-rows: 1fr;
  animation: tcn-collapse-in 0.18s ease-out both;
}

/* 与 tcn-collapse-in 镜像：同时长，ease-out 反向为 ease-in。 */
.tcn.tcn--closing > .tcn-collapse {
  animation: tcn-collapse-out 0.18s ease-in both;
}

.tcn[open] > .tcn-collapse > .tcn-body {
  animation: tcn-body-in 0.18s ease-out both;
}

.tcn.tcn--closing > .tcn-collapse > .tcn-body {
  animation: tcn-body-out 0.18s ease-in both;
}

@keyframes tcn-collapse-in {
  from {
    grid-template-rows: 0fr;
  }
}

@keyframes tcn-collapse-out {
  to {
    grid-template-rows: 0fr;
  }
}

@keyframes tcn-body-in {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
}

@keyframes tcn-body-out {
  to {
    opacity: 0;
    transform: translateY(-3px);
  }
}

/* Agent loop 动效统一豁免：用户偏好减弱动态效果时关闭所有新增
   入场/过渡动画，保留静态可见性不受影响。 */
@media (prefers-reduced-motion: reduce) {
  .chat-message-group,
  .tcg,
  .tcn,
  .chat-run-summary,
  .chat-vision-status,
  .response-incomplete-notice,
  .ai-response-actions,
  .stream-cursor,
  .stream-stopping,
  .stream-retry-notice,
  .tcn[open] > .tcn-collapse,
  .tcn[open] > .tcn-collapse > .tcn-body,
  .tcn-dot--running {
    animation: none;
  }

  .tcg-collapse,
  .thinking-block-collapse,
  .thinking-block-footer-btn,
  .tcn-dot {
    transition: none;
  }
}

