  cursor: pointer;
}

.tool-call-user-question-custom-form button {
  width: 30px;
  height: 30px;
}

.tool-call-user-question-custom-form button:hover:not(:disabled),
.tool-call-user-question-custom-item button:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.tool-call-user-question-custom-form button:disabled {
  cursor: default;
  opacity: 0.55;
}

.tool-call-user-question-custom-list {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.tool-call-user-question-custom-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  padding: 3px 5px 3px 7px;
  border-radius: var(--radius-sm);
  background: var(--bg-active);
  color: var(--text-secondary);
  font-size: 11.5px;
}

.tool-call-user-question-custom-item-body {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  min-width: 0;
  overflow-wrap: anywhere;
}

.tool-call-user-question-custom-item button {
  width: 20px;
  height: 20px;
  border-color: transparent;
}

.tool-call-user-question-waiting {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-size: 12px;
}

.tool-call-user-question-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  padding-top: 2px;
  color: var(--text-tertiary);
  font-size: 11px;
}

.tool-call-user-question-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}

.tool-call-user-question-cancel,
.tool-call-user-question-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 28px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}

.tool-call-user-question-cancel {
  border: 1px solid var(--accent-red-text);
  background: transparent;
  color: var(--accent-red-text);
}

.tool-call-user-question-cancel:hover {
  background: var(--accent-red-bg);
}

.tool-call-user-question-submit {
  border: 1px solid var(--text-primary);
  background: var(--text-primary);
  color: var(--bg-primary);
}

.tool-call-user-question-submit:hover:not(:disabled) {
  opacity: 0.88;
}

.tool-call-user-question-cancel:focus-visible,
.tool-call-user-question-submit:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

.tool-call-user-question-submit:disabled {
  cursor: default;
  opacity: 0.4;
}

/* ============================================================
   提问 Tab 组（同一轮多个提问合并展示）
   ============================================================ */
.tool-call-user-question-group {
  display: flex;
  flex-direction: column;
  margin: 2px 0;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  overflow: hidden;
  animation: chat-enter 0.18s ease-out both;
}

.auqg-head {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px 0;
  font-size: 12px;
  color: var(--text-tertiary);
}

.auqg-progress {
  font-weight: 500;
}

.auqg-settled {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: auto;
  padding: 1px 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent-green, #22c55e) 15%, transparent);
  color: var(--accent-green, #22c55e);
  font-size: 11px;
  font-weight: 500;
}

.auqg-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 8px;
  border-bottom: 1px solid var(--border-light);
}

/* Tab 过多时横向滚动（导航按钮固定在最右，不随滚动移出视野）。 */
.auqg-tabstrip {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  flex: 1 1 auto;
  overflow-x: auto;
  scrollbar-width: none;
}

.auqg-tabstrip::-webkit-scrollbar {
  display: none;
}

.auqg-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
  max-width: 220px;
  padding: 3px 8px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.4;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;
}

.auqg-tab:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.auqg-tab.is-active {
  border-color: var(--border-color);
  background: var(--bg-active);
  color: var(--text-primary);
}

.auqg-tab:focus-visible {
  outline: 2px solid var(--accent-color);
  outline-offset: 1px;
}

.auqg-tab-index {
  flex: 0 0 auto;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-tertiary);
  letter-spacing: 0.3px;
}

.auqg-tab.is-active .auqg-tab-index {
  color: var(--text-secondary);
}

.auqg-tab-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.auqg-tab-status {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
}

.auqg-tab-status--waiting {
  color: var(--accent-blue, #3b82f6);
}

.auqg-tab-status--answered {
  color: var(--accent-green, #22c55e);
}

.auqg-tab-status--cancelled,
.auqg-tab-status--interrupted,
.auqg-tab-status--error {
  color: var(--accent-red-text);
}

/* 等待回答：进行中的脉冲点（其余终态用图标）。 */
.auqg-tab-pulse {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  animation: auqg-pulse 1.4s ease-in-out infinite;
}

@keyframes auqg-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }

  50% {
    opacity: 0.35;
    transform: scale(0.75);
  }
}

.auqg-nav {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex: 0 0 auto;
}

.auqg-nav button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
}

.auqg-nav button:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* 一次只显示一个问题面板；长问题由容器限高 + 内部滚动兜住。 */
.auqg-panels {
  max-height: 60vh;
  overflow-y: auto;
  overscroll-behavior: contain;
}

.tool-call-user-question--panel {
  margin: 0;
}

@media (prefers-reduced-motion: reduce) {
  .tool-call-user-question-group,
  .auqg-tab-pulse {
    animation: none;
  }

  .auqg-tab {
    transition: none;
  }
}

.tool-call-plan-approval-body {
  gap: 12px;
}

.tool-call-plan-approval-heading {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-plan-approval-heading > svg {
  flex: 0 0 auto;
  margin-top: 1px;
  color: var(--text-primary);
}

.tool-call-plan-approval-heading strong {
  display: block;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  line-height: 1.45;
}

.tool-call-plan-approval-heading p {
  margin: 3px 0 0;
  color: var(--text-tertiary);
  font-size: 11.5px;
  line-height: 1.5;
}

.tool-call-plan-approval-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  color: var(--text-tertiary);
  font-size: 11px;
}

.tool-call-plan-approval-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
}

.tool-call-plan-approval-continue,
.tool-call-plan-approval-approve {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  min-height: 28px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
}

.tool-call-plan-approval-continue {
  border: 1px solid var(--border-color);
  background: transparent;
  color: var(--text-secondary);
}

.tool-call-plan-approval-continue:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.tool-call-plan-approval-approve {
  border: 1px solid var(--text-primary);
  background: var(--text-primary);
  color: var(--bg-primary);
}

.tool-call-plan-approval-approve:hover {
  opacity: 0.88;
}

.tool-call-plan-approval-continue:focus-visible,
.tool-call-plan-approval-approve:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 2px;
}

/* ===== WorkFlow tool call ===== */
.tool-call-workflow-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.workflow-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.workflow-canvas-wrap {
  position: relative;
}

/* 空图（JSON 截断/解析失败）收掉画布后的紧凑占位提示。 */
.workflow-canvas-empty {
  padding: 10px 12px;
  border: 1px dashed var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* 画布收起条：同一 flow 的画布只由「发起当前 run 的卡片」展示，被其他
   卡片（续跑）接管时收成一行提示 + 展开按钮。 */
.workflow-canvas-collapsed {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px dashed var(--border-light);
  border-radius: var(--radius-sm);
  color: var(--text-tertiary);
  font-size: 12px;
}

.workflow-canvas-collapsed span:first-of-type {
  flex: 1;
  min-width: 0;
}

.workflow-canvas-collapsed button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  flex-shrink: 0;
}

.workflow-canvas-collapsed button:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.workflow-canvas {
  height: 500px;
  min-height: 380px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  overflow: hidden;
}

/* React Flow 主题化：@xyflow/react 默认样式写死浅色（控制面板白底、
   深色手柄/连线等），其自带 dark 变量只在容器加 .dark 类时生效，与项目
   data-theme 机制不联动。这里按画布作用域覆盖 --xy-* 默认值并映射到
   设计令牌，亮/暗及自定义主题预设自动跟随。 */
.workflow-canvas .react-flow {
  --xy-edge-stroke-default: var(--text-muted);
  --xy-edge-stroke-selected-default: var(--text-secondary);
  --xy-background-pattern-dots-color-default: var(--border-subtle);
  --xy-handle-background-color-default: var(--text-tertiary);
  --xy-handle-border-color-default: var(--bg-secondary);
  --xy-controls-button-background-color-default: var(--bg-primary);
  --xy-controls-button-background-color-hover-default: var(--bg-hover);
  --xy-controls-button-color-default: var(--text-secondary);
  --xy-controls-button-color-hover-default: var(--text-primary);
  --xy-controls-button-border-color-default: var(--border-light);
  --xy-controls-box-shadow-default: 0 8px 24px rgba(0, 0, 0, 0.18);
}

.workflow-canvas .react-flow__controls {
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  overflow: hidden;
}

/* 连线视觉：线条稍加粗提升辨识度；流向箭头（marker 为共享 defs，无法按
   边状态区分颜色）与线条共用同一令牌，亮/暗主题自动跟随。 */
.workflow-canvas .react-flow__edge-path {
  stroke-width: 1.5;
}

.workflow-canvas .react-flow__arrowclosed path,
.workflow-canvas .react-flow__arrowclosed polyline,
.workflow-canvas .react-flow__arrowclosed polygon {
  fill: var(--xy-edge-stroke-default);
  stroke: var(--xy-edge-stroke-default);
}

.workflow-node {
  min-width: 130px;
  max-width: 190px;
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  font-size: 11px;
  color: var(--text-primary);
}

.workflow-node.is-selected {
  border-color: var(--text-primary);
}

/* 运行中（loading）节点的边框高亮：仅描边跟随主题色（--accent-color）；
   置于 is-selected 之后，运行态优先展示。 */
.workflow-node.is-running {
  border-color: var(--accent-color);
}

.workflow-node-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

/* 节点状态 icon：完成绿色、失败红色（与错误文案色一致）。 */
.workflow-node-icon-completed {
  color: #3fb950;
}

.workflow-node-icon-failed {
  color: #f85149;
}

.workflow-node-title {
  font-weight: 600;
  font-size: 12px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.workflow-node-description {
  margin-top: 3px;
  color: var(--text-tertiary);
  font-size: 10.5px;
  line-height: 1.4;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.workflow-node-error {
  margin-top: 5px;
  padding: 4px 6px;
  border-radius: 4px;
  background: rgba(248, 81, 73, 0.12);
  color: #f85149;
  font-size: 10px;
  word-break: break-all;
}

.workflow-context-menu {
  position: absolute;
  z-index: 20;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 148px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
}

.workflow-context-menu button {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  text-align: left;
  cursor: pointer;
}

.workflow-context-menu button:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* 删除二次确认浮层：画布内居中，确认后才真正删除。 */
.workflow-delete-confirm {
  position: absolute;
  z-index: 30;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 262px;
  padding: 12px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
}

.workflow-delete-confirm-title {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 600;
}

.workflow-delete-confirm-title svg {
  color: #f85149;
}

.workflow-delete-confirm-content {
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.5;
}

.workflow-delete-confirm-hint {
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.workflow-delete-confirm-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 4px;
}

.workflow-delete-confirm-actions button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px;
  border-radius: 4px;
  font-size: 11.5px;
  cursor: pointer;
}

.workflow-delete-confirm-cancel {
  border: 1px solid var(--border-color);
  background: var(--bg-secondary);
  color: var(--text-secondary);
}

.workflow-delete-confirm-cancel:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.workflow-delete-confirm-confirm {
  border: 1px solid rgba(248, 81, 73, 0.5);
  background: rgba(248, 81, 73, 0.12);
  color: #f85149;
}

.workflow-delete-confirm-confirm:hover {
  background: rgba(248, 81, 73, 0.2);
}

/* 删除后的撤销提示条：画布底部居中，避开左下角 Controls。 */
.workflow-undo-toast {
  position: absolute;
  z-index: 30;
  bottom: 34px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
  color: var(--text-secondary);
  font-size: 11.5px;
  white-space: nowrap;
}

.workflow-undo-toast button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: transparent;
  color: var(--text-primary);
  font-size: 11.5px;
  cursor: pointer;
}

.workflow-undo-toast button:hover {
  background: var(--bg-hover);
}

.workflow-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.workflow-execute-hint {
  color: var(--text-tertiary);
  font-size: 11px;
}

.workflow-reply {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.workflow-reply-label {
  color: var(--text-tertiary);
  font-size: 11px;
}

/* 已提交的反馈内容：用户拒绝当前流程后的意见留痕。 */
.workflow-reply-record {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.workflow-reply-record-label {
  color: var(--text-tertiary);
  font-size: 11px;
}

.workflow-reply-record-content {
  margin: 0;
  color: var(--text-primary);
  font-size: 12px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
}

.workflow-reply textarea {
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 12px;
  font-family: inherit;
  resize: vertical;
}

.workflow-reply textarea:focus {
  outline: none;
  border-color: var(--accent-color);
}

.workflow-reply .tool-call-plan-approval-approve {
  align-self: flex-end;
}

.workflow-reply .tool-call-plan-approval-approve:disabled {
  opacity: 0.5;
  cursor: default;
}

.workflow-node-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.workflow-node-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.workflow-node-row-main {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  min-height: 26px;
  padding: 4px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-secondary);
  font-size: 11.5px;
  cursor: pointer;
}

.workflow-node-row-main:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.workflow-node-row-label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
}

.workflow-node-row-open {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
}

.workflow-node-row-open:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.workflow-editor {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.workflow-editor .custom-select-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.workflow-editor-overlay {
  position: absolute;
  z-index: 10;
  width: 280px;
  max-height: calc(100% - 16px);
  overflow-y: auto;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
}

.workflow-editor-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 600;
}

.workflow-editor-header > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.workflow-editor-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border: none;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
}

.workflow-editor-close:hover {
  color: var(--text-primary);
}

.workflow-editor-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  color: var(--text-tertiary);
  font-size: 11px;
}

.workflow-editor-field input,
.workflow-editor-field textarea {
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 12px;
  font-family: inherit;
  resize: vertical;
}

.workflow-editor-field input:focus,
.workflow-editor-field textarea:focus {
  outline: none;
  border-color: var(--accent-color);
}

.workflow-editor-field input:disabled,
.workflow-editor-field textarea:disabled {
  opacity: 0.6;
}

/* 编辑浮层下拉的加载/错误提示。 */
.workflow-editor-hint {
  color: var(--text-tertiary);
  font-size: 10px;
}

.workflow-editor-footer {
  display: flex;
  justify-content: flex-end;
}

.workflow-editor-footer .tool-call-plan-approval-continue:disabled {
  opacity: 0.5;
  cursor: default;
}

/* 定时任务工作流画布 */
.st-workflow-canvas-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.st-workflow-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* 外观复用 .scheduled-tasks-new-btn，这里只覆盖尺寸（提高优先级压过预设主题） */
.st-workflow-canvas-wrap
  .st-workflow-toolbar
  .st-workflow-toolbar-btn.scheduled-tasks-new-btn {
  flex-shrink: 0;
  gap: 4px;
  width: auto;
  height: auto;
  min-height: 0;
  padding: 4px 10px;
  font-size: 12px;
}

.st-workflow-toolbar-btn.st-workflow-expand-btn {
  margin-left: auto;
}

/* 画布放大弹窗 */
.st-workflow-modal-overlay {
  padding: 32px;
}

.st-workflow-modal {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 1600px;
  height: min(72vh, 720px);
  padding: 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--bg-primary);
  box-shadow: var(--shadow-xl);
}

.st-workflow-modal .st-workflow-canvas-wrap {
  flex: 1;
  min-height: 0;
}

.st-workflow-modal .workflow-canvas.st-workflow-canvas {
  flex: 1;
  height: auto;
  min-height: 0;
}

.workflow-canvas.st-workflow-canvas {
  position: relative;
  height: 420px;
  min-height: 320px;
}

/* 获得焦点后才响应滚轮缩放 */
.workflow-canvas.st-workflow-canvas.is-focused {
  border-color: var(--accent-color);
}

.st-workflow-empty {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-tertiary);
  font-size: 12px;
  pointer-events: none;
}

/* ===== 输入区 WorkFlow 手动编排器弹窗（复用定时任务画布） ===== */
.workflow-composer-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* 画布容器给显式高度，保证 React Flow 有可测量的绘制区域 */
.workflow-composer-canvas {
  display: flex;
  height: min(60vh, 560px);
  min-height: 0;
}

.workflow-composer-canvas > .st-workflow-canvas-wrap {
  flex: 1;
  min-height: 0;
}

/* 画布高度撑满容器（定时任务画布默认固定 420px） */
.workflow-composer-canvas .workflow-canvas.st-workflow-canvas {
  flex: 1;
  height: auto;
  min-height: 0;
}

/* 备注输入区 */
.workflow-composer-note {
  min-height: 52px;
  resize: vertical;
}

/* 空画布轻提示 */
.workflow-composer-hint {
  margin: 0;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

/* 发送前校验错误 */
.workflow-composer-error {
  margin: 0;
  color: var(--accent-red-text);
  font-size: 11.5px;
  line-height: 1.5;
}

/* 输入工具栏的手动编排入口：仅在 WorkFlow 模式开启时出现，视觉对齐模式徽标口径
   （26×26 紧凑方形 + 强调色）。选择器带 .toolbar-btn 提升特异性，避免被
   后面定义的 .toolbar-btn 基础样式（padding/color）覆盖。 */
.toolbar-btn.workflow-composer-trigger {
  width: 26px;
  height: 26px;
  padding: 0;
  justify-content: center;
  color: var(--accent);
}

.toolbar-btn.workflow-composer-trigger:hover {
  color: var(--accent);
}

.st-workflow-node .workflow-node-description {
  white-space: pre-wrap;
}

.st-workflow-node-hint {
  margin-top: 4px;
  color: var(--text-tertiary);
  font-size: 11px;
}

.st-workflow-node-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  margin-top: 5px;
}

.st-workflow-node-tag {
  max-width: 120px;
  padding: 1px 5px;
  border: 1px solid var(--border-light);
  border-radius: 4px;
  color: var(--text-tertiary);
  font-size: 10px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.st-workflow-node-status {
  color: var(--text-tertiary);
  font-size: 10px;
}

/* 只读画布节点外包 Tooltip：撑满节点，避免 inline 基线留白 */
.react-flow__node-stWorkflowCard > .tooltip-wrapper {
  display: flex;
}

.st-workflow-node-tip {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-width: 260px;
}

.st-workflow-node-tip-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--text-primary);
  font-weight: 600;
  word-break: break-word;
}

.st-workflow-node-tip-status {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 3px;
  color: var(--text-tertiary);
  font-weight: 400;
}

.st-workflow-node-tip-field {
  display: flex;
  flex-direction: column;
  gap: 2px;
  word-break: break-word;
}

.st-workflow-node-tip-label {
  color: var(--text-tertiary);
  font-size: 10px;
}

.st-workflow-node-tip-prompt {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 12;
  overflow: hidden;
  color: var(--text-primary);
  white-space: pre-wrap;
}

.st-workflow-node-tip-error {
  padding: 4px 6px;
  border-radius: 4px;
  background: rgba(248, 81, 73, 0.12);
  color: #f85149;
  word-break: break-all;
}

.st-workflow-node-tip-hint {
  color: var(--text-tertiary);
  font-size: 10px;
}

.st-workflow-icon-muted {
  color: var(--text-tertiary);
}

.st-workflow-edge-label {
  position: absolute;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 6px;
  border: 1px solid var(--border-light);
  border-radius: 10px;
  background: var(--bg-primary);
  color: var(--text-tertiary);
  font-size: 10px;
  line-height: 16px;
  white-space: nowrap;
  cursor: pointer;
  pointer-events: all;
}

.st-workflow-edge-label.has-delay {
  border-color: var(--accent-color);
  color: var(--text-primary);
}

.st-workflow-edge-label:disabled {
  cursor: default;
}

.st-workflow-edge-label:not(:disabled):hover {
  background: var(--bg-hover);
}

.st-workflow-delay-editor {
  width: 240px;
}

.st-workflow-delay-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.st-workflow-delay-row input {
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 12px;
}

.st-workflow-editor .workflow-editor-footer {
  justify-content: space-between;
}

.st-workflow-danger-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  border: 1px solid rgba(248, 81, 73, 0.5);
  border-radius: 4px;
  background: rgba(248, 81, 73, 0.12);
  color: #f85149;
  font-size: 11.5px;
  cursor: pointer;
}

.st-workflow-danger-btn:hover {
  background: rgba(248, 81, 73, 0.2);
}

.st-workflow-context-badge {
  margin-left: 8px;
  padding: 1px 6px;
  border: 1px solid var(--border-light);
  border-radius: 4px;
  color: var(--text-tertiary);
  font-size: 11px;
  font-weight: 400;
}

.tool-call-file-path {
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--text-tertiary);
  word-break: break-all;
  user-select: text;
}

.tool-call-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-section-label {
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.tool-call-section-pre {
  margin: 0;
  max-height: 300px;
  overflow: auto;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-all;
}

/* Tool name badge with icon */
.tool-call-tool-name {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  background: var(--bg-active);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  line-height: 1.2;
}

.tool-call-tool-name-icon {
  display: block;
  flex-shrink: 0;
  opacity: 0.7;
}

/* TodoToolCall specific styles */
.tool-call-todo-action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.tool-call-todo-action-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-active);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}

.tool-call-todo-hint {
  font-size: 10.5px;
  color: var(--text-muted);
  font-style: italic;
}

/* 可点击的"在顶栏查看完整列表"入口：链接式交互反馈 */
.tool-call-todo-hint-link {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 2px 6px;
  margin: -2px -6px;
  border-radius: var(--radius-sm);
  font-family: inherit;
  font-style: normal;
  transition:
    color 0.15s ease,
    background-color 0.15s ease;
}

.tool-call-todo-hint-link:hover {
  color: var(--accent-primary-text, var(--text-secondary));
  background: var(--accent-primary-bg, var(--bg-active));
}

.tool-call-todo-count {
  font-size: 11px;
  color: var(--text-muted);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.tool-call-todo-args {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tool-call-todo-arg-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex-wrap: wrap;
}

.tool-call-todo-arg-label {
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  flex-shrink: 0;
}

.tool-call-todo-arg-value {
  margin: 0;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
  flex: 1;
  min-width: 0;
}

.tool-call-todo-arg-code {
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  word-break: break-all;
}

.tool-call-todo-status-badge {
  font-size: 11px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-weight: 500;
}

.tool-call-todo-status-pending {
  color: var(--text-muted);
  background: var(--bg-tertiary);
}

.tool-call-todo-status-inProgress {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}

.tool-call-todo-status-completed {
  color: var(--success);
  background: color-mix(in srgb, var(--success) 12%, transparent);
}

/* ============================================================
   Enhanced Tool Call Rendering Styles
   ============================================================ */

/* Bash Command Copy Button */
.tool-call-bash-command {
  position: relative;
}
.tool-call-bash-cmd-copy {
  position: absolute;
  top: 4px;
  right: 6px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: var(--bg-secondary, #21262d);
  color: var(--text-tertiary, #8b949e);
  border: 1px solid var(--border-color, #30363d);
  border-radius: var(--radius-xs, 3px);
  padding: 2px 6px;
  font-size: 10.5px;
  cursor: pointer;
  opacity: 0.6;
  transition:
    opacity 0.15s ease,
    color 0.15s ease;
}
.tool-call-bash-command:hover .tool-call-bash-cmd-copy {
  opacity: 1;
}
.tool-call-bash-cmd-copy:hover {
  color: var(--text-primary, #e6edf3);
  border-color: var(--accent, #58a6ff);
}

/* AnsiOutput Terminal Styles */
.tool-call-ansi-container {
  display: flex;
  flex-direction: column;
  width: 100%;
}
.tool-call-ansi-toolbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  margin-bottom: 4px;
}
.tool-call-ansi-filter-tabs {
  display: flex;
  align-items: center;
  gap: 4px;
}
.tool-call-ansi-filter-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-tertiary, #8b949e);
  font-size: 10.5px;
  padding: 1px 6px;
  border-radius: var(--radius-xs, 3px);
  cursor: pointer;
  transition: all 0.12s ease;
}
.tool-call-ansi-filter-btn:hover {
  color: var(--text-primary, #e6edf3);
  background: var(--bg-tertiary, #30363d);
}
.tool-call-ansi-filter-btn.active {
  color: var(--text-primary, #e6edf3);
  background: var(--bg-tertiary, #30363d);
  border-color: var(--border-color, #30363d);
}
.tool-call-ansi-filter-err.active {
  color: #f85149;
  border-color: rgba(248, 81, 73, 0.4);
}
.tool-call-ansi-output {
  position: relative;
}
.tool-call-ansi-copy-btn {
  position: absolute;
  top: 6px;
  right: 8px;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: var(--bg-secondary, #21262d);
  color: var(--text-tertiary, #8b949e);
  border: 1px solid var(--border-color, #30363d);
  border-radius: var(--radius-xs, 3px);
  padding: 2px 6px;
  font-size: 10.5px;
  cursor: pointer;
  opacity: 0.6;
  transition:
    opacity 0.15s ease,
    color 0.15s ease;
}
.tool-call-ansi-output:hover .tool-call-ansi-copy-btn {
  opacity: 1;
}
.tool-call-ansi-copy-btn:hover {
  color: var(--text-primary, #e6edf3);
  border-color: var(--accent, #58a6ff);
}
.tool-call-ansi-pre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-all;
}
.tool-call-ansi-line {
  line-height: 1.5;
}
.tool-call-ansi-line.is-error-line {
  background: rgba(248, 81, 73, 0.08);
  border-left: 2px solid #f85149;
  padding-left: 4px;
  margin-left: -6px;
}

/* CodeHighlightView Styles */
.tool-call-code-highlight-wrap {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border-color, #30363d);
  border-radius: var(--radius-md, 6px);
  background: var(--bg-secondary, #161b22);
  overflow: hidden;
  margin: 4px 0;
}
.tool-call-code-highlight-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 10px;
  background: var(--bg-tertiary, #21262d);
  border-bottom: 1px solid var(--border-color, #30363d);
}
.tool-call-code-file-badge {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  font-family: var(--font-mono, monospace);
  color: var(--text-primary, #e6edf3);
}
.tool-call-code-filename {
  font-weight: 500;
}
.tool-call-code-lang-tag,
.tool-call-code-lines-tag {
  font-size: 10px;
  color: var(--text-muted, #8b949e);
  background: var(--bg-primary, #0d1117);
  padding: 1px 5px;
  border-radius: 3px;
  border: 1px solid var(--border-color, #30363d);
}
.tool-call-code-copy-btn {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  background: transparent;
  border: none;
  color: var(--text-tertiary, #8b949e);
  font-size: 10.5px;
  padding: 2px 6px;
  border-radius: var(--radius-xs, 3px);
  cursor: pointer;
}
.tool-call-code-copy-btn:hover {
  color: var(--text-primary, #e6edf3);
}
.tool-call-code-scroll-area {
  overflow: auto;
  max-height: 480px;
}
.tool-call-code-table {
  display: table;
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-mono, monospace);
  font-size: 12px;
  line-height: 1.5;
}
.tool-call-code-row {
  display: table-row;
}
.tool-call-code-row:hover {
  background: rgba(255, 255, 255, 0.03);
}
.tool-call-code-lineno {
  display: table-cell;
  text-align: right;
  padding: 0 10px;
  user-select: none;
  color: var(--text-muted, #484f58);
  font-size: 11px;
  width: 1%;
  white-space: nowrap;
}
.tool-call-code-content {
  display: table-cell;
  padding: 0 10px 0 4px;
  white-space: pre-wrap;
  word-break: break-all;
  color: var(--text-primary, #e6edf3);
}

/* Todo Progress Enhancements */
.tool-call-todo-meta-wrap {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.tool-call-todo-progress-pill {
  font-size: 9.5px;
  font-weight: 600;
  padding: 1px 5px;
  border-radius: 9px;
  background: color-mix(in srgb, var(--accent, #58a6ff) 14%, transparent);
  color: var(--accent, #58a6ff);
}
.tool-call-todo-progress-track {
  width: 100%;
  height: 4px;
  border-radius: 2px;
  background: var(--bg-tertiary, #30363d);
  overflow: hidden;
  margin: 6px 0 2px 0;
}
.tool-call-todo-progress-fill {
  height: 100%;
  background: linear-gradient(
    90deg,
    var(--accent, #58a6ff),
    var(--success, #3fb950)
  );
  border-radius: 2px;
  transition: width 0.3s ease;
}

/* Generic Tool Call Table Enhancements */
.tool-call-generic-table-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 8px;
  background: var(--bg-tertiary, #21262d);
  border-bottom: 1px solid var(--border-color, #30363d);
  gap: 8px;
}
.tool-call-generic-table-search-box {
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--bg-primary, #0d1117);
  border: 1px solid var(--border-color, #30363d);
  border-radius: var(--radius-sm, 4px);
  padding: 2px 6px;
  flex: 1;
  max-width: 240px;
}
.tool-call-generic-table-search {
  background: transparent;
  border: none;
  outline: none;
  font-size: 11px;
  color: var(--text-primary, #e6edf3);
  width: 100%;
}
.tool-call-generic-table-search::placeholder {
  color: var(--text-muted, #8b949e);
}
.tool-call-generic-table-export-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--bg-primary, #0d1117);
  border: 1px solid var(--border-color, #30363d);
  color: var(--text-secondary, #c9d1d9);
  font-size: 10.5px;
  padding: 2px 8px;
  border-radius: var(--radius-xs, 3px);
  cursor: pointer;
  transition: all 0.12s ease;
}
.tool-call-generic-table-export-btn:hover {
  color: var(--text-primary, #e6edf3);
  border-color: var(--accent, #58a6ff);
}
.tool-call-generic-th-sortable {
  cursor: pointer;
  user-select: none;
  transition: background 0.12s ease;
}
.tool-call-generic-th-sortable:hover {
  background: var(--bg-hover, #30363d);
}
.tool-call-generic-th-sortable span {
  margin-right: 4px;
}
.tool-call-generic-th-sortable .sort-idle {
  opacity: 0.3;
}

/* ============================================================
   DataTableViewer & Extra UX Enhancements
   ============================================================ */

/* DataTableViewer */

/* CodeHighlightView Expand Bar */
.tool-call-code-expand-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 10px;
  background: var(--bg-tertiary, #21262d);
  border-top: 1px solid var(--border-color, #30363d);
  font-size: 10.5px;
  color: var(--text-muted, #8b949e);
}
.tool-call-code-expand-btn {
  background: transparent;
  border: none;
  color: var(--accent, #58a6ff);
  font-size: 10.5px;
  cursor: pointer;
}
.tool-call-code-expand-btn:hover {
  text-decoration: underline;
}

/* Filesystem Edit Closest Hint */
.tool-call-edit-closest-hint {
  margin-top: 6px;
  padding: 6px 8px;
  border-radius: var(--radius-sm, 4px);
  background: rgba(210, 153, 34, 0.08);
  border: 1px solid rgba(210, 153, 34, 0.3);
}
.tool-call-edit-closest-title {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 500;
  color: var(--warning, #d29922);
  margin-bottom: 4px;
}
.tool-call-edit-closest-pre {
  margin: 0;
  padding: 4px 6px;
  background: var(--bg-primary, #0d1117);
  border: 1px solid var(--border-color, #30363d);
  font-size: 11px;
  line-height: 1.4;
  color: var(--text-primary, #e6edf3);
}

/* ============================================================
   Hook Execution UI - shows hook execution results
   ============================================================ */
.hook-exec-group {
  align-self: stretch;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.hook-exec-group--has-failure .hook-exec-group-header {
  color: var(--accent-red-text);
}

.hook-exec-group--has-warning .hook-exec-group-header {
  color: var(--warning, #e0a800);
}

.hook-exec-group-header {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11.5px;
  color: var(--text-tertiary);
  padding: 2px 0;
}

.hook-exec-group-header svg {
  flex-shrink: 0;
  opacity: 0.7;
}

.hook-exec-group-title {
  font-weight: 500;
}

.hook-exec-group-count {
  color: var(--text-muted);
}

.hook-exec-group-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-left: 6px;
  padding-left: 12px;
  border-left: 1.5px solid var(--border-light);
}

.hook-exec-item {
  position: relative;
}

.hook-exec-item-header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 5px 6px;
  cursor: pointer;
  list-style: none;
  font-size: 12px;
  line-height: 1.4;
  user-select: none;
  border-radius: var(--radius-sm);
  transition: background 0.15s ease;
}

.hook-exec-item-header::-webkit-details-marker {
  display: none;
}

.hook-exec-item-header:focus {
  outline: none;
}

.hook-exec-item-header:focus-visible {
  background: var(--bg-hover);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--accent) 42%, transparent);
}

.hook-exec-item-header:hover {
  background: var(--bg-hover);
  border-radius: var(--radius-sm);
}

.hook-exec-status-icon {
  flex-shrink: 0;
}

.hook-exec-status-pass {
  color: var(--success, #22c55e);
}

.hook-exec-status-warn {
  color: var(--warning, #e0a800);
}

.hook-exec-status-abort {
  color: var(--accent-red-text, #ef4444);
}

.hook-exec-item-sep {
  color: var(--text-muted);
  opacity: 0.5;
}

.hook-exec-item-label {
  color: var(--text-secondary);
  font-size: 11.5px;
}

.hook-exec-item-actions {
  font-size: 10.5px;
  color: var(--text-muted);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.hook-exec-item-chevron {
  flex-shrink: 0;
  transition: transform 0.15s ease;
  color: var(--text-tertiary);
  margin-left: auto;
}

.hook-exec-item-chevron--open {
  transform: rotate(90deg);
}

.hook-exec-item-body {
  padding: 4px 0 8px 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.hook-exec-block-message {
  overflow: hidden;
  border: 1px solid
    color-mix(in srgb, var(--accent-red-text, #ef4444) 28%, var(--border-light));
  border-radius: var(--radius-md);
  background: color-mix(
    in srgb,
    var(--accent-red-text, #ef4444) 7%,
    var(--bg-secondary)
  );
}

.hook-exec-block-message-header,
.hook-exec-action-header,
.hook-exec-output-header {
  display: flex;
  align-items: center;
  min-width: 0;
}

.hook-exec-block-message-header {
  gap: 6px;
  padding: 7px 10px;
  font-size: 11px;
  font-weight: 600;
  color: var(--accent-red-text, #ef4444);
  border-bottom: 1px solid
    color-mix(in srgb, var(--accent-red-text, #ef4444) 18%, transparent);
}

.hook-exec-block-message-header > span {
  flex: 1;
}

.hook-exec-block-message p {
  margin: 0;
  padding: 9px 10px;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
}

.hook-exec-actions-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.hook-exec-action {
  overflow: hidden;
  min-width: 0;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: transparent;
}

.hook-exec-action--error {
  border-color: color-mix(
    in srgb,
    var(--accent-red-text, #ef4444) 28%,
    var(--border-light)
  );
}

.hook-exec-action-header {
  gap: 6px;
  padding: 6px 8px;
  color: var(--text-tertiary);
  background: color-mix(in srgb, var(--text-primary) 4%, transparent);
  border-bottom: 1px solid var(--border-light);
}

.hook-exec-action--success > .hook-exec-action-header > svg {
  color: var(--success, #22c55e);
}

.hook-exec-action--error > .hook-exec-action-header > svg {
  color: var(--accent-red-text, #ef4444);
}

.hook-exec-action-index {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.hook-exec-action-type,
.hook-exec-exit-code {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10.5px;
  line-height: 1.5;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
}

.hook-exec-exit-code--success {
  color: var(--success, #22c55e);
  background: color-mix(in srgb, var(--success, #22c55e) 10%, transparent);
}

.hook-exec-exit-code--error {
  color: var(--accent-red-text, #ef4444);
  background: color-mix(
    in srgb,
    var(--accent-red-text, #ef4444) 10%,
    transparent
  );
}

.hook-exec-copy {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  min-width: 20px;
  margin-left: auto;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  opacity: 0.7;
  transition:
    color 0.15s ease,
    background 0.15s ease,
    opacity 0.15s ease;
}

.hook-exec-copy:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
  opacity: 1;
}

.hook-exec-copy:focus-visible {
  outline: 1px solid var(--accent);
  outline-offset: 1px;
}

.hook-exec-copy--copied {
  color: var(--success, #22c55e);
  opacity: 1;
}

.hook-exec-action-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.hook-exec-output-section + .hook-exec-output-section {
  border-top: 1px solid var(--border-light);
}

.hook-exec-output-section--error {
  background: color-mix(
    in srgb,
    var(--accent-red-text, #ef4444) 4%,
    transparent
  );
}

.hook-exec-output-section--context {
  background: color-mix(in srgb, var(--accent) 4%, transparent);
}

.hook-exec-output-header {
  gap: 6px;
  min-height: 26px;
  padding: 2px 6px 2px 8px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-tertiary);
}

.hook-exec-output-meta {
  flex-shrink: 0;
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  font-size: 9.5px;
  font-weight: 500;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 9%, transparent);
}

.hook-exec-output-section--error .hook-exec-output-header {
  color: var(--accent-red-text, #ef4444);
}

.hook-exec-output-section--context .hook-exec-output-header {
  color: var(--accent);
}

.hook-exec-output-content {
  margin: 0;
  max-height: 180px;
  overflow: auto;
  padding: 6px 8px 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--text-primary) 3%, transparent);
  white-space: pre-wrap;
  word-break: break-word;
}

.hook-exec-empty-output {
  padding: 10px;
  font-size: 11.5px;
  color: var(--text-muted);
  font-style: italic;
}

.hook-exec-item--abort .hook-exec-item-label,
.hook-exec-item--error .hook-exec-item-label {
  color: var(--accent-red-text, #ef4444);
}

.hook-exec-item--warn .hook-exec-item-label,
.hook-exec-item--needsDecision .hook-exec-item-label {
  color: var(--warning, #e0a800);
}

.hook-exec-item--pass .hook-exec-item-label {
  color: var(--success, #22c55e);
}

.hook-exec-status-decision {
  color: var(--warning, #e0a800);
}

.hook-exec-decision {
  margin: 4px 0 8px 24px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  border: 1px solid
    color-mix(in srgb, var(--warning, #e0a800) 28%, var(--border-light));
  border-radius: var(--radius-md);
  background: color-mix(
    in srgb,
    var(--warning, #e0a800) 6%,
    var(--bg-secondary)
  );
}

.hook-exec-decision-message {
  margin: 0;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
}

.hook-exec-decision-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.hook-exec-decision-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 28px;
  padding: 4px 12px;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.hook-exec-decision-btn:hover {
  opacity: 0.85;
}

.hook-exec-decision-btn:active {
  opacity: 0.7;
}

.hook-exec-decision-btn:focus-visible {
  outline: 1px solid var(--accent);
  outline-offset: 2px;
}

.hook-exec-decision-approve {
  background: color-mix(in srgb, var(--success, #22c55e) 15%, transparent);
  color: var(--success, #22c55e);
}

.hook-exec-decision-reject {
  background: color-mix(
    in srgb,
    var(--accent-red-text, #ef4444) 15%,
    transparent
  );
  color: var(--accent-red-text, #ef4444);
}

@media (max-width: 720px) {
  .hook-exec-group {
    max-width: 100%;
  }

  .hook-exec-group-list {
    margin-left: 4px;
    padding-left: 10px;
  }

  .hook-exec-item-header {
    gap: 4px;
    padding-inline: 4px;
  }

  .hook-exec-item-label {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .hook-exec-item-body,
  .hook-exec-decision {
    margin-left: 0;
    padding-left: 12px;
  }

  .hook-exec-item-body {
    padding-right: 2px;
  }

  .hook-exec-action-header {
    flex-wrap: wrap;
  }

  .hook-exec-action-header .hook-exec-copy {
    margin-left: auto;
  }
}

.tool-call-todo-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  font-size: 12px;
  color: var(--text-muted);
}

.tool-call-todo-pending-running {
  color: var(--text-secondary);
}

.tool-call-line-range {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 11px;
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.tool-call-cache-badge {
  display: inline-flex;
  align-items: center;
  font-size: 10px;
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  border: 1px solid var(--border-subtle, transparent);
}

.tool-call-error {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
  font-size: 12px;
  line-height: 1.4;
  min-width: 0;
  overflow-wrap: anywhere;
}

.tool-call-error > span {
  min-width: 0;
}

/* 无文案的错误行（如拒绝场景：理由已由卡片下方的提示条承载）整体隐藏，
   避免只剩一个孤零零的错误图标。 */
.tool-call-error:has(> span:empty),
.tool-call-codelens-no-results:has(> span:empty) {
  display: none;
}

.tool-call-error svg {
  display: block;
  flex-shrink: 0;
}

/* 生图错误：本地化标题 + 原始英文详情（小字次级展示） */
.tool-call-error-summary {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.tool-call-error-title {
  font-weight: 500;
}

.tool-call-error-detail {
  font-size: 11px;
  opacity: 0.75;
  word-break: break-all;
  white-space: pre-wrap;
}

/* 生图部分失败警告条（n 张中有失败时展示失败摘要） */
.tool-call-imagegen-partial-warning {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 8px;
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
  font-size: 12px;
  line-height: 1.5;
  word-break: break-all;
}

.tool-call-imagegen-partial-warning svg {
  display: block;
  flex-shrink: 0;
  margin-top: 2px;
}

.tool-call-dir-listing {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 300px;
  overflow: auto;
}

.tool-call-dir-entry {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: var(--text-secondary);
  padding: 2px 4px;
  border-radius: var(--radius-sm);
}

.tool-call-dir-entry:hover {
  background: var(--bg-hover);
}

.tool-call-dir-entry svg {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-file-result {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-file-meta {
  font-size: 11px;
  color: var(--text-tertiary);
  padding: 2px 0;
}

.tool-call-file-content {
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-secondary);
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  padding: 6px 8px;
  white-space: pre;
  overflow: auto;
  max-height: 400px;
}

.tool-call-image-result {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-image-preview {
  max-width: 100%;
  max-height: 300px;
  object-fit: contain;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

:is(.ai-message, .context-compaction-markdown, .thinking-block-body)
  .tool-call-image-preview {
  cursor: default;
}

.tool-call-pending {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

/* Filesystem Read - Multi-file */
.tool-call-multi-files {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tool-call-multi-file-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
}

.tool-call-multi-file-header {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tool-call-multi-file-header svg {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-multi-file-name {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-multi-file-path {
  font-size: 10.5px;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Filesystem Edit / Create Tool Call */
.tool-call-diff-stats {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-family: var(--font-mono);
  flex-shrink: 0;
}

.tool-call-diff-add {
  color: var(--accent-green-text);
}

.tool-call-diff-del {
  color: var(--accent-red-text);
}

.tool-call-diff-content {
  position: relative;
  max-height: 400px;
  overflow: auto;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.5;
}

.tool-call-diff-shell {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.tool-call-diff-view {
  min-width: 0;
}

.tool-call-diff-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 4px;
}

.tool-call-diff-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
}

.tool-call-diff-action-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.tool-call-diff-action-btn.active {
  background: var(--bg-active);
  color: var(--text-primary);
}

.tool-call-meta-row {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
}

.tool-call-meta-label {
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.tool-call-meta-value {
  font-family: var(--font-mono);
  color: var(--text-secondary);
}

.tool-call-success-row {
  font-size: 11.5px;
  color: var(--accent-green-text);
  padding: 4px 0;
}

/* Bash Tool Call */
.tool-call-bash-exit-code {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10.5px;
}

.tool-call-bash-exit-success {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.tool-call-bash-exit-error {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
}

.tool-call-bash-timeout-badge {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--accent-orange-text, #e8973a);
  background: color-mix(
    in srgb,
    var(--accent-orange-text, #e8973a) 14%,
    transparent
  );
}

.tool-call-bash-detached-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--accent-blue-text, #4a9eff);
  background: color-mix(
    in srgb,
    var(--accent-blue-text, #4a9eff) 14%,
    transparent
  );
}

/* 决策模型判定徽章（卡片头部）：托管自动放行/拒绝的敏感命令 */
.tool-call-bash-decision-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10.5px;
  line-height: 1.6;
}

.tool-call-bash-decision-badge em {
  font-style: normal;
  opacity: 0.75;
}

.tool-call-bash-decision-allow {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.tool-call-bash-decision-deny {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
}

/* 模型拒绝但用户复核后已确认执行 */
.tool-call-bash-decision-overridden {
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

/* Tooltip 内容：判定标题 / 理由 / 判定模型 */
.tool-call-bash-decision-tip-title {
  display: block;
  font-weight: 600;
}

.tool-call-bash-decision-tip-reason {
  display: block;
  margin-top: 2px;
}

.tool-call-bash-decision-tip-model {
  display: block;
  margin-top: 2px;
  opacity: 0.75;
}

/* 决策模型判定详情（卡片内部） */
.tool-call-bash-decision {
  display: grid;
  gap: 4px;
  min-width: 0;
  margin-bottom: 6px;
  padding: 6px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
}

.tool-call-bash-decision-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.tool-call-bash-decision-verdict {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  font-size: 12px;
  line-height: 1.4;
}

.tool-call-bash-decision-is-allow .tool-call-bash-decision-verdict {
  color: var(--accent-green-text);
}

.tool-call-bash-decision-is-deny .tool-call-bash-decision-verdict {
  color: var(--accent-red-text);
}

.tool-call-bash-decision-is-overridden .tool-call-bash-decision-verdict {
  color: var(--accent-amber-text);
}

.tool-call-bash-decision-tag {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  color: var(--text-muted);
  background: color-mix(in srgb, var(--text-muted) 12%, transparent);
  font-size: 10.5px;
}

.tool-call-bash-decision-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  color: var(--text-muted);
  font-size: 11px;
}

.tool-call-bash-decision-reason {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.5;
  user-select: text;
}

.tool-call-bash-logpath {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 6px;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--text-secondary) 8%, transparent);
  word-break: break-all;
}

.tool-call-bash-countdown {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
}

.tool-call-bash-countdown-urgent {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
  animation: tool-call-bash-countdown-pulse 0.8s ease-in-out infinite;
}

@keyframes tool-call-bash-countdown-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.6;
  }
}

.tool-call-bash-kill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  padding: 2px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 10.5px;
  line-height: 1.4;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
}

.tool-call-bash-kill:hover:not(:disabled) {
  border-color: var(--accent-red-text);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.tool-call-bash-kill:disabled {
  opacity: 0.7;
  cursor: default;
  animation: tool-call-bash-countdown-pulse 1s ease-in-out infinite;
}

/* 终止二次确认态：按钮转为警示配色，配合自动展开的确认 tooltip 提示
   「需再次点击」；确认态超时或点击别处即回到默认外观。 */
.tool-call-bash-kill-armed {
  border-color: var(--accent-red-text);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
  font-weight: 600;
}

/* 终止二次确认 tooltip 内容：标题 + 操作提示两行。 */
.tool-call-bash-kill-confirm {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tool-call-bash-kill-confirm-title {
  color: var(--text-primary);
  font-weight: 600;
}

.tool-call-bash-kill-confirm-hint {
  color: var(--text-tertiary);
}

.tool-call-bash-timeout-notice {
  border-left: 2px solid var(--accent-orange-text, #e8973a);
}

.tool-call-bash-body {
  gap: 10px;
}

.tool-call-bash-terminal {
  overflow: hidden;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-bash-terminal-live {
  border-color: color-mix(
    in srgb,
    var(--accent-blue-text) 28%,
    var(--border-light)
  );
}
.tool-call-bash-workdir {
  padding: 6px 12px;
  border-bottom: 1px solid var(--border-light);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.4;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  user-select: text;
}

.tool-call-bash-description {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 12px;
  border-bottom: 1px solid var(--border-light);
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.45;
  user-select: text;
}

.tool-call-bash-description svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--accent-blue-text);
}

.tool-call-bash .tool-call-bash-command {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  max-height: 180px;
  margin: 0;
  padding: 10px 12px;
  overflow: auto;
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}

.tool-call-bash .tool-call-bash-command code {
  min-width: 0;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  white-space: inherit;
  word-break: inherit;
}

.tool-call-bash-prompt {
  flex-shrink: 0;
  color: var(--accent-green-text);
  user-select: none;
}

.tool-call-bash .tool-call-bash-output-pre {
  max-height: 320px;
  margin: 0;
  padding: 10px 12px;
  border-top: 1px solid var(--border-light);
  overflow: auto;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.55;
  white-space: pre;
  user-select: text;
}

.tool-call-bash-stream-cursor {
  display: inline-block;
  width: 6px;
  height: 12px;
  margin-left: 2px;
  vertical-align: -2px;
  background: currentColor;
  animation: tool-call-bash-cursor-blink 0.9s steps(2, start) infinite;
}

.tool-call-bash-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border-top: 1px solid var(--border-light);
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.tool-call-bash-pending-running {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-bash-loading-dots {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: auto;
}

.tool-call-bash-loading-dots i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
  animation: tool-call-bash-dot-pulse 1.1s ease-in-out infinite;
}

.tool-call-bash-loading-dots i:nth-child(2) {
  animation-delay: 0.14s;
}

.tool-call-bash-loading-dots i:nth-child(3) {
  animation-delay: 0.28s;
}

@keyframes tool-call-bash-dot-pulse {
  0%,
  70%,
  100% {
    opacity: 0.25;
    transform: translateY(0);
  }
  35% {
    opacity: 1;
    transform: translateY(-2px);
  }
}

@keyframes tool-call-bash-cursor-blink {
  50% {
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tool-call-bash-loading-dots i,
  .tool-call-bash-stream-cursor {
    animation: none;
  }
}

.tool-call-bash-interactive-badge {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--accent-orange-text, #e8973a);
  background: color-mix(
    in srgb,
    var(--accent-orange-text, #e8973a) 14%,
    transparent
  );
}

.tool-call-bash-terminal-interactive {
  border-color: color-mix(
    in srgb,
    var(--accent-orange-text, #e8973a) 28%,
    var(--border-light)
  );
}

.tool-call-bash-interactive-input-area {
  border-top: 1px solid var(--border-light);
  padding: 8px 12px;
}

.tool-call-bash-interactive-error {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  color: var(--accent-red-text);
  font-size: 11px;
}

.tool-call-bash-interactive-input-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tool-call-bash-interactive-input {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.4;
  outline: none;
  transition: border-color 0.15s ease;
}

.tool-call-bash-interactive-input:focus {
  border-color: var(--accent-color);
}

.tool-call-bash-interactive-input::placeholder {
  color: var(--text-tertiary);
}

.tool-call-bash-interactive-input:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.tool-call-bash-interactive-send {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--accent-orange-text, #e8973a);
  color: white;
  cursor: pointer;
  transition: opacity 0.15s ease;
}

.tool-call-bash-interactive-send:hover:not(:disabled) {
  opacity: 0.85;
}

.tool-call-bash-interactive-send:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Terminal Tool Call (terminal-open/send/read/resize/wait/close/focus/list) */
.tool-call-terminal-body {
  gap: 10px;
}

.tool-call-terminal-displayname {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.tool-call-terminal-displayname-icon {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-terminal-displayname code {
  min-width: 0;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font-family: var(--font-mono);
  font-size: 11.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tool-call-terminal-meta-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
  font-family: var(--font-mono);
  flex-shrink: 0;
}

.tool-call-terminal-meta-badge svg {
  color: var(--accent-blue-text);
}

.tool-call-terminal-success-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
  font-size: 10.5px;
  flex-shrink: 0;
}

.tool-call-terminal-args {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-terminal-arg-row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.tool-call-terminal-arg-label {
  flex-shrink: 0;
  min-width: 70px;
  color: var(--text-tertiary);
  font-size: 11px;
  line-height: 1.5;
}

.tool-call-terminal-arg-value {
  min-width: 0;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.5;
  word-break: break-all;
  user-select: text;
}

.tool-call-terminal-input-pre {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 0;
  padding: 0;
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}

.tool-call-terminal-input-pre code {
  min-width: 0;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  white-space: inherit;
  word-break: inherit;
}

.tool-call-terminal-prompt {
  flex-shrink: 0;
  color: var(--accent-green-text);
  user-select: none;
}

.tool-call-terminal-result {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tool-call-terminal-result-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tool-call-terminal-result-ok {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
  font-size: 11px;
  font-family: var(--font-mono);
}

.tool-call-terminal-result-empty {
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.tool-call-terminal-wait-status {
  display: inline-flex;
  align-items: center;
  padding: 1px 8px;
  border-radius: var(--radius-sm);
  font-size: 10.5px;
  font-weight: 500;
}

.tool-call-terminal-wait-idle {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.tool-call-terminal-wait-timeout {
  background: var(--accent-orange-bg, rgba(232, 151, 58, 0.12));
  color: var(--accent-orange-text, #e8973a);
}

/* 终端等待输入徽章：read/wait 检测到交互提示时显示（黄色警示） */
.tool-call-terminal-awaiting {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border: 1px solid
    color-mix(in srgb, var(--accent-orange-text, #e8973a) 40%, transparent);
  border-radius: var(--radius-sm);
  background: var(--accent-orange-bg, rgba(232, 151, 58, 0.1));
  color: var(--accent-orange-text, #e8973a);
  font-size: 11px;
  font-weight: 500;
  align-self: flex-start;
  animation: tool-call-terminal-awaiting-in 0.18s ease;
}

@keyframes tool-call-terminal-awaiting-in {
  from {
    opacity: 0;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.tool-call-terminal-awaiting-hint {
  max-width: 320px;
  padding: 0;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 400;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* terminal-send 的 keys 按键序列展示 */
.tool-call-terminal-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  min-width: 0;
}

.tool-call-terminal-key-chip {
  padding: 1px 7px;
  border: 1px solid var(--border-light);
  border-radius: 5px;
  background: var(--bg-tertiary);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  line-height: 1.5;
  user-select: text;
}

.tool-call-terminal-elapsed {
  color: var(--text-tertiary);
  font-size: 11px;
  font-family: var(--font-mono);
}

.tool-call-terminal-output-pre {
  max-height: 320px;
  margin: 0;
  padding: 10px 12px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  overflow: auto;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.55;
  white-space: pre;
  user-select: text;
}

.tool-call-terminal-tab-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-terminal-tab-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  font-size: 11px;
}

.tool-call-terminal-tab-active {
  border-color: color-mix(
    in srgb,
    var(--accent-blue-text) 40%,
    var(--border-light)
  );
  background: color-mix(in srgb, var(--accent-blue-text) 6%, var(--bg-primary));
}

.tool-call-terminal-tab-id {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10.5px;
}

.tool-call-terminal-tab-title {
  flex: 1;
  min-width: 0;
  color: var(--text-primary);
  font-size: 11.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-terminal-tab-cwd {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 200px;
}

.tool-call-terminal-tab-active-badge {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--accent-blue-bg, rgba(59, 130, 246, 0.12));
  color: var(--accent-blue-text);
  font-size: 10px;
}

.tool-call-terminal-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.tool-call-terminal-pending-running {
  background: color-mix(
    in srgb,
    var(--accent-blue-text) 6%,
    var(--bg-tertiary)
  );
  color: var(--text-secondary);
}

.tool-call-terminal-loading-dots {
  display: inline-flex;
  gap: 3px;
}

.tool-call-terminal-loading-dots i {
  display: block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--accent-blue-text);
  animation: tool-call-bash-cursor-blink 1.2s ease-in-out infinite;
}

.tool-call-terminal-loading-dots i:nth-child(2) {
  animation-delay: 0.2s;
}

.tool-call-terminal-loading-dots i:nth-child(3) {
  animation-delay: 0.4s;
}

.tool-call-terminal-countdown {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
}

.tool-call-terminal-countdown-urgent {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
  animation: tool-call-bash-countdown-pulse 0.8s ease-in-out infinite;
}

@media (max-width: 520px) {
  .tool-call-terminal-tab-cwd {
    display: none;
  }
}

/* Computer Use Tool Call (computer-use-*) */
.computer-use-summary {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.computer-use-summary span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.computer-use-body {
  gap: 10px;
}

.computer-use-screenshot-img {
  display: block;
  width: 100%;
  max-width: 640px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  cursor: zoom-in;
}

.computer-use-screenshot-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 6px;
}

.computer-use-screenshot-meta span {
  padding: 1px 7px;
  border: 1px solid var(--border-light);
  border-radius: 5px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  line-height: 1.5;
}

.computer-use-mapping-text {
  max-height: 120px;
  overflow: auto;
  white-space: pre-wrap;
}

.computer-use-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-tertiary);
  font-size: 11.5px;
}

/* HTML Renderer Tool Call (html-render) */
.html-render-size {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.html-render-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  overflow: hidden;
}

.html-render-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 4px 6px;
  border-bottom: 1px solid var(--border-light);
}

.html-render-tabs,
.html-render-actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-width: 0;
}

.html-render-tab,
.html-render-action {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border: 1px solid transparent;
  border-radius: 5px;
  background: transparent;
  color: var(--text-tertiary);
  font-size: 11px;
  line-height: 1.6;
  white-space: nowrap;
  cursor: pointer;
  transition:
    color 0.12s ease,
    background-color 0.12s ease,
    border-color 0.12s ease;
}

.html-render-tab:hover,
.html-render-action:hover:not(:disabled) {
  color: var(--text-primary);
  background: var(--bg-hover);
}

.html-render-tab.is-active {
  color: var(--text-primary);
  background: var(--bg-primary);
  border-color: var(--border-light);
}

.html-render-action:disabled {
  opacity: 0.5;
  cursor: default;
}

.html-render-tab:focus-visible,
.html-render-action:focus-visible {
  outline: 1px solid var(--accent);
  outline-offset: 1px;
}

/* 预览区可纵向拖拽调整高度；页面背景按浏览器默认的白底呈现，与在浏览器中
   打开时一致，不随应用主题变化。 */
.html-render-frame-wrap {
  position: relative;
  min-height: 160px;
  max-height: 1600px;
  resize: vertical;
  overflow: hidden;
  background: #ffffff;
}

.html-render-frame {
  display: block;
  width: 100%;
  height: 100%;
  border: 0;
  background: #ffffff;
}

.html-render-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 100%;
  padding: 12px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11.5px;
  text-align: center;
  overflow-wrap: anywhere;
}

.html-render-placeholder--error {
  color: var(--accent-red-text);
}

.html-render-source.tool-call-code-highlight-wrap {
  margin: 0;
  border: 0;
  border-radius: 0;
}

.html-render-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-tertiary);
  font-size: 11.5px;
}

/* Decision Tool Call (decision-evaluate) */
.decision-tool-meta {
  color: var(--text-tertiary);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.decision-tool-body {
  gap: 8px;
}

.decision-tool-answers {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.decision-tool-answer {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px 8px;
  min-width: 0;
  font-size: 12px;
}

.decision-tool-answer-name {
  color: var(--text-secondary);
  font-size: 11.5px;
  overflow-wrap: anywhere;
}

/* 有问题正文时 name 退为小标签 */
.decision-tool-answer-name.is-tag {
  flex-shrink: 0;
  padding: 0 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
  line-height: 16px;
}

.decision-tool-answer-question {
  flex: 0 1 auto;
  min-width: 0;
  color: var(--text-primary);
  overflow-wrap: anywhere;
}

.decision-tool-answer-type {
  flex-shrink: 0;
  padding: 0 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
  line-height: 16px;
}

.decision-tool-answer-value {
  flex-shrink: 0;
  color: var(--text-primary);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.decision-tool-answer-value.is-muted {
  color: var(--text-tertiary);
  font-weight: 400;
}

.decision-tool-answer-extra {
  color: var(--text-tertiary);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

.decision-tool-images {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 6px;
  color: var(--text-tertiary);
  font-size: 11px;
}

.decision-tool-images-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.decision-tool-image {
  padding: 0 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
}

.decision-tool-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-tertiary);
  font-size: 11.5px;
}

/* Grep Tool Call */
.tool-call-grep-body {
  gap: 10px;
}

.tool-call-grep-match-count {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
}

.tool-call-grep-has-matches {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-grep-no-matches {
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
}

/* 释义行：模型用用户语言解释检索意图，用户无需自行解读正则 */
.tool-call-grep-description {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 7px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  font-size: 11.5px;
  line-height: 1.45;
  user-select: text;
}

.tool-call-grep-description svg {
  display: block;
  flex-shrink: 0;
  margin-top: 2px;
  color: var(--accent-blue-text);
}

.tool-call-grep-description-text {
  min-width: 0;
  color: var(--text-secondary);
  word-break: break-word;
}

.tool-call-grep-params {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-grep-param-item {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 11.5px;
  line-height: 1.4;
}

.tool-call-grep-param-item svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-grep-param-label {
  flex-shrink: 0;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-grep-param-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-tertiary);
  user-select: text;
}

/* code 变体（pattern / fileGlob）需要覆盖 .ai-message code 的通用样式 */
.tool-call-grep code.tool-call-grep-param-value {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
  white-space: normal;
  word-break: break-all;
}

.tool-call-grep-param-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
}

.tool-call-grep-param-tag {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.tool-call-grep-backend {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-grep-backend svg {
  display: block;
  flex-shrink: 0;
  color: var(--accent-green-text);
}

.tool-call-grep-truncated {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  font-size: 10.5px;
}

.tool-call-grep-results {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 420px;
  overflow: auto;
}

.tool-call-grep-file-group {
  /* flex item 默认 flex-shrink:1 且 overflow:hidden 会把自动最小高度归零，
     导致在 max-height 容器内被压缩裁剪，必须禁止收缩改为整体滚动 */
  flex-shrink: 0;
  overflow: hidden;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-grep-file-header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 5px 8px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-tertiary);
}

.tool-call-grep-file-header svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-grep-file-name {
  flex-shrink: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}

.tool-call-grep-file-path {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
  user-select: text;
}

.tool-call-grep-file-count {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-active);
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.tool-call-grep-match-list {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 4px;
}

.tool-call-grep-match-line {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  line-height: 1.5;
}

.tool-call-grep-match-line:hover {
  background: var(--bg-hover);
}

.tool-call-grep-line-num {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--text-tertiary);
  user-select: none;
}

/* 覆盖 .ai-message code 通用样式，使匹配内容纯净显示 */
.tool-call-grep .tool-call-grep-line-content {
  flex: 1;
  min-width: 0;
  margin: 0;
  padding: 0;
  background: transparent;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-all;
  user-select: text;
}

.tool-call-grep-no-results,
.tool-call-grep-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.tool-call-grep-no-results svg,
.tool-call-grep-pending svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-grep-pending-running {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* WebSearch Tool Call */
.tool-call-websearch-body {
  gap: 10px;
}

.tool-call-websearch-count {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
}

.tool-call-websearch-count svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-websearch-count-active {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-websearch-count-image {
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

/* 搜索引擎来源标签：与计数标签同形，文字加深以区分 */
.tool-call-websearch-count-engine {
  color: var(--text-secondary);
  font-weight: 500;
}

.tool-call-websearch-meta-group {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

/* 搜索结果站点图标（仅展示加载成功的站点图标）。
   注意：全局 `:is(.ai-message, ...) img` 规则（Markdown 内联图片）会覆盖
   display / margin / border-radius / cursor，因此这里统一用 `.tool-call-websearch`
   作为前缀提升特异性，避免被其覆盖。 */
.tool-call-websearch .tool-call-websearch-favicons {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  /* 与首个图标的负边距抵消，避免堆叠左缘超出布局区 */
  padding-left: 6px;
}

.tool-call-websearch .tool-call-websearch-favicons-pending {
  display: none;
}

/* 头部堆叠：相邻图标重叠，描边区分层次 */
.tool-call-websearch .tool-call-websearch-favicon {
  box-sizing: border-box;
  display: block;
  width: 16px;
  height: 16px;
  max-height: none;
  flex-shrink: 0;
  margin: 0 0 0 -6px;
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--bg-primary);
  background: var(--bg-primary);
  object-fit: contain;
  cursor: default;
}

/* 列表条目前的站点图标（替代默认地球图标） */
.tool-call-websearch .tool-call-websearch-result-favicon {
  box-sizing: border-box;
  display: block;
  width: 12px;
  height: 12px;
  max-height: none;
  flex-shrink: 0;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: 2px;
  object-fit: contain;
  cursor: default;
}

/* 加载中 / 无效图标：隐藏（同时覆盖上面两种图标） */
.tool-call-websearch .tool-call-websearch-favicon-pending {
  display: none;
}

.tool-call-websearch-count-blocked {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
}

.tool-call-websearch-blocked {
  border: 1px solid var(--accent-red-bg, var(--border-color));
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  overflow: hidden;
}

.tool-call-websearch-blocked > summary {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  cursor: pointer;
  font-size: 11px;
  font-weight: 650;
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
  list-style: none;
}

.tool-call-websearch-blocked > summary::-webkit-details-marker {
  display: none;
}

.tool-call-websearch-blocked-rules {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  padding: 8px 8px 0;
}

.tool-call-websearch-blocked-rules code {
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  font-size: 10.5px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-family: var(--font-mono, ui-monospace, "SF Mono", Consolas, monospace);
}

.tool-call-websearch-blocked-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 0;
  padding: 8px;
  list-style: none;
}

.tool-call-websearch-blocked-list li {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}

.tool-call-websearch-blocked-index {
  flex-shrink: 0;
  font-size: 10px;
  color: var(--accent-red-text);
  font-weight: 700;
}

.tool-call-websearch-blocked-title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  color: var(--text-secondary);
}

.tool-call-websearch-blocked-url {
  flex-shrink: 0;
  max-width: 40%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10px;
  color: var(--text-muted);
}

.tool-call-websearch-params {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-websearch-param-item {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 11.5px;
  line-height: 1.4;
}

.tool-call-websearch-param-item svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-websearch-param-label {
  flex-shrink: 0;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-websearch-param-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-tertiary);
  user-select: text;
}

/* code 变体（query）需要覆盖 .ai-message code 的通用样式 */
.tool-call-websearch code.tool-call-websearch-param-value {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
  white-space: normal;
  word-break: break-all;
}

.tool-call-websearch-param-tags {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
}

.tool-call-websearch-param-tag {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
}

/* 搜索结果列表（SERP 风格） */
.tool-call-websearch-results {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 420px;
  overflow: auto;
  padding-right: 2px;
}

.tool-call-websearch-result {
  /* 与 grep 分组一致：禁止收缩，容器整体滚动 */
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  transition:
    border-color 0.15s ease,
    background-color 0.15s ease;
}

.tool-call-websearch-result:hover {
  border-color: var(--accent-blue);
  background: var(--bg-secondary);
}

.tool-call-websearch-result-head {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
}

.tool-call-websearch-result-index {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10px;
  user-select: none;
}

.tool-call-websearch-result-title {
  /* button 重置 */
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  font: inherit;
  text-align: left;
  /* 布局 */
  display: inline-flex;
  align-items: center;
  flex: 1;
  min-width: 0;
  color: var(--accent-blue-text);
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.4;
  cursor: pointer;
}

.tool-call-websearch-result-title-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-websearch-result-title:hover .tool-call-websearch-result-title-text {
  text-decoration: underline;
}

.tool-call-websearch-result-title:focus-visible,
.tool-call-websearch-page-link:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
  border-radius: var(--radius-sm);
}

/* 悬停出现的外链小按钮（在系统浏览器打开） */
.tool-call-websearch-external {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.15s ease,
    background-color 0.15s ease,
    color 0.15s ease;
}

.tool-call-websearch-result:hover .tool-call-websearch-external,
.tool-call-websearch-page:hover .tool-call-websearch-external,
.tool-call-websearch-external:focus-visible {
  opacity: 1;
}

.tool-call-websearch-external:hover {
  background: var(--bg-active);
  color: var(--accent-blue-text);
}

.tool-call-websearch-external:active {
  transform: scale(0.92);
}

.tool-call-websearch-external:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
}

.tool-call-websearch-result-url {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  /* 与标题文字对齐（序号 16px + 间距 7px） */
  margin-left: 23px;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10.5px;
}

.tool-call-websearch-result-url svg {
  display: block;
  flex-shrink: 0;
  color: var(--accent-green-text);
}

.tool-call-websearch-result-url span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  user-select: text;
}

.tool-call-websearch-result-snippet {
  margin: 0 0 0 23px;
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.55;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  user-select: text;
}

/* 抓取结果：页面信息卡 */
.tool-call-websearch-page {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-websearch-page-title {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.tool-call-websearch-page-title svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-websearch-page-title-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  user-select: text;
}

.tool-call-websearch-page-link-row {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.tool-call-websearch-page-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  font: inherit;
  text-align: left;
  color: var(--accent-blue-text);
  font-size: 11px;
  cursor: pointer;
}

.tool-call-websearch-page-link svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-websearch-page-link span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  user-select: text;
}

.tool-call-websearch-page-link:hover span {
  text-decoration: underline;
}

/* 抓取结果：图片内联预览 */
.tool-call-websearch-image {
  display: flex;
  justify-content: center;
  padding: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
}

.tool-call-websearch-image img {
  max-width: 100%;
  max-height: 320px;
  border-radius: var(--radius-sm);
  object-fit: contain;
}

/* 抓取结果：正文预览 + 完整内容折叠 */
.tool-call-websearch-preview-wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-websearch-section-label {
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.tool-call-websearch-preview {
  margin: 0;
  max-height: 170px;
  overflow: auto;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}

.tool-call-websearch-full {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-websearch-full > summary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  cursor: pointer;
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  user-select: none;
  transition: color 0.15s ease;
}

.tool-call-websearch-full > summary:hover {
  color: var(--text-secondary);
}

.tool-call-websearch-truncated {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
  font-size: 10.5px;
  letter-spacing: 0;
  text-transform: none;
}

/* 空结果 / 等待状态 */
.tool-call-websearch-empty,
.tool-call-websearch-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.tool-call-websearch-empty svg,
.tool-call-websearch-pending svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-websearch-pending-running {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* External tool-specific styles are supplied by renderer plugins. */

/* ImageGen Tool Call */
.tool-call-imagegen-body {
  gap: 10px;
}

.tool-call-imagegen-count {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

.tool-call-imagegen-count svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-imagegen-params {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-imagegen-param-item {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 11.5px;
  line-height: 1.4;
}

.tool-call-imagegen-param-item svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-imagegen-param-label {
  flex-shrink: 0;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-imagegen-param-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-tertiary);
  user-select: text;
}

.tool-call-imagegen code.tool-call-imagegen-param-value {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
  white-space: normal;
  word-break: break-all;
}

.tool-call-imagegen-param-tags {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
  margin-top: 2px;
}

.tool-call-imagegen-param-tag {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11px;
}

/* 成功结果：纯相框画廊（不渲染工具卡片头部） */
.tool-call-imagegen-result {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.tool-call-imagegen-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 14px;
  align-items: start;
}

/* 单张图片：放大展示，宽度跟随图片比例（方图/竖图窄、横图宽） */
.tool-call-imagegen-grid.tool-call-imagegen-grid-single {
  grid-template-columns: minmax(0, 1fr);
  justify-content: center;
}

/* 卡片容器：启用容器查询，超窄图用 100cqw 按真实比例计算限高高度 */
.tool-call-imagegen-figure {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin: 0;
  min-width: 0;
  container-type: inline-size;
}

/* 单张展示的卡片宽度：方图/竖图适中，横图更宽更大气 */
.tool-call-imagegen-grid-single .tool-call-imagegen-figure {
  justify-self: center;
  width: min(100%, 420px);
}

.tool-call-imagegen-grid-single .tool-call-imagegen-figure-wide {
  width: min(100%, 640px);
}

.tool-call-imagegen-grid-single .tool-call-imagegen-figure-tall {
  width: min(100%, 360px);
}

/* 超宽图：通栏展示，避免在列内被压缩过矮 */
.tool-call-imagegen-figure-wide {
  grid-column: 1 / -1;
}

/* 超窄图：保持真实比例计算高度，但限制上限防止过高 */
.tool-call-imagegen-figure-tall .tool-call-imagegen-thumb {
  aspect-ratio: auto;
  height: min(calc(100cqw / var(--img-ar, 1)), 440px);
}

/* 图片卡片：无相框，直接展示图片，比例跟随生成图片真实比例（--img-ar 由组件按批次统一设置） */
.tool-call-imagegen-thumb {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  aspect-ratio: var(--img-ar, 1);
  padding: 0;
  border: none;
  border-radius: var(--radius-lg);
  background: transparent;
  cursor: zoom-in;
  transition: opacity 0.15s ease;
}

.tool-call-imagegen-thumb:hover {
  opacity: 0.92;
}

/* 生成中卡片（不可点击放大，保持静态）：等待中无图，用浅色底作为占位 */
.tool-call-imagegen-thumb-static,
.tool-call-imagegen-thumb-static:hover {
  cursor: default;
  opacity: 1;
  background: var(--bg-tertiary);
}

/* 生成中占位（等待/执行） */
.tool-call-imagegen-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  min-height: 200px;
  padding: 20px;
  color: var(--text-tertiary);
  font-size: 12px;
  user-select: none;
}

/* 远程图加载失败占位（链接过期/403 等）：浅色底 + 图标 + 提示，与画廊同尺寸 */
.tool-call-imagegen-remote-fallback {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  height: 100%;
  min-height: 120px;
  padding: 16px;
  border-radius: var(--radius-lg);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11px;
  line-height: 1.5;
  text-align: center;
  user-select: none;
}

/* 图片：填满整个比例卡片，contain 保证完整显示不变形 */
.tool-call-imagegen-thumb img {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: var(--radius-lg);
  object-fit: contain;
}

/* 并行生成序号角标：覆盖在图片左上角，轻量区分第几张 */
.tool-call-imagegen-badge {
  position: absolute;
  top: 8px;
  left: 8px;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.55);
  color: #fff;
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  pointer-events: none;
  user-select: none;
  backdrop-filter: blur(2px);
}

/* 图注：序号徽章 | 标签 | 下载，三列布局让标签居中 */
.tool-call-imagegen-figure-caption {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 8px;
  width: 100%;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-imagegen-figure-index {
  justify-self: start;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 18px;
  padding: 0 6px;
  border-radius: 9px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
}

.tool-call-imagegen-figure-label {
  justify-self: center;
  font-size: 10.5px;
  color: var(--text-tertiary);
}

/* 合并画廊（并行 imagegen 调用）：图注标签弹性收缩防溢出
   （多格网格中标签可能比图片还宽，省略号兜底） */
.tool-call-imagegen-gallery-grid .tool-call-imagegen-figure-label {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 合并画廊容器：开启容器查询，消息区变窄时自动降列。
   React inline 的数量分档（gridTemplateColumns）只在容器 ≥640px 时生效；
   640/460/300 三档保证每格图片始终有可读大小（如 4 列在 600px 容器下
   每格 ~140px 过窄 → 降到 3 列）。与 .chat-area 的视口断点互补：
   视口断点管"内容区多宽"，容器查询管"网格在内容区内如何分列"。 */
.tool-call-imagegen-gallery {
  container-type: inline-size;
}

@container (max-width: 640px) {
  .tool-call-imagegen-gallery-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  }
}

@container (max-width: 460px) {
  .tool-call-imagegen-gallery-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}

@container (max-width: 300px) {
  .tool-call-imagegen-gallery-grid {
    grid-template-columns: minmax(0, 1fr) !important;
  }
}

.tool-call-imagegen-figure-caption .tool-call-imagegen-download {
  justify-self: end;
}

.tool-call-imagegen-download {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
  cursor: pointer;
}

.tool-call-imagegen-download:hover {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* 生图结果画廊工具栏：图片数量 + 全部保存 */
.tool-call-imagegen-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.tool-call-imagegen-toolbar-count {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-secondary);
  min-width: 0;
}

.tool-call-imagegen-toolbar-actions {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

/* 实际 seed 标签（点击复制） */
.tool-call-imagegen-seed {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10px;
  font-family: var(--font-mono, monospace);
  cursor: pointer;
}

.tool-call-imagegen-seed:hover {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* 结果图上的「以此为参考」按钮 */
.tool-call-imagegen-figure-edit {
  position: absolute;
  top: 6px;
  right: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: rgba(0, 0, 0, 0.45);
  color: #fff;
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.tool-call-imagegen-figure:hover .tool-call-imagegen-figure-edit,
.tool-call-imagegen-figure-edit:focus-visible {
  opacity: 1;
}

.tool-call-imagegen-figure-edit:hover {
  background: rgba(0, 0, 0, 0.65);
}

/* 以图为参考重生成（轻量工作台）面板 */
.tool-call-imagegen-edit-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 8px;
  padding: 10px;
  border: 1px solid var(--border-color, rgba(128, 128, 128, 0.3));
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.tool-call-imagegen-edit-title {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
}

.tool-call-imagegen-edit-row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
}

.tool-call-imagegen-edit-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  flex-shrink: 0;
  overflow: hidden;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
}

.tool-call-imagegen-edit-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tool-call-imagegen-edit-panel textarea {
  flex: 1;
  min-width: 0;
  padding: 6px 8px;
  border: 1px solid var(--border-color, rgba(128, 128, 128, 0.3));
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12px;
  line-height: 1.5;
  resize: vertical;
}

.tool-call-imagegen-edit-panel textarea:focus {
  outline: none;
  border-color: var(--accent-color);
}

.tool-call-imagegen-edit-actions {
  display: flex;
  justify-content: flex-end;
  gap: 6px;
}

.tool-call-imagegen-edit-go,
.tool-call-imagegen-edit-cancel {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 10px;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 11px;
  cursor: pointer;
}

.tool-call-imagegen-edit-go {
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.tool-call-imagegen-edit-go:hover {
  background: var(--accent-blue-text);
  color: var(--on-solid);
}

.tool-call-imagegen-edit-go:disabled {
  opacity: 0.6;
  cursor: default;
}

.tool-call-imagegen-edit-cancel {
  background: var(--bg-tertiary);
  color: var(--text-secondary);
}

.tool-call-imagegen-edit-cancel:hover {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
}

.tool-call-imagegen-download-all,
.tool-call-imagegen-retry {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11px;
  cursor: pointer;
}

.tool-call-imagegen-download-all:hover,
.tool-call-imagegen-retry:hover {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-imagegen-download-all:disabled,
.tool-call-imagegen-retry:disabled {
  opacity: 0.6;
  cursor: default;
}

.tool-call-imagegen-retry {
  margin-top: 8px;
}

/* 多提示词（prompts 数组）：逐行展示，序号徽章 + 等宽文本 */
.tool-call-imagegen-prompts {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.tool-call-imagegen-prompts-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.tool-call-imagegen-prompts-index {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border-radius: 9px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
}

.tool-call-imagegen-prompts-item code {
  word-break: break-word;
}

.tool-call-imagegen-remote {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tool-call-imagegen-remote-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-imagegen-remote-link {
  font-size: 11px;
  color: var(--accent-blue-text);
  text-decoration: none;
  word-break: break-all;
}

.tool-call-imagegen-remote-link:hover {
  text-decoration: underline;
}

.tool-call-imagegen-refs {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-imagegen-refs-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-imagegen-refs-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.tool-call-imagegen-ref-thumb {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  overflow: hidden;
  border-radius: var(--radius-sm);
  border: 1px solid var(--bg-tertiary);
  background: var(--bg-tertiary);
}

.tool-call-imagegen-ref-thumb img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.tool-call-imagegen-ref-placeholder {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-imagegen-describe-preview {
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

.tool-call-imagegen-describe-preview img {
  display: block;
  max-width: 240px;
  max-height: 160px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-light);
  background: var(--bg-tertiary);
  object-fit: contain;
  cursor: zoom-in;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.tool-call-imagegen-describe-preview img:hover {
  transform: scale(1.01);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);
}

.tool-call-imagegen-describe-result {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-imagegen-describe-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.tool-call-imagegen-describe-head-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.tool-call-imagegen-describe-head-label svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-imagegen-describe-copy {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 7px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.tool-call-imagegen-describe-copy:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.tool-call-imagegen-describe-copy svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-imagegen-describe-text {
  margin: 0;
  max-height: 360px;
  overflow: auto;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}

.tool-call-imagegen-describe-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.tool-call-imagegen-describe-pending svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-imagegen-describe-pending-running {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* 生图设置面板：模型能力标签 */
.imagegen-model-caps {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 4px;
}

.imagegen-model-cap {
  display: inline-flex;
  align-items: center;
  padding: 1px 7px;
  border-radius: 9px;
  font-size: 10.5px;
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

/* ===== 生图设置面板：渠道表格模式（左侧并发设置 + 渠道列表） ===== */
.imagegen-layout {
  display: grid;
  grid-template-columns: 232px minmax(0, 1fr);
  gap: 14px;
  align-items: start;
  margin-bottom: 4px;
}

/* 左侧渠道导航 */
.imagegen-nav {
  position: sticky;
  top: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
}

.imagegen-nav-head {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 2px 6px 8px;
}

.imagegen-nav-head strong {
  font-size: 12.5px;
  font-weight: 700;
}

.imagegen-nav-head small {
  color: var(--text-muted);
  font-size: 10.5px;
  line-height: 1.45;
}

.imagegen-nav-item {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr) auto auto auto;
  align-items: center;
  gap: 8px;
  width: 100%;
  min-width: 0;
  padding: 8px 9px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background 0.12s ease,
    border-color 0.12s ease;
}

.imagegen-nav-item:hover:not(:disabled) {
  background: var(--bg-hover);
}

.imagegen-nav-item:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: -1px;
}

.imagegen-nav-item.active {
  border-color: var(--border-light);
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.imagegen-nav-item:disabled {
  cursor: default;
  opacity: 0.7;
}

.imagegen-nav-icon {
  display: inline-flex;
  width: 28px;
  height: 28px;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.imagegen-nav-icon.gemini {
  color: var(--accent-purple-text, var(--accent-blue-text));
  background: color-mix(
    in srgb,
    var(--accent-purple-text, var(--accent-blue-text)) 14%,
    transparent
  );
}

.imagegen-nav-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 1px;
}

.imagegen-nav-copy strong,
.imagegen-nav-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.imagegen-nav-copy strong {
  font-size: 11.5px;
  font-weight: 650;
}

.imagegen-nav-copy small {
  color: var(--text-muted);
  font-family: var(--font-mono, monospace);
  font-size: 10px;
}

.imagegen-nav-dirty {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-amber-text);
  box-shadow: 0 0 0 3px
    color-mix(in srgb, var(--accent-amber-text) 16%, transparent);
}

.imagegen-nav-state {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  white-space: nowrap;
}

.imagegen-nav-state.on {
  color: var(--accent-green-text);
}

.imagegen-nav-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* 渠道内联重命名（铅笔按钮，hover 显示） */
.imagegen-nav-rename-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.12s ease,
    background 0.12s ease,
    color 0.12s ease;
}

.imagegen-nav-item:hover .imagegen-nav-rename-btn,
.imagegen-nav-rename-btn:focus-visible {
  opacity: 1;
}

.imagegen-nav-rename-btn:hover {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* 重命名态条目与输入框 */
.imagegen-nav-item.imagegen-nav-renaming {
  cursor: default;
  border-color: var(--border-light);
  background: var(--bg-tertiary);
}

.imagegen-nav-rename {
  width: 100%;
  min-width: 0;
  padding: 3px 6px;
  border: 1px solid var(--accent-blue-text);
  border-radius: var(--radius-sm);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 11.5px;
  font-weight: 650;
}

.imagegen-nav-rename::placeholder {
  color: var(--text-tertiary);
  font-weight: 600;
}

/* 当前模型支持的图片尺寸提示 */
.imagegen-size-model-note {
  color: var(--accent-blue-text);
  font-weight: 600;
}

.imagegen-nav-note {
  margin: 6px 4px 2px;
  padding-top: 8px;
  border-top: 1px dashed var(--border-light);
  color: var(--text-muted);
  font-size: 10.5px;
  line-height: 1.5;
}

.imagegen-nav-add {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 4px;
  padding: 7px 9px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  transition:
    color 0.12s ease,
    border-color 0.12s ease,
    background 0.12s ease;
}

.imagegen-nav-add:hover:not(:disabled) {
  border-color: var(--accent-color, var(--text-muted));
  background: var(--bg-hover);
  color: var(--text-primary);
}

.imagegen-nav-add:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: -1px;
}

.imagegen-nav-add:disabled {
  cursor: default;
  opacity: 0.6;
}

/* 右侧表单面板 */
.imagegen-panel-wrap {
  min-width: 0;
}

.imagegen-empty {
  display: flex;
  min-height: 260px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 24px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-lg);
  color: var(--text-tertiary);
  text-align: center;
}

.imagegen-empty svg {
  opacity: 0.6;
}

.imagegen-empty p {
  margin: 0;
  max-width: 300px;
  color: var(--text-muted);
  font-size: 11.5px;
  line-height: 1.5;
}

.imagegen-panel {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 16px;
}

.imagegen-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
}

.imagegen-panel-heading {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 4px;
}

.imagegen-panel-heading strong {
  overflow: hidden;
  font-size: 13px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.imagegen-panel-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: fit-content;
  padding: 2px 8px;
  border-radius: 999px;
  color: var(--text-muted);
  background: var(--bg-tertiary);
  font-size: 10.5px;
  font-weight: 650;
}

.imagegen-panel-badge.on {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.imagegen-panel-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.imagegen-panel-toggle {
  flex-shrink: 0;
}

/* 面板头部：可编辑渠道名 + 协议选择 + 开关 + 删除 */
.imagegen-panel-heading-editable {
  flex: 1;
  min-width: 0;
  gap: 4px;
}

.imagegen-channel-name {
  width: 100%;
  min-width: 0;
  padding: 2px 3px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  outline: none;
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  transition:
    border-color 0.12s ease,
    background 0.12s ease;
}

.imagegen-channel-name:hover:not(:disabled) {
  border-color: var(--border-light);
}

.imagegen-channel-name:focus {
  border-color: var(--accent-color);
  background: var(--bg-primary);
}

.imagegen-channel-name::placeholder {
  color: var(--text-tertiary);
  font-weight: 600;
}

.imagegen-panel-tools {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 8px;
}

.imagegen-provider-field select {
  min-width: 0;
  max-width: 170px;
  padding: 5px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-secondary);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
}

.imagegen-provider-field select:focus {
  border-color: var(--accent-color);
}

.imagegen-provider-field select:disabled {
  cursor: default;
  opacity: 0.68;
}

.imagegen-panel-delete {
  color: var(--text-tertiary);
}

.imagegen-panel-delete:hover:not(:disabled) {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.imagegen-groups {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 18px;
}

.imagegen-group {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 10px;
}

.imagegen-group-title {
  margin: 0;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--border-light);
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.imagegen-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 12px;
}

.imagegen-field-wide {
  grid-column: 1 / -1;
}

/* 生图设置面板：字段名标注（请求参数原名，非解释性小字） */
.imagegen-thinking-field {
  margin-left: 6px;
  padding: 1px 5px;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-muted);
  background: var(--bg-tertiary);
}

.imagegen-panel .api-settings-field-hint {
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1.45;
}

/* 开关选项列表（无卡片，行间分隔线） */
.imagegen-toggle-list {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  overflow: hidden;
}

.imagegen-toggle-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
}

.imagegen-toggle-row + .imagegen-toggle-row {
  border-top: 1px solid var(--border-light);
}

.imagegen-toggle-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.imagegen-toggle-copy span {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 600;
}

.imagegen-toggle-copy small {
  color: var(--text-muted);
  font-size: 10.5px;
  line-height: 1.45;
}

/* 流式 / 非流式 分段按钮（替代单一开关，明确两种模式） */
.imagegen-stream-segmented {
  display: flex;
  gap: 4px;
  padding: 3px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle, var(--border-color));
  flex-shrink: 0;
}

.imagegen-stream-segmented-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 5px 12px;
  border-radius: 5px;
  background: transparent;
  border: none;
  color: var(--text-tertiary);
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.12s,
    color 0.12s;
}

.imagegen-stream-segmented-btn:hover:not(:disabled) {
  color: var(--text-secondary);
  background: var(--bg-hover);
}

.imagegen-stream-segmented-btn.active {
  background: var(--bg-primary);
  color: var(--text-primary);
  font-weight: 600;
  /* 选中态抬升：用极淡的当前文字色描边替代固定黑阴影，
     浅色/深色与各预设主题下都成立 */
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--text-primary) 8%, transparent);
}

.imagegen-stream-segmented-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* OpenAI 尺寸预设：比例 × 档位联动 + 自定义输入 */
.imagegen-size-row {
  display: grid;
  grid-template-columns: 104px 70px minmax(0, 1fr);
  gap: 6px;
}

.imagegen-size-row select,
.imagegen-size-input {
  min-width: 0;
  padding: 5px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-secondary);
  font: inherit;
  font-size: 11px;
}

.imagegen-size-row select:focus,
.imagegen-size-input:focus {
  border-color: var(--accent-color);
}

.imagegen-size-row select:disabled {
  cursor: default;
  opacity: 0.6;
}

.imagegen-size-input {
  font-family: var(--font-mono, monospace);
}

/* 头部状态（已整合进页面头部，不再有独立保存栏） */
.imagegen-footer-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
}

.imagegen-footer-status.dirty {
  color: var(--accent-amber-text);
}

.imagegen-footer-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent-amber-text);
  box-shadow: 0 0 0 3px
    color-mix(in srgb, var(--accent-amber-text) 16%, transparent);
}

@media (max-width: 720px) {
  .imagegen-layout {
    grid-template-columns: 1fr;
  }

  .imagegen-nav {
    position: static;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .imagegen-nav-head {
    width: 100%;
  }

  .imagegen-nav-item {
    flex: 1 1 200px;
  }

  .imagegen-grid {
    grid-template-columns: 1fr;
  }

  .imagegen-size-row {
    grid-template-columns: 1fr 1fr;
  }

  .imagegen-size-input {
    grid-column: 1 / -1;
  }
}

/* 渠道内多模型管理区（支持单渠道多模型） */
.imagegen-models-manager {
  display: flex;
  flex-direction: column;
  gap: 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: 12px;
}

.imagegen-models-tabs-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.imagegen-models-tabs-list {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}

.imagegen-model-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  border: 1px solid var(--border-subtle, var(--border-color));
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition: all 0.15s ease;
  user-select: none;
}

.imagegen-model-tab:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--border-light);
}

.imagegen-model-tab.active {
  background: color-mix(in srgb, var(--accent-color) 14%, transparent);
  color: var(--text-primary);
  border-color: color-mix(in srgb, var(--accent-color) 45%, transparent);
  font-weight: 500;
}

.imagegen-model-tab.disabled {
  opacity: 0.55;
}

.imagegen-model-tab-star {
  color: var(--accent-amber-text);
  font-size: 12px;
  line-height: 1;
}

/* 模型品牌图标：渠道内多模型 Tab 与渠道表格「模型」列，复用全局 ModelBrandIcon */
.imagegen-model-tab-icon,
.imagegen-table-model-icon {
  flex-shrink: 0;
  vertical-align: middle;
}

.imagegen-model-tab-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  font-size: 12px;
  line-height: 1;
  opacity: 0.65;
  transition: all 0.12s ease;
  margin-left: 2px;
  border: none;
  background: transparent;
  color: inherit;
  padding: 0;
  cursor: pointer;
}

.imagegen-model-tab-close:hover {
  opacity: 1;
  background: color-mix(in srgb, currentColor 24%, transparent);
}

.imagegen-model-actions-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 6px 10px;
  background: var(--bg-primary);
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-light);
  font-size: 11.5px;
}

/* 控制条左侧：当前配置模型名 + 主模型标记/设置按钮，长模型名截断不挤压右侧开关 */
.imagegen-model-actions-title {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.imagegen-model-actions-title > strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.imagegen-model-primary-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--accent-amber-text);
  font-weight: 600;
}

.imagegen-model-more-tag {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  font-size: 10px;
  border-radius: 9999px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-subtle, var(--border-color));
  color: var(--text-muted);
}

.tool-call-imagegen-lightbox {
  position: fixed;
  inset: 0;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.78);
  backdrop-filter: blur(6px);
  cursor: zoom-out;
  padding: 40px;
  animation: tool-call-imagegen-lightbox-in 0.18s ease;
}

/* Markdown 图片灯箱：复用生图工具灯箱样式，提升层级避免被输入区浮层遮挡 */
.markdown-image-lightbox.tool-call-imagegen-lightbox {
  z-index: 10001;
}

@keyframes tool-call-imagegen-lightbox-in {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* 放大照片：直接展示无装裱框，始终水平 + 垂直居中 */
.tool-call-imagegen-lightbox img {
  display: block;
  width: auto;
  height: auto;
  max-width: min(92vw, 1500px);
  max-height: 86vh;
  object-fit: contain;
  border-radius: var(--radius-md);
  box-shadow: 0 12px 48px rgba(0, 0, 0, 0.6);
  user-select: none;
  -webkit-user-drag: none;
}

/* 灯箱加载中占位：图片数据尚未解析完成时显示（避免破图图标闪烁） */
.tool-call-imagegen-lightbox-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-width: 220px;
  min-height: 160px;
  color: var(--text-tertiary);
  font-size: 12px;
  user-select: none;
}

.tool-call-imagegen-lightbox-toolbar {
  position: absolute;
  top: 16px;
  right: 16px;
  display: flex;
  align-items: center;
  gap: 6px;
}

/* 灯箱工具栏内下载按钮与关闭按钮等高 */
.tool-call-imagegen-lightbox-toolbar .tool-call-imagegen-download {
  height: 26px;
  padding: 0 8px;
}

.tool-call-imagegen-lightbox-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 13px;
  cursor: pointer;
}

.tool-call-imagegen-lightbox-close:hover {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* Browser Tool Call */
.tool-call-browser-body {
  gap: 10px;
}

/* 结果卡片入场的轻动画 */
@keyframes tool-call-browser-rise {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 头部 meta 徽章 */
.tool-call-browser-meta {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  max-width: 260px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-browser-meta svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-meta-active {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-browser-meta-code {
  font-family: var(--font-mono);
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.tool-call-browser-meta-image {
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

/* 仿浏览器地址栏 */
.tool-call-browser-address {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 5px 10px;
  border: 1px solid var(--border-light);
  border-radius: 999px;
  background: var(--bg-tertiary);
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.4;
  animation: tool-call-browser-rise 0.18s ease both;
}

.tool-call-browser-address svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-browser-address-protocol {
  flex-shrink: 0;
  color: var(--text-muted);
  user-select: text;
}

.tool-call-browser-address-rest {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  user-select: text;
}

/* 参数标签行 */
.tool-call-browser-tags {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}

.tool-call-browser-tag {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
  line-height: 1.5;
}

.tool-call-browser-tag svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-tag-blue {
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.tool-call-browser-tag-green {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.tool-call-browser-tag-amber {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

/* 实例 ID 徽章（可点击切换 tab） */
.tool-call-browser-instance {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin: 0;
  padding: 2px 7px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  line-height: 1.5;
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    color 0.15s ease,
    background-color 0.15s ease,
    transform 0.1s ease;
}

.tool-call-browser-instance svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-instance:hover {
  border-color: var(--accent-blue);
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-browser-instance:active {
  transform: scale(0.95);
}

.tool-call-browser-instance:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
}

/* 单行状态条（create / close / focus / devtools-open） */
.tool-call-browser-status {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  padding: 7px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  font-size: 12px;
  color: var(--text-secondary);
  animation: tool-call-browser-rise 0.18s ease both;
}

.tool-call-browser-status > svg {
  display: block;
  flex-shrink: 0;
  color: var(--accent-green-text);
}

.tool-call-browser-status-label {
  font-weight: 600;
  color: var(--text-primary);
}

/* 页面信息卡 */
.tool-call-browser-page {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  transition:
    border-color 0.15s ease,
    background-color 0.15s ease;
  animation: tool-call-browser-rise 0.18s ease both;
}

.tool-call-browser-page:hover {
  border-color: var(--accent-blue);
}

.tool-call-browser-page-title {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.tool-call-browser-page-title > svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-browser-page-title-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  user-select: text;
}

.tool-call-browser-page-row {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.tool-call-browser-page-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  font: inherit;
  text-align: left;
  color: var(--accent-blue-text);
  font-size: 11px;
  cursor: pointer;
}

.tool-call-browser-page-link svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-page-link span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  user-select: text;
}

.tool-call-browser-page-link:hover span {
  text-decoration: underline;
}

.tool-call-browser-page-link:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
  border-radius: var(--radius-sm);
}

/* 悬停出现的外链小按钮 */
.tool-call-browser-external {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  margin: 0;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.15s ease,
    background-color 0.15s ease,
    color 0.15s ease;
}

.tool-call-browser-page:hover .tool-call-browser-external,
.tool-call-browser-external:focus-visible {
  opacity: 1;
}

.tool-call-browser-external:hover {
  background: var(--bg-active);
  color: var(--accent-blue-text);
}

.tool-call-browser-external:active {
  transform: scale(0.92);
}

.tool-call-browser-external:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
}

/* click：目标行 */
.tool-call-browser-target {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  font-size: 11.5px;
  color: var(--text-tertiary);
}

.tool-call-browser-target > svg {
  display: block;
  flex-shrink: 0;
  color: var(--accent-blue-text);
}

.tool-call-browser-target-selector {
  max-width: 100%;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  word-break: break-all;
  user-select: text;
}

.tool-call-browser-target-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  font-style: italic;
  user-select: text;
}

/* evaluate：表达式行 */
.tool-call-browser-expression {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  min-width: 0;
  padding: 6px 9px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  font-size: 11.5px;
  line-height: 1.5;
}

.tool-call-browser-expression > svg {
  display: block;
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--accent-blue-text);
}

.tool-call-browser-expression code {
  min-width: 0;
  font-family: var(--font-mono);
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-all;
  user-select: text;
}

/* evaluate：结果多行内容可滚动 */
.tool-call-browser-eval-result {
  margin: 0;
}

/* type：输入值行 */
.tool-call-browser-type-value {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 11.5px;
}

.tool-call-browser-type-value-label {
  color: var(--text-tertiary);
}

.tool-call-browser-type-value-text {
  max-width: 100%;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--accent-blue-text);
  font-family: var(--font-mono);
  font-size: 11px;
  word-break: break-all;
  user-select: text;
}

/* select_option：选中结果列表 */
.tool-call-browser-selected {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  font-size: 11.5px;
}

.tool-call-browser-selected > span {
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
  font-size: 11px;
  word-break: break-all;
  user-select: text;
}

/* devtools 网络调试：请求列表 */
.tool-call-browser-network {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.tool-call-browser-network-row {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 3px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
}

.tool-call-browser-network-row:hover {
  background: var(--bg-tertiary);
}

.tool-call-browser-network-status {
  flex-shrink: 0;
  min-width: 28px;
  font-family: var(--font-mono);
  color: var(--accent-amber-text, var(--text-secondary));
}

.tool-call-browser-network-status-ok {
  color: var(--accent-green-text);
}

.tool-call-browser-network-url {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  user-select: text;
}

.tool-call-browser-network-duration {
  flex-shrink: 0;
  font-size: 10px;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}

/* devtools 网络详情 */
.tool-call-browser-network-detail-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
}

.tool-call-browser-headers {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tool-call-browser-headers-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  font-size: 11px;
}

.tool-call-browser-headers-key {
  flex-shrink: 0;
  color: var(--accent-blue-text);
  font-family: var(--font-mono);
  font-size: 10.5px;
  user-select: text;
}

.tool-call-browser-headers-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  user-select: text;
}

/* devtools cookies */
.tool-call-browser-cookies {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.tool-call-browser-cookie {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 3px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
}

.tool-call-browser-cookie:hover {
  background: var(--bg-tertiary);
}

.tool-call-browser-cookie-name {
  flex-shrink: 0;
  color: var(--text-secondary);
  font-weight: 600;
  user-select: text;
}

.tool-call-browser-cookie-domain {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10px;
  user-select: text;
}

.tool-call-browser-cookie-value {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--accent-blue-text);
  font-family: var(--font-mono);
  font-size: 10.5px;
  user-select: text;
}

/* devtools dialog 列表 */
.tool-call-browser-dialogs {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.tool-call-browser-dialog {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 3px 6px;
  border-radius: var(--radius-sm);
  font-size: 11px;
}

.tool-call-browser-dialog-message {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  user-select: text;
}

/* devtools ax 无障碍树 */
.tool-call-browser-ax {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 280px;
  overflow: auto;
}

.tool-call-browser-ax-node {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  font-size: 11px;
}

.tool-call-browser-ax-node:hover {
  background: var(--bg-tertiary);
}

.tool-call-browser-ax-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-secondary);
  user-select: text;
}

.tool-call-browser-ax-uid {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10px;
  user-select: text;
}

.tool-call-browser-meta-offline {
  color: var(--accent-amber-text, var(--text-tertiary));
}

/* config：配置工具卡片 */
.tool-call-config-path {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 11.5px;
  color: var(--text-tertiary);
}

.tool-call-config-path code {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--accent-blue-text);
  font-family: var(--font-mono);
  font-size: 11px;
  word-break: break-all;
  user-select: text;
}

.tool-call-config-path-sep {
  color: var(--text-tertiary);
  opacity: 0.6;
}

.tool-call-config-keys {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.tool-call-config-key {
  padding: 1px 7px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 10.5px;
  word-break: break-all;
  user-select: text;
}

.tool-call-config-meta {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.tool-call-config-meta svg {
  flex-shrink: 0;
}

.tool-call-config-meta-ok {
  color: var(--accent-green-text);
}

.tool-call-config-meta-missing {
  color: var(--text-tertiary);
}

/* config：写入/读取的长值美化展示 */
.tool-call-section-head {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tool-call-config-value-badge {
  padding: 0 7px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10px;
  line-height: 1.7;
  user-select: text;
}

.tool-call-config-value-inline {
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  word-break: break-all;
  user-select: text;
}

.tool-call-config-value-text {
  margin: 0;
  max-height: 280px;
  overflow: auto;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}

/* JSON 树查看器（config 等结构化结果） */
.json-tree {
  max-height: 320px;
  overflow: auto;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.65;
  color: var(--text-secondary);
  user-select: text;
  word-break: break-all;
}

.json-tree-node {
  min-width: 0;
}

.json-tree-row {
  display: flex;
  align-items: flex-start;
  gap: 3px;
  min-width: 0;
  border-radius: 3px;
}

.json-tree-row-toggle {
  cursor: pointer;
}

.json-tree-row-toggle:hover {
  background: var(--bg-active);
}

.json-tree-children {
  padding-left: 16px;
  margin-left: 4px;
  border-left: 1px solid var(--border-subtle);
}

.json-tree-arrow {
  flex-shrink: 0;
  width: 0;
  height: 0;
  margin-top: 6px;
  border-left: 4px solid var(--text-tertiary);
  border-top: 3px solid transparent;
  border-bottom: 3px solid transparent;
  transition: transform 0.12s ease;
}

.json-tree-arrow-open {
  transform: rotate(90deg);
}

.json-tree-key {
  color: var(--accent-blue-text);
}

.json-tree-punct {
  color: var(--text-tertiary);
}

.json-tree-string {
  color: var(--accent-green-text);
  white-space: pre-wrap;
  word-break: break-word;
}

.json-tree-string-collapsed,
.json-tree-string-expanded {
  cursor: pointer;
  border-radius: 3px;
}

.json-tree-string-collapsed:hover,
.json-tree-string-expanded:hover {
  background: var(--bg-active);
}

.json-tree-string-badge {
  display: inline-block;
  margin-left: 6px;
  padding: 0 6px;
  border-radius: 999px;
  background: var(--bg-primary);
  color: var(--text-tertiary);
  font-size: 10px;
  line-height: 1.6;
}

.json-tree-number {
  color: var(--accent-amber-text);
}

.json-tree-bool {
  color: var(--accent-blue-text);
}

.json-tree-null {
  color: var(--text-muted);
  font-style: italic;
}

/* app-control：应用控制工具卡片 */
.tool-call-app-detail {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  font-size: 11.5px;
  color: var(--text-secondary);
}

.tool-call-app-detail > svg {
  display: block;
  flex-shrink: 0;
  color: var(--accent-blue-text);
}

.tool-call-app-detail code {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--accent-blue-text);
  font-family: var(--font-mono);
  font-size: 11px;
  word-break: break-all;
  user-select: text;
}

.tool-call-app-detail-col {
  flex-direction: column;
  align-items: flex-start;
  gap: 5px;
}

.tool-call-app-detail-label {
  color: var(--text-tertiary);
  font-size: 11px;
}

.tool-call-app-meta {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.tool-call-app-meta svg {
  flex-shrink: 0;
}

.tool-call-app-meta-ok {
  color: var(--accent-green-text);
}

/* Shared application-log styles remain in the host. */

.tool-call-app-logs-body {
  gap: 8px;
}

.tool-call-logs-breakdown-label {
  color: var(--text-tertiary);
  font-size: 10px;
  font-weight: 600;
}

.tool-call-logs-summary {
  display: grid;
  grid-template-columns: minmax(120px, 1.4fr) repeat(4, minmax(54px, 1fr));
  gap: 6px;
}

.tool-call-logs-total,
.tool-call-logs-stat {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
}

.tool-call-logs-total strong,
.tool-call-logs-stat strong {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.tool-call-logs-total span {
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-log-level {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  border-radius: 4px;
  padding: 2px 5px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 9px;
  font-weight: 700;
}

.tool-call-log-level-error {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.tool-call-log-level-warn {
  background: var(--accent-yellow-bg);
  color: var(--accent-yellow-text);
}

.tool-call-log-level-info {
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.tool-call-log-level-debug {
  color: var(--text-tertiary);
}

.tool-call-logs-meta,
.tool-call-log-subline,
.tool-call-log-trace {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 10px;
  color: var(--text-tertiary);
  font-size: 10px;
}

.tool-call-logs-meta > span,
.tool-call-log-trace > span {
  border: 1px solid var(--border-light);
  border-radius: 999px;
  padding: 2px 7px;
}

.tool-call-logs-list {
  display: flex;
  max-height: 560px;
  flex-direction: column;
  gap: 6px;
  overflow: auto;
  padding-right: 2px;
}

.tool-call-log-entry {
  min-width: 0;
  border: 1px solid var(--border-light);
  border-left: 3px solid var(--border-medium, var(--border-light));
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  padding: 7px 9px;
}

.tool-call-log-entry-error {
  border-left-color: var(--accent-red-text);
}

.tool-call-log-entry-warn {
  border-left-color: var(--accent-yellow-text);
}

.tool-call-log-head {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 7px;
}

.tool-call-log-module,
.tool-call-log-head code,
.tool-call-log-subline code,
.tool-call-log-trace code {
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 10px;
}

.tool-call-log-message {
  min-width: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-log-subline {
  margin-top: 4px;
}

.tool-call-log-subline time {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-variant-numeric: tabular-nums;
}

.tool-call-log-error {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  margin-top: 6px;
  color: var(--accent-red-text);
  font-size: 10.5px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.tool-call-log-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.tool-call-log-field {
  min-width: 0;
  max-width: 100%;
  color: var(--text-secondary);
  font-size: 10px;
}

.tool-call-log-field summary {
  cursor: pointer;
  border: 1px solid var(--border-light);
  border-radius: 4px;
  padding: 2px 6px;
  user-select: none;
}

.tool-call-log-pre {
  max-height: 240px;
  max-width: 100%;
  overflow: auto;
  margin: 4px 0 0;
  border: 1px solid var(--border-light);
  border-radius: 4px;
  padding: 7px;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 10px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.tool-call-logs-empty {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-tertiary);
  padding: 10px 2px;
  font-size: 11px;
}

.tool-call-logs-hint {
  margin: 0;
  color: var(--text-tertiary);
  font-size: 10px;
}

@media (max-width: 520px) {
  .tool-call-logs-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

.tool-call-dbx-meta {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.tool-call-dbx-meta svg {
  flex-shrink: 0;
}

.tool-call-dbx-meta-ok {
  color: var(--accent-green-text);
}

/* Generic Tool Call */
.tool-call-generic-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tool-call-generic-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-generic-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 2px;
}

.tool-call-generic-view-tabs {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  padding: 1px;
}

.tool-call-generic-tab {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  font-size: 10.5px;
  color: var(--text-tertiary);
  background: transparent;
  border: none;
  border-radius: var(--radius-xs, 3px);
  cursor: pointer;
  transition: all 0.15s ease;
}

.tool-call-generic-tab:hover {
  color: var(--text-primary);
  background: var(--bg-hover, rgba(255, 255, 255, 0.05));
}

.tool-call-generic-tab.active {
  color: var(--accent-blue-text, #38bdf8);
  background: var(--bg-primary);
  font-weight: 500;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
}

.tool-call-generic-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.tool-call-generic-pre {
  margin: 0;
  max-height: 360px;
  overflow: auto;
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.5;
}

/* Generic Table */
.tool-call-generic-table-wrapper {
  overflow: auto;
  max-height: 380px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-generic-table {
  border-collapse: collapse;
  width: 100%;
  font-size: 11px;
}

.tool-call-generic-table th,
.tool-call-generic-table td {
  padding: 4px 8px;
  border-bottom: 1px solid var(--border-light);
  text-align: left;
  white-space: nowrap;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tool-call-generic-table th {
  position: sticky;
  top: 0;
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-weight: 600;
  z-index: 1;
  border-bottom: 1px solid var(--border-light);
}

.tool-call-generic-th-index,
.tool-call-generic-td-index {
  width: 32px;
  text-align: center !important;
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10px;
}

.tool-call-generic-table td {
  color: var(--text-primary);
  font-family: var(--font-mono);
}

.tool-call-generic-table tbody tr:hover td {
  background: var(--bg-hover, rgba(255, 255, 255, 0.04));
}

.tool-call-generic-table-more {
  padding: 5px 8px;
  font-size: 10.5px;
  color: var(--text-tertiary);
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-light);
  text-align: center;
}

.tool-call-generic-markdown {
  padding: 8px 10px;
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  font-size: 11.5px;
  line-height: 1.55;
  color: var(--text-primary);
  max-height: 400px;
  overflow-y: auto;
}

.tool-call-generic-markdown p {
  margin: 0 0 6px 0;
}

.tool-call-generic-markdown p:last-child {
  margin-bottom: 0;
}

.tool-call-generic-tree-wrapper {
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  padding: 6px 8px;
  max-height: 400px;
  overflow: auto;
}

/* click：命中元素卡 */
.tool-call-browser-element {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-left: 3px solid var(--accent-green-text);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  animation: tool-call-browser-rise 0.18s ease both;
}

.tool-call-browser-element-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  min-width: 0;
}

.tool-call-browser-element-tagname {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
  font-family: var(--font-mono);
  font-size: 10.5px;
  font-weight: 600;
}

.tool-call-browser-element-tagname svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-element-id {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--accent-blue-text);
  user-select: text;
}

.tool-call-browser-element-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11.5px;
  color: var(--text-secondary);
  user-select: text;
}

.tool-call-browser-element-href {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  color: var(--text-tertiary);
}

.tool-call-browser-element-href > svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-element-href-link {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  font: inherit;
  text-align: left;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--accent-blue-text);
  cursor: pointer;
}

.tool-call-browser-element-href-link:hover {
  text-decoration: underline;
}

.tool-call-browser-element-href-link:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
  border-radius: var(--radius-sm);
}

/* screenshot：图片框（棋盘格底暗示透明区域） */
.tool-call-browser-shot {
  display: flex;
  justify-content: center;
  padding: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background-color: var(--bg-tertiary);
  background-image: repeating-conic-gradient(
    var(--bg-secondary) 0% 25%,
    transparent 0% 50%
  );
  background-size: 14px 14px;
  animation: tool-call-browser-rise 0.18s ease both;
}

.tool-call-browser-shot img {
  max-width: 100%;
  max-height: 360px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-light);
  object-fit: contain;
  background: var(--bg-primary);
  cursor: pointer;
  transition:
    transform 0.2s ease,
    box-shadow 0.2s ease;
}

.tool-call-browser-shot img:hover {
  transform: scale(1.01);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.18);
}

/* devtools snapshot：元信息网格 */
.tool-call-browser-meta-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(130px, 1fr));
  gap: 5px;
}

.tool-call-browser-meta-cell {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 5px 8px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  transition: border-color 0.15s ease;
}

.tool-call-browser-meta-cell:hover {
  border-color: var(--accent-blue);
}

.tool-call-browser-meta-label {
  font-size: 10px;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.tool-call-browser-meta-value {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  user-select: text;
}

/* devtools snapshot：页面文本 + 区块标签 */
.tool-call-browser-text-wrap {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-browser-section-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
}

.tool-call-browser-section-label svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-text {
  margin: 0;
  max-height: 170px;
  overflow: auto;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
  user-select: text;
}

/* devtools snapshot：链接折叠列表 */
.tool-call-browser-links {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-browser-links > summary {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  width: fit-content;
  cursor: pointer;
  font-size: 11px;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  user-select: none;
  transition: color 0.15s ease;
}

.tool-call-browser-links > summary:hover {
  color: var(--text-secondary);
}

.tool-call-browser-links > summary svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-links-count {
  padding: 0 5px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0;
}

.tool-call-browser-links-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 220px;
  overflow: auto;
  padding-right: 2px;
}

.tool-call-browser-link-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  transition: background-color 0.12s ease;
}

.tool-call-browser-link-row:hover {
  background: var(--bg-tertiary);
}

.tool-call-browser-link-text {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin: 0;
  padding: 0;
  border: none;
  background: transparent;
  font: inherit;
  text-align: left;
  font-size: 11.5px;
  color: var(--accent-blue-text);
  cursor: pointer;
}

.tool-call-browser-link-text:hover {
  text-decoration: underline;
}

.tool-call-browser-link-text:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
  border-radius: var(--radius-sm);
}

.tool-call-browser-link-host {
  flex-shrink: 0;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-muted);
}

/* devtools console：终端风格消息列表 */
.tool-call-browser-console {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 260px;
  overflow: auto;
  padding: 6px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  font-family: var(--font-mono);
  animation: tool-call-browser-rise 0.18s ease both;
}

.tool-call-browser-console-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  padding: 3px 6px;
  border-left: 2px solid transparent;
  border-radius: 2px;
  font-size: 11px;
  line-height: 1.5;
}

.tool-call-browser-console-level {
  flex-shrink: 0;
  min-width: 34px;
  font-size: 9.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  color: var(--text-muted);
}

.tool-call-browser-console-message {
  flex: 1;
  min-width: 0;
  white-space: pre-wrap;
  word-break: break-word;
  color: var(--text-secondary);
  user-select: text;
}

.tool-call-browser-console-source {
  flex-shrink: 0;
  max-width: 150px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10px;
  color: var(--text-muted);
}

.tool-call-browser-console-info {
  border-left-color: var(--accent-blue-text);
}

.tool-call-browser-console-info .tool-call-browser-console-level {
  color: var(--accent-blue-text);
}

.tool-call-browser-console-warning {
  border-left-color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

.tool-call-browser-console-warning .tool-call-browser-console-level {
  color: var(--accent-amber-text);
}

.tool-call-browser-console-error {
  border-left-color: var(--accent-red-text);
  background: var(--accent-red-bg);
}

.tool-call-browser-console-error .tool-call-browser-console-level,
.tool-call-browser-console-error .tool-call-browser-console-message {
  color: var(--accent-red-text);
}

/* list：标签页列表 */
.tool-call-browser-tabs {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 260px;
  overflow: auto;
  padding-right: 2px;
}

.tool-call-browser-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  margin: 0;
  padding: 6px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    background-color 0.15s ease,
    transform 0.1s ease;
}

.tool-call-browser-tab:hover {
  border-color: var(--accent-blue);
  background: var(--bg-secondary);
}

.tool-call-browser-tab:active {
  transform: scale(0.99);
}

.tool-call-browser-tab:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
}

.tool-call-browser-tab-active {
  border-color: var(--accent-blue);
}

.tool-call-browser-tab-dot {
  flex-shrink: 0;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-muted);
  opacity: 0.4;
}

.tool-call-browser-tab-dot-active {
  background: var(--accent-green-text);
  opacity: 1;
  box-shadow: 0 0 0 3px var(--accent-green-bg);
}

.tool-call-browser-tab-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
}

.tool-call-browser-tab-flag {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
  font-size: 10px;
}

.tool-call-browser-tab-id {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-muted);
}

/* 空状态 / 等待状态 */
.tool-call-browser-empty,
.tool-call-browser-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.tool-call-browser-empty svg,
.tool-call-browser-pending svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-browser-pending-running {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

/* Sub-Agent Tool Call */
.tool-call-sub-agent-count {
  font-size: 11px;
  color: var(--text-muted);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

/* 卡片头部：摘要之后的代理名（次要信息，宽度受限避免挤占摘要） */
.tool-call-sub-agent-head-agent {
  flex-shrink: 0;
  max-width: 42%;
  margin-left: 3px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-sub-agent-body {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Hook records bound to the sub-agent tool call (beforeSubAgentStart above
   the card content, onSubAgentComplete below) — rendered as inset panels so
   they read as pre/post steps of the sub-agent instead of a detached
   message-footer block. */
.tool-call-sub-agent-hooks {
  min-width: 0;
  padding: 6px 8px;
  background: color-mix(in srgb, var(--bg-tertiary) 45%, transparent);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
}

.tool-call-sub-agent-hooks .hook-exec-group-header {
  padding-top: 0;
}

.tool-call-sub-agent-hooks--pre {
  margin-bottom: -2px;
}

.tool-call-sub-agent-hooks--post {
  margin-top: -2px;
}

.tool-call-sub-agent-identity {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.tool-call-sub-agent-identity-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-active);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}

.tool-call-sub-agent-agent-id {
  font-size: 10.5px;
  color: var(--text-muted);
  font-family: var(--font-mono, monospace);
}

/* ===== 共享只读提示词块 ===== */
.prompt-preview {
  --prompt-preview-line-height: 1.6;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}

.prompt-preview-head {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  min-height: 22px;
}

.prompt-preview-label {
  flex-shrink: 0;
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 600;
}

.prompt-preview-stats {
  min-width: 0;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 10.5px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.prompt-preview-actions {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  margin-left: auto;
  flex-shrink: 0;
}

.prompt-preview-toggle {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  height: 22px;
  padding: 0 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.1s,
    color 0.1s;
}

.prompt-preview-toggle:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.prompt-preview-body {
  max-height: calc(
    var(--prompt-preview-lines, 3) * var(--prompt-preview-line-height) * 1em
  );
  overflow: hidden;
  padding: 6px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 12px;
  line-height: var(--prompt-preview-line-height);
  word-break: break-word;
  box-sizing: content-box;
}

.prompt-preview.is-overflowing .prompt-preview-body {
  -webkit-mask-image: linear-gradient(to bottom, #000 60%, transparent);
  mask-image: linear-gradient(to bottom, #000 60%, transparent);
}

.prompt-preview.is-expanded .prompt-preview-body {
  max-height: 360px;
  overflow-y: auto;
  overscroll-behavior-y: contain;
}

.prompt-preview-line {
  white-space: pre-wrap;
}

.prompt-preview-line.is-command {
  font-family: var(--font-mono, monospace);
  font-size: 11.5px;
}

.prompt-preview-gap {
  height: 4px;
}

.prompt-inline-code {
  padding: 0 3px;
  border-radius: 3px;
  background: var(--bg-hover);
  font-family: var(--font-mono, monospace);
  font-size: 0.92em;
  word-break: break-all;
}

.prompt-preview-line.is-command .prompt-inline-code {
  padding: 0;
  background: transparent;
}

/* ===== Sidebar Search ===== */
.sidebar-search-bar {
  padding: 6px 8px 2px;
  flex-shrink: 0;
}

.sidebar-search-btn,
.sidebar-new-chat-btn {
  width: 100%;
  color: var(--text-secondary);
  font-size: 13px;
  cursor: pointer;
}

.sidebar-search-btn:hover,
.sidebar-new-chat-btn:hover {
  color: var(--text-primary);
}

.sidebar-search-btn svg,
.sidebar-new-chat-btn svg {
  color: var(--text-tertiary);
}

.sidebar-search-btn:hover svg,
.sidebar-new-chat-btn:hover svg {
  color: var(--text-secondary);
}

/* 侧边栏「新建会话」行：悬停时右侧显示「在新窗口中打开」图标，快捷键提示让位。 */
.sidebar-new-chat-row {
  position: relative;
  width: 100%;
}

.sidebar-new-chat-window-btn {
  position: absolute;
  top: 50%;
  right: 6px;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  opacity: 0;
  pointer-events: none;
  transition:
    opacity 0.15s ease,
    background-color 0.15s ease,
    color 0.15s ease;
}

.sidebar-new-chat-window-btn:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.sidebar-new-chat-row:hover .sidebar-new-chat-window-btn,
.sidebar-new-chat-window-btn:focus-visible {
  opacity: 1;
  pointer-events: auto;
}

.sidebar-new-chat-row:hover .sidebar-new-chat-shortcut,
.sidebar-new-chat-row:focus-within .sidebar-new-chat-shortcut {
  opacity: 0;
}

.sidebar-more-btn {
  width: 100%;
  color: var(--text-secondary);
  font-size: 13px;
  cursor: pointer;
}

.sidebar-more-btn:hover {
  color: var(--text-primary);
}

.sidebar-more-chevron {
  margin-left: auto;
  transition: transform 0.15s ease;
}

.sidebar-more-btn.expanded .sidebar-more-chevron {
  transform: rotate(180deg);
}

.sidebar-more-items {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  visibility: hidden;
  transition:
    grid-template-rows 0.22s ease,
    opacity 0.16s ease,
    visibility 0s linear 0.22s;
}

.sidebar-more-items.expanded {
  grid-template-rows: 1fr;
  opacity: 1;
  visibility: visible;
  transition:
    grid-template-rows 0.22s ease,
    opacity 0.16s ease 0.04s,
    visibility 0s;
}

.sidebar-more-items-inner {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-height: 0;
  overflow: hidden;
  margin-left: 12px;
  padding-left: 6px;
  border-left: 1px solid var(--border-light);
}

.sidebar-more-items .nav-item {
  font-size: 12.5px;
}

/* ===== Search Modal ===== */
.search-modal {
  height: min(560px, calc(100vh - 48px));
}

.search-modal .app-modal-body {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: 12px;
  padding: 0;
}

.search-modal-input-wrapper {
  position: relative;
  display: flex;
  align-items: center;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-light);
  flex-shrink: 0;
}

.search-modal-input-icon {
  position: absolute;
  left: 28px;
  color: var(--text-muted);
  pointer-events: none;
}

.search-modal-input {
  width: 100%;
  padding: 8px 12px 8px 34px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 13.5px;
  outline: none;
  transition: border-color 0.12s;
}

.search-modal-input:focus {
  outline: none;
  border-color: var(--accent-color);
}

.search-modal-input::placeholder {
  color: var(--text-muted);
}

.search-modal-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 6px 8px;
}

.search-modal-loading,
.search-modal-hint,
.search-modal-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 100%;
  color: var(--text-muted);
  font-size: 13px;
}

.search-modal-results {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.search-result-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.1s;
}

.search-result-item:hover,
.search-result-item.active {
  background: var(--bg-hover);
}

.search-result-item.active {
  background: var(--bg-active);
}

.search-result-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--text-muted);
}

.search-result-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.search-result-title {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.search-result-preview {
  font-size: 11.5px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.search-result-time {
  flex-shrink: 0;
  font-size: 11px;
  color: var(--text-tertiary);
  white-space: nowrap;
}

.search-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 4px 0;
}

.search-group + .search-group {
  border-top: 1px solid var(--border-light);
}

.search-group-title {
  padding: 6px 10px 2px;
  font-size: 10.5px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-tertiary);
}

.search-group-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 10px;
  color: var(--text-muted);
  font-size: 12px;
}

.tool-call-sub-agent-activity {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-sub-agent-activity-label {
  font-size: 10.5px;
  color: var(--text-muted);
  font-weight: 500;
}

.tool-call-sub-agent-activity-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-height: 200px;
  overflow-y: auto;
}

.tool-call-sub-agent-activity-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  padding: 3px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  min-width: 0;
}

.tool-call-sub-agent-activity-item svg {
  flex-shrink: 0;
}

.tool-call-sub-agent-activity-name {
  color: var(--text-secondary);
  font-weight: 500;
  flex-shrink: 0;
  font-family: var(--font-mono, monospace);
  font-size: 10.5px;
}

.tool-call-sub-agent-activity-summary {
  color: var(--text-muted);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-sub-agent-activity-status {
  font-size: 10px;
  flex-shrink: 0;
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  font-weight: 500;
}

.tool-call-sub-agent-activity-status-running {
  color: var(--color-primary, #4c9aff);
  background: color-mix(
    in srgb,
    var(--color-primary, #4c9aff) 12%,
    transparent
  );
}

.tool-call-sub-agent-activity-status-completed {
  color: var(--color-success, #22c55e);
  background: color-mix(
    in srgb,
    var(--color-success, #22c55e) 12%,
    transparent
  );
}

.tool-call-sub-agent-activity-status-error {
  color: var(--color-error, #ef4444);
  background: color-mix(in srgb, var(--color-error, #ef4444) 12%, transparent);
}

.tool-call-sub-agent-activity-status-pending {
  color: var(--text-muted);
  background: var(--bg-active);
}

.tool-call-sub-agent-summary {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-sub-agent-summary-label {
  font-size: 10.5px;
  color: var(--text-muted);
  font-weight: 500;
}

.tool-call-sub-agent-summary-value {
  font-size: 12px;
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  border-radius: var(--radius-sm);
  padding: 6px 8px;
  white-space: pre-wrap;
  word-break: break-word;
  margin: 0;
  max-height: 200px;
  overflow-y: auto;
}

.tool-call-sub-agent-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 0;
  font-size: 12px;
  color: var(--text-muted);
}

.tool-call-sub-agent-pending-running {
  color: var(--text-secondary);
}

.tool-call-sub-agent-jump {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-active);
  border: 1px solid var(--border-color);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  align-self: flex-start;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;
}

.tool-call-sub-agent-jump:hover {
  background: var(--bg-hover, var(--bg-tertiary));
  border-color: var(--color-primary, #4c9aff);
  color: var(--color-primary, #4c9aff);
}

.tool-call-sub-agent-jump:focus-visible {
  outline: 2px solid var(--color-primary, #4c9aff);
  outline-offset: 1px;
}

.tool-call-sub-agent-jump.active {
  background: var(--bg-active);
  border-color: var(--color-primary, #4c9aff);
  color: var(--color-primary, #4c9aff);
}

/* Sub-agent queued notice (sub-agents-continue 排队结果) */
.tool-call-sub-agent-queued {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--color-success, #22c55e);
  padding: 4px 0;
}

.tool-call-sub-agent-queued.is-pending {
  color: var(--text-muted);
}

.tool-call-sub-agent-queued.is-withdrawn {
  color: var(--accent-red-text);
}

.tool-call-sub-agent-queued-time {
  color: var(--text-muted);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}

/* 子代理间通信卡片 */
.tool-call-sub-agent-comms-route {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  font-size: 12px;
}

.tool-call-sub-agent-comms-route > svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

.tool-call-sub-agent-comms-party {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  max-width: 45%;
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--text-secondary);
  font-size: 11.5px;
  white-space: nowrap;
}

.tool-call-sub-agent-comms-party span {
  overflow: hidden;
  text-overflow: ellipsis;
}

button.tool-call-sub-agent-comms-party {
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

button.tool-call-sub-agent-comms-party:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.tool-call-sub-agent-comms-status {
  font-size: 11px;
  color: var(--text-muted);
}

.tool-call-sub-agent-comms-status.is-delivered {
