.memo-list-item-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.memo-list-item-preview {
  font-size: 13px;
  color: var(--text-primary);
  line-height: 1.4;
  overflow: hidden;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  word-break: break-word;
}

.memo-list-item.done .memo-list-item-preview {
  color: var(--text-tertiary);
  text-decoration: line-through;
}

.memo-list-item-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--text-muted);
}

.memo-list-item-status {
  color: var(--accent-green);
  display: inline-flex;
  align-items: center;
}

.memo-list-item-actions {
  display: flex;
  flex-direction: column;
  gap: 2px;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity 0.12s,
    visibility 0.12s;
}

.memo-list-item:hover .memo-list-item-actions,
.memo-list-item.selected .memo-list-item-actions {
  opacity: 1;
  visibility: visible;
}

.memo-icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  border-radius: var(--radius-sm);
  background: transparent;
  border: none;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.memo-icon-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.memo-icon-btn.danger:hover {
  color: var(--accent-red);
  background: var(--accent-red-bg);
}

/* 已完成状态切换按钮：实心绿色带勾 */
.memo-icon-btn.done-toggle {
  color: var(--accent-green);
}

.memo-icon-btn.done-toggle:hover {
  background: var(--accent-green-bg);
  color: var(--accent-green);
}

.memo-loading,
.memo-empty,
.memo-editor-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 32px 16px;
  color: var(--text-tertiary);
  font-size: 13px;
  text-align: center;
}

.memo-loading {
  flex-direction: row;
}

/* 未选中备忘时撑满右栏，让空状态提示居中显示 */
.memo-editor-empty {
  flex: 1;
}

.memo-loading-more {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px;
  color: var(--text-muted);
  font-size: 12px;
}

.memo-all-loaded {
  text-align: center;
  padding: 8px;
  color: var(--text-muted);
  font-size: 11px;
}

.memo-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.memo-editor-wrapper {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.memo-editor-area {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}

.memo-editor-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
  flex-shrink: 0;
}

.memo-editor-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--text-tertiary);
}

.memo-editor-status-badge {
  padding: 2px 8px;
  border-radius: var(--radius-lg);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

/* 待处理：琥珀色语义，与应用内 warning/未完成状态保持一致 */
.memo-editor-status-badge.pending {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

/* 已完成：绿色语义，与应用内 success/done 状态保持一致 */
.memo-editor-status-badge.done {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.memo-editor-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}

.memo-saving {
  display: inline-flex;
  align-items: center;
  color: var(--text-muted);
}

.memo-editor {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 14px 18px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--text-primary);
  outline: none;
  word-break: break-word;
}

.memo-editor:empty::before {
  content: attr(data-placeholder);
  color: var(--text-muted);
  pointer-events: none;
}

.memo-editor img {
  max-width: 100%;
  border-radius: var(--radius-md);
  margin: 4px 0;
}

.memo-editor p {
  margin: 4px 0;
}

.memo-editor ul,
.memo-editor ol {
  margin: 4px 0;
  padding-left: 22px;
}

.memo-editor a {
  color: var(--accent-blue-text);
}

.memo-editor code {
  background: var(--bg-active);
  padding: 1px 4px;
  border-radius: var(--radius-sm);
  font-size: 0.9em;
}

.memo-editor pre {
  background: var(--bg-active);
  padding: 8px 10px;
  border-radius: var(--radius-md);
  overflow-x: auto;
  margin: 6px 0;
}

/* ===== Scheduled Tasks ===== */
.sidebar-scheduled-tasks-btn {
  width: 100%;
  margin-top: 4px;
  color: var(--text-secondary);
  font-size: 13px;
  position: relative;
  cursor: pointer;
}

.sidebar-scheduled-tasks-btn:hover {
  color: var(--text-primary);
}

.sidebar-scheduled-tasks-btn svg {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.sidebar-scheduled-tasks-btn:hover svg {
  color: var(--text-secondary);
}

.sidebar-scheduled-tasks-btn:focus-visible {
  outline: 2px solid var(--text-muted);
  outline-offset: 2px;
}

.sidebar-plugins-btn {
  width: 100%;
  margin-top: 4px;
  color: var(--text-secondary);
  font-size: 13px;
  position: relative;
  cursor: pointer;
}

.sidebar-plugins-btn:hover {
  color: var(--text-primary);
}

.sidebar-plugins-btn svg {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.sidebar-plugins-btn:hover svg {
  color: var(--text-secondary);
}

/* 独立页面入口的选中态：对应页面展开时按钮跟随主题高亮 */
.sidebar-memo-btn.active,
.sidebar-memory-btn.active,
.sidebar-scheduled-tasks-btn.active,
.sidebar-plugins-btn.active {
  background: var(--bg-active);
  color: var(--text-primary);
}

.sidebar-memo-btn.active svg,
.sidebar-memory-btn.active svg,
.sidebar-scheduled-tasks-btn.active svg,
.sidebar-plugins-btn.active svg {
  color: var(--text-primary);
}

.sidebar-update-icon {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  color: var(--accent-blue);
}

.sidebar-update-icon svg {
  color: var(--accent-blue);
}

.sidebar-plugins-btn .sidebar-update-icon {
  margin-left: auto;
}

.sidebar-update-icon ~ .sidebar-memory-badge {
  margin-left: 0;
}

/* 「更多」行容器：按钮为主点击区，数值徽章绝对定位叠在右侧（避开箭头），
   常驻显示；徽章各自可点击直达对应面板；插件更新箭头同样常亮 */
.sidebar-more-row {
  position: relative;
  width: 100%;
}

.sidebar-more-row:hover .sidebar-more-btn {
  background: var(--bg-hover);
}

.sidebar-more-summary {
  position: absolute;
  top: 50%;
  right: 30px;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: calc(100% - 56px);
  overflow: hidden;
}

/* 常亮的更新箭头占据右侧时，数值徽章整体左移让位，避免叠字 */
.sidebar-more-summary.is-shifted {
  right: 48px;
}

.sidebar-more-badge {
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border: none;
  border-radius: 999px;
  background: var(--bg-active);
  color: var(--text-tertiary);
  font-size: 10px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  line-height: 16px;
  text-align: center;
  flex-shrink: 0;
  cursor: pointer;
  transition: filter 0.12s ease;
}

.sidebar-more-badge:hover {
  filter: brightness(0.94);
}

.sidebar-more-badge:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
}

.sidebar-more-badge.is-pending {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.sidebar-more-badge.is-tasks {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

.sidebar-more-badge.is-plugins {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

/* 插件更新箭头：常亮入口，点击进入插件页 */
.sidebar-more-update {
  position: absolute;
  top: 50%;
  right: 30px;
  transform: translateY(-50%);
  display: inline-flex;
}

.sidebar-more-update-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--accent-blue);
  cursor: pointer;
  flex-shrink: 0;
}

.sidebar-more-update-btn:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 1px;
  border-radius: var(--radius-sm);
}

.scheduled-tasks-panel-layout {
  display: grid;
  /* 列宽：左栏（可拖拽）/ 中轴拖拽条 / 内容区 */
  grid-template-columns:
    var(--scheduled-tasks-split-width, 320px) auto
    minmax(0, 1fr);
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  gap: 0;
}

/* 列表栏做成嵌套圆角卡片（同备忘录页），内容区用与主岛一致的表面色 */
.scheduled-tasks-sidebar {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--surface-island-muted);
  overflow: hidden;
}

.scheduled-tasks-sidebar-header {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border-bottom: 1px solid var(--border-light);
  flex-shrink: 0;
}

.scheduled-tasks-filter-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 3px;
  min-width: 0;
  padding: 3px;
  border: 1px solid var(--border-subtle, var(--border-color));
  border-radius: var(--radius-md);
  background: var(--bg-primary);
}

.scheduled-tasks-filter-tab {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-width: 0;
  padding: 5px 6px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.scheduled-tasks-filter-tab > span:first-child {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scheduled-tasks-filter-tab:hover:not(:disabled) {
  color: var(--text-secondary);
  background: var(--bg-hover);
}

.scheduled-tasks-filter-tab.active {
  color: var(--text-primary);
  background: var(--bg-active);
  font-weight: 600;
}

.scheduled-tasks-filter-tab:disabled {
  opacity: 0.45;
  cursor: default;
}

.scheduled-tasks-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 17px;
  height: 17px;
  padding: 0 4px;
  border-radius: var(--radius-lg);
  background: var(--bg-hover);
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  flex-shrink: 0;
}

.scheduled-tasks-filter-tab.active .scheduled-tasks-count {
  background: var(--bg-primary);
  color: var(--text-secondary);
}

.scheduled-tasks-new-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  width: 100%;
  padding: 7px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: var(--text-primary);
  color: var(--on-solid);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: filter 0.12s;
}

.scheduled-tasks-new-btn:hover {
  filter: brightness(1.08);
}

.scheduled-tasks-list-scroll {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 4px;
  min-height: 0;
  overflow-y: auto;
  padding: 8px;
}

.scheduled-tasks-empty,
.scheduled-task-details-empty {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 120px;
  padding: 28px 18px;
  color: var(--text-tertiary);
  font-size: 13px;
  line-height: 1.5;
  text-align: center;
}

.scheduled-task-list-row {
  min-width: 0;
}

.scheduled-task-item {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 100%;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background 0.12s,
    border-color 0.12s,
    box-shadow 0.12s;
}

.scheduled-task-item:hover {
  background: var(--bg-hover);
}

.scheduled-task-item.selected {
  border-color: var(--border-color);
  background: var(--bg-active);
  box-shadow: var(--shadow-sm, none);
}

.scheduled-task-item.is-running {
  border-color: var(--accent-blue);
  background: var(--accent-blue-bg);
}

.scheduled-task-item-header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.scheduled-task-item-name {
  min-width: 0;
  flex: 1;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scheduled-task-item-status-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: var(--radius-lg);
  font-size: 10px;
  font-weight: 600;
  line-height: 1.35;
  white-space: nowrap;
  flex-shrink: 0;
}

.scheduled-task-item-status-badge.pending {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

.scheduled-task-item-status-badge.running {
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.scheduled-task-item-status-badge.completed {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.scheduled-task-item-status-badge.error {
  background: var(--accent-red-bg);
  color: var(--accent-red);
}

.scheduled-task-item-status-badge.paused {
  background: var(--bg-hover);
  color: var(--text-tertiary);
}

.scheduled-task-item-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  color: var(--text-muted);
  font-size: 11px;
}

.scheduled-task-item-scope,
.scheduled-task-item-schedule,
.scheduled-task-item-next,
.scheduled-task-item-last,
.scheduled-task-item-runs,
.scheduled-task-item-skipped,
.scheduled-task-item-script {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  min-width: 0;
}

.scheduled-task-item-script {
  font-size: 11px;
  color: var(--text-muted);
  font-family: var(--font-mono, monospace);
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

.scheduled-task-item-skipped {
  color: var(--text-secondary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.scheduled-task-item-error {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: var(--accent-red);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.scheduled-task-item-scope {
  flex-shrink: 0;
}

.scheduled-task-item-schedule {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scheduled-task-item-scope svg,
.scheduled-task-item-schedule svg,
.scheduled-task-item-next svg {
  flex-shrink: 0;
}

.scheduled-task-item-next {
  color: var(--text-muted);
  font-size: 11px;
}

.scheduled-task-item-next > span {
  flex-shrink: 0;
}

.scheduled-task-item-prompt {
  overflow: hidden;
  display: -webkit-box;
  color: var(--text-tertiary);
  font-size: 12px;
  line-height: 1.4;
  overflow-wrap: anywhere;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.scheduled-tasks-sidebar-footer {
  flex-shrink: 0;
  border-top: 1px solid var(--border-light);
  background: var(--bg-secondary);
}

.scheduled-tasks-warning {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 8px 8px 0;
  padding: 8px 9px;
  border-radius: var(--radius-md);
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
  font-size: 11px;
  line-height: 1.4;
}

.scheduled-tasks-warning svg {
  margin-top: 1px;
  flex-shrink: 0;
}

.scheduled-tasks-scope-actions {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px 9px;
}

.scheduled-tasks-clear-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  min-width: 0;
  padding: 6px 7px;
  border: 0;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 11px;
  text-align: left;
  cursor: pointer;
  transition: color 0.12s;
}

.scheduled-tasks-clear-btn:hover {
  color: var(--accent-red);
}

.scheduled-tasks-clear-btn svg {
  flex-shrink: 0;
}

.scheduled-tasks-content {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: var(--surface-island-strong);
}

.scheduled-task-details {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

.scheduled-task-details-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 18px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-primary);
  flex-shrink: 0;
}

.scheduled-task-details-heading {
  min-width: 0;
}

.scheduled-task-details-eyebrow {
  display: block;
  margin-bottom: 3px;
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.35px;
  text-transform: uppercase;
}

.scheduled-task-details-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.scheduled-task-details-title-row h2 {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 17px;
  font-weight: 650;
  line-height: 1.35;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scheduled-task-details-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
  flex-wrap: wrap;
  flex-shrink: 0;
}

.scheduled-task-action-btn,
.scheduled-task-copy-btn,
.scheduled-tasks-back-btn,
.scheduled-tasks-cancel-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 6px 9px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  color: var(--text-secondary);
  font: inherit;
  font-size: 11px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background 0.12s,
    border-color 0.12s,
    color 0.12s;
}

.scheduled-task-action-btn:hover:not(:disabled),
.scheduled-task-copy-btn:hover,
.scheduled-tasks-back-btn:hover,
.scheduled-tasks-cancel-btn:hover {
  border-color: var(--text-muted);
  background: var(--bg-hover);
  color: var(--text-primary);
}

.scheduled-task-action-btn.primary {
  border-color: transparent;
  background: var(--text-primary);
  color: var(--on-solid);
}

.scheduled-task-action-btn.primary:hover:not(:disabled) {
  filter: brightness(1.08);
}

.scheduled-task-action-btn.danger {
