  background: var(--bg-tertiary);
}

.tool-call-codebase-params {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-codebase-param-item {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  font-size: 11.5px;
  line-height: 1.4;
}

.tool-call-codebase-param-item svg {
