  background: var(--bg-tertiary);
  font-size: 11px;
}

.tool-call-codebase-pipeline svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-codebase-pipeline-label {
  font-weight: 500;
  color: var(--text-secondary);
}

.tool-call-codebase-pipeline-agent .tool-call-codebase-pipeline-label {
  color: var(--accent-purple-text, var(--accent-blue-text));
}

.tool-call-codebase-pipeline-rerank .tool-call-codebase-pipeline-label {
  color: var(--accent-green-text);
}

.tool-call-codebase-pipeline-detail {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-active);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

/* 配置的决策 / 重排模型没有生效（回退 LLM / 回退向量排序），悬停看原因 */
.tool-call-codebase-pipeline-fallback {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
  font-size: 10.5px;
  cursor: help;
}

.tool-call-codebase-pipeline-refined {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}

.tool-call-codebase-pipeline-refined svg {
  color: var(--text-tertiary);
}

.tool-call-codebase-pipeline-refined span {
  flex-shrink: 0;
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.tool-call-codebase-pipeline-refined code {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-active);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 10.5px;
}

/* Progress steps (shown while running) */
.tool-call-codebase-progress {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
}

.tool-call-codebase-progress-step {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
  color: var(--text-tertiary);
}

.tool-call-codebase-progress-step svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-codebase-progress-active {
  color: var(--accent-blue-text);
}
.tool-call-codebase-progress-active svg {
  color: var(--accent-blue-text);
}

.tool-call-codebase-progress-counts {
  flex-shrink: 0;
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  background: var(--bg-active);
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
}

.tool-call-codebase-progress-refined {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}

.tool-call-codebase-progress-refined svg {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-codebase-progress-refined code {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  background: var(--bg-active);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 10px;
}

/* Results */
