  background: var(--bg-tertiary);
  cursor: pointer;
  user-select: none;
}

.tool-call-codebase-file-header:hover {
  background: var(--bg-hover);
}

.tool-call-codebase-file-group-collapsed .tool-call-codebase-file-header {
