}

.tool-call-codebase-file-chevron-open {
  transform: rotate(90deg);
}

.tool-call-codebase-file-header svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-codebase-file-name {
  flex-shrink: 1;
  min-width: 0;
