/* LSP Progress & Running State */
.tool-call-lsp-progress-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
}

.tool-call-lsp-progress-header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.tool-call-lsp-progress-spinner {
  color: var(--accent-blue-text);
  flex-shrink: 0;
}

.tool-call-lsp-progress-text {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  flex: 1;
}

.tool-call-lsp-progress-phase {
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tool-call-lsp-progress-detail {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  padding: 1px 5px;
  border-radius: var(--radius-sm);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 240px;
}

.tool-call-lsp-progress-meta {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  flex-shrink: 0;
}

.tool-call-lsp-progress-elapsed,
.tool-call-lsp-progress-timeout {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
}

.tool-call-lsp-progress-elapsed {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-lsp-progress-timeout {
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
}

.tool-call-lsp-progress-track {
  width: 100%;
  height: 3px;
  border-radius: 2px;
  background: var(--border-light);
  overflow: hidden;
  position: relative;
}

.tool-call-lsp-progress-bar {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 40%;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    var(--accent-blue-bg),
    var(--accent-blue-text)
  );
  animation: lsp-progress-slide 1.5s ease-in-out infinite alternate;
}

@keyframes lsp-progress-slide {
  0% {
    left: 0;
    width: 25%;
  }
  50% {
    width: 55%;
  }
  100% {
    left: 75%;
    width: 25%;
  }
}

.tool-call-lsp-incomplete-note,
.tool-call-lsp-preview-note {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

.tool-call-lsp-incomplete-note svg,
.tool-call-lsp-preview-note svg {
  display: block;
  flex-shrink: 0;
}

/* Rename view */
.tool-call-lsp-rename-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 420px;
  overflow: auto;
}

.tool-call-lsp-rename-file {
  flex-shrink: 0;
  overflow: hidden;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-lsp-rename-file-header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 5px 8px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-tertiary);
}

.tool-call-lsp-rename-file-header svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-lsp-rename-file-name {
  flex-shrink: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}

.tool-call-lsp-rename-file-path {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
  user-select: text;
}

.tool-call-lsp-rename-applied {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10.5px;
}

.tool-call-lsp-rename-applied.applied {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.tool-call-lsp-rename-applied.skipped {
  color: var(--text-tertiary);
  background: var(--bg-active);
}

.tool-call-lsp-edit-list {
  display: flex;
  flex-direction: column;
  padding: 4px 0;
}

.tool-call-lsp-edit-row {
  display: flex;
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  padding: 3px 8px;
  font-size: 11px;
}

.tool-call-lsp-edit-row:hover {
  background: var(--bg-tertiary);
}

.tool-call-lsp-edit-loc {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.tool-call-lsp-edit-loc svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-lsp-edit-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-secondary);
  user-select: text;
}

/* Completion view */
.tool-call-lsp-completion-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 320px;
  overflow: auto;
}

.tool-call-lsp-completion-item {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
  padding: 4px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  font-size: 11px;
}

.tool-call-lsp-completion-label {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
}

.tool-call-lsp-completion-label svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-lsp-completion-label code {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 260px;
}

.tool-call-lsp-completion-detail {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10.5px;
  color: var(--text-secondary);
  max-width: 220px;
}

.tool-call-lsp-completion-doc {
  flex-basis: 100%;
  min-width: 0;
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--text-tertiary);
  white-space: pre-wrap;
  word-break: break-all;
  user-select: text;
}

/* Code action view */
.tool-call-lsp-action-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 320px;
  overflow: auto;
}

.tool-call-lsp-action-item {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
  padding: 5px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  font-size: 11px;
}

.tool-call-lsp-action-title {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-primary);
}

.tool-call-lsp-action-title svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-lsp-preferred-badge,
.tool-call-lsp-edit-badge,
.tool-call-lsp-command-badge,
.tool-call-lsp-applied-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10px;
}

.tool-call-lsp-preferred-badge {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.tool-call-lsp-edit-badge {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-lsp-command-badge {
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

.tool-call-lsp-applied-badge {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.tool-call-lsp-result-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 2px;
}

.tool-call-lsp-section-label {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  padding: 1px 0;
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.tool-call-lsp-section-label svg {
  display: block;
  flex-shrink: 0;
}

.tool-call-lsp-deferred-command {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
  user-select: text;
}

/* Signature help view */
.tool-call-lsp-signature-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 320px;
  overflow: auto;
}

.tool-call-lsp-signature-item {
  flex-shrink: 0;
  padding: 7px 9px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-lsp-signature-item.active {
  border-color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-lsp-signature-label {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}

.tool-call-lsp-signature-label svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-lsp-signature-label code {
  font-family: var(--font-mono);
  font-size: 11.5px;
  font-weight: 500;
  color: var(--text-primary);
  word-break: break-all;
  user-select: text;
}

.tool-call-lsp-active-badge {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  color: var(--accent-blue-text);
  background: var(--bg-primary);
}

.tool-call-lsp-signature-doc {
  margin-top: 4px;
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--text-tertiary);
  white-space: pre-wrap;
  word-break: break-all;
  user-select: text;
}

.tool-call-lsp-param-list {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-wrap: wrap;
  margin-top: 6px;
}

.tool-call-lsp-param-chip {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
  user-select: text;
}

.tool-call-lsp-param-chip.active {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
  font-weight: 500;
}

/* ---- definition-jump（lsp-goto / lsp-type-definition / lsp-implementation） ---- */

.tool-call-lsp-def-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 420px;
  overflow: auto;
}

.tool-call-lsp-def-item {
  flex-shrink: 0;
  overflow: hidden;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-lsp-def-header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 5px 8px;
}

.tool-call-lsp-def-header svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-lsp-def-name {
  flex-shrink: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}

.tool-call-lsp-def-path {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
  user-select: text;
}

/* ---- workspace-symbols（lsp-workspace-symbols） ---- */

.tool-call-lsp-workspace-symbols {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tool-call-lsp-ws-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 3px 2px;
  font-size: 11.5px;
}

.tool-call-lsp-ws-toolbar-left {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}

.tool-call-lsp-ws-toolbar-icon {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.tool-call-lsp-ws-toolbar-count {
  font-weight: 600;
  color: var(--text-primary);
}

.tool-call-lsp-ws-query-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 1px 6px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  font-size: 10.5px;
}

.tool-call-lsp-ws-query-pill-label {
  color: var(--text-tertiary);
}

.tool-call-lsp-ws-query-pill-val {
  color: var(--accent-blue-text);
  font-family: var(--font-mono);
  font-weight: 500;
}

.tool-call-lsp-ws-copy-all-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-light);
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  font-size: 11px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.tool-call-lsp-ws-copy-all-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
  border-color: var(--border-subtle);
}

.tool-call-lsp-ws-copy-all-btn .copy-ok {
  color: var(--accent-green);
}

.tool-call-lsp-symbol-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-height: 480px;
  overflow-y: auto;
  padding-right: 2px;
}

.tool-call-lsp-symbol-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
  padding: 6px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  transition:
    background 0.12s ease,
    border-color 0.12s ease;
}

.tool-call-lsp-symbol-item:hover {
  background: var(--bg-hover);
  border-color: var(--border-subtle);
}

.tool-call-lsp-symbol-left {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  flex: 1 1 auto;
}

.tool-call-lsp-symbol-kind-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
}

.tool-call-lsp-symbol-kind-icon.kind-function {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
}

.tool-call-lsp-symbol-kind-icon.kind-type {
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}

.tool-call-lsp-symbol-kind-icon.kind-interface {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
}

.tool-call-lsp-symbol-kind-icon.kind-constant {
  color: var(--syntax-keyword);
  background: var(--bg-tertiary);
}

.tool-call-lsp-symbol-kind-icon.kind-variable {
  color: var(--text-secondary);
  background: var(--bg-tertiary);
}

.tool-call-lsp-symbol-identity {
  display: inline-flex;
  align-items: baseline;
  min-width: 0;
  max-width: 380px;
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.4;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-lsp-symbol-scope {
  color: var(--text-tertiary);
  font-weight: 400;
  flex-shrink: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-lsp-symbol-core-name {
  color: var(--text-primary);
  font-weight: 600;
  flex-shrink: 0;
}

.tool-call-lsp-kind-badge {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  font-weight: 500;
  font-family: var(--font-mono);
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
  border: 1px solid transparent;
}

.tool-call-lsp-kind-badge.kind-function {
  color: var(--accent-blue-text);
  background: var(--accent-blue-bg);
  border-color: rgba(59, 130, 246, 0.2);
}

.tool-call-lsp-kind-badge.kind-type {
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
  border-color: rgba(245, 158, 11, 0.2);
}

.tool-call-lsp-kind-badge.kind-interface {
  color: var(--accent-green-text);
  background: var(--accent-green-bg);
  border-color: rgba(34, 197, 94, 0.2);
}

.tool-call-lsp-kind-badge.kind-constant {
  color: var(--syntax-keyword);
  background: var(--bg-tertiary);
  border-color: var(--border-light);
}

.tool-call-lsp-kind-badge.kind-variable {
  color: var(--text-secondary);
  background: var(--bg-tertiary);
  border-color: var(--border-light);
}

.tool-call-lsp-symbol-detail {
  flex-shrink: 1;
  min-width: 0;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-lsp-symbol-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
  margin-left: auto;
}

.tool-call-lsp-symbol-file-loc {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-secondary);
}

.tool-call-lsp-symbol-file-icon {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.tool-call-lsp-symbol-file-name {
  color: var(--text-secondary);
  font-weight: 500;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-lsp-symbol-loc {
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.tool-call-lsp-symbol-copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition: all 0.15s ease;
  opacity: 0.7;
}

.tool-call-lsp-symbol-item:hover .tool-call-lsp-symbol-copy-btn {
  opacity: 1;
}

.tool-call-lsp-symbol-copy-btn:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  border-color: var(--border-light);
}

.tool-call-lsp-symbol-copy-btn .copy-ok {
  color: var(--accent-green);
}
/* ---- ambiguous symbol ---- */

.tool-call-lsp-ambiguous-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 4px 0;
}

.tool-call-lsp-ambiguous-banner {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: var(--radius-sm, 6px);
  background: rgba(245, 158, 11, 0.1);
  border: 1px solid rgba(245, 158, 11, 0.25);
  font-size: 11.5px;
  color: #d97706;
}

.tool-call-lsp-ambiguous-banner svg {
  flex-shrink: 0;
}

.tool-call-lsp-ambiguous-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 380px;
  overflow: auto;
}

.tool-call-lsp-ambiguous-candidate {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-secondary, rgba(0, 0, 0, 0.02));
  border: 1px solid var(--border-subtle, rgba(0, 0, 0, 0.06));
}

.tool-call-lsp-ambiguous-header {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11.5px;
}

.tool-call-lsp-ambiguous-file {
  font-weight: 500;
  color: var(--text-primary);
}

.tool-call-lsp-ambiguous-loc {
  display: flex;
  align-items: center;
  gap: 2px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-secondary);
}

.tool-call-lsp-ambiguous-container {
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-lsp-ambiguous-preview {
  margin: 0;
  padding: 4px 8px;
  background: var(--bg-tertiary, rgba(0, 0, 0, 0.04));
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.4;
  overflow-x: auto;
  color: var(--text-secondary);
}

/* ---- diagnostics（单文件 + 批量） ---- */

.tool-call-lsp-diag-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 420px;
  overflow: auto;
  padding: 2px 0;
}

.tool-call-lsp-diag-summary {
  padding: 2px 4px 4px;
  font-size: 11px;
  color: var(--text-tertiary);
}

.tool-call-lsp-diag-item {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
  padding: 3px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  border-left: 2px solid var(--text-tertiary);
}

.tool-call-lsp-diag-item.severity-error {
  border-left-color: var(--accent-red-text);
}

.tool-call-lsp-diag-item.severity-warning {
  border-left-color: var(--accent-amber-text);
}

.tool-call-lsp-diag-item.severity-information,
.tool-call-lsp-diag-item.severity-hint {
  border-left-color: var(--accent-blue-text);
}

.tool-call-lsp-diag-sev {
  flex-shrink: 0;
  font-size: 10px;
  font-weight: 600;
  text-transform: uppercase;
  color: var(--text-tertiary);
}

.tool-call-lsp-diag-item.severity-error .tool-call-lsp-diag-sev {
  color: var(--accent-red-text);
}

.tool-call-lsp-diag-item.severity-warning .tool-call-lsp-diag-sev {
  color: var(--accent-amber-text);
}

.tool-call-lsp-diag-item.severity-information .tool-call-lsp-diag-sev,
.tool-call-lsp-diag-item.severity-hint .tool-call-lsp-diag-sev {
  color: var(--accent-blue-text);
}

.tool-call-lsp-diag-loc {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.tool-call-lsp-diag-message {
  flex: 1;
  min-width: 0;
  font-size: 11.5px;
  color: var(--text-primary);
  word-break: break-word;
  user-select: text;
}

.tool-call-lsp-diag-source {
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--text-tertiary);
}

/* ---- diagnostics batch ---- */

.tool-call-lsp-diag-batch {
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 480px;
  overflow: auto;
}

.tool-call-lsp-diag-file {
  flex-shrink: 0;
  overflow: hidden;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.tool-call-lsp-diag-file-header {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 5px 8px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-tertiary);
}

.tool-call-lsp-diag-file-header svg {
  display: block;
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.tool-call-lsp-diag-file-name {
  flex-shrink: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}

.tool-call-lsp-diag-file-summary {
  flex-shrink: 0;
  margin-left: auto;
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.tool-call-lsp-diag-file-error {
  flex-shrink: 1;
  min-width: 0;
  margin-left: auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 10.5px;
  color: var(--accent-red-text);
}

/* LSP-only controls and lazy result views. Do not change shared switch semantics. */
.lsp-accessible-switch {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  border: 0;
  border-radius: var(--radius-sm);
  padding: 3px;
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  cursor: pointer;
}
.lsp-accessible-switch[aria-checked="true"] .toggle-slider {
  background: var(--text-primary);
  border-color: var(--text-primary);
}
.lsp-accessible-switch[aria-checked="true"] .toggle-slider::after {
  transform: translateX(14px);
  background: var(--on-solid);
}
.lsp-accessible-switch:disabled {
  opacity: 0.5;
  cursor: default;
}
.lsp-accessible-switch:focus-visible,
.lsp-status-badge:focus-visible,
.tool-call-lsp-show-more:focus-visible,
.tool-call-lsp-tree-branch > summary:focus-visible,
.tool-call-lsp-diag-file > summary:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}
.lsp-runtime-badge.unknown {
  color: var(--accent-amber-text);
}
.lsp-status-row.stale .lsp-status-dot {
  background: var(--warning, #f59e0b);
}
.tool-call-lsp-result-notice {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  font-size: 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  overflow-wrap: anywhere;
  transition: all 0.15s ease;
}

.tool-call-lsp-result-notice.is-warning {
  background: var(--accent-amber-bg);
  border-color: rgba(245, 158, 11, 0.28);
}

.tool-call-lsp-result-notice.is-failed {
  background: var(--accent-red-bg);
  border-color: rgba(239, 68, 68, 0.28);
}

.tool-call-lsp-notice-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.tool-call-lsp-notice-title-wrap {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.tool-call-lsp-notice-icon {
  flex-shrink: 0;
}

.tool-call-lsp-notice-icon.is-warning {
  color: var(--accent-amber-text);
}

.tool-call-lsp-notice-icon.is-failed {
  color: var(--accent-red-text);
}

.tool-call-lsp-notice-icon.is-info {
  color: var(--accent-blue-text);
}

.tool-call-lsp-notice-title {
  font-weight: 600;
  font-size: 12px;
  line-height: 1.4;
  color: var(--text-primary);
}

.tool-call-lsp-result-notice.is-warning .tool-call-lsp-notice-title {
  color: var(--accent-amber-text);
}

.tool-call-lsp-result-notice.is-failed .tool-call-lsp-notice-title {
  color: var(--accent-red-text);
}

.tool-call-lsp-notice-status-pills {
  display: flex;
  align-items: center;
  gap: 4px;
}

.tool-call-lsp-notice-pill {
  display: inline-flex;
  align-items: center;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  font-weight: 500;
  line-height: 1.4;
}

.tool-call-lsp-notice-pill.is-warning {
  background: var(--bg-primary);
  color: var(--accent-amber-text);
  border: 1px solid rgba(245, 158, 11, 0.25);
}

.tool-call-lsp-notice-body {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tool-call-lsp-notice-desc {
  margin: 0;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-secondary);
}

.tool-call-lsp-notice-desc.is-alert {
  color: var(--accent-red-text);
  font-weight: 500;
}

.tool-call-lsp-notice-meta-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding-top: 2px;
}

.tool-call-lsp-meta-tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 7px;
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  font-size: 11px;
  color: var(--text-secondary);
  max-width: 100%;
}

.tool-call-lsp-meta-tag svg {
  color: var(--text-tertiary);
  flex-shrink: 0;
}

.tool-call-lsp-meta-tag-label {
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.tool-call-lsp-meta-tag-val {
  font-weight: 500;
  color: var(--text-primary);
}

.tool-call-lsp-meta-tag-code {
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-primary);
  max-width: 340px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-lsp-notice-warnings-box {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  margin-top: 2px;
}

.tool-call-lsp-notice-warnings-header {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--accent-amber-text);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.tool-call-lsp-notice-warnings-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: 180px;
  overflow-y: auto;
}

.tool-call-lsp-notice-warning-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-size: 11px;
  line-height: 1.4;
  color: var(--text-secondary);
}

.tool-call-lsp-notice-warning-lang {
  display: inline-flex;
  align-items: center;
  padding: 0 4px;
  border-radius: var(--radius-sm);
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 600;
  flex-shrink: 0;
}

.tool-call-lsp-notice-warning-text {
  word-break: break-all;
}

/* 参数区针对 LSP 的样式美化 */
.tool-call-lsp-body .tool-call-codelens-params {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 2px;
}

.tool-call-lsp-body .tool-call-codelens-param-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  width: fit-content;
  max-width: 100%;
}

.tool-call-lsp-body .tool-call-codelens-param-item svg {
  color: var(--accent-blue-text);
  flex-shrink: 0;
}

.tool-call-lsp-body .tool-call-codelens-param-label {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-tertiary);
}

.tool-call-lsp-body .tool-call-codelens-param-value {
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 500;
  word-break: break-all;
}
.tool-call-lsp-symbol-tree {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.tool-call-lsp-tree-branch > .tool-call-lsp-symbol-tree {
  margin-left: 16px;
  border-left: 1px solid var(--border-light);
  padding-left: 7px;
}
.tool-call-lsp-tree-branch > summary,
.tool-call-lsp-tree-leaf {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 4px;
  font-size: 12px;
  overflow-wrap: anywhere;
}
.tool-call-lsp-tree-branch > summary,
.tool-call-lsp-diag-file > summary {
  cursor: pointer;
  list-style: none;
}
.tool-call-lsp-tree-branch > summary::-webkit-details-marker,
.tool-call-lsp-diag-file > summary::-webkit-details-marker {
  display: none;
}
.tool-call-lsp-tree-branch[open] > summary > svg:first-child,
.tool-call-lsp-diag-file[open] > summary > svg:first-child {
  transform: rotate(90deg);
}
.tool-call-lsp-show-more {
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  padding: 5px 10px;
  color: var(--text-secondary);
  background: var(--bg-secondary);
  font: inherit;
  cursor: pointer;
}
.tool-call-lsp-diag-file .tool-call-error {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  padding: 8px;
}

.lsp-diagnostics-summary {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  padding: 7px 9px;
  font-size: 11px;
  color: var(--text-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
}
.lsp-diagnostics-summary.is-compact {
  padding: 0;
  border: 0;
  font-size: 10px;
}
.lsp-diagnostic-file-status {
  flex-shrink: 0;
  font-size: 11px;
}
.tool-call-lsp-diag-file-header {
  flex-wrap: wrap;
}
.lsp-diagnostic-warning-badge {
  font-size: 10px;
  color: var(--accent-amber-text);
}
.lsp-diagnostic-partial .lsp-diagnostic-file-status,
.tool-call-lsp-file-notice {
  color: var(--accent-amber-text);
}
.lsp-diagnostic-failed .lsp-diagnostic-file-status {
  color: var(--accent-red-text);
}
.tool-call-lsp-file-notice {
  margin: 4px 8px;
  font-size: 11px;
}

/* ---- lsp-symbols 批量与多文件卡片样式 ---- */
.tool-call-lsp-symbols-batch {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
}

.tool-call-lsp-symbols-batch-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2px 4px 6px;
  border-bottom: 1px solid var(--border-light, rgba(255, 255, 255, 0.08));
  font-size: 11px;
}

.tool-call-lsp-symbols-batch-summary {
  color: var(--text-secondary);
  font-weight: 500;
}

.tool-call-lsp-symbols-toggle-all-btn {
  background: transparent;
  border: 1px solid var(--border-light, rgba(255, 255, 255, 0.12));
  border-radius: var(--radius-sm, 4px);
  padding: 2px 8px;
  font-size: 11px;
  color: var(--text-tertiary);
  cursor: pointer;
  transition: all 0.15s ease;
}

.tool-call-lsp-symbols-toggle-all-btn:hover {
  background: var(--bg-hover, rgba(255, 255, 255, 0.06));
  color: var(--text-primary);
  border-color: var(--border-medium, rgba(255, 255, 255, 0.2));
}

.tool-call-lsp-symbols-batch-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tool-call-lsp-symbol-file-group {
  border: 1px solid var(--border-light, rgba(255, 255, 255, 0.08));
  border-radius: var(--radius-sm, 6px);
  background: var(--bg-secondary, rgba(255, 255, 255, 0.02));
  overflow: hidden;
  transition: border-color 0.15s ease;
}

.tool-call-lsp-symbol-file-group:hover {
  border-color: var(--border-medium, rgba(255, 255, 255, 0.18));
}

.tool-call-lsp-symbol-file-group.is-open {
  background: var(--bg-secondary, rgba(255, 255, 255, 0.03));
}

.tool-call-lsp-symbol-file-header {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  font-size: 12px;
  cursor: pointer;
  user-select: none;
  background: transparent;
  transition: background 0.12s ease;
}

.tool-call-lsp-symbol-file-header:hover {
  background: var(--bg-hover, rgba(255, 255, 255, 0.04));
}

.tool-call-lsp-symbol-file-arrow {
  color: var(--text-tertiary);
  flex-shrink: 0;
  transition: transform 0.18s ease;
}

.tool-call-lsp-symbol-file-arrow.open {
  transform: rotate(90deg);
}

.tool-call-lsp-symbol-file-icon {
  color: var(--accent-blue-text, #60a5fa);
  flex-shrink: 0;
}

.tool-call-lsp-symbol-file-name {
  font-weight: 600;
  color: var(--text-primary);
  flex-shrink: 0;
}

.tool-call-lsp-symbol-file-path {
  color: var(--text-tertiary);
  font-size: 11px;
  font-family: var(--font-mono);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  direction: rtl;
  text-align: left;
  max-width: 300px;
  flex: 1 1 auto;
}

.tool-call-lsp-file-copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-tertiary);
  border-radius: var(--radius-sm, 3px);
  cursor: pointer;
  flex-shrink: 0;
  opacity: 0;
  transition:
    opacity 0.15s ease,
    color 0.15s ease,
    background 0.15s ease;
}

.tool-call-lsp-symbol-file-header:hover .tool-call-lsp-file-copy-btn {
  opacity: 1;
}

.tool-call-lsp-file-copy-btn:hover {
  color: var(--text-primary);
  background: var(--bg-hover, rgba(255, 255, 255, 0.1));
}

.tool-call-lsp-file-copy-btn .copy-ok {
  color: var(--accent-green-text, #34d399);
}

.tool-call-lsp-symbol-file-meta-right {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  flex-shrink: 0;
}

.tool-call-lsp-symbol-file-count-badge {
  font-size: 10.5px;
  padding: 1px 6px;
  border-radius: var(--radius-sm, 4px);
  background: var(--bg-tertiary, rgba(255, 255, 255, 0.06));
  color: var(--text-secondary);
}

.tool-call-lsp-symbol-file-content {
  padding: 6px 12px 10px 18px;
  border-top: 1px solid var(--border-light, rgba(255, 255, 255, 0.05));
}

.tool-call-lsp-symbol-file-empty {
  padding: 10px 4px;
  font-size: 11.5px;
  color: var(--text-tertiary);
  font-style: italic;
}

.tool-call-lsp-rename-safety {
  font-size: 12px;
  overflow-wrap: anywhere;
}
.tool-call-lsp-rename-safety p {
  margin: 5px 0;
}
.tool-call-lsp-rename-safety ul {
  max-height: 240px;
  overflow: auto;
}
.tool-call-lsp-rename-safety [role="alert"] {
  color: var(--accent-red-text);
}

/* ===== Usage statistics panel ===== */

.usage-summary-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 10px;
  margin-bottom: 18px;
}

.usage-date-filter-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 14px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.usage-date-filter-label {
  font-size: 12.5px;
  font-weight: 500;
  color: var(--text-secondary);
  white-space: nowrap;
}

/* 配置筛选行：位于日期筛选栏上方，风格与之一致 */
.usage-profile-filter-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.usage-profile-filter-bar .custom-select {
  min-width: 200px;
  max-width: 320px;
}

.usage-profile-filter-bar .custom-select-trigger {
  padding: 4px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  font-size: 12px;
}

.usage-date-preset-select {
  position: relative;
  flex-shrink: 0;
}

.usage-date-preset-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-width: 116px;
  padding: 4px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  white-space: nowrap;
}

.usage-date-preset-trigger:hover {
  border-color: var(--text-muted);
}

.usage-date-preset-trigger:focus {
  outline: none;
  border-color: var(--accent-color);
}

.usage-date-preset-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.usage-date-preset-dropdown {
  position: absolute;
  top: calc(100% + 4px);
  left: 0;
  z-index: 100;
  min-width: 100%;
  max-height: 240px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow);
}

.usage-date-preset-item {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 6px 8px;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  text-align: left;
  white-space: nowrap;
}

.usage-date-preset-item:hover {
  background: var(--bg-hover);
}

.usage-date-preset-item.selected {
  background: var(--bg-hover);
  color: var(--text-primary);
  font-weight: 500;
}

.usage-summary-card {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 12px 14px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.usage-summary-card-label {
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 500;
}

.usage-summary-card-value {
  color: var(--text-primary);
  font-size: 18px;
  font-weight: 600;
  line-height: 1.2;
}

/* 成功率卡片副行：错误请求数 */
.usage-summary-card-sub {
  color: var(--text-muted);
  font-size: 11px;
}

/* 图表总览区：每日趋势 + 模型占比环形图并排 */
.usage-charts-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 10px;
  margin-bottom: 18px;
}

.usage-chart-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  padding: 12px 14px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.usage-chart-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 18px;
}

.usage-chart-header strong {
  font-size: 13px;
}

.usage-chart-legend {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 10.5px;
  color: var(--text-muted);
}

.usage-chart-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.usage-chart-legend-dot {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}

/* 每日趋势图 */
.usage-trend-chart {
  position: relative;
  width: 100%;
}

.usage-trend-chart svg {
  display: block;
  width: 100%;
  height: 138px;
}

.usage-chart-axis-label {
  fill: var(--text-muted);
  font-size: 9.5px;
}

.usage-chart-tooltip {
  position: absolute;
  z-index: 5;
  pointer-events: none;
  min-width: 150px;
  padding: 8px 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow);
  font-size: 11px;
}

.usage-chart-tooltip-title {
  margin-bottom: 4px;
  font-weight: 600;
  color: var(--text-primary);
}

.usage-chart-tooltip-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.usage-chart-tooltip-label {
  color: var(--text-muted);
}

.usage-chart-tooltip-value {
  font-weight: 500;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}

/* 模型占比环形图 */
.usage-donut {
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex: 1;
}

.usage-donut svg {
  flex-shrink: 0;
  width: 116px;
  height: 116px;
}

.usage-donut-segment {
  transition: opacity 0.15s;
}

.usage-donut-segment.dim {
  opacity: 0.3;
}

.usage-donut-center-value {
  fill: var(--text-primary);
  font-size: 15px;
  font-weight: 600;
}

.usage-donut-center-label {
  fill: var(--text-muted);
  font-size: 9px;
}

.usage-donut-legend {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  flex: 1;
}

.usage-donut-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding: 2px 4px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  cursor: default;
}

.usage-donut-legend-item:hover {
  background: var(--bg-hover);
}

.usage-donut-legend-dot {
  flex-shrink: 0;
  width: 8px;
  height: 8px;
  border-radius: 2px;
}

.usage-donut-legend-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

.usage-donut-legend-pct {
  flex-shrink: 0;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

/* 图表空态 */
.usage-chart-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 138px;
  color: var(--text-muted);
  font-size: 12px;
}

/* 使用记录折叠开关 */
.usage-records-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  width: 100%;
  padding: 2px 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.usage-records-toggle-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.usage-records-chevron {
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform 0.15s;
}

.usage-records-chevron.open {
  transform: rotate(180deg);
}

.usage-heatmap-section {
  margin-bottom: 22px;
}

.usage-heatmap-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.usage-heatmap-header strong {
  font-size: 14px;
}

.usage-date-filter {
  display: flex;
  align-items: center;
  gap: 6px;
}

.usage-date-input {
  padding: 4px 8px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 12px;
  font-family: inherit;
}
.usage-date-input:focus {
  outline: none;
  border-color: var(--accent-color);
}

.usage-date-separator {
  color: var(--text-muted);
  font-size: 12px;
}

/* 清理用量数据：日期起止 + 删除按钮 */
.usage-clear-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.usage-clear-bar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.usage-clear-hint {
  font-size: 11.5px;
  color: var(--text-muted);
  white-space: nowrap;
}

.usage-clear-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: auto;
  padding: 5px 12px;
  border: 1px solid
    color-mix(in srgb, var(--accent-red-text, #ef4444) 40%, transparent);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--accent-red-text, #ef4444);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  white-space: nowrap;
}

.usage-clear-btn:hover:not(:disabled) {
  background: color-mix(
    in srgb,
    var(--accent-red-text, #ef4444) 12%,
    transparent
  );
}

.usage-clear-btn:disabled {
  opacity: 0.5;
  cursor: default;
}

.usage-heatmap-scroll {
  overflow-x: hidden;
  padding-bottom: 4px;
}

.usage-heatmap-month-labels {
  position: relative;
  height: 14px;
  margin-left: 24px;
  margin-bottom: 4px;
}

.usage-heatmap-month-label {
  position: absolute;
  top: 0;
  font-size: 10px;
  line-height: 14px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.usage-heatmap-container {
  display: flex;
  gap: 6px;
  align-items: stretch;
}

.usage-heatmap-weekday-labels {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex-shrink: 0;
  width: 18px;
}

.usage-heatmap-weekday-label {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  font-size: 10px;
  line-height: 1;
  color: var(--text-muted);
  visibility: hidden;
  overflow: hidden;
}

.usage-heatmap-weekday-label.visible {
  visibility: visible;
}

.usage-heatmap-grid {
  display: flex;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.usage-heatmap-column {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.usage-heatmap-grid .usage-heatmap-cell {
  width: 100%;
  height: auto;
  aspect-ratio: 1;
}

.usage-heatmap-cell {
  width: 11px;
  height: 11px;
  border-radius: 2px;
  border: 1px solid transparent;
  transition: border-color 0.1s;
}

.usage-heatmap-cell:hover {
  border-color: var(--text-muted);
}

.usage-heatmap-cell.empty {
  background: transparent;
  border-color: transparent;
}

.usage-heatmap-legend {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 8px;
}

.usage-heatmap-legend-label {
  font-size: 10px;
  color: var(--text-muted);
  margin: 0 2px;
}

.usage-table-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.usage-model-breakdown-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-bottom: 18px;
}

/* 模型统计表列宽：模型 / 类型 / 请求数 / 输入 / 输出 / 缓存写 / 缓存读 / 总计 */
.usage-model-breakdown-section .usage-table thead th:first-child,
.usage-model-breakdown-section .usage-table tbody td:first-child {
  width: 150px;
}

.usage-model-breakdown-section .usage-table thead th:nth-child(2),
.usage-model-breakdown-section .usage-table tbody td:nth-child(2) {
  width: 96px;
}

.usage-model-breakdown-section .usage-table thead th:nth-child(3),
.usage-model-breakdown-section .usage-table tbody td:nth-child(3) {
  width: 84px;
}

.usage-model-breakdown-section .usage-table thead th:nth-child(4),
.usage-model-breakdown-section .usage-table thead th:nth-child(5),
.usage-model-breakdown-section .usage-table thead th:nth-child(6),
.usage-model-breakdown-section .usage-table thead th:nth-child(7),
.usage-model-breakdown-section .usage-table tbody td:nth-child(4),
.usage-model-breakdown-section .usage-table tbody td:nth-child(5),
.usage-model-breakdown-section .usage-table tbody td:nth-child(6),
.usage-model-breakdown-section .usage-table tbody td:nth-child(7) {
  width: 78px;
}

.usage-model-breakdown-section .usage-table thead th:last-child,
.usage-model-breakdown-section .usage-table tbody td:last-child {
  width: 96px;
}

.usage-table-header {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.usage-table-header strong {
  font-size: 14px;
}

/* 用量记录标题紧贴表格，与上方清理区保持分隔 */
.usage-table-section .usage-clear-section + .usage-table-header {
  margin-top: 8px;
}

.usage-table-wrapper {
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.usage-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  font-size: 12.5px;
}

.usage-table thead,
.usage-table tbody tr {
  display: table;
  width: 100%;
  table-layout: fixed;
  box-sizing: border-box;
}

.usage-table thead {
  border-right: 10px solid var(--bg-secondary);
  border-bottom: 1px solid var(--border-subtle);
}

.usage-table tbody {
  display: block;
  max-height: 380px;
  overflow-y: auto;
  scrollbar-gutter: stable;
}

.usage-table thead th {
  padding: 8px 10px;
  text-align: left;
  font-weight: 600;
  color: var(--text-secondary);
  background: var(--bg-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.usage-table thead th:first-child,
.usage-table tbody td:first-child {
  width: 160px;
}

/* 数值列表头与右对齐的数值单元格保持同一对齐基线 */
.usage-table thead th.usage-th-number {
  text-align: right;
}

.usage-table thead th:nth-child(5),
.usage-table thead th:nth-child(6),
.usage-table thead th:nth-child(7),
.usage-table thead th:nth-child(8),
.usage-table thead th:nth-child(9),
.usage-table tbody td:nth-child(5),
.usage-table tbody td:nth-child(6),
.usage-table tbody td:nth-child(7),
.usage-table tbody td:nth-child(8),
.usage-table tbody td:nth-child(9) {
  width: 72px;
}

.usage-table thead th:last-child,
.usage-table tbody td:last-child {
  width: 112px;
}
.usage-table tbody td.usage-cell-status {
  overflow: visible;
  text-overflow: clip;
}

.usage-table tbody td {
  padding: 7px 10px;
  border-bottom: 1px solid var(--border-subtle);
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.usage-table tbody tr:last-child td {
  border-bottom: none;
}

.usage-table tbody tr:hover td {
  background: var(--bg-hover);
}

.usage-cell-time {
  color: var(--text-muted);
  font-size: 11.5px;
}

.usage-cell-model,
.usage-cell-profile {
  overflow: hidden;
  text-overflow: ellipsis;
}

.usage-cell-method {
  color: var(--text-muted);
  font-size: 11.5px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.usage-cell-number {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
}

.usage-cell-total {
  font-weight: 600;
}

.usage-table-loading,
.usage-table-empty {
  text-align: center;
  color: var(--text-muted);
  padding: 24px 10px;
}

.usage-status-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 500;
}

.usage-status-badge.success {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.usage-status-badge.error {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.usage-status-badge.warning {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.usage-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 6px 0;
}

.usage-pagination-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  cursor: pointer;
  transition:
    background 0.12s,
    border-color 0.12s;
}
.usage-pagination-btn:hover:not(:disabled) {
  background: var(--bg-hover);
  border-color: var(--text-muted);
}

.usage-pagination-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.usage-pagination-info {
  font-size: 12.5px;
  color: var(--text-secondary);
  white-space: nowrap;
}

.usage-floating-tooltip-root {
  position: fixed;
  top: 0;
  left: 0;
  min-width: 200px;
  max-width: 320px;
  padding: 8px 11px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow);
  z-index: 10000;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-secondary);
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transform: translateY(2px);
  transition:
    opacity 0.12s ease,
    visibility 0.12s ease,
    transform 0.12s ease;
}

.usage-floating-tooltip-root.visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.usage-floating-tooltip {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.usage-floating-tooltip-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 3px;
  word-break: break-word;
}

.usage-floating-tooltip-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
}

.usage-floating-tooltip-label {
  flex-shrink: 0;
  color: var(--text-muted);
}

.usage-floating-tooltip-value {
  text-align: right;
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
  color: var(--text-primary);
  font-weight: 500;
  word-break: break-all;
}

.usage-floating-tooltip-value.usage-floating-tooltip-total {
  font-weight: 600;
  color: var(--text-primary);
}

.usage-floating-tooltip-divider {
  height: 1px;
  background: var(--border-light);
  margin: 4px 0;
}

/* ===== System Logs Panel ===== */

.system-logs-request-logging-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.system-logs-retention-select {
  width: 140px;
  flex-shrink: 0;
}

.system-logs-request-logging-label {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
}

.system-logs-countdown-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border: 1px solid var(--accent-red);
  border-radius: var(--radius-sm);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.4;
  white-space: nowrap;
}

.system-logs-countdown-time {
  font-family: var(
    --font-mono,
    ui-monospace,
    "Cascadia Code",
    Consolas,
    monospace
  );
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

/* ===== Request Logging Duration Modal ===== */
.request-logging-modal {
  width: 440px;
}

.request-logging-duration {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.request-logging-duration-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.request-logging-duration-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-secondary);
}

.request-logging-duration-value {
  font-size: 16px;
  font-weight: 650;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}

.request-logging-duration-value em {
  margin-left: 3px;
  font-size: 11px;
  font-style: normal;
  font-weight: 500;
  color: var(--text-muted);
}

.request-logging-duration-presets {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 3px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.request-logging-duration-preset {
  flex: 1;
  padding: 4px 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 12px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.request-logging-duration-preset:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.request-logging-duration-preset.active {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
  font-weight: 600;
}

/* 请求日志「自动关闭时长」滑块：沿用统一滑块样式，仅把主色换成红色语义色。 */
.request-logging-duration-slider {
  --range-accent: var(--accent-red);
}

.request-logging-duration-scale {
  display: flex;
  justify-content: space-between;
  margin-top: -6px;
  color: var(--text-muted);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.request-logging-duration-hint {
  margin: 0;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.5;
}

.system-logs-filter-row {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}

.system-logs-level-chips {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.system-logs-level-chip {
  padding: 3px 11px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 11.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.14s,
    color 0.14s;
}

.system-logs-level-chip:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.system-logs-level-chip.active {
  background: var(--bg-active);
  color: var(--text-primary);
}

.system-logs-level-chip.active.debug {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.system-logs-level-chip.active.info {
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.system-logs-level-chip.active.warn {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

.system-logs-level-chip.active.error {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

/* 按模块筛选（模块名来自日志里实际出现过的 module） */
.system-logs-module-filter {
  width: 180px;
  min-width: 0;
}

.system-logs-page {
  overflow: hidden;
}

.system-logs-stream-section {
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex: 1;
}

.system-logs-stream-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 6px;
}

.system-logs-stream {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  overflow-y: auto;
  scrollbar-gutter: stable;
}

.system-logs-state {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 12px;
  color: var(--text-muted);
  font-size: 12.5px;
}

.system-logs-entry {
  background: transparent;
  transition: background 0.14s;
}

.system-logs-entry + .system-logs-entry {
  border-top: 1px solid var(--border-subtle);
}

.system-logs-entry:hover {
  background: var(--bg-hover);
}

.system-logs-entry.expanded {
  background: var(--bg-hover);
}

/* 勾选 / 单条导出：行内选择与操作 */
.system-logs-entry-row {
  display: flex;
  align-items: center;
  min-width: 0;
}

.system-logs-entry.selected {
  background: var(--bg-hover);
}

.system-logs-entry-checkbox {
  width: 13px;
  height: 13px;
  margin: 0 0 0 10px;
  flex-shrink: 0;
  accent-color: var(--accent-color, #4a9eff);
  cursor: pointer;
}

.system-logs-entry-export {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 4px;
  margin-right: 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  opacity: 0;
  flex-shrink: 0;
  transition:
    opacity 0.14s,
    color 0.14s,
    background 0.14s;
}

.system-logs-entry:hover .system-logs-entry-export,
.system-logs-entry.expanded .system-logs-entry-export,
.system-logs-entry-export:focus-visible {
  opacity: 1;
}

.system-logs-entry-export:hover {
  color: var(--text-secondary);
  background: var(--bg-tertiary);
}

.system-logs-selection-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.system-logs-select-page {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  color: var(--text-muted);
  cursor: pointer;
  user-select: none;
}

.system-logs-select-page input {
  width: 13px;
  height: 13px;
  margin: 0;
  accent-color: var(--accent-color, #4a9eff);
  cursor: pointer;
}

.system-logs-selected-count {
  font-size: 11.5px;
  color: var(--accent-color);
}

.system-logs-clear-selection {
  padding: 1px 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  font-size: 11.5px;
  cursor: pointer;
}

.system-logs-clear-selection:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

/* 导出对话框 */
.system-logs-export-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.system-logs-export-group {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.system-logs-export-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.system-logs-export-options {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.system-logs-export-option {
  padding: 5px 11px;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
  transition:
    background 0.14s,
    border-color 0.14s,
    color 0.14s;
}

.system-logs-export-option:hover:not(:disabled) {
  background: var(--bg-hover);
}

.system-logs-export-option.active {
  border-color: var(--accent-color);
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--accent-color);
}

.system-logs-export-option:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.system-logs-export-hint {
  margin: 0;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-muted);
}

.system-logs-entry-head {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
  padding: 7px 10px;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.system-logs-entry-time {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  flex-shrink: 0;
  font-family: var(--font-mono);
  font-size: 11px;
  line-height: 1.3;
}

.system-logs-entry-date {
  color: var(--text-muted);
}

.system-logs-entry-clock {
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

.system-logs-level-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 48px;
  padding: 1px 7px;
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.05em;
  flex-shrink: 0;
}

.system-logs-level-badge.debug {
  background: var(--bg-hover);
  color: var(--text-tertiary);
}

.system-logs-level-badge.info {
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.system-logs-level-badge.warn {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

.system-logs-level-badge.error {
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.system-logs-source-tag {
  display: inline-flex;
  align-items: center;
  padding: 1px 7px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-subtle);
  background: transparent;
  color: var(--text-muted);
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 500;
  flex-shrink: 0;
}

.system-logs-source-tag.renderer {
  color: var(--accent-blue-text);
  border-color: var(--accent-blue-bg);
}

.system-logs-entry-location {
  flex-shrink: 0;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--text-tertiary);
}

.system-logs-entry-message {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px;
  color: var(--text-primary);
}

.system-logs-entry-chevron {
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform 0.18s ease;
}

.system-logs-entry.expanded .system-logs-entry-chevron {
  transform: rotate(180deg);
}

.system-logs-entry-detail {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px 12px;
  border-top: 1px solid var(--border-subtle);
  background: var(--bg-tertiary);
  animation: system-logs-detail-in 0.18s ease;
}

@keyframes system-logs-detail-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.system-logs-detail-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.system-logs-detail-label {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.system-logs-detail-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.system-logs-detail-copy-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 3px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.14s,
    color 0.14s,
    background 0.14s;
}

.system-logs-detail-row:hover .system-logs-detail-copy-btn {
  opacity: 1;
}
.system-logs-detail-copy-btn:hover {
  color: var(--text-secondary);
  background: var(--bg-hover);
}

.system-logs-detail-copy-btn.copied {
  color: var(--accent-green);
  opacity: 1;
}

.system-logs-detail-value {
  padding: 7px 9px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11.5px;
  line-height: 1.55;
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 180px;
  overflow-y: auto;
}

/* ===== Personalization (global & project rules) ===== */
.personalization-page {
  gap: 12px;
  padding-bottom: 32px;
}

.personalization-rule-chain {
  flex-shrink: 0;
}

.personalization-workspace {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  border: 1px solid var(--border-light);
  border-radius: 8px;
  background: var(--bg-secondary);
}

/* 编辑器区域独立滚动：scope 切换栏固定，内容超高时在 tabpanel 内滚动，
   避免 flex 压缩导致 textarea 被 overflow 截断。 */
.personalization-tabpanel:not([hidden]) {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  overflow-y: auto;
}

.personalization-scope-bar {
  display: flex;
  min-height: 48px;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 7px 10px;
  border-bottom: 1px solid var(--border-light);
  border-radius: 8px 8px 0 0;
  background: var(--bg-tertiary);
}

.personalization-scope-tabs {
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: var(--bg-primary);
}

.personalization-scope-tabs button {
  display: inline-flex;
  min-height: 30px;
  align-items: center;
  gap: 7px;
  padding: 5px 12px;
  border: 0;
  border-radius: 5px;
  background: transparent;
  color: var(--text-muted);
  font-size: 12px;
  font-weight: 600;
}

.personalization-scope-tabs button:hover {
  color: var(--text-primary);
  background: var(--bg-secondary);
}

.personalization-scope-tabs button.active {
  background: var(--bg-tertiary);
  color: var(--text-primary);
  box-shadow: inset 0 0 0 1px var(--border-light);
}

.personalization-scope-tabs button.active svg {
  color: var(--text-secondary);
}

.personalization-scope-summary {
  color: var(--text-muted);
  font-size: 11px;
}

.personalization-section {
  position: relative;
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: 12px;
  padding: 16px 18px 18px;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.personalization-section:hover {
  border-color: transparent;
  box-shadow: none;
}

.personalization-section-header {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.personalization-section-title {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px 10px;
}

.personalization-section-icon {
  display: inline-flex;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
}

.personalization-section-icon svg {
  width: 15px;
  height: 15px;
  stroke-width: 2;
}

.personalization-section-title strong {
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 650;
  letter-spacing: 0.01em;
}

.personalization-section-title > span:last-child {
  flex-basis: 100%;
  margin-left: 40px;
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.45;
}

.personalization-current-project {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  gap: 10px;
  padding: 4px 0 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.personalization-current-project-label {
  flex-shrink: 0;
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 600;
}

.personalization-current-project strong {
  min-width: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.personalization-project-kind {
  flex-shrink: 0;
  padding: 3px 10px;
  border-radius: 4px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 10px;
  font-weight: 650;
  letter-spacing: 0.02em;
}

/* --- Personalization: 作用域提示条 --- */
.personalization-toolbar {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--border-light);
  border-radius: 10px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11.5px;
}

.personalization-toolbar-main {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 9px;
}

.personalization-toolbar-main > svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

.personalization-toolbar-info {
  display: flex;
  min-width: 0;
  flex: 1;
  flex-direction: column;
  gap: 2px;
}

.personalization-toolbar-info > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.personalization-toolbar .project-skills-path {
  font-size: 10.5px;
}

/* --- Personalization: 保存按钮（与其他界面主按钮一致） --- */
.personalization-save-btn {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 30px;
  padding: 5px 16px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: var(--text-primary);
  color: var(--on-solid);
  font-size: 12px;
  font-weight: 600;
  box-shadow: 0 1px 2px rgb(0 0 0 / 0.2);
  transition:
    filter 0.15s ease,
    transform 0.1s ease,
    box-shadow 0.15s ease;
}

.personalization-save-btn:hover:not(:disabled) {
  filter: brightness(1.15);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--text-primary) 22%, transparent);
}

.personalization-save-btn:active:not(:disabled) {
  transform: translateY(1px);
}

.personalization-save-btn:focus-visible {
  outline: 2px solid var(--text-primary);
  outline-offset: 2px;
}

.personalization-save-btn:disabled {
  cursor: not-allowed;
  opacity: 0.45;
  box-shadow: none;
}

/* --- Personalization: 规则编辑器 --- */
.personalization-textarea {
  flex: 1;
  min-height: 360px;
  padding: 14px 16px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-mono);
  font-size: 12.5px;
  line-height: 1.6;
  resize: vertical;
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease;
}

.personalization-textarea:hover {
  border-color: var(--border-color);
}

.personalization-textarea:focus {
  border-color: var(--accent-color);
}

/* --- Personalization: 空状态 --- */
.personalization-empty {
  display: flex;
  min-height: 200px;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 12px;
  padding: 28px 24px;
  border: 1px dashed var(--border-color);
  border-radius: 10px;
  background: color-mix(in srgb, var(--bg-primary) 55%, transparent);
  color: var(--text-muted);
  font-size: 12px;
  text-align: center;
  line-height: 1.55;
}

.personalization-empty > svg {
  width: 42px;
  height: 42px;
  padding: 11px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  box-sizing: border-box;
}

.personalization-inheritance-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 10px 12px;
  border: 1px solid var(--border-light);
  border-radius: 7px;
  background: color-mix(in srgb, var(--bg-tertiary) 72%, transparent);
}

.personalization-inheritance-copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 2px;
}

.personalization-inheritance-copy strong {
  color: var(--text-primary);
  font-size: 11.5px;
  font-weight: 650;
}

.personalization-inheritance-copy span {
  color: var(--text-muted);
  font-size: 10.5px;
  line-height: 1.45;
}

.personalization-rule-chain {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 7px 16px;
  padding: 10px 12px;
  border-top: 1px solid var(--border-light);
  border-bottom: 1px solid var(--border-light);
  color: var(--text-muted);
}

.personalization-rule-chain-label,
.personalization-rule-chain-steps {
  display: flex;
  align-items: center;
}

.personalization-rule-chain-label {
  gap: 7px;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 650;
}

.personalization-rule-chain-label svg {
  color: var(--text-muted);
}

.personalization-rule-chain-steps {
  min-width: 0;
  gap: 7px;
  font-size: 11px;
}

.personalization-rule-chain-steps span {
  padding: 3px 7px;
  border-radius: 4px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  white-space: nowrap;
}

.personalization-rule-chain-steps svg {
  flex-shrink: 0;
  color: var(--text-muted);
}

.personalization-rule-chain small {
  grid-column: 2;
  font-size: 10.5px;
  line-height: 1.45;
}

@media (max-width: 640px) {
  .personalization-scope-bar {
    align-items: stretch;
    flex-direction: column;
    gap: 6px;
  }

  .personalization-scope-tabs {
    align-self: flex-start;
  }

  .personalization-rule-chain {
    grid-template-columns: 1fr;
  }

  .personalization-rule-chain-steps {
    overflow-x: auto;
  }

  .personalization-rule-chain small {
    grid-column: 1;
  }

  .personalization-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .personalization-save-btn {
    align-self: flex-end;
  }

  .personalization-section-title > span:last-child {
    margin-left: 0;
  }
}

/* ===== 生图设置面板：渠道表格模式（复用 API 设置页交互） ===== */
/* 嵌入 API 设置页「图像生成」标签页：外层页面负责滚动，避免嵌套滚动容器 */
.api-settings-page.imagegen-tab-page {
  overflow: visible;
  flex: none;
}

/* 面板内原生复选框跟随主题强调色 */
.imagegen-tab-page input[type="checkbox"] {
  accent-color: var(--accent-color);
}

/* 汇总卡片区：与 API 设置页 api-settings-summary-grid 同构。
   5 列单行：渠道数 / 已启用 / 最大并发生成数 / 生成超时 / 执行模式 */
.imagegen-summary-grid {
  grid-template-columns: 0.6fr 0.6fr 1.4fr 1.4fr 1.4fr;
}

@media (max-width: 640px) {
  .imagegen-summary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* 并发配置卡片：标题行 + 步进器 + 提示 */
.imagegen-concurrency-card {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 7px;
}

.imagegen-concurrency-card .imagegen-concurrency-head {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  overflow: hidden;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.imagegen-concurrency-head svg {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.imagegen-concurrency-control {
  display: flex;
  align-items: center;
  gap: 6px;
}

.imagegen-concurrency-control input {
  width: 52px;
  padding: 4px 6px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  outline: none;
  background: var(--bg-primary);
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  font-weight: 650;
  text-align: center;
  -moz-appearance: textfield;
  appearance: textfield;
  transition:
    border-color 0.12s,
    box-shadow 0.12s;
}

.imagegen-concurrency-control input::-webkit-outer-spin-button,
.imagegen-concurrency-control input::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.imagegen-concurrency-control input:focus {
  border-color: var(--accent-color);
}

.imagegen-concurrency-control input:disabled {
  cursor: default;
  opacity: 0.6;
}

.imagegen-concurrency-control .icon-btn {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  font-size: 14px;
  line-height: 1;
}

/* 执行模式控件：占满卡片剩余宽度并允许收缩，下拉触发器不溢出卡片 */
.imagegen-mode-control {
  min-width: 0;
}

.imagegen-mode-control .custom-select {
  min-width: 0;
  flex: 1;
}

.imagegen-mode-card .custom-select-label {
  font-weight: 500;
}

.imagegen-concurrency-range {
  margin-left: auto;
  color: var(--text-tertiary);
  font-family: var(--font-mono, monospace);
  font-size: 10.5px;
  white-space: nowrap;
}

.imagegen-concurrency-hint {
  display: -webkit-box;
  overflow: hidden;
  color: var(--text-muted);
  font-size: 10.5px;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

/* 操作区：搜索 + 添加渠道 */
.imagegen-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

.imagegen-search {
  flex: 1;
  min-width: 0;
}

.imagegen-add-btn {
  flex-shrink: 0;
}

.imagegen-table-panel {
  margin-bottom: 10px;
}

/* 空状态：图标 + 文案 */
.imagegen-empty-state {
  flex-direction: column;
  gap: 10px;
}

.imagegen-empty-state > svg {
  width: 40px;
  height: 40px;
  padding: 9px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  box-sizing: border-box;
}

.imagegen-provider-badge.gemini {
  color: var(--accent-purple-text, var(--accent-blue-text));
  border-color: color-mix(
    in srgb,
    var(--accent-purple-text, var(--accent-blue-text)) 30%,
    transparent
  );
}

/* 渠道编辑弹窗 */
.imagegen-editor {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.imagegen-editor .api-settings-field-hint {
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 500;
  line-height: 1.45;
}

/* 弹窗内原生复选框跟随主题强调色 */
.imagegen-editor input[type="checkbox"] {
  accent-color: var(--accent-color);
}

.imagegen-editor-actions {
  width: 100%;
}

.imagegen-editor-modal .app-modal-body {
  max-height: 66vh;
  overflow-y: auto;
}

/* 弹窗尺寸行：自定义输入 + 预设下拉 */
.imagegen-editor-size-row {
  display: flex;
  gap: 6px;
}

.imagegen-editor-size-row .imagegen-size-input {
  flex: 1;
  min-width: 0;
}
.imagegen-editor-size-row .custom-select {
  flex: 0 0 116px;
  min-width: 0;
}

.imagegen-editor-size-row .custom-select:last-child {
  flex-basis: 104px;
}

/* 宽高比下拉选项：小矩形图示 + 比例文本 */
.imagegen-ratio-option {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.imagegen-ratio-box {
  flex-shrink: 0;
  border: 1px solid var(--text-muted);
  border-radius: 2px;
  background: color-mix(in srgb, var(--text-muted) 14%, transparent);
}

.imagegen-ratio-box.portrait {
  border-color: var(--accent-purple-text, var(--accent-blue-text));
  background: color-mix(
    in srgb,
    var(--accent-purple-text, var(--accent-blue-text)) 14%,
    transparent
  );
}

.imagegen-ratio-option-label {
  font-family: var(--font-mono, monospace);
  font-size: 11px;
}

/* 模型档位能力提示 */
.imagegen-model-size-hint {
  display: block;
  color: var(--accent-blue-text, var(--text-link));
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1.45;
}

/* 模型下拉选项：ID + 别名 + 状态徽章 */
.api-model-combobox-option-main {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.api-model-combobox-option-icon {
  flex-shrink: 0;
}

/* 模型品牌图标：LobeHub 头像容器（.lobe-flex）只输出 CSS 变量，真正的 flex
   居中规则在其官方样式表中（项目未引入），缺失时内部 logo 会按内联元素坐在
   文字基线上导致中心偏移，这里统一补齐居中规则。 */
.model-brand-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  line-height: 0;
}

.model-brand-icon > svg {
  display: block;
  flex: none;
}

/* 未匹配到品牌 logo 时的默认占位 */
.model-brand-icon-fallback {
  background: var(--bg-tertiary);
  color: var(--text-muted);
  pointer-events: none;
  user-select: none;
}

.api-model-combobox-option-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.api-model-combobox-option-alias {
  flex-shrink: 0;
  color: var(--text-tertiary);
  font-size: 10.5px;
}

.api-model-combobox-badge {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: 999px;
  font-size: 9.5px;
  font-weight: 700;
  line-height: 1.4;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.api-model-combobox-badge.preview {
  color: var(--accent-amber-text);
  background: var(--accent-amber-bg);
}
.api-model-combobox-badge.deprecated {
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
}

/* ============================================================================
 * 图像管理系统（Image Library）面板
 * ========================================================================== */

.image-library-page {
  display: flex;
  flex-direction: column;
  gap: 14px;
  min-height: 0;
}

/* 本地图片拖入面板导入：整页虚线高亮 */
.image-library-page.drag-over {
  outline: 2px dashed var(--accent-color, #4f9cf9);
  outline-offset: -2px;
  border-radius: var(--radius-md);
}

/* ---- 存储路径栏：悬浮卡片 ---- */
.image-library-root-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  color: var(--text-tertiary);
  font-size: 11px;
}

.image-library-root-bar > svg {
  flex-shrink: 0;
  color: var(--accent-color);
}

.image-library-root-path {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-secondary);
}

.image-library-root-action {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 24px;
  padding: 0 9px;
  flex-shrink: 0;
  border: none;
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.image-library-root-action:hover {
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--accent-color);
}

.image-library-root-action:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ---- 目录迁移进度条 ---- */
.image-library-migrate-bar {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 8px 12px;
  border-radius: var(--radius-md);
  background: var(--bg-tertiary);
  border: 1px solid var(--border-subtle);
}

.image-library-migrate-info {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 11px;
}

.image-library-migrate-cancel {
  margin-left: auto;
  flex-shrink: 0;
  padding: 2px 8px;
  border: none;
  border-radius: 999px;
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  font-size: 10.5px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.image-library-migrate-cancel:hover {
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--accent-color);
}

.image-library-migrate-progress-bar {
  width: 100%;
  height: 5px;
  border-radius: 999px;
  background: var(--bg-active);
  overflow: hidden;
}

.image-library-migrate-progress-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--accent-color);
  transition: width 0.3s ease;
}

/* ---- 通用设置：存储与资源（占用概览 + 分类卡片） ---- */
.storage-overview {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 14px;
  padding: 14px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
}

.storage-overview-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.storage-overview-heading {
  display: flex;
  align-items: baseline;
  gap: 6px;
  min-width: 0;
}

.storage-overview-app {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.storage-overview-used {
  font-size: 12px;
  color: var(--text-secondary);
}

.storage-overview-bar {
  display: flex;
  height: 10px;
  border-radius: 999px;
  overflow: hidden;
  background: var(--bg-active);
}

.storage-overview-segment {
  height: 100%;
  min-width: 0;
  transition: width 0.3s ease;
}

.storage-overview-segment.empty {
  width: 100%;
  background: var(--bg-tertiary);
}

.storage-overview-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 24px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.storage-overview-legend-item {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.storage-overview-legend-name {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--text-secondary);
  white-space: nowrap;
}

.storage-overview-dot {
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  border-radius: 50%;
}

.storage-overview-legend-value {
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
}

.storage-overview-path {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-muted);
}

.storage-card {
  display: flex;
  flex-direction: column;
  margin-bottom: 10px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  background: var(--bg-secondary);
}

.storage-card-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
}

.storage-card-text {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.storage-card-title {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.storage-card-desc {
  font-size: 11px;
  line-height: 1.45;
  color: var(--text-muted);
}

.storage-card-detail {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 14px 14px;
}

/* 卡片内嵌的独立区块（如已移除项目残留数据） */
.storage-embedded-section {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

/* ---- 通用设置：存储位置 ---- */
.general-storage-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
}

.general-storage-info {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1;
}

.general-storage-icon {
  flex-shrink: 0;
  color: var(--accent-color);
}

.general-storage-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.general-storage-label {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.general-storage-path {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.general-storage-size {
  font-size: 10.5px;
  color: var(--accent-color);
  opacity: 0.85;
}

.general-storage-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.general-storage-action {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 24px;
  padding: 0 9px;
  flex-shrink: 0;
  border: none;
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 10.5px;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.general-storage-action:hover {
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--accent-color);
}

.general-storage-action:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ---- 通用设置：存储目录迁移进度模态框（不可关闭） ---- */
.storage-migration-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(3px);
  animation: confirm-overlay-in 0.15s ease;
}

.storage-migration-dialog {
  display: flex;
  width: 380px;
  max-width: 88vw;
  flex-direction: column;
  gap: 12px;
  padding: 18px 20px 16px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--bg-primary);
  box-shadow:
    var(--island-shadow),
    0 24px 60px rgba(0, 0, 0, 0.28);
  animation: confirm-dialog-in 0.18s ease;
}

.storage-migration-head {
  display: flex;
  align-items: center;
  gap: 12px;
}

.storage-migration-spinner {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent-color) 14%, transparent);
  color: var(--accent-color);
}

.storage-migration-heading {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.storage-migration-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.storage-migration-destination {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 10.5px;
  color: var(--text-tertiary);
}

.storage-migration-percent {
  flex-shrink: 0;
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--accent-color);
}

.storage-migration-progress {
  width: 100%;
  height: 6px;
  border-radius: 999px;
  background: var(--bg-active);
  overflow: hidden;
}

.storage-migration-progress-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--accent-color) 55%, transparent),
    var(--accent-color)
  );
  transition: width 0.25s ease;
}

/* 回滚阶段没有确定进度：滑块循环移动 */
.storage-migration-progress-fill.indeterminate {
  width: 35%;
  animation: storage-migration-slide 1.1s ease-in-out infinite;
}

@keyframes storage-migration-slide {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(320%);
  }
}

.storage-migration-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-height: 26px;
}

.storage-migration-count {
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  color: var(--text-secondary);
}

.storage-migration-cancel {
  height: 26px;
  margin-left: auto;
  padding: 0 12px;
  flex-shrink: 0;
  border: 1px solid var(--border-color);
  border-radius: 999px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 11.5px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease;
}

.storage-migration-cancel:hover {
  border-color: color-mix(in srgb, var(--accent-red-text) 45%, transparent);
  background: color-mix(in srgb, var(--accent-red-text) 10%, transparent);
  color: var(--accent-red-text);
}

.storage-migration-note {
  margin: 0;
  font-size: 10.5px;
  line-height: 1.5;
  color: var(--text-tertiary);
}

/* ---- 通用设置：数据清理（分类勾选 + 破坏性操作按钮） ---- */
.cleanup-category-check {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
  cursor: pointer;
}

/* 原生复选框视觉隐藏但保留键盘焦点（可访问性） */
.cleanup-category-check input[type="checkbox"] {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.cleanup-category-check:has(input:disabled) {
  cursor: default;
  opacity: 0.45;
}

.cleanup-category-box {
  position: relative;
  display: block;
  width: 14px;
  height: 14px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: var(--bg-tertiary);
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.cleanup-category-check:hover .cleanup-category-box {
  border-color: var(--text-tertiary);
}

.cleanup-category-check input:checked + .cleanup-category-box {
  background: var(--text-primary);
  border-color: var(--text-primary);
}

.cleanup-category-check input:checked + .cleanup-category-box::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 4px;
  width: 3px;
  height: 7px;
  border: solid var(--on-solid);
  border-width: 0 1.6px 1.6px 0;
  transform: rotate(45deg);
}

.cleanup-category-check input:focus-visible + .cleanup-category-box {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}

/* 半选（项目下仅勾选了部分分类） */
.cleanup-category-check.partial .cleanup-category-box {
  border-color: var(--text-primary);
}

.cleanup-category-check.partial .cleanup-category-box::after {
  content: "";
  position: absolute;
  top: 5.5px;
  left: 3px;
  width: 6px;
  height: 1.6px;
  border-radius: 1px;
  background: var(--text-primary);
}

/* ---- 通用设置：孤儿项目数据（按项目分组 + 分类芯片） ---- */
.orphan-project-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
}

.orphan-project-head {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orphan-project-path {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-mono);
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
}

.orphan-project-meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.orphan-project-categories {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding-left: 22px;
}

.orphan-category-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 24px;
  padding: 0 9px 0 7px;
  border-radius: 999px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-tertiary);
  font-size: 10.5px;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    border-color 0.15s ease,
    color 0.15s ease;
}

.orphan-category-chip:hover {
  border-color: var(--border-color);
}

.orphan-category-chip.active {
  border-color: var(--text-tertiary);
  color: var(--text-secondary);
}

.orphan-category-chip:has(input:disabled) {
  cursor: default;
}

.orphan-category-name {
  font-weight: 600;
}

.orphan-category-count {
  font-variant-numeric: tabular-nums;
  opacity: 0.85;
}

.general-storage-text .settings-item-description {
  line-height: 1.35;
}

.general-storage-action.danger {
  background: rgba(248, 81, 73, 0.12);
  color: #f85149;
}

.general-storage-action.danger:hover {
  background: rgba(248, 81, 73, 0.2);
  color: #f85149;
}

.general-storage-action.danger:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ---- 图库相册 Tab 栏：沿用设置页 Tab 样式（全部 / 未分类 / 相册 / 新建） ---- */
.image-library-albums {
  flex-wrap: nowrap;
  align-items: center;
  overflow-x: auto; /* 相册多时横向滚动 */
  scrollbar-width: thin;
  flex-shrink: 0;
}

.image-library-albums > * {
  flex: 0 0 auto;
}

.image-library-album-tab {
  max-width: 170px;
}

.image-library-album-tab.dragging {
  opacity: 0.45;
}

.image-library-album-tab.drag-over {
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--accent-color);
}

.image-library-album-tab-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-library-album-tab-count {
  font-size: 10px;
  font-weight: 400;
  opacity: 0.75;
}

.image-library-album-tab-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.image-library-album-tab-actions {
  display: none;
  position: absolute;
  right: 0;
  top: 100%;
  z-index: 10;
  flex-direction: column;
  gap: 2px;
  padding: 4px;
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  box-shadow: var(--island-shadow);
}

.image-library-album-tab-wrap:hover .image-library-album-tab-actions {
  display: flex;
}

.image-library-album-tab-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
}

.image-library-album-tab-actions button:hover {
  color: var(--accent-color);
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
}

.image-library-album-tab-actions button.danger:hover {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
}

/* ===== 相册卡片墙（overview 视图，按相册级别展示） ===== */
.image-library-albums-view {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding-bottom: 10px;
}

.image-library-albums-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.image-library-albums-title {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--text-secondary);
  letter-spacing: 0.02em;
}

.image-library-albums-count {
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 10px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-subtle);
  font-size: 10.5px;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}

.image-library-album-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(164px, 1fr));
  gap: 14px;
  align-items: stretch;
}

/* 相册卡片：封面（4:3）+ 名称/数量信息栏 */
.image-library-album-card-wrap {
  position: relative;
}

.image-library-album-card {
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  padding: 0;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  background: var(--bg-secondary);
  overflow: hidden;
  cursor: pointer;
  text-align: left;
  transition: border-color 0.18s ease;
}

.image-library-album-card:hover,
.image-library-album-card:focus-visible {
  border-color: color-mix(
    in srgb,
    var(--accent-color) 45%,
    var(--border-subtle)
  );
  outline: none;
}

.image-library-album-card-cover {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  aspect-ratio: 4 / 3;
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  overflow: hidden;
}

/* 封面底部渐变遮罩：与信息栏视觉衔接 */
.image-library-album-card-cover::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0, 0, 0, 0.28), transparent 45%);
  pointer-events: none;
}

.image-library-album-card-cover img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* 无封面时的占位图标：圆形底 */
.image-library-album-card:not(.add) .image-library-album-card-cover > svg {
  width: 44px;
  height: 44px;
  padding: 11px;
  box-sizing: border-box;
  border-radius: 50%;
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  color: var(--text-tertiary);
}

.image-library-album-card-info {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 11px;
}

.image-library-album-card-name {
  min-width: 0;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-library-album-card-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 22px;
  height: 19px;
  padding: 0 7px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-subtle);
  font-size: 10px;
  font-weight: 600;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

/* 新建相册卡片：虚线 + 主题微光 */
.image-library-album-card.add {
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 100%;
  border: 1.5px dashed var(--border-color);
  background: radial-gradient(
    120% 100% at 50% 0%,
    color-mix(in srgb, var(--accent-color) 8%, transparent),
    transparent 70%
  );
  color: var(--text-tertiary);
}

.image-library-album-card.add .image-library-album-card-cover {
  aspect-ratio: auto;
  width: auto;
  background: transparent;
}

.image-library-album-card.add .image-library-album-card-cover::after {
  display: none;
}

.image-library-album-card.add .image-library-album-card-cover > svg {
  width: 44px;
  height: 44px;
  padding: 11px;
  box-sizing: border-box;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px dashed var(--border-color);
  color: var(--text-tertiary);
  transition:
    color 0.15s ease,
    border-color 0.15s ease;
}

.image-library-album-card.add .image-library-album-card-info {
  padding: 0;
}

.image-library-album-card.add .image-library-album-card-name {
  color: var(--text-tertiary);
  font-weight: 500;
  transition: color 0.15s ease;
}

.image-library-album-card.add:hover,
.image-library-album-card.add:focus-visible {
  border-color: var(--accent-color);
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--accent-color);
  outline: none;
}

.image-library-album-card.add:hover .image-library-album-card-name,
.image-library-album-card.add:hover .image-library-album-card-cover > svg {
  color: var(--accent-color);
  border-color: var(--accent-color);
}

/* 空图库时的紧凑新建卡片（居中于空态区） */
.image-library-album-card.add.compact {
  min-height: 0;
  width: fit-content;
  padding: 9px 18px;
  flex-direction: row;
  margin-top: 4px;
}

.image-library-album-card.add.compact .image-library-album-card-cover > svg {
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  background: transparent;
  color: inherit;
}

/* 相册卡片悬停操作（重命名 / 删除） */
.image-library-album-card-actions {
  position: absolute;
  top: 8px;
  right: 8px;
  z-index: 2;
  display: flex;
  gap: 5px;
  opacity: 0;
  transition: opacity 0.18s ease;
}

.image-library-album-card-wrap:hover .image-library-album-card-actions,
.image-library-album-card-wrap:focus-within .image-library-album-card-actions {
  opacity: 1;
}

.image-library-album-card-actions button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.5);
  color: #fff;
  cursor: pointer;
  backdrop-filter: blur(3px);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
  transition: background 0.15s ease;
}

.image-library-album-card-actions button:hover {
  background: rgba(0, 0, 0, 0.78);
}

.image-library-album-card-actions button.danger:hover {
  background: var(--accent-red);
}

/* ===== 图片网格视图顶部：返回 + 标题 + 数量 ===== */
.image-library-gallery-header {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.image-library-back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
  height: 27px;
  padding: 0 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
}

.image-library-back-btn:hover {
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  border-color: color-mix(in srgb, var(--accent-color) 45%, transparent);
  color: var(--accent-color);
}

.image-library-gallery-title {
  min-width: 0;
  font-size: 13.5px;
  font-weight: 700;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-library-gallery-count {
  flex-shrink: 0;
  margin-left: auto;
  display: inline-flex;
  align-items: center;
  height: 20px;
  padding: 0 10px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-subtle);
  font-size: 10.5px;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}

/* 图片卡片上的「移入相册」下拉（CustomSelect，portal 渲染） */
.image-library-card-actions .custom-select {
  width: auto;
  max-width: 90px;
}

.image-library-card-actions .custom-select-trigger {
  height: 22px;
  padding: 0 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  color: var(--text-secondary);
  font-size: 10px;
}

.image-library-card-actions .custom-select-trigger:hover:not(:disabled) {
  border-color: var(--border-subtle);
}

.image-library-toolbar {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

/* ---- 筛选按钮组（分段控件） ---- */
.image-library-filter-group {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-subtle);
}

.image-library-filter-btn {
  height: 22px;
  padding: 0 12px;
  border: none;
  border-radius: 999px;
  background: transparent;
  color: var(--text-tertiary);
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.image-library-filter-btn:hover {
  color: var(--text-primary);
}

.image-library-filter-btn.active {
  background: var(--bg-primary);
  color: var(--text-primary);
  font-weight: 600;
}

/* ---- 下拉选择（CustomSelect） ---- */
.image-library-toolbar .custom-select,
.image-library-batch-bar .custom-select {
  width: auto;
  max-width: 180px;
}

.image-library-toolbar .custom-select-trigger,
.image-library-batch-bar .custom-select-trigger {
  height: 27px;
  padding: 0 8px;
  border-color: var(--border-subtle);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 11.5px;
}

.image-library-toolbar .custom-select-trigger:hover:not(:disabled),
.image-library-batch-bar .custom-select-trigger:hover:not(:disabled) {
  border-color: var(--border-color);
}

.image-library-count {
  margin-left: auto;
  font-size: 11px;
  color: var(--text-tertiary);
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

/* ---- 图片库搜索框 ---- */
.image-library-search {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  color: var(--text-tertiary);
  flex: 0 1 240px;
  min-width: 150px;
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease;
}

.image-library-search:focus-within {
  border-color: var(--accent-color);
}

.image-library-search input {
  flex: 1;
  min-width: 0;
  padding: 0;
  border: none !important;
  outline: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--text-primary);
  font-size: 11.5px;
}

.image-library-search input::placeholder {
  color: var(--text-tertiary);
}

.image-library-search button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.image-library-search button:hover {
  color: var(--text-primary);
  background: var(--bg-hover);
}

/* ---- 内容滚动区（细滚动条） ---- */
.image-library-content {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--scrollbar-thumb) transparent;
}

.image-library-content::-webkit-scrollbar {
  width: 8px;
}

.image-library-content::-webkit-scrollbar-thumb {
  background: var(--scrollbar-thumb);
  border-radius: 999px;
  border: 2px solid transparent;
  background-clip: padding-box;
}

.image-library-content::-webkit-scrollbar-thumb:hover {
  background: var(--scrollbar-thumb-hover);
  border: 2px solid transparent;
  background-clip: padding-box;
}

/* ---- 状态区（加载 / 错误 / 空） ---- */
.image-library-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  height: 100%;
  min-height: 240px;
  padding: 24px;
  color: var(--text-tertiary);
  font-size: 12px;
  text-align: center;
}

.image-library-state-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  border: 1px solid var(--border-subtle);
  color: var(--text-tertiary);
}

.image-library-state-hint {
  font-size: 11px;
  color: var(--text-tertiary);
  max-width: 300px;
  line-height: 1.5;
}

.image-library-state-clear {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 16px;
  border: none;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--accent-color);
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease;
}

.image-library-state-clear:hover {
  background: color-mix(in srgb, var(--accent-color) 20%, transparent);
}

/* ---- 图片网格 ---- */
.image-library-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 12px;
  align-items: start;
  padding-bottom: 8px;
}

/* 瀑布流模式（CSS columns，图片保持原始比例） */
.image-library-grid.masonry {
  display: block;
  columns: 6 140px;
  column-gap: 12px;
  padding-bottom: 8px;
}

.image-library-grid.masonry .image-library-card {
  break-inside: avoid;
  margin-bottom: 12px;
}

.image-library-grid.masonry .image-library-card img {
  aspect-ratio: auto;
  height: auto;
}

.image-library-card {
  position: relative;
  border: 1px solid transparent;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--bg-tertiary);
  cursor: zoom-in;
  outline: none;
  transition: border-color 0.18s ease;
}

.image-library-card:hover,
.image-library-card:focus-visible,
.image-library-card.menu-open {
  border-color: color-mix(
    in srgb,
    var(--accent-color) 45%,
    var(--border-subtle)
  );
}

.image-library-card img {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  background: var(--bg-tertiary);
}

.image-library-card-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: var(--bg-tertiary);
}

.image-library-card-meta {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 7px 9px 8px;
  border-top: 1px solid var(--border-subtle);
}

.image-library-card-model {
  font-size: 10.5px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.image-library-card-date {
  font-size: 10px;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}

.image-library-card-actions {
  position: absolute;
  top: 6px;
  right: 6px;
  display: flex;
  gap: 4px;
  opacity: 0;
  transition: opacity 0.15s ease;
}

.image-library-card:hover .image-library-card-actions,
.image-library-card:focus-visible .image-library-card-actions,
.image-library-card.menu-open .image-library-card-actions {
  opacity: 1;
}

.image-library-card-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.55);
  color: #fff;
  cursor: pointer;
  backdrop-filter: blur(2px);
  transition: background 0.15s ease;
}

.image-library-card-btn:hover {
  background: rgba(0, 0, 0, 0.75);
}

.image-library-card-btn.danger:hover {
  background: var(--accent-red);
}

/* ---- 批量操作工具栏（有选中时显示） ---- */
.image-library-batch-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  border: 1px solid color-mix(in srgb, var(--accent-color) 35%, transparent);
  border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--accent-color) 8%, var(--bg-secondary));
  animation: image-library-batch-in 0.2s ease;
}

@keyframes image-library-batch-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.image-library-batch-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
}

.image-library-batch-close:hover {
  color: var(--accent-red-text);
  background: var(--accent-red-bg);
}

.image-library-batch-count {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.image-library-batch-select-all {
  padding: 2px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--accent-color);
  font-size: 11.5px;
  cursor: pointer;
}

.image-library-batch-select-all:hover {
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
}

.image-library-batch-copy {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-size: 11.5px;
  cursor: pointer;
}

.image-library-batch-copy:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-color) 12%, transparent);
  color: var(--text-primary);
}

.image-library-batch-copy:disabled {
  opacity: 0.7;
  cursor: default;
}

/* 轻量操作反馈（设为封面/发送到聊天框等） */
.image-library-action-toast {
  position: fixed;
  bottom: 28px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 3000;
  padding: 7px 16px;
  border-radius: 999px;
  background: var(--surface-island-strong);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  font-size: 12px;
  box-shadow: var(--island-shadow);
  animation: image-library-batch-in 0.18s ease;
  pointer-events: none;
}

/* 灯箱快捷操作按钮（设为参考图 / 发送到聊天框） */
.image-library-lightbox-action {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: color-mix(in srgb, var(--bg-secondary) 70%, transparent);
  color: var(--text-secondary);
  font-size: 11.5px;
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.image-library-lightbox-action:hover {
  background: color-mix(in srgb, var(--accent-color) 16%, transparent);
  color: var(--text-primary);
}

.image-library-batch-delete {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 8px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--accent-red-text);
  font-size: 11.5px;
  cursor: pointer;
}

.image-library-batch-delete:hover {
  background: var(--accent-red-bg);
}

/* ---- 图片卡片多选勾选框（hover 显示，选中常显） ---- */
.image-library-card-check {
  position: absolute;
  top: 7px;
  left: 7px;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 17px;
  height: 17px;
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 5px;
  background: rgba(0, 0, 0, 0.45);
  color: #fff;
  cursor: pointer;
  opacity: 0;
  backdrop-filter: blur(2px);
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
}

.image-library-card:hover .image-library-card-check,
.image-library-card:focus-visible .image-library-card-check,
.image-library-card.menu-open .image-library-card-check,
.image-library-card-check.checked {
  opacity: 1;
}

.image-library-card-check:hover {
  background: rgba(0, 0, 0, 0.7);
}

.image-library-card-check.checked {
  background: var(--accent-color);
  border-color: var(--accent-color);
}

/* 选中卡片高亮 */
.image-library-card.selected {
  border-color: var(--accent-color);
  box-shadow: 0 0 0 2px var(--accent-color);
}

/* 相册 Tab 封面缩略图（圆形小图，与 13px 图标同高） */
.image-library-album-tab-cover {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px solid var(--border-subtle);
  object-fit: cover;
  flex-shrink: 0;
}

/* 灯箱详情面板（右下角） */
.image-library-lightbox-details {
  position: absolute;
  right: 16px;
  bottom: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(380px, 40vw);
  max-height: 45vh;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  background: color-mix(in srgb, var(--bg-primary) 88%, transparent);
  color: var(--text-primary);
  font-size: 11px;
  overflow-y: auto;
  backdrop-filter: blur(4px);
}

/* 详情面板头部（标题 + 收起/展开按钮） */
.image-library-lightbox-details-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex-shrink: 0;
}

.image-library-lightbox-details-title {
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--text-tertiary);
}

.image-library-lightbox-details-toggle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
}

.image-library-lightbox-details-toggle:hover {
  color: var(--accent-color);
  background: var(--bg-hover);
}

/* 收起状态：仅保留头部条，不遮挡图片 */
.image-library-lightbox-details.collapsed {
  width: auto;
  padding: 6px 8px;
}

.image-library-lightbox-details.collapsed
  .image-library-lightbox-details-title {
  display: none;
}

.image-library-lightbox-details.collapsed
  .image-library-lightbox-details-toggle {
  width: 24px;
  height: 24px;
}

.image-library-lightbox-detail-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.image-library-lightbox-detail-label {
  color: var(--text-tertiary);
  font-size: 10.5px;
  flex-shrink: 0;
}

.image-library-lightbox-copy {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-size: 10.5px;
  cursor: pointer;
}

.image-library-lightbox-copy:hover {
  color: var(--accent-color);
  border-color: var(--accent-color);
}

.image-library-lightbox-prompt {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.image-library-lightbox-prompt-text {
  margin: 0;
  line-height: 1.55;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 120px;
  overflow-y: auto;
}

.image-library-lightbox-detail-grid {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  align-items: baseline;
  color: var(--text-secondary);
  word-break: break-all;
}

.image-library-lightbox-file-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.image-library-lightbox-nav-hint {
  font-size: 10px;
  color: var(--text-tertiary);
  text-align: right;
}

.image-library-lightbox-meta {
  font-size: 11px;
  color: var(--text-secondary);
  margin-right: auto;
  max-width: 60vw;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 无限滚动加载指示 */
.image-library-load-more {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 14px 0 6px;
  font-size: 11px;
  color: var(--text-tertiary);
}

/* 灯箱左右切换按钮（hover 容器时浮现） */
.image-library-lightbox-nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border: none;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.45);
  color: #fff;
  cursor: pointer;
  opacity: 0;
  transition:
    opacity 0.15s ease,
    background 0.15s ease;
  z-index: 2;
}

.image-library-lightbox-nav.prev {
  left: 16px;
}

.image-library-lightbox-nav.next {
  right: 16px;
}

.tool-call-imagegen-lightbox:hover .image-library-lightbox-nav {
  opacity: 1;
}

.image-library-lightbox-nav:hover:not(:disabled) {
  background: rgba(0, 0, 0, 0.7);
}

.image-library-lightbox-nav:disabled {
  opacity: 0;
  cursor: default;
}

/* 灯箱图片切换动画（img key 变化重放） */
.tool-call-imagegen-lightbox img {
  animation: image-library-lightbox-switch-in 0.18s ease;
}

@keyframes image-library-lightbox-switch-in {
  from {
    opacity: 0.4;
    transform: scale(0.98);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* 删除会话确认：是否级联删除图库图片的选项 */
.chat-item-menu-delete-images {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 6px 10px;
  margin: 2px 8px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  font-size: 11px;
  line-height: 1.45;
  color: var(--text-secondary);
  cursor: pointer;
  user-select: none;
}

.chat-item-menu-delete-images input[type="checkbox"] {
  flex-shrink: 0;
  margin: 2px 0 0;
  accent-color: var(--accent-red);
  cursor: pointer;
}

/* 删除会话确认弹窗（ChatDeleteConfirmModal） */
.chat-delete-confirm-modal .chat-delete-confirm-option {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-tertiary);
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-secondary);
  cursor: pointer;
  user-select: none;
}

.chat-delete-confirm-modal .chat-delete-confirm-option input[type="checkbox"] {
  flex-shrink: 0;
  margin: 2px 0 0;
  accent-color: var(--accent-red);
  cursor: pointer;
}

.chat-delete-confirm-modal .chat-delete-confirm-note {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin: 8px 2px 0;
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-tertiary);
}

.chat-delete-confirm-modal .chat-delete-confirm-note svg {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--accent-red);
}

.chat-delete-confirm-modal .chat-delete-confirm-btn {
  background: var(--accent-red);
  color: var(--on-solid);
}

.chat-delete-confirm-modal .chat-delete-confirm-btn:hover {
  filter: brightness(1.1);
}

/* ===== Detached Chat Window（独立会话窗口） ===== */
.detached-chat-window {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  padding-top: env(titlebar-area-height, 0px);
  overflow: hidden;
  background: var(--app-bg);
}

.detached-chat-titlebar {
  position: relative;
  z-index: 50;
  display: flex;
  align-items: center;
  height: 44px;
  flex-shrink: 0;
  padding: 0 8px 0 14px;
  background: var(--app-bg);
  -webkit-app-region: drag;
  user-select: none;
}

/* macOS 无原生标题栏：为左上角 traffic lights 预留空间 */
.detached-chat-window.is-macos .detached-chat-titlebar {
  padding-left: 84px;
}

.detached-chat-titlebar-info {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex: 1;
}

.detached-chat-titlebar-icon {
  width: 18px;
  height: 18px;
  object-fit: contain;
  pointer-events: none;
  flex-shrink: 0;
}

.detached-chat-titlebar-title {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.detached-chat-titlebar-dir {
  flex-shrink: 0;
  max-width: 220px;
  padding: 2px 8px;
  border-radius: 999px;
  background: var(--bg-hover);
  color: var(--text-tertiary);
  font-size: 11px;
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.detached-chat-titlebar .window-controls-buttons {
  height: 100%;
}

/* 子代理切换 Tab 行：仅当会话存在子代理时渲染 */
.detached-chat-tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 0 10px 8px;
  flex-shrink: 0;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}

.detached-chat-tabs::-webkit-scrollbar {
  display: none;
}

.detached-chat-tab {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 999px;
  background: var(--surface-island-muted);
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.2;
  white-space: nowrap;
  flex-shrink: 0;
  transition:
    background 0.12s ease,
    color 0.12s ease,
    box-shadow 0.12s ease;
}

.detached-chat-tab:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.detached-chat-tab.active {
  background: var(--surface-island-strong);
  color: var(--text-primary);
  box-shadow: var(--island-shadow);
}

.detached-chat-tab-label {
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
}

.detached-chat-tab-status {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-tertiary);
  flex-shrink: 0;
}

.detached-chat-tab-status.status-running {
  background: var(--accent-blue);
  animation: detached-chat-tab-pulse 1.2s ease-in-out infinite;
}

.detached-chat-tab-status.status-completed {
  background: var(--accent-green);
}

.detached-chat-tab-status.status-failed {
  background: var(--accent-red);
}

@keyframes detached-chat-tab-pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.35;
  }
}

/* 主内容岛：与主窗口 .app-layout 的内边距保持一致 */
.detached-chat-window .detached-chat-main {
  margin: 0 10px 10px;
}

/* 运行中提示条：会话正运行于主窗口时展示，结束后自动消失 */
.detached-chat-running-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 10px 8px;
  padding: 6px 12px;
  border-radius: var(--radius-md);
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
  font-size: 12px;
  line-height: 1.4;
  flex-shrink: 0;
}

.detached-chat-running-banner .spin {
  flex-shrink: 0;
  color: var(--accent-blue);
}

/* ════════════════════════════════════════════════════════════════════
   设置 —— 桌面宠物独立页（Codex 宠物包兼容）
   ════════════════════════════════════════════════════════════════════ */

.pets-empty {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 6px;
  font-size: 12px;
  line-height: 1.5;
  color: var(--text-tertiary);
}

.pets-empty svg {
  flex-shrink: 0;
  margin-top: 1px;
}

.pets-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.pets-list-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 6px;
  border-radius: var(--radius-md);
  border: 1px solid transparent;
  background: var(--bg-secondary);
  transition:
    background 0.12s,
    border-color 0.12s;
}

.pets-list-item:hover {
  background: var(--bg-hover);
}

.pets-list-item.active {
  border-color: var(--accent);
  background: var(--bg-tertiary);
}

.pets-preview-canvas {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-sm);
  background:
    linear-gradient(
      45deg,
      rgba(128, 128, 128, 0.08) 25%,
      transparent 25%,
      transparent 75%,
      rgba(128, 128, 128, 0.08) 75%
    ),
    linear-gradient(
      45deg,
      rgba(128, 128, 128, 0.08) 25%,
      transparent 25%,
      transparent 75%,
      rgba(128, 128, 128, 0.08) 75%
    );
  background-size: 8px 8px;
  background-position:
    0 0,
    4px 4px;
}

.pets-list-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  flex: 1;
}

.pets-list-name {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.pets-list-source {
  font-size: 11px;
  color: var(--text-tertiary);
}

.pets-uninstall-btn {
  flex-shrink: 0;
  opacity: 0;
  transition: opacity 0.12s;
}

.pets-list-item:hover .pets-uninstall-btn,
.pets-list-item:focus-within .pets-uninstall-btn {
  opacity: 1;
}

/* 人设编辑按钮：常驻可见（低透明度），悬停或聚焦时提亮。 */
.pets-persona-btn {
  flex-shrink: 0;
  opacity: 0.45;
  transition: opacity 0.12s;
}

.pets-list-item:hover .pets-persona-btn,
.pets-list-item:focus-within .pets-persona-btn {
  opacity: 1;
}

/* --- 动画速度：滑块 + 实时预览区并排 --- */
.pets-speed-row {
  display: flex;
  align-items: flex-end;
  gap: 12px;
}

.pets-speed-slider {
  flex: 1;
  min-width: 0;
}

.pets-speed-preview {
  display: flex;
  flex-shrink: 0;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 4px 8px 2px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background:
    linear-gradient(
      45deg,
      rgba(128, 128, 128, 0.08) 25%,
      transparent 25%,
      transparent 75%,
      rgba(128, 128, 128, 0.08) 75%
    ),
    linear-gradient(
      45deg,
      rgba(128, 128, 128, 0.08) 25%,
      transparent 25%,
      transparent 75%,
      rgba(128, 128, 128, 0.08) 75%
    ),
    var(--bg-secondary);
  background-size: 8px 8px;
  background-position:
    0 0,
    4px 4px;
}

.pets-speed-preview-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--text-tertiary);
}

/* ==========================================================================
   会话拖拽 — 历史会话拖入输入框作为 conversation chip 引用
   ========================================================================== */

/* --- 会话项拖拽状态（拖拽源） --- */
.chat-item.dragging {
  opacity: 0.45;
}

/* ===== Update Dialog（更新弹窗） ===== */
.update-dialog {
  height: min(560px, calc(100vh - 48px));
}

.update-dialog .app-modal-footer {
  flex-wrap: wrap;
}

.update-dialog .app-modal-body {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: 12px;
  padding: 14px 16px 16px;
  overflow: hidden;
}

/* 下载进度（页脚内联，与主操作按钮同一行） */
.update-dialog-progress {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  gap: 8px;
}

.update-dialog-progress-spinner {
  flex-shrink: 0;
  color: var(--accent-color);
}

.update-dialog-progress-label {
  flex-shrink: 0;
  color: var(--text-secondary);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.update-dialog-progress-bar {
  min-width: 60px;
  flex: 1;
  height: 5px;
  border-radius: 999px;
  background: var(--bg-active);
  overflow: hidden;
}

.update-dialog-progress-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--accent-color);
  transition: width 0.3s ease;
}

/* 错误提示 */
.update-dialog-error {
  flex-shrink: 0;
  padding: 8px 10px;
  border: 1px solid var(--accent-red-bg);
  border-radius: var(--radius-sm);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
  font-size: 12px;
  word-break: break-word;
}

/* 发行说明 */
.update-dialog-notes-title {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.update-dialog-lang-switch {
  display: inline-flex;
  align-items: center;
  padding: 2px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.update-dialog-lang-switch button {
  padding: 2px 8px;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 500;
  letter-spacing: 0;
  cursor: pointer;
  transition:
    background 0.12s ease,
    color 0.12s ease;
}

.update-dialog-lang-switch button:hover {
  color: var(--text-secondary);
}

.update-dialog-lang-switch button.active {
  background: var(--bg-active);
  color: var(--text-primary);
  font-weight: 600;
}

.update-dialog-notes {
  min-height: 0;
  flex: 1;
  padding: 10px 12px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
  overflow-y: auto;
}

.update-dialog-notes-markdown {
  color: var(--text-primary);
  font-size: 12.5px;
  line-height: 1.65;
  word-break: break-word;
}

.update-dialog-notes-markdown h1,
.update-dialog-notes-markdown h2,
.update-dialog-notes-markdown h3,
.update-dialog-notes-markdown h4,
.update-dialog-notes-markdown h5,
.update-dialog-notes-markdown h6 {
  margin: 10px 0 6px;
  color: var(--text-primary);
  font-weight: 650;
  line-height: 1.35;
}

.update-dialog-notes-markdown h1 {
  font-size: 15px;
}

.update-dialog-notes-markdown h1:first-child,
.update-dialog-notes-markdown h2:first-child {
  margin-top: 0;
}

.update-dialog-notes-markdown h2 {
  font-size: 13.5px;
}

.update-dialog-notes-markdown h3,
.update-dialog-notes-markdown h4,
.update-dialog-notes-markdown h5,
.update-dialog-notes-markdown h6 {
  font-size: 12.5px;
}

.update-dialog-notes-markdown p {
  margin: 6px 0;
}

.update-dialog-notes-markdown ul,
.update-dialog-notes-markdown ol {
  margin: 6px 0;
  padding-left: 20px;
}

.update-dialog-notes-markdown li {
  margin: 2px 0;
}

.update-dialog-notes-markdown a {
  color: var(--accent-color);
  text-decoration: none;
}

.update-dialog-notes-markdown a:hover {
  text-decoration: underline;
}

.update-dialog-notes-markdown pre {
  margin: 8px 0;
  padding: 8px 10px;
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  overflow-x: auto;
  font-size: 11.5px;
  line-height: 1.5;
}

.update-dialog-notes-markdown code {
  font-family: var(--font-mono);
  font-size: 0.92em;
}

.update-dialog-notes-markdown :not(pre) > code {
  padding: 1px 4px;
  border-radius: 4px;
  background: var(--bg-active);
}

.update-dialog-notes-markdown blockquote {
  margin: 8px 0;
  padding: 2px 12px;
  border-left: 3px solid var(--border-color);
  color: var(--text-muted);
}

.update-dialog-notes-markdown hr {
  margin: 12px 0;
  border: none;
  border-top: 1px solid var(--border-light);
}

.update-dialog-notes-markdown table {
  margin: 8px 0;
  border-collapse: collapse;
  font-size: 12px;
}

.update-dialog-notes-markdown th,
.update-dialog-notes-markdown td {
  padding: 5px 10px;
  border: 1px solid var(--border-light);
}

.update-dialog-notes-markdown th {
  background: var(--bg-hover);
  font-weight: 600;
}

.update-dialog-no-notes {
  min-height: 0;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
  color: var(--text-muted);
  font-size: 12px;
  text-align: center;
}

.settings-changelog-card {
  flex: 1;
  min-height: 0;
  margin-bottom: 0;
}

.settings-changelog-card > .api-settings-form-body {
  flex: 1;
  min-height: 0;
}

.settings-changelog-notes {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
}

.settings-changelog-node {
  border: 1px solid var(--border-light);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
}

.settings-changelog-node-header {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 7px 10px;
  border: none;
  background: transparent;
  color: var(--text-primary);
  font-size: 12.5px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
  border-radius: 5px 5px 0 0;
}

.settings-changelog-node-header:hover {
  background: var(--bg-hover);
}

.settings-changelog-node.open .settings-changelog-node-header {
  border-bottom: 1px solid var(--border-light);
}

.settings-changelog-node-chevron {
  flex-shrink: 0;
  color: var(--text-muted);
  transition: transform 0.15s ease;
}

.settings-changelog-node.open .settings-changelog-node-chevron {
  transform: rotate(90deg);
}

.settings-changelog-node-body {
  padding: 2px 12px 10px;
}

.settings-changelog-loading {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 24px;
  color: var(--text-muted);
  font-size: 12px;
}

/* 主操作按钮（footer）：使用主题色 */
.update-dialog-primary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 30px;
  padding: 5px 16px;
  border: none;
  border-radius: var(--radius-sm);
  background: var(--accent-color);
  color: var(--on-solid);
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.1s ease;
}

.update-dialog-primary-btn:hover {
  background: color-mix(in srgb, var(--accent-color) 88%, var(--bg-primary));
  color: var(--on-solid);
}

.update-dialog-background-hint {
  flex-shrink: 0;
  color: var(--text-muted);
  font-size: 11.5px;
  white-space: nowrap;
}

/* ============================================================================
   团队协作（基于 Git 的共享数据平面）
   ========================================================================== */

/* ---- 侧边栏顶部入口 ---- */
.sidebar-team-entry {
  padding: 8px 8px 2px;
  flex-shrink: 0;
}
.sidebar-team-entry .team-entry {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 6px 8px;
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-size: 13px;
  text-align: left;
  transition: background 0.12s;
  width: 100%;
}
.sidebar-team-entry .team-entry:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* ---- 头像 ---- */
.team-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #fff;
  font-weight: 600;
  flex-shrink: 0;
  user-select: none;
  position: relative;
}
.team-avatar.is-online::after {
  content: "";
  position: absolute;
  right: -1px;
  bottom: -1px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--accent-green, #4caf50);
  border: 2px solid var(--surface-island, #fff);
}

.team-member-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--text-secondary);
  font-size: 12px;
  min-width: 0;
}
.team-me-tag {
  font-size: 10px;
  padding: 0 4px;
  border-radius: 4px;
  background: var(--accent-color);
  color: var(--on-solid);
  margin-left: 2px;
}

/* ---- 通用按钮 ---- */
.team-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border-radius: var(--radius-md);
  background: var(--bg-hover);
  color: var(--text-secondary);
  font-size: 12.5px;
  border: 1px solid var(--border-subtle);
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s,
    border-color 0.12s;
  white-space: nowrap;
}
.team-btn:hover:not(:disabled) {
  background: var(--bg-active);
  color: var(--text-primary);
}
.team-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}
.team-btn-primary {
  background: var(--accent-color);
  border-color: transparent;
  color: var(--on-solid);
}
.team-btn-primary:hover:not(:disabled) {
  background: var(--accent-color);
  color: var(--on-solid);
  opacity: 0.9;
}
.team-btn-accent {
  background: var(--accent-blue-bg, rgba(77, 144, 254, 0.12));
  border-color: transparent;
  color: var(--accent-blue, #4d90fe);
}
.team-btn-danger {
  color: var(--accent-red, #e5484d);
  border-color: transparent;
}
.team-btn-danger:hover:not(:disabled) {
  background: var(--accent-red-bg, rgba(229, 72, 77, 0.12));
  color: var(--accent-red, #e5484d);
}
.team-btn-success {
  color: var(--accent-green, #30a46c);
  border-color: transparent;
}
.team-btn-success:hover:not(:disabled) {
  background: var(--accent-green-bg, rgba(48, 164, 108, 0.12));
  color: var(--accent-green, #30a46c);
}

/* ---- 面板布局 ---- */
/* 背景透传 .main-content 的 --surface-island-strong（与聊天/设置等视图一致），
   避免深色模式下用 --bg-primary 导致与主内容区背景色差突兀 */
.team-panel {
  display: flex;
  flex-direction: column;
  height: 100%;
  overflow: hidden;
}

/* ---- 设置视图 ---- */
.team-setup {
  align-items: center;
  justify-content: center;
  padding: 24px;
}
.team-panel-loading {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.team-setup-card {
  max-width: 420px;
  width: 100%;
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-xl);
  padding: 28px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: var(--island-shadow);
}
.team-setup-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: var(--accent-color);
  color: var(--on-solid);
}
.team-setup-card h2 {
  font-size: 17px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0;
}
.team-setup-desc {
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-secondary);
  margin: 0;
}

/* ---- 主体 + 导航 ---- */
.team-panel-body {
  display: flex;
  flex: 1;
  min-height: 0;
}
.team-panel-nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 10px 8px;
  width: 128px;
  flex-shrink: 0;
  border-right: 1px solid var(--border-subtle);
}
.team-panel-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-size: 13px;
  text-align: left;
  transition:
    background 0.12s,
    color 0.12s;
  border: none;
  background: transparent;
  cursor: pointer;
}
.team-panel-tab:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}
.team-panel-tab.is-active {
  background: var(--bg-active);
  color: var(--text-primary);
  font-weight: 500;
}
.team-panel-tab svg {
  color: var(--text-tertiary);
}
.team-panel-tab.is-active svg {
  color: var(--accent-color);
}
.team-tab-badge {
  margin-left: auto;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 9px;
  background: var(--accent-color);
  color: var(--on-solid);
  font-size: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.team-panel-content {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}
.team-tasks {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---- 页签工具栏 ---- */
.team-tab-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px 8px;
  flex-shrink: 0;
}
.team-tab-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.team-task-group-count {
  font-size: 11px;
  color: var(--text-tertiary);
  background: var(--bg-hover);
  padding: 1px 7px;
  border-radius: 9px;
}
.team-members-online {
  font-size: 11px;
  color: var(--accent-green, #30a46c);
}

/* ---- 空状态 ---- */
.team-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  color: var(--text-tertiary);
  font-size: 13px;
  padding: 24px;
  text-align: center;
  max-width: 360px;
  margin: 0 auto;
  line-height: 1.6;
}
.team-empty-icon {
  color: var(--text-tertiary);
  opacity: 0.7;
}

/* ---- 动态（聊天式时间线） ---- */
.team-feed {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
}
.team-feed-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 14px 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.team-feed-empty {
  margin: auto;
  color: var(--text-tertiary);
  font-size: 13px;
  text-align: center;
  max-width: 380px;
  line-height: 1.6;
}
.team-feed-item {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
/* 系统事件：居中独占一行 */
.team-feed-item.is-event {
  align-items: center;
  justify-content: center;
  margin: 2px 0;
}
.team-feed-message {
  min-width: 0;
  max-width: 78%;
}
.team-feed-message-meta {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin-bottom: 3px;
}
.team-feed-author {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
}
.team-feed-time {
  font-size: 11px;
  color: var(--text-tertiary);
  white-space: nowrap;
}
.team-feed-delete {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  opacity: 0.55;
  transition:
    color 0.12s,
    opacity 0.12s,
    background 0.12s;
}
.team-feed-delete:hover {
  opacity: 1;
  color: var(--accent-red, #e5484d);
  background: var(--bg-hover);
}
/* 删除中：按钮位置转为 loading */
.team-feed-delete.is-busy {
  opacity: 0.8;
  cursor: default;
}
.team-feed-delete.is-busy svg {
  animation: spin 0.9s linear infinite;
}
.team-feed-bubble-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.team-feed-item.is-mine .team-feed-bubble-row {
  justify-content: flex-end;
}
.team-feed-message-bubble {
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  border-top-left-radius: 4px;
  padding: 9px 12px;
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-primary);
  white-space: pre-wrap;
  word-break: break-word;
  min-width: 0;
}
/* 发送态：转圈表示推送中，红色感叹号可点击重发 */
.team-feed-send-state {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-tertiary);
}
.team-feed-send-state.is-sending svg {
  animation: spin 0.9s linear infinite;
}
.team-feed-send-state.is-failed {
  color: var(--accent-red, #e5484d);
  cursor: pointer;
}
.team-feed-send-state.is-failed:hover {
  opacity: 0.8;
}
.team-feed-item.is-mine .team-feed-message {
  order: -1;
}
.team-feed-item.is-mine {
  flex-direction: row-reverse;
}
.team-feed-item.is-mine .team-feed-message-meta {
  flex-direction: row-reverse;
}
.team-feed-item.is-mine .team-feed-message-bubble {
  background: var(--accent-color);
  border-color: transparent;
  color: var(--on-solid);
  border-top-left-radius: var(--radius-lg);
  border-top-right-radius: 4px;
}
.team-feed-event {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-tertiary);
  font-size: 12.5px;
  background: var(--bg-hover);
  border-radius: var(--radius-md);
  padding: 4px 10px;
  line-height: 1.5;
  max-width: 100%;
}
.team-feed-event-text {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.team-feed-event-icon {
  display: inline-flex;
  color: var(--text-secondary);
}
.team-feed-input {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 10px 16px;
  border-top: 1px solid var(--border-subtle);
  flex-shrink: 0;
}
.team-feed-input textarea {
  flex: 1;
  resize: none;
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 13.5px;
  line-height: 20px;
  padding: 9px 12px;
  outline: none;
  max-height: 120px;
  min-height: 36px;
}
.team-feed-input textarea:focus {
  border-color: var(--accent-color);
}
.team-feed-send {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  background: var(--accent-color);
  color: var(--on-solid);
  border: none;
  cursor: pointer;
  flex-shrink: 0;
}
.team-feed-send:hover:not(:disabled) {
  opacity: 0.9;
}
.team-feed-send:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ---- 消息附件 ---- */
.team-feed-composer {
  flex-shrink: 0;
}
.team-feed-notice {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0 16px 6px;
  padding: 5px 10px;
  font-size: 12px;
  color: var(--accent-red, #e5484d);
  background: var(--bg-hover);
  border-radius: var(--radius-md);
}
.team-feed-notice span {
  flex: 1;
}
.team-feed-notice button {
  display: inline-flex;
  border: none;
  background: transparent;
  color: inherit;
  cursor: pointer;
  opacity: 0.7;
  padding: 2px;
}
.team-feed-notice button:hover {
  opacity: 1;
}
.team-feed-pending {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 0 16px 8px;
}
.team-feed-pending-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 220px;
  padding: 3px 6px 3px 4px;
  font-size: 12px;
  color: var(--text-secondary);
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
}
.team-feed-pending-item img {
  width: 30px;
  height: 30px;
  object-fit: cover;
  border-radius: var(--radius-sm);
}
.team-feed-pending-icon {
  display: inline-flex;
  color: var(--text-tertiary);
}
.team-feed-pending-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.team-feed-pending-item button {
  display: inline-flex;
  border: none;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  padding: 2px;
}
.team-feed-pending-item button:hover {
  color: var(--accent-red, #e5484d);
}
.team-feed-uploading {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-tertiary);
}
.team-feed-uploading svg {
  animation: spin 0.9s linear infinite;
}
.team-feed-tools {
  display: flex;
  gap: 2px;
  flex-shrink: 0;
}
.team-feed-tool-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 36px;
  border: none;
  border-radius: var(--radius-md);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    color 0.12s,
    background 0.12s;
}
.team-feed-tool-btn:hover:not(:disabled) {
  color: var(--text-primary);
  background: var(--bg-hover);
}
.team-feed-tool-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
/* 气泡内附件区 */
.team-feed-message-bubble .team-feed-message-text + .team-feed-attachments,
.team-feed-message-bubble .team-feed-attachments:not(:first-child) {
  margin-top: 6px;
}
.team-feed-attachments {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}
.team-feed-attach-images {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.team-feed-attach-thumb {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 116px;
  height: 86px;
  padding: 0;
  border: none;
  border-radius: var(--radius-md);
  background: var(--bg-hover);
  color: var(--text-tertiary);
  cursor: pointer;
  overflow: hidden;
}
.team-feed-attach-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.15s ease;
}
.team-feed-attach-thumb:hover img {
  transform: scale(1.04);
}
.team-feed-attach-thumb.is-loading svg {
  animation: spin 0.9s linear infinite;
}
.team-feed-attach-file {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  max-width: 260px;
  padding: 6px 10px;
  font-size: 12.5px;
  color: var(--text-primary);
  background: var(--bg-hover);
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background 0.12s;
}
.team-feed-attach-file:hover {
  background: var(--border-subtle);
}
.team-feed-attach-file-name {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.team-feed-attach-file-size {
  flex-shrink: 0;
  font-size: 11px;
  color: var(--text-tertiary);
}
/* 图片预览灯箱 */
.team-feed-lightbox {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.72);
  cursor: zoom-out;
}
.team-feed-lightbox img {
  max-width: 90vw;
  max-height: 90vh;
  border-radius: var(--radius-lg);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.4);
}

/* ---- 任务 / 评审列表 ---- */
.team-task-groups {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 4px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.team-task-group-title {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 4px 2px 6px;
}
.team-status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.team-status-dot.is-todo {
  background: var(--text-tertiary);
}
.team-status-dot.is-in_progress {
  background: var(--accent-blue, #4d90fe);
}
.team-status-dot.is-review {
  background: var(--accent-amber, #f5a623);
}
.team-status-dot.is-done {
  background: var(--accent-green, #30a46c);
}
.team-status-dot.is-muted {
  background: var(--text-tertiary);
  opacity: 0.5;
}
.team-task-group-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.team-task-card,
.team-review-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 10px 12px;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.12s;
}
.team-task-card:hover,
.team-review-card:hover {
  border-color: var(--border-color);
}
.team-task-card-top {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.team-task-card-title {
  flex: 1;
  font-size: 13.5px;
  font-weight: 500;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.team-task-card-desc {
  font-size: 12.5px;
  color: var(--text-secondary);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.team-task-card-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.team-priority {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}
.team-priority.is-low {
  color: var(--text-tertiary);
}
.team-priority.is-medium {
  color: var(--accent-amber, #f5a623);
}
.team-priority.is-high {
  color: var(--accent-red, #e5484d);
}
.team-status {
  font-size: 11px;
  padding: 1px 8px;
  border-radius: 10px;
  flex-shrink: 0;
}
.team-status.is-todo {
  background: var(--bg-hover);
  color: var(--text-tertiary);
}
.team-status.is-in_progress {
  background: var(--accent-blue-bg, rgba(77, 144, 254, 0.14));
  color: var(--accent-blue, #4d90fe);
}
.team-status.is-review {
  background: var(--accent-amber-bg, rgba(245, 166, 35, 0.14));
  color: var(--accent-amber, #f5a623);
}
.team-status.is-done {
  background: var(--accent-green-bg, rgba(48, 164, 108, 0.14));
  color: var(--accent-green, #30a46c);
}
.team-status.is-pending {
  background: var(--accent-amber-bg, rgba(245, 166, 35, 0.14));
  color: var(--accent-amber, #f5a623);
}
.team-status.is-approved {
  background: var(--accent-green-bg, rgba(48, 164, 108, 0.14));
  color: var(--accent-green, #30a46c);
}
.team-status.is-rejected {
  background: var(--accent-red-bg, rgba(229, 72, 77, 0.14));
  color: var(--accent-red, #e5484d);
}
.team-status.is-merged {
  background: var(--accent-blue-bg, rgba(77, 144, 254, 0.14));
  color: var(--accent-blue, #4d90fe);
}
.team-label {
  font-size: 11px;
  padding: 1px 8px;
  border-radius: 10px;
  background: var(--bg-hover);
  color: var(--text-tertiary);
}
.team-task-labels {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

/* ---- 评审 ---- */
.team-review-icon {
  display: inline-flex;
  color: var(--accent-color);
  flex-shrink: 0;
}
.team-review-meta {
  display: flex;
  align-items: center;
  gap: 6px;
}
.team-branch-tag {
  font-family: var(--font-mono);
  font-size: 11.5px;
  background: var(--bg-hover);
  color: var(--accent-blue, #4d90fe);
  padding: 2px 8px;
  border-radius: 6px;
}
.team-review-arrow {
  color: var(--text-tertiary);
  font-size: 11px;
}
.team-comment-count {
  font-size: 11px;
  color: var(--text-tertiary);
}

/* ---- 表单 ---- */
.team-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.team-form-label {
  display: flex;
  flex-direction: column;
  gap: 5px;
  font-size: 12.5px;
  color: var(--text-secondary);
  flex: 1;
  min-width: 0;
}
.team-form-input {
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 13px;
  padding: 7px 10px;
  outline: none;
  width: 100%;
}
.team-form-input:focus {
  border-color: var(--accent-color);
}
.team-color-picker {
  display: flex;
  align-items: center;
  gap: 8px;
}
.team-color-swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid transparent;
  box-shadow: inset 0 0 0 1px rgb(0 0 0 / 10%);
  cursor: pointer;
  transition:
    transform 0.12s,
    border-color 0.12s;
}
.team-color-swatch:hover {
  transform: scale(1.08);
}
.team-color-swatch.is-active {
  border-color: var(--text-primary);
}
.team-color-default {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: 1px dashed var(--border-color);
  border-radius: 50%;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    border-color 0.12s,
    color 0.12s;
}
.team-color-default:hover {
  color: var(--text-primary);
}
.team-color-default.is-active {
  border-style: solid;
  border-color: var(--text-primary);
  color: var(--text-primary);
}
.team-form .custom-select-trigger {
  padding: 7px 10px;
  border-color: var(--border-subtle);
  background: var(--surface-island);
  font-size: 13px;
}
.team-form-textarea {
  font-family: inherit;
  resize: vertical;
  line-height: 1.5;
}
.team-form-row {
  display: flex;
  gap: 12px;
}
.team-form-error {
  font-size: 12px;
  color: var(--accent-red, #e5484d);
}
.team-form-hint {
  font-size: 12.5px;
  color: var(--text-tertiary);
  line-height: 1.6;
  margin: 0;
}

/* ---- 详情 ---- */
.team-detail {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.team-detail-meta {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}
.team-detail-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--text-tertiary);
}
.team-status-stepper {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.team-status-step {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  padding: 4px 10px;
  border-radius: 14px;
  border: 1px solid var(--border-subtle);
  background: var(--bg-hover);
  color: var(--text-tertiary);
  cursor: pointer;
  transition: all 0.12s;
}
.team-status-step:hover:not(:disabled) {
  color: var(--text-primary);
}
.team-status-step.is-active {
  border-color: var(--accent-color);
  color: var(--accent-color);
  background: var(--bg-active);
}
.team-status-step.is-done {
  color: var(--accent-green, #30a46c);
}
.team-detail-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.team-detail-section-title {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.team-detail-text {
  font-size: 13px;
  line-height: 1.6;
  color: var(--text-primary);
  white-space: pre-wrap;
  word-break: break-word;
}
.team-detail-files {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.team-detail-files code {
  font-family: var(--font-mono);
  font-size: 12px;
  background: var(--bg-hover);
  padding: 2px 8px;
  border-radius: 6px;
  color: var(--text-secondary);
}
.team-detail-history {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 220px;
  overflow-y: auto;
}
.team-detail-history-item {
  display: flex;
  align-items: baseline;
  gap: 8px;
  font-size: 12.5px;
}
.team-detail-history-author {
  font-weight: 600;
  color: var(--text-secondary);
}
.team-detail-history-action {
  color: var(--accent-blue, #4d90fe);
}
.team-detail-history-detail {
  color: var(--text-secondary);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.team-detail-history-time {
  font-size: 11px;
  color: var(--text-tertiary);
  margin-left: auto;
  white-space: nowrap;
}
.team-detail-hint {
  font-size: 12px;
  color: var(--text-tertiary);
  background: var(--bg-hover);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  line-height: 1.5;
}
.team-detail-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.team-detail-actions .team-form-error {
  margin-right: auto;
}

/* ---- 评论 ---- */
.team-comments {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.team-comments-empty {
  font-size: 12.5px;
  color: var(--text-tertiary);
}
.team-comment {
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.team-comment-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.team-comment-delete {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    color 0.12s,
    background 0.12s;
}
.team-comment-delete:hover {
  color: var(--accent-red, #e5484d);
  background: var(--bg-hover);
}
.team-comment-delete:disabled {
  opacity: 0.5;
  cursor: default;
}
.team-comment-body {
  font-size: 13px;
  line-height: 1.5;
  color: var(--text-primary);
  white-space: pre-wrap;
  word-break: break-word;
}
.team-comment-input {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 4px;
}
.team-comment-input textarea {
  resize: vertical;
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 13px;
  padding: 8px 10px;
  outline: none;
}
.team-comment-input textarea:focus {
  border-color: var(--accent-color);
}

/* ---- 知识 ---- */
.team-note-grid {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 4px 16px 16px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 10px;
  align-content: start;
}
.team-note-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: 12px;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.12s;
}
.team-note-card:hover {
  border-color: var(--border-color);
}
.team-note-card-title {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
}
.team-note-card-snippet {
  font-size: 12.5px;
  color: var(--text-secondary);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.team-note-card-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.team-detail-note-content {
  font-size: 13.5px;
  line-height: 1.7;
  color: var(--text-primary);
  white-space: pre-wrap;
  word-break: break-word;
}

/* ---- 笔记 Markdown 编辑器 ---- */
.team-note-modal {
  width: min(1040px, calc(100vw - 48px));
  height: min(88vh, calc(100vh - 48px));
}
.team-note-modal .app-modal-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}
.team-note-modal .app-modal-body .team-form {
  display: flex;
  flex-direction: column;
  min-height: 100%;
}
.team-note-modal .team-form-label {
  flex: 0 0 auto;
}
/* 编辑区独占剩余高度：整条链用 flex 传导（flex 拉伸出的高度不能用 % 参照）。 */
.team-note-modal .team-form-label-grow {
  flex: 1 1 auto;
  min-height: 0;
}
.team-note-modal .team-form-label-grow .team-md-editor {
  flex: 1 1 auto;
  min-height: 0;
}
.team-md-editor {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-height: 0;
}
.team-md-toolbar {
  display: flex;
  align-items: center;
  gap: 2px;
  flex-wrap: wrap;
  padding: 4px 6px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--surface-island);
}
.team-md-tool-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-secondary);
  cursor: pointer;
}
.team-md-tool-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}
.team-md-toolbar-hint {
  margin-left: auto;
  font-size: 11px;
  color: var(--text-tertiary);
}
.team-md-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: minmax(0, 1fr);
  gap: 8px;
  flex: 1 1 auto;
  min-height: 220px;
}
.team-md-textarea {
  width: 100%;
  height: 100%;
  min-height: 0;
  resize: none;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--surface-island);
  color: var(--text-primary);
  font-family: inherit;
  font-size: 13px;
  line-height: 1.65;
  padding: 10px 12px;
  outline: none;
}
.team-md-textarea:focus {
  border-color: var(--accent-color);
}
.team-md-preview {
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--surface-island);
  padding: 10px 12px;
  overflow-y: auto;
  height: 100%;
  min-height: 0;
}
.team-md-preview .context-compaction-markdown img {
  max-width: 100%;
}
.team-md-preview-empty {
  color: var(--text-tertiary);
  font-size: 12.5px;
}
.team-note-markdown {
  min-height: 60px;
}
.team-note-markdown img {
  max-width: 100%;
  border-radius: var(--radius-md);
}

/* ---- 成员 ---- */
.team-member-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 4px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.team-member-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: var(--surface-island);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
}
.team-member-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.team-member-name {
  font-size: 13.5px;
  font-weight: 600;
  color: var(--text-primary);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.team-member-email {
  font-size: 12px;
  color: var(--text-tertiary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.team-member-side {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  flex-shrink: 0;
}
.team-member-role {
  font-size: 11px;
  color: var(--text-tertiary);
  background: var(--bg-hover);
  padding: 1px 8px;
  border-radius: 10px;
}
.team-online-tag {
  font-size: 10px;
  color: var(--accent-green, #30a46c);
  border: 1px solid var(--accent-green, #30a46c);
  padding: 0 5px;
  border-radius: 8px;
}

/* ===== Skill 编辑弹窗：左侧文件结构 + 右侧 FileViewerContent 编辑器 ===== */
.skill-edit-modal {
  width: min(1200px, calc(100vw - 48px));
  height: min(88vh, calc(100vh - 48px));
}

.skill-edit-modal .app-modal-body {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  padding: 0;
  overflow: hidden;
}

.skill-edit-modal-layout {
  display: flex;
  min-height: 0;
  flex: 1;
}

.skill-edit-tree-pane {
  display: flex;
  flex-direction: column;
  width: 260px;
  flex-shrink: 0;
  border-right: 1px solid var(--border-color);
  background: var(--bg-secondary);
}

.skill-edit-tree-pane-header {
  padding: 8px 12px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--text-tertiary);
  border-bottom: 1px solid var(--border-color);
}

.skill-edit-tree {
  flex: 1;
  overflow-y: auto;
  padding: 6px;
}

.skill-edit-tree-row {
  display: flex;
  align-items: center;
  gap: 5px;
  width: 100%;
  box-sizing: border-box;
  padding: 4px 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-size: 12.5px;
  cursor: pointer;
  text-align: left;
}

.skill-edit-tree-row:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.skill-edit-tree-row.active {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.skill-edit-tree-row.loading {
  cursor: default;
  color: var(--text-tertiary);
}

.skill-edit-tree-chevron {
  flex-shrink: 0;
  color: var(--text-tertiary);
  transition: transform 0.15s;
}

.skill-edit-tree-chevron.expanded {
  transform: rotate(90deg);
}

.skill-edit-tree-folder,
.skill-edit-tree-file {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.skill-edit-tree-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.skill-edit-tree-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  font-size: 12px;
  color: var(--text-tertiary);
}

.skill-edit-viewer-pane {
  display: flex;
  min-width: 0;
  flex: 1;
}

.skill-edit-viewer-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex: 1;
  color: var(--text-tertiary);
  font-size: 13px;
}

/* ============================================================
 * 用户脚本 Section（嵌入 BrowserSettingsPanel Tab）
 * ============================================================ */
/* 搜索行：输入框与搜索按钮同行排列，按钮独立于输入框容器外，垂直居中对齐 */
.userscripts-search-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.userscripts-search-row .browser-settings-search-row {
  flex: 1;
  min-width: 0;
  margin-bottom: 0;
}

.userscripts-search-submit {
  flex-shrink: 0;
  margin-top: 0;
  white-space: nowrap;
}

.userscripts-search-submit:disabled,
.userscripts-search-submit:disabled:hover {
  cursor: default;
  opacity: 0.55;
}

/* 提示行与下方内容保持间距，避免死贴 */
.userscripts-section .browser-settings-hint-row {
  margin-bottom: 6px;
}

/* 用户脚本区独占剩余高度：section 弹性伸展，表格内部滚动，不限制高度 */
.userscripts-section {
  flex: 1;
  min-height: 0;
}

.userscripts-section .browser-settings-table-wrap {
  flex: 1;
  min-height: 0;
  max-height: none;
}

.userscripts-section-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.userscripts-section-actions .browser-settings-scan-action {
  margin-top: 0;
}

.userscripts-tab-count {
  padding: 0 6px;
  border-radius: 10px;
  background: var(--bg-hover);
  font-size: 11px;
  color: var(--text-tertiary);
}

/* 表格单元格辅助 */
.userscripts-cell-desc {
  display: block;
  font-size: 11px;
  color: var(--text-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 360px;
}

.userscripts-cell-version {
  display: inline-block;
  margin-left: 6px;
  font-size: 10px;
  color: var(--text-tertiary);
  font-family: var(--font-mono, monospace);
}

.userscripts-cell-matches {
  font-size: 11px;
  color: var(--text-tertiary);
  font-family: var(--font-mono, monospace);
}

.userscripts-cell-runat {
  display: inline-block;
  padding: 1px 6px;
  border-radius: 8px;
  background: var(--bg-hover);
  font-size: 10px;
  color: var(--text-tertiary);
}

.userscripts-cell-rating {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: 6px;
  font-size: 11px;
  color: var(--accent-amber-text, #b45309);
}

.userscripts-cell-installs {
  font-size: 11px;
  color: var(--text-tertiary);
  white-space: nowrap;
}

/* 搜索链接 */
.userscripts-search-link {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  margin-left: 8px;
  font-size: 11px;
  color: var(--accent-blue);
  text-decoration: none;
}

.userscripts-search-link:hover {
  text-decoration: underline;
}

/* 安装按钮（表格内紧凑） */
.userscripts-install-btn {
  white-space: nowrap;
}

/* 搜索结果分页：上一页 / 页码 / 下一页（API 无总数，做相对分页） */
.userscripts-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-top: 10px;
  flex-shrink: 0;
}

.userscripts-page-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  padding: 0;
  border: 1px solid var(--border-light);
  border-radius: 6px;
  background: var(--bg-secondary);
  color: var(--text-secondary);
  cursor: pointer;
}

.userscripts-page-btn:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.userscripts-page-btn:disabled {
  cursor: default;
  opacity: 0.45;
}

.userscripts-page-indicator {
  min-width: 60px;
  text-align: center;
  font-size: 12px;
  color: var(--text-tertiary);
  font-variant-numeric: tabular-nums;
}

.script-editor-overlay {
  position: absolute;
  inset: 0;
  z-index: 70;
  display: flex;
  padding: 16px 14px;
  background: color-mix(in srgb, var(--bg-primary) 62%, transparent);
  backdrop-filter: blur(3px);
  animation: script-editor-overlay-in 0.15s ease-out;
}

@keyframes script-editor-overlay-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

.script-editor-page {
  display: flex;
  flex: 1;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  overflow: hidden;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-xl);
  background: var(--bg-primary);
  box-shadow: var(--shadow-xl);
}

.script-editor-header {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 16px;
  border-bottom: 1px solid var(--border-light);
  background: var(--bg-secondary);
}

.script-editor-header strong {
  min-width: 0;
  overflow: hidden;
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 650;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.script-editor-body {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  overflow: hidden;
}

/* ===== Browser downloads panel & JS dialog (theme tokens) ===== */

.browser-toolbar {
  position: relative;
}

.browser-downloads-btn {
  position: relative;
}

.browser-downloads-badge {
  position: absolute;
  top: 1px;
  right: 1px;
  min-width: 13px;
  height: 13px;
  padding: 0 3px;
  border-radius: 7px;
  background: var(--accent-blue);
  color: var(--on-solid);
  font-size: 9px;
  line-height: 13px;
  font-weight: 600;
  text-align: center;
  pointer-events: none;
}

.browser-downloads-panel {
  position: absolute;
  top: calc(100% + 6px);
  right: 4px;
  z-index: 60;
  width: 320px;
  max-height: 380px;
  display: flex;
  flex-direction: column;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-lg);
  box-shadow: var(--island-shadow, 0 4px 16px rgba(0, 0, 0, 0.12));
  overflow: hidden;
}

.browser-downloads-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-light);
}

.browser-downloads-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.1s ease,
    color 0.1s ease;
}

.browser-downloads-close:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.browser-downloads-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 28px 0;
  color: var(--text-muted);
  font-size: 12px;
}

.browser-downloads-list {
  overflow-y: auto;
  padding: 4px;
}

.browser-download-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px;
  border-radius: var(--radius-md);
}

.browser-download-item:hover {
  background: var(--bg-hover);
}

.browser-download-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  flex-shrink: 0;
  border-radius: var(--radius-md);
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.browser-download-info {
  flex: 1;
  min-width: 0;
}

.browser-download-name {
  font-size: 12px;
  font-weight: 500;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.browser-download-progress {
  height: 3px;
  margin-top: 5px;
  border-radius: 2px;
  background: var(--bg-active);
  overflow: hidden;
}

.browser-download-progress-bar {
  height: 100%;
  border-radius: 2px;
  background: var(--accent-blue);
  transition: width 0.25s ease;
}

.browser-download-meta {
  margin-top: 3px;
  font-size: 11px;
  color: var(--text-tertiary);
}

.browser-download-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.browser-download-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 22px;
  padding: 0 7px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--accent-blue-text);
  font-size: 11px;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.1s ease;
}

.browser-download-action:hover {
  background: var(--accent-blue-bg);
}

/* ============================================================ */
/* 项目记忆页面（ProjectMemoryPanel）：复用备忘录页面的尺寸与双栏   */
/* 骨架（.memo-panel-layout / .memo-sidebar 等），                  */
/* 此处只保留 memory 特有的覆盖与右栏编辑器样式。                  */
/* ============================================================ */

.memory-sidebar {
  width: var(--memo-split-width, 360px);
}

.memory-sidebar-subrow {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 10px 8px;
  flex-shrink: 0;
}

.memory-sidebar-subrow .custom-select {
  width: 132px;
  flex: 0 0 auto;
}

.memory-sidebar-subrow .custom-select-trigger {
  padding: 4px 8px;
}

.memory-sidebar-stats {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 11px;
  color: var(--text-muted);
}

/* 关键词检索行（搜索框 + 清除）与命中高亮 / 命中上下文预览 */
.memory-search-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 0 10px 8px;
  padding: 0 8px;
  height: 28px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  flex-shrink: 0;
}

.memory-search-row:focus-within {
  border-color: var(--accent-color);
}

.memory-search-icon {
  flex-shrink: 0;
  color: var(--text-tertiary);
}

.memory-search-input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--text-primary);
  font-size: 12.5px;
  font-family: inherit;
  outline: none !important;
  appearance: none;
}

.memory-search-input::placeholder {
  color: var(--text-muted);
}

.memory-search-clear {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  padding: 0;
  border: none;
  border-radius: 4px;
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  flex-shrink: 0;
}

.memory-search-clear:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

/* 命中关键词高亮：备忘录面板 / 项目记忆面板共用
   （components/common/HighlightedText.tsx） */
.search-hit-mark {
  padding: 0 1px;
  border-radius: 2px;
  background: var(--accent-amber-bg, rgba(245, 179, 1, 0.18));
  color: inherit;
  font-weight: 600;
}

.memory-list-item-snippet {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-tertiary);
}

.memory-clear-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  flex-shrink: 0;
  transition:
    background 0.12s,
    color 0.12s;
}

.memory-clear-btn:hover:not(:disabled) {
  background: var(--accent-red-bg);
  color: var(--accent-red);
}

.memory-clear-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.memory-list-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 32px 16px;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.6;
  text-align: center;
}

.memory-list-item {
  margin-bottom: 4px;
  position: relative;
  flex-direction: column;
  gap: 4px;
}

.memory-list-item.archived {
  opacity: 0.6;
}

.memory-list-item .memo-list-item-actions {
  position: absolute;
  top: 50%;
  right: 6px;
  transform: translateY(-50%);
  flex-direction: row;
}

.memory-list-item-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.memory-list-item-title-row {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  padding-right: 22px;
}

.memory-kind-badge {
  flex-shrink: 0;
  padding: 1px 6px;
  border-radius: var(--radius-lg);
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.2px;
  white-space: nowrap;
}

.memory-kind-badge.decision {
  background: color-mix(
    in srgb,
    var(--accent-purple-text, var(--accent-blue-text)) 14%,
    transparent
  );
  color: var(--accent-purple-text, var(--accent-blue-text));
}

.memory-kind-badge.preference {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.memory-kind-badge.pitfall {
  background: var(--accent-orange-bg, rgba(232, 151, 58, 0.12));
  color: var(--accent-orange-text, #e8973a);
}

.memory-kind-badge.task_state {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

.memory-kind-badge.scope-global {
  background: transparent;
  border: 1px solid color-mix(in srgb, var(--accent-blue-text) 40%, transparent);
  color: var(--accent-blue-text);
}

.memory-list-item-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-primary);
}

.memory-list-item-importance {
  display: inline-flex;
  align-items: center;
  gap: 1px;
  flex-shrink: 0;
  font-size: 10px;
  color: var(--warning, #f5b301);
  line-height: 1;
}

.memory-list-item-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 10.5px;
  color: var(--text-muted);
  flex-wrap: wrap;
}

.memory-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  padding: 0 5px;
  border-radius: var(--radius-lg);
  font-size: 10px;
}

.memory-status-badge.pending {
  background: var(--accent-amber-bg);
  color: var(--accent-amber-text);
}

.memory-status-badge.archived {
  background: var(--bg-hover);
  color: var(--text-tertiary);
}

.memory-content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.memory-content-empty {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 24px;
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.7;
  text-align: center;
}

.memory-editor {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px;
}

.memory-editor-header {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.memory-editor-meta {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: var(--text-muted);
}

.memory-editor-source {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 来源会话徽章（「来自《会话名》」）：解析中显示中性文案，指向真实会话时
   渲染为可点击徽章（悬停变蓝、点击直达该会话），来源会话已删除则为降级态。 */
.memory-editor-conversation,
.memory-list-item-source {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  max-width: 220px;
  overflow: hidden;
  padding: 1px 6px;
  border: none;
  border-radius: var(--radius-lg);
  background: var(--bg-hover);
  color: var(--text-tertiary);
  font-size: 10px;
  font-family: inherit;
  white-space: nowrap;
}

.memory-editor-conversation {
  flex-shrink: 0;
}

/* 列表行内的紧凑变体：只显示会话名，宽度更窄（超出以省略号截断） */
.memory-list-item-source {
  flex-shrink: 0;
  max-width: 150px;
  padding: 0 5px;
}

.memory-editor-conversation svg,
.memory-list-item-source svg {
  flex-shrink: 0;
}

.memory-source-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.memory-editor-conversation.is-linked,
.memory-list-item-source.is-linked {
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.memory-editor-conversation.is-linked:hover:not(:disabled),
.memory-list-item-source.is-linked:hover:not(:disabled) {
  background: var(--accent-blue-bg);
  color: var(--accent-blue-text);
}

.memory-editor-conversation.is-linked:disabled,
.memory-list-item-source.is-linked:disabled {
  cursor: default;
}

.memory-editor-conversation.is-deleted,
.memory-list-item-source.is-deleted {
  opacity: 0.75;
}

.memory-editor-header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.memory-editor-title {
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 13px;
  font-weight: 600;
  font-family: inherit;
  box-sizing: border-box;
  flex-shrink: 0;
}

.memory-editor-title:focus {
  outline: none;
  border-color: var(--accent-color);
}

.memory-editor-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  flex-shrink: 0;
}

.memory-editor-row .custom-select {
  flex: 1;
  min-width: 0;
}

/* 重要性下拉的两行选项：等级名 + 说明。 */
.memory-editor-row .custom-select-item > span:first-child {
  white-space: normal;
}

.memory-importance-option {
  display: flex;
  flex-direction: column;
  gap: 2px;
  width: 100%;
}

.memory-importance-option-desc {
  color: var(--text-muted);
  font-size: 10.5px;
  line-height: 1.35;
}

.memory-editor-content {
  flex: 1;
  min-height: 120px;
  width: 100%;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12.5px;
  font-family: inherit;
  line-height: 1.6;
  resize: none;
  box-sizing: border-box;
}

.memory-editor-content:focus {
  outline: none;
  border-color: var(--accent-color);
}

.memory-editor-tags {
  width: 100%;
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12px;
  font-family: inherit;
  box-sizing: border-box;
  flex-shrink: 0;
}

.memory-editor-tags:focus {
  outline: none;
  border-color: var(--accent-color);
}

.memory-editor-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.memory-editor-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 28px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: var(--text-primary);
  color: var(--on-solid);
  font-size: 12px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  white-space: nowrap;
  transition:
    filter 0.12s,
    background 0.12s;
}

.memory-editor-btn:hover:not(:disabled) {
  filter: brightness(1.08);
}

.memory-editor-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* 多选删除：header 工具条 + 条目勾选框（参照 chat-multi-select 交互） */
.memory-multi-select-exit-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-tertiary);
  cursor: pointer;
  transition:
    background 0.12s,
    color 0.12s;
}

.memory-multi-select-exit-btn:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.memory-multi-select-exit-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.memory-multi-select-count {
  flex-shrink: 0;
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  white-space: nowrap;
}

.memory-multi-select-actions {
  display: flex;
  gap: 2px;
  margin-left: auto;
}

.memory-multi-select-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px;
  border: none;
  border-radius: var(--radius-sm, 6px);
  background: transparent;
  color: var(--text-secondary);
  font-size: 11px;
  cursor: pointer;
  white-space: nowrap;
  transition:
    background 0.12s,
    color 0.12s;
}

.memory-multi-select-action-btn:hover:not(:disabled) {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.memory-multi-select-action-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.memory-multi-select-action-btn.danger {
  color: var(--accent-red);
}

.memory-multi-select-action-btn.danger:hover:not(:disabled) {
  background: var(--accent-red-bg);
}

/* 多选模式下条目由纵向堆叠改为勾选框 + 内容的横向布局 */
.memory-list-item.multi-select {
  flex-direction: row;
  align-items: flex-start;
}

.memory-item-checkbox {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  margin-top: 2px;
  border-radius: var(--radius-sm);
  border: 1.5px solid var(--text-muted);
  background: transparent;
  color: var(--on-solid);
  transition:
    background 0.15s ease,
    border-color 0.15s ease;
}

.memory-item-checkbox:hover {
  border-color: var(--accent-color);
}

.memory-item-checkbox.checked {
  background: var(--accent-color);
  border-color: color-mix(in srgb, var(--accent-color) 60%, transparent);
}

/* MemoryToolCall specific styles */
.tool-call-memory-action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.tool-call-memory-action-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 500;
  color: var(--text-secondary);
  background: var(--bg-active);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
}

.tool-call-memory-hint {
  font-size: 10.5px;
  color: var(--text-muted);
  font-style: italic;
}

.tool-call-memory-count {
  font-size: 11px;
  color: var(--text-muted);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.tool-call-memory-args {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tool-call-memory-arg-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex-wrap: wrap;
}

.tool-call-memory-arg-label {
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  flex-shrink: 0;
}

.tool-call-memory-arg-value {
  margin: 0;
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-secondary);
  white-space: pre-wrap;
  word-break: break-word;
  flex: 1;
  min-width: 0;
}

.tool-call-memory-arg-code {
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  word-break: break-all;
}

.tool-call-memory-kind-badge {
  font-size: 11px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-weight: 500;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}

.tool-call-memory-importance-badge {
  font-size: 11px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  color: var(--warning);
  background: color-mix(in srgb, var(--warning) 15%, transparent);
}

.tool-call-memory-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.tool-call-memory-tag {
  font-size: 10.5px;
  font-family: var(--font-mono);
  color: var(--text-tertiary);
  background: var(--bg-active);
  padding: 1px 5px;
  border-radius: var(--radius-sm);
}

.tool-call-memory-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-muted);
}

.tool-call-memory-pending-running {
  color: var(--accent);
}

.tool-call-memory-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
  max-height: 260px;
  overflow-y: auto;
}

.tool-call-memory-list-item {
  background: var(--bg-tertiary);
  border-radius: var(--radius-sm);
}

.tool-call-memory-list-head {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 4px 6px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 11.5px;
  text-align: left;
  cursor: pointer;
  transition: background 0.15s ease;
}

.tool-call-memory-list-head:hover {
  background: var(--bg-active);
}

.tool-call-memory-list-title {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tool-call-memory-list-head .tool-call-memory-tags {
  flex-shrink: 0;
  flex-wrap: nowrap;
  max-width: 45%;
  overflow: hidden;
}

.tool-call-memory-list-content {
  margin: 0;
  padding: 2px 8px 6px 24px;
  font-size: 11px;
  line-height: 1.55;
  color: var(--text-tertiary);
  white-space: pre-wrap;
  word-break: break-word;
}

.tool-call-skill-meta {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.tool-call-skill-meta-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  flex-wrap: wrap;
}

.tool-call-skill-meta-label {
  font-size: 11px;
  line-height: 1.5;
  color: var(--text-tertiary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  flex-shrink: 0;
}

.tool-call-skill-meta-value {
  font-size: 11.5px;
  line-height: 1.5;
  color: var(--text-secondary);
  word-break: break-word;
  flex: 1;
  min-width: 0;
}

.tool-call-skill-meta-code {
  font-size: 11px;
  font-family: var(--font-mono);
  color: var(--text-tertiary);
  background: var(--bg-tertiary);
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  word-break: break-all;
}

.tool-call-skill-root {
  font-size: 11px;
  padding: 1px 6px;
  border-radius: var(--radius-sm);
  font-weight: 500;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
}

.tool-call-skill-tools {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.tool-call-skill-tool {
  font-size: 10.5px;
  font-family: var(--font-mono);
  color: var(--text-tertiary);
  background: var(--bg-active);
  padding: 1px 5px;
  border-radius: var(--radius-sm);
}

.tool-call-skill-content {
  max-height: 320px;
  overflow: auto;
}

.tool-call-skill-pending {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  color: var(--text-muted);
}

.tool-call-skill-pending-running {
  color: var(--accent);
}

/* ===== App lock ===== */
.app-lock-overlay {
  position: fixed;
  inset: 0;
  z-index: 30000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(15, 23, 42, 0.32);
  backdrop-filter: blur(30px) saturate(1.1);
  -webkit-backdrop-filter: blur(30px) saturate(1.1);
  animation: confirm-overlay-in 0.15s ease;
}

:root[data-theme="dark"] .app-lock-overlay {
  background: rgba(0, 0, 0, 0.5);
}

.app-lock-card {
  display: flex;
  width: 340px;
  max-width: 88vw;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  padding: 26px 24px 20px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-xl);
  background: var(--surface-island-strong);
  box-shadow: var(--island-shadow);
  text-align: center;
}

.app-lock-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: var(--surface-island-muted);
  color: var(--text-secondary);
}

.app-lock-title {
  color: var(--text-primary);
  font-size: 15px;
}

.app-lock-subtitle {
  color: var(--text-tertiary);
  font-size: 12px;
  line-height: 1.6;
}

.app-lock-form {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
}

.app-lock-input {
  flex: 1;
  min-width: 0;
  height: 34px;
  padding: 0 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 14px;
  letter-spacing: 4px;
  text-align: center;
  outline: none;
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease;
}

.app-lock-input:focus {
  border-color: var(--accent-color);
}

.app-lock-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 34px;
  padding: 0 16px;
  border: none;
  border-radius: var(--radius-md);
  background: var(--accent-color);
  color: var(--on-solid);
  font-size: 12.5px;
  font-weight: 500;
  cursor: pointer;
  transition:
    background 0.15s ease,
    opacity 0.15s ease;
}

.app-lock-submit:hover:not(:disabled) {
  background: color-mix(in srgb, var(--accent-color) 88%, var(--bg-primary));
}

.app-lock-submit:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.app-lock-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 30px;
  padding: 5px 14px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  background: var(--bg-hover);
  color: var(--text-secondary);
  font-size: 12px;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background 0.15s ease,
    border-color 0.15s ease,
    color 0.15s ease,
    opacity 0.15s ease;
}

.app-lock-action:hover:not(:disabled) {
  border-color: var(--text-primary);
  background: var(--bg-active);
  color: var(--text-primary);
}

.app-lock-action:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.app-lock-action.primary {
  border-color: transparent;
  background: var(--accent-color);
  color: var(--on-solid);
  font-weight: 500;
}

.app-lock-action.primary:hover:not(:disabled) {
  border-color: transparent;
  background: color-mix(in srgb, var(--accent-color) 88%, var(--bg-primary));
  color: var(--on-solid);
}

.app-lock-action.danger {
  border-color: color-mix(in srgb, var(--accent-red) 45%, transparent);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
}

.app-lock-action.danger:hover:not(:disabled) {
  border-color: transparent;
  background: var(--accent-red);
  color: var(--on-solid);
}

.app-lock-error {
  color: var(--accent-red-text);
  font-size: 12px;
}

.app-lock-link {
  margin-top: 2px;
  border: none;
  background: none;
  color: var(--text-tertiary);
  font-size: 11px;
  text-decoration: underline;
  cursor: pointer;
}

.app-lock-link:hover:not(:disabled) {
  color: var(--text-secondary);
}

.app-lock-hint {
  color: var(--text-muted);
  font-size: 11px;
}

.app-lock-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 10px;
  border-radius: var(--radius-pill);
  background: var(--bg-tertiary);
  color: var(--text-tertiary);
  font-size: 11px;
}

.app-lock-badge.is-on {
  background: var(--accent-green-bg);
  color: var(--accent-green-text);
}

.app-lock-settings-input {
  width: 132px;
  height: 28px;
  padding: 0 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-size: 12px;
  letter-spacing: 2px;
  text-align: center;
  outline: none;
}

.app-lock-settings-input:focus {
  border-color: var(--accent-color);
}

.app-lock-bind {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 12px;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--surface-island-muted);
}

.app-lock-qr {
  width: 168px;
  height: 168px;
  padding: 6px;
  border-radius: var(--radius-md);
  background: #ffffff;
}

.app-lock-secret {
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 1px;
  word-break: break-all;
  user-select: all;
}

.top-bar-plus-dropdown-separator {
  height: 1px;
  margin: 4px 0;
  background: var(--border-subtle);
}

.top-bar-plus-dropdown-item.disabled {
  opacity: 0.5;
  cursor: default;
}

/* ── Plugins ─────────────────────────────────────────────────────────── */

.top-bar-plus-dropdown-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.top-bar-plus-dropdown-divider {
  height: 1px;
  margin: 3px 2px;
  background: var(--border-subtle, var(--border-light));
}

/* 带分组文字的分隔线：文字在左，横线填充剩余宽度（与右键菜单一致）。 */
.top-bar-plus-dropdown-divider.labeled {
  display: flex;
  align-items: center;
  gap: 6px;
  height: auto;
  margin: 6px 8px 2px;
  background: transparent;
}

.top-bar-plus-dropdown-divider.labeled::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--border-subtle, var(--border-light));
}

.top-bar-plus-dropdown-divider-label {
  flex-shrink: 0;
  font-size: 10.5px;
  line-height: 1.4;
  color: var(--text-muted);
  white-space: nowrap;
  user-select: none;
}

.plugin-panel-root {
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: auto;
}

.plugin-panel-iframe {
  width: 100%;
  height: 100%;
  border: none;
  background: var(--bg-primary);
}

.plugin-panel-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 24px;
  color: var(--text-muted);
  font-size: 12px;
}

.plugin-panel-error {
  display: flex;
  height: 100%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 24px;
  color: var(--accent-red-text);
  text-align: center;
}

.plugin-panel-error-title {
  color: var(--text-primary);
  font-size: 13px;
}

.plugin-panel-error-detail {
  max-width: 100%;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: 11px;
  word-break: break-word;
}

.plugin-panel-retry {
  padding: 4px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-primary);
  font-size: 12px;
  cursor: pointer;
}

.plugin-panel-retry:hover {
  background: var(--bg-hover);
}

.plugins-panel-body {
  display: flex;
  width: 100%;
  min-height: 0;
  flex-direction: column;
  gap: 10px;
  padding: 12px;
  overflow: hidden;
}

.plugins-tab-content {
  display: flex;
  min-height: 0;
  flex: 1;
  flex-direction: column;
  gap: 10px;
}

.plugins-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  flex-shrink: 0;
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-secondary);
}

.plugins-tab {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 10px;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text-tertiary);
  font: inherit;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
}

.plugins-tab:hover {
  background: var(--bg-hover);
  color: var(--text-secondary);
}

.plugins-tab.active {
  background: var(--bg-primary);
  color: var(--text-primary);
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.08);
}

.plugins-tab small {
  display: inline-flex;
  min-width: 20px;
  height: 18px;
  align-items: center;
  justify-content: center;
  padding: 0 5px;
  border-radius: 999px;
  background: var(--bg-tertiary);
  color: var(--text-muted);
  font-size: 10px;
}

.plugins-tab.active small {
  color: var(--text-secondary);
}

.plugins-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.plugins-toolbar-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background: var(--bg-secondary);
  color: var(--text-secondary);
  font-size: 12px;
  cursor: pointer;
}

.plugins-toolbar-btn:hover {
  background: var(--bg-hover);
  color: var(--text-primary);
}

.plugins-toolbar-btn.primary {
  border-color: var(--accent-color);
  background: var(--accent-color);
  color: var(--on-solid);
}

.plugins-toolbar-btn.primary:hover {
  background: color-mix(in srgb, var(--accent-color) 88%, white);
  border-color: color-mix(in srgb, var(--accent-color) 88%, white);
  color: var(--on-solid);
}

.plugins-toolbar-btn:disabled {
  opacity: 0.6;
  cursor: default;
}

.plugins-error {
  padding: 8px 10px;
  border: 1px solid var(--accent-red);
  border-radius: var(--radius-sm);
  background: var(--accent-red-bg);
  color: var(--accent-red-text);
  font-size: 12px;
  word-break: break-word;
}

.plugins-empty {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 40px 0;
  color: var(--text-muted);
  font-size: 12px;
}

.plugins-empty-hint {
  max-width: 420px;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.6;
  text-align: center;
}

/* 输入框与操作按钮同处一个描边容器（对齐聊天输入框的 composer 形态）：
   焦点环落在容器上，输入框自身无边框，也就没有原生右下角的拖拽手柄 */
.plugins-create {
  display: flex;
  width: min(440px, calc(100% - 24px));
  flex-direction: column;
  gap: 8px;
  margin-top: 6px;
  padding: 10px 12px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  background: var(--bg-primary);
  transition:
    border-color 0.12s,
    box-shadow 0.12s;
}

.plugins-create:focus-within {
  border-color: var(--accent-color);
}

.plugins-create-input {
  width: 100%;
  min-height: 60px;
  /* 自动增高上限：约 8 行（8 × 18px 行高），更高改为内部滚动 */
  max-height: 160px;
  padding: 0;
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  color: var(--text-primary);
  font: inherit;
  font-size: 12px;
  line-height: 1.5;
  box-sizing: border-box;
  /* 高度交给 CSS：field-sizing 让输入框随内容自然长高，超出 max-height
     后转为内部滚动；resize: none 关闭原生拖拽改尺寸。 */
  resize: none;
  field-sizing: content;
  overflow-y: auto;
  /* cream 等主题对所有 textarea:focus-visible 施加橙色 outline（preset-cream.css）；
     焦点反馈由 .plugins-create:focus-within 承担，此处压掉浏览器 outline。
     !important 用于覆盖主题规则的高特异性。 */
  outline: none !important;
}

.plugins-create-input::placeholder {
  color: var(--text-muted);
}

.plugins-create-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.plugins-create-inline {
  width: 100%;
  margin-top: 0;
}

/* “AI 生成”是展开 / 收起下方描述框的开关，不是一次性动作按钮：
   尾随箭头给出“可展开”的暗示，展开态用强调色底填充并让箭头翻转，
   与旁边的动作按钮（安装 / 刷新 / 更新）在视觉上区分开。 */
.plugins-create-toggle-chevron {
  flex-shrink: 0;
  margin-left: -1px;
  color: var(--text-tertiary);
  transition:
    transform 0.15s ease,
    color 0.15s ease;
}

.plugins-toolbar-btn:hover .plugins-create-toggle-chevron {
  color: currentColor;
}

.plugins-toolbar-btn.active {
  border-color: var(--accent-color);
  background: color-mix(in srgb, var(--accent-color) 14%, var(--bg-secondary));
  color: var(--accent-color);
}

.plugins-toolbar-btn.active .plugins-create-toggle-chevron {
  color: var(--accent-color);
  transform: rotate(180deg);
}

